window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s18-241","number":241,"surah":18,"verses":[83],"references":[{"surah":18,"verses":[83]}],"verseLabel":"الكهف: 83","question":"ما معنى ﴿ذِكْرًا﴾، وما سر تنكيرها في خبر ذي القرنين؟","answer":"الذكر هنا الخبر الذي يُتلى ويُحفظ للاتعاظ، وجاء منكرًا لأن المقصود بعض أخباره النافعة للعبرة، لا استقصاء جميع أحواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص485، تحت «معنى ﴿ذِكْرًا﴾ وسر وروده منكرًا»","url":""}]},{"id":"s18-179","number":179,"surah":18,"verses":[84],"references":[{"surah":18,"verses":[84]}],"verseLabel":"الكهف: 84","question":"ما دلالة الجمع لذي القرنين بين التمكين وإيتاء الأسباب؟","answer":"مكّن الله له في الأرض وآتاه وسائل الوصول إلى مقاصده؛ فالسبب هو الوسيلة، ويطلق في سياق رحلاته على الطريق الموصل إلى المكان المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص489، تحت «سر التقييد بالمفعول به سببًا منكرًا مفردًا»","url":""}]},{"id":"s18-180","number":180,"surah":18,"verses":[85],"references":[{"surah":18,"verses":[85]}],"verseLabel":"الكهف: 85","question":"ما دلالة تكرار ذكر السبب واتباعه في رحلات ذي القرنين؟","answer":"يدل تكرار ذكر السبب واتباعه على سلوك ذي القرنين طريقًا مناسبًا لكل وجهة من رحلاته. وجاء الانتقال بين الرحلات مع استمرار الأخذ بما آتاه الله من وسائل بلوغ المقاصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص533، تحت «دلالة التكرار في قوله ثم أتبع سببًا»","url":""}]},{"id":"s18-181","number":181,"surah":18,"verses":[86],"references":[{"surah":18,"verses":[86]}],"verseLabel":"الكهف: 86","question":"ما سرّ التعبير بـ﴿وَجَدَهَا تَغْرُبُ فِي عَيْنٍ حَمِئَةٍ﴾؟","answer":"وصف ما يلوح للناظر عند منتهى المعمور من جهة الغرب؛ فليس للشمس مغرب حقيقي في عين، وإنما يبدو ذلك للتخيل عند الأفق.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص501، تحت «سر وصف العين بحمئة»","url":""}]},{"id":"s18-182","number":182,"surah":18,"verses":[86],"references":[{"surah":18,"verses":[86]}],"verseLabel":"الكهف: 86","question":"ما دلالة تخيير ذي القرنين بين تعذيب القوم والإحسان إليهم؟","answer":"يدل على تمكينه من الحكم مع إلزامه بالعدل، فيعامل الناس بحسب إيمانهم وظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص503، تحت «دلالة التخيير»","url":""}]},{"id":"s18-242","number":242,"surah":18,"verses":[86],"references":[{"surah":18,"verses":[86]}],"verseLabel":"الكهف: 86","question":"ما دلالة قوله لذي القرنين: ﴿أو تتخذ فيهم حسنًا﴾؟","answer":"أطلق الحسن وأريد به المعاملة الحسنة من الدعوة والرفق والعدل؛ فعبّر بالمعنى الجامع عن وجوه الإحسان كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص506، تحت «بلاغة المجاز المرسل في حسنًا»","url":""}]},{"id":"s18-183","number":183,"surah":18,"verses":[87,88],"references":[{"surah":18,"verses":[87,88]}],"verseLabel":"الكهف: 87-88","question":"ما دلالة تكرار ﴿أما﴾ في حكم ذي القرنين؟","answer":"يفصل بين مصير الظالم والمؤمن فصلًا واضحًا، ويبرز عدله في تنزيل الجزاء على اختلاف العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص514، تحت «سر تكرار أما»","url":""}]},{"id":"s18-243","number":243,"surah":18,"verses":[87,88],"references":[{"surah":18,"verses":[87,88]}],"verseLabel":"الكهف: 87-88","question":"لماذا عطف العمل الصالح على الإيمان في حكم ذي القرنين؟","answer":"لأن دعوى الإيمان لا تكفي وحدها، بل يظهر صدقها في العمل الصالح الذي يستحق صاحبه الحسنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص515، تحت «دلالة عطف العمل الصالح على الإيمان»","url":""}]},{"id":"s18-184","number":184,"surah":18,"verses":[88],"references":[{"surah":18,"verses":[88]}],"verseLabel":"الكهف: 88","question":"ما سرّ التعبير بـ﴿وَسَنَقُولُ لَهُ مِنْ أَمْرِنَا يُسْرًا﴾؟","answer":"أي نكلف المؤمن بما هو سهل ونخاطبه بلين، فجمع له حسن الجزاء وحسن المعاملة في سلطان ذي القرنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص519، تحت «الغرض من تنكير لفظ يسرًا»","url":""}]},{"id":"s18-185","number":185,"surah":18,"verses":[90],"references":[{"surah":18,"verses":[90]}],"verseLabel":"الكهف: 90","question":"ما دلالة قوله عن القوم ﴿لَمْ نَجْعَلْ لَهُمْ مِنْ دُونِهَا سِتْرًا﴾؟","answer":"كانوا في أرض مكشوفة لا ساتر فيها من حر الشمس، أو لم تكن لهم ثياب ولا مساكن تقيهم منها؛ وهو وصف لشدة انكشاف بيئتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص529، تحت «بلاغة الكناية في عدم جعل الستر من دونها»","url":""}]},{"id":"s18-186","number":186,"surah":18,"verses":[91],"references":[{"surah":18,"verses":[91]}],"verseLabel":"الكهف: 91","question":"ما دلالة التعبير بجملة وقد أحطنا في قوله تعالى: ﴿وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًا﴾؟","answer":"أي أحاط الله علمًا بما عند ذي القرنين من عظمة الملك والجند والقوة والثروة؛ وفي التعبير كناية عن عظم ذلك بحيث لا يحيط به إلا علام الغيوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص531، تحت «دلالة التعبير بجملة وقد أحطنا»","url":""}]},{"id":"s18-187","number":187,"surah":18,"verses":[93],"references":[{"surah":18,"verses":[93]}],"verseLabel":"الكهف: 93","question":"ما سرّ وصف القوم بأنهم ﴿لَا يَكَادُونَ يَفْقَهُونَ قَوْلًا﴾؟","answer":"يصوّر صعوبة التفاهم معهم، ومن توجيهاته غرابة لغتهم أو قلة فهمهم وبداوتهم. ولا ينفي حصول التفاهم بعد جهد؛ فقد حكى السياق طلبهم وجواب ذي القرنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص541، تحت «سر التعبير بالفعل يفقهون دون غيره»","url":""}]},{"id":"s18-188","number":188,"surah":18,"verses":[94],"references":[{"surah":18,"verses":[94]}],"verseLabel":"الكهف: 94","question":"ما دلالة التعبير بالمسند مفسدون جمعًا في قوله تعالى: ﴿إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِي الْأَرْضِ﴾؟","answer":"بيّنوا سبب طلب السد: كانوا أضعف من يأجوج ومأجوج ويصيب بلادهم فسادهم المتكرر، فطلبوا حاجزًا يقيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص546، تحت «دلالة التعبير بالمسند مفسدون جمعًا»","url":""}]},{"id":"s18-189","number":189,"surah":18,"verses":[94],"references":[{"surah":18,"verses":[94]}],"verseLabel":"الكهف: 94","question":"ما دلالة عرض القوم ﴿خَرْجًا﴾ على ذي القرنين؟","answer":"عرضوا مالًا يجمعونه له في مقابلة أن يجعل بينهم وبين المفسدين سدًا، لما علموا أن العمل يحتاج مؤونة وصناعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص548، تحت «دلالة لفظ خرجًا وتنكيره وتأخيره»","url":""}]},{"id":"s18-190","number":190,"surah":18,"verses":[95],"references":[{"surah":18,"verses":[95]}],"verseLabel":"الكهف: 95","question":"ما دلالة استغناء ذي القرنين عن مالهم بقوله: ﴿مَا مَكَّنِّي فِيهِ رَبِّي خَيْرٌ﴾؟","answer":"استغنى بما مكّنه الله فيه من الملك والقدرة عن مالهم، واكتفى بأن يعينوه بقوة العمل والآلات.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص561، تحت «سر اختيار لفظ الربوبية مضافًا»","url":""}]},{"id":"s18-191","number":191,"surah":18,"verses":[95],"references":[{"surah":18,"verses":[95]}],"verseLabel":"الكهف: 95","question":"ما سرّ التعبير بالقوة نكرة في قوله تعالى: ﴿فَأَعِينُونِي بِقُوَّةٍ﴾؟","answer":"طلب منهم قوة الأبدان والعمل والآلات لإقامة الردم، بدل المال الذي عرضوه؛ فكانوا عمال التنفيذ تحت تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص562، تحت «سر التعبير بالقوة نكرة»","url":""}]},{"id":"s18-192","number":192,"surah":18,"verses":[97],"references":[{"surah":18,"verses":[97]}],"verseLabel":"الكهف: 97","question":"ما سرّ اختلاف الصيغتين في ﴿فَمَا اسْطَاعُوا أَنْ يَظْهَرُوهُ وَمَا اسْتَطَاعُوا لَهُ نَقْبًا﴾؟","answer":"خففت الأولى للتفنن وتجنب إعادة الكلمة، وناسبت الصيغة الزائدة النقب لأنه أشد من تسلق الردم؛ فزيادة المبنى وافقت زيادة المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص573، 574، 575، 576، تحت «دلالة التعبير باسطاعوا محذوف التاء؛ سر عدم حذف التاء من الفعل كسابقه»","url":""}]},{"id":"s18-193","number":193,"surah":18,"verses":[98],"references":[{"surah":18,"verses":[98]}],"verseLabel":"الكهف: 98","question":"ما دلالة قول ذي القرنين ﴿هَذَا رَحْمَةٌ مِنْ رَبِّي﴾ بعد الإنجاز؟","answer":"نسب إنجاز الردم إلى رحمة الله وتوفيقه، لما فيه من حماية الناس من فساد يأجوج ومأجوج. وفي ذلك اعتراف بالنعمة وتواضع عند ظهور القوة، وتنكير «رحمة» لتعظيمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص581، تحت «علة التعبير بلفظ رحمة وتنكيره»","url":""}]},{"id":"s18-194","number":194,"surah":18,"verses":[98],"references":[{"surah":18,"verses":[98]}],"verseLabel":"الكهف: 98","question":"ما سرّ إضافة الوعد إلى لفظ الربوبية في قوله تعالى: ﴿فَإِذَا جَاءَ وَعْدُ رَبِّي جَعَلَهُ دَكَّاءَ﴾؟","answer":"مهما بلغ الردم من الصلابة فبقاؤه مؤقت إلى الوقت الذي وعد الله فيه بخروج يأجوج ومأجوج؛ عندئذ يسويه بالأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص585، تحت «سر إضافة الوعد إلى لفظ الربوبية»","url":""}]},{"id":"s18-195","number":195,"surah":18,"verses":[99],"references":[{"surah":18,"verses":[99]}],"verseLabel":"الكهف: 99","question":"ما سرّ التعبير بـ﴿يَمُوجُ فِي بَعْضٍ﴾؟","answer":"تصوّر الاستعارة كثرة الخلق واضطرابهم وتدافعهم كموج البحر. ويرجح المصدر عود الضمير إلى عموم الخلق يوم القيامة لمناسبة ما بعده من الجمع، ويذكر وجهًا آخر في يأجوج ومأجوج عند خروجهم؛ فلا يُحصر المعنى في الوجه الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص593، تحت «بلاغة الاستعارة في جملة يموج في بعض»","url":""}]},{"id":"s18-196","number":196,"surah":18,"verses":[100],"references":[{"surah":18,"verses":[100]}],"verseLabel":"الكهف: 100","question":"ما دلالة توكيد ﴿وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذٍ لِلْكَافِرِينَ عَرْضًا﴾ بالمصدر؟","answer":"يحقق المصدر وقوع العرض ويؤكده، ويهوّل تنكيره ذلك المشهد. ويذكر المصدر في «عرضنا» وجهًا من التهكم بإظهار جهنم كأنها مما يُرغَب فيه، ووجهًا آخر هو الكناية عن تعذيبهم بها؛ فلا يلزم حصر التعبير في التهكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص603، تحت «دلالة التعبير بالمفعول المطلق عرضًا»","url":""}]},{"id":"s18-197","number":197,"surah":18,"verses":[101],"references":[{"surah":18,"verses":[101]}],"verseLabel":"الكهف: 101","question":"ما سرّ التعبير بـ﴿فِي غِطَاءٍ عَنْ ذِكْرِي﴾؟","answer":"الغطاء استعارة لعدم انتفاعهم بدلالة أبصارهم على تفرد الله، و﴿في﴾ تصور تمكن الغطاء منهم، و﴿عن﴾ مجاوزتهم النظر فيما يذكر بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص607، تحت «بلاغة الاستعارة في غطاء»","url":""}]},{"id":"s18-198","number":198,"surah":18,"verses":[101],"references":[{"surah":18,"verses":[101]}],"verseLabel":"الكهف: 101","question":"ما سرّ التعبير بـ﴿لَا يَسْتَطِيعُونَ سَمْعًا﴾؟","answer":"يصوّر شدة إعراضهم عن سماع الحق حتى كأنهم فقدوا القدرة على الانتفاع بالسمع. ويذكر المصدر نفي مطاوعة نفوسهم للاستماع لشدة كراهتهم له؛ فالمراد إعراض راسخ، لا مجرد فقد الحاسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص609، تحت «سر التعبير بنفي استطاعة السمع دون الصمم»","url":""}]},{"id":"s18-199","number":199,"surah":18,"verses":[102],"references":[{"surah":18,"verses":[102]}],"verseLabel":"الكهف: 102","question":"ما دلالة الاستفهام في إنكار اتخاذ عباد الله أولياء من دونه؟","answer":"الاستفهام إنكاري لحسبانهم الباطل أن أولياءهم من دون الله سينفعونهم وينصرونهم، وقد نشأ هذا الحسبان من إعراضهم عن دلائل التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص614، تحت «بلاغة الاستفهام في صدر الآية الكريمة»","url":""}]},{"id":"s18-200","number":200,"surah":18,"verses":[103],"references":[{"surah":18,"verses":[103]}],"verseLabel":"الكهف: 103","question":"ما دلالة الاستفهام في ﴿هَلْ نُنَبِّئُكُمْ بِالْأَخْسَرِينَ أَعْمَالًا﴾؟","answer":"الاستفهام للتشويق إلى خبر عجيب: أناس ضل عملهم وهم يحسبون أنهم يحسنون، فجمعوا خسارة السعي وخسارة الاعتقاد فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص625، تحت «الغرض من افتتاح الكلام بالاستفهام في صدر الآية»","url":""}]},{"id":"s18-201","number":201,"surah":18,"verses":[104],"references":[{"surah":18,"verses":[104]}],"verseLabel":"الكهف: 104","question":"ما دلالة الجمع بين ضلال السعي وحسبان أصحابه أنهم يحسنون صنعًا؟","answer":"ضل عملهم عن طريق النفع وبطل أثره، وزاد خسارهم أنهم كانوا يعتقدون فسادهم صلاحًا؛ فجهلوا سوء العمل وسوء اعتقادهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص636، تحت «سر التعبير بالجملة الحالية في وهم يحسبون»","url":""}]},{"id":"s18-202","number":202,"surah":18,"verses":[105],"references":[{"surah":18,"verses":[105]}],"verseLabel":"الكهف: 105","question":"ما سرّ التعبير بـ﴿فَحَبِطَتْ أَعْمَالُهُمْ﴾؟","answer":"الحبوط بطلان أثر العمل بعد وجود صورته؛ فكفرهم بآيات الله ولقائه أذهب ما توهموه نافعًا من أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص644، تحت «دلالة التعبير بصيغة الماضي حبطت»","url":""}]},{"id":"s18-203","number":203,"surah":18,"verses":[105],"references":[{"surah":18,"verses":[105]}],"verseLabel":"الكهف: 105","question":"ما سرّ التعبير بـ﴿فَلَا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا﴾؟","answer":"نفي الوزن كناية عن عدم الاعتداد بهم وحقارتهم؛ فالشيء التافه لا يوزن، وقد تفرع ذلك على حبوط أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص647، تحت «الغرض من التعبير بعدم إقامة الوزن»","url":""}]},{"id":"s18-204","number":204,"surah":18,"verses":[106],"references":[{"surah":18,"verses":[106]}],"verseLabel":"الكهف: 106","question":"ما النكتة البلاغية في مرجع الإشارة للفظ ذلك وسر التعبير به في قوله تعالى: ﴿ذَلِكَ جَزَاؤُهُمْ جَهَنَّمُ﴾؟","answer":"من توجيهات اسم الإشارة أنه يعود إلى إعداد جهنم السابق، فتكون «جزاؤهم» خبرًا و«جهنم» بدلًا يبينه ويؤكد الوعيد. ويذكر المصدر أوجهًا أخرى في مرجع الإشارة والإعراب، تشترك في بيان استحقاقهم الجزاء بسبب كفرهم واستهزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص649، تحت «نكتة مرجع الإشارة للفظ ذلك وسر التعبير به»","url":""}]},{"id":"s18-205","number":205,"surah":18,"verses":[107],"references":[{"surah":18,"verses":[107]}],"verseLabel":"الكهف: 107","question":"لماذا قال في الكافرين: ﴿إنا أعتدنا﴾ ولم يكررها عند ذكر جنات المؤمنين؟","answer":"دل ذكر الإعداد أولًا وسياق المقابلة على المحذوف، فاستغنى عن تكراره مع المؤمنين إيجازًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص660، تحت «نكتة عدم ذكر أعتدنا للمؤمنين مع ذكره للكافرين»","url":""}]},{"id":"s18-244","number":244,"surah":18,"verses":[107],"references":[{"surah":18,"verses":[107]}],"verseLabel":"الكهف: 107","question":"ما سر وصف جنات الفردوس بأنها ﴿نزلًا﴾؟","answer":"النزل ما يهيأ للضيف عند قدومه؛ فوصف الجنة به يشعر بالإكرام، وإذا كان هذا نزلهم فما أعظم ما وراءه من نعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص661، تحت «دلالة التعبير بالنزل في سياق الآية الأكمل»","url":""}]},{"id":"s18-206","number":206,"surah":18,"verses":[108],"references":[{"surah":18,"verses":[108]}],"verseLabel":"الكهف: 108","question":"ما سرّ التعبير بـ﴿لَا يَبْغُونَ عَنْهَا حِوَلًا﴾؟","answer":"لا يتطلعون إلى مفارقتها إلى مكان خير، لأنهم يجدون فيها كل ما تشتهيه نفوسهم من ضروب اللذات.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص666، تحت «بلاغة التعبير بقوله لا يبغون عنها حولًا»","url":""}]},{"id":"s18-207","number":207,"surah":18,"verses":[109],"references":[{"surah":18,"verses":[109]}],"verseLabel":"الكهف: 109","question":"ما دلالة تمثيل البحر مدادًا لكلمات الله؟","answer":"شبهت معلومات الله التي يخبر بها بالمكتوبات، ورمز إلى الكتابة بالمداد؛ فلو كان البحر حبرًا لكتابتها لنفد مع استحالة نفاد معلومات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص673، تحت «بلاغة المجاز في لو كان البحر مدادًا لكلمات ربي»","url":""}]},{"id":"s18-208","number":208,"surah":18,"verses":[109],"references":[{"surah":18,"verses":[109]}],"verseLabel":"الكهف: 109","question":"ما موقع قوله ولو جئنا بمثله مددًا مما قبله ودلالته؟","answer":"هذه مبالغة ثانية: حتى لو مُد البحر ببحر مثله لبقي نفاد المداد ممكنًا، ولم تقارب كلمات الله النفاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص676، تحت «موقع قوله ولو جئنا بمثله مددًا مما قبله ودلالته»","url":""}]},{"id":"s18-209","number":209,"surah":18,"verses":[110],"references":[{"surah":18,"verses":[110]}],"verseLabel":"الكهف: 110","question":"ما دلالة قوله في ختام السورة: ﴿إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ﴾؟","answer":"يبين أنه بشر لا يحيط بالغيب، وأن ما أخبر به من أمر الغيب مستند إلى الوحي. فبعد الأجوبة الواردة في السورة يوجّه الختام إلى حقيقة الرسالة وما أوحاه الله إليه من التوحيد والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص683، تحت «الغرض من التعبير بأسلوب القصر في الآية»","url":""}]},{"id":"s18-210","number":210,"surah":18,"verses":[110],"references":[{"surah":18,"verses":[110]}],"verseLabel":"الكهف: 110","question":"ما دلالة إبراز توحيد الله في قوله: ﴿أَنَّمَا إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾؟","answer":"لأن توحيد الله أهم ما أوحي إلى الرسول وما بعث لأجله، ثم فرع عليه الإيمان بالبعث والعمل الصالح والنهي عن الإشراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص685، تحت «بلاغة القصر في قوله أنما إلهكم إله واحد»","url":""}]},{"id":"s18-211","number":211,"surah":18,"verses":[110],"references":[{"surah":18,"verses":[110]}],"verseLabel":"الكهف: 110","question":"ما دلالة الأمر بالعمل الصالح في ختام سورة الكهف؟","answer":"يبين أن رجاء لقاء الله لا يصح بالدعوى، بل يصدقه عمل صالح موافق لأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص688، تحت «الغرض من التعبير بالأمر بالعمل الصالح»","url":""}]},{"id":"s18-245","number":245,"surah":18,"verses":[110],"references":[{"surah":18,"verses":[110]}],"verseLabel":"الكهف: 110","question":"ما دلالة الجمع بين العمل الصالح وقوله: ﴿ولا يشرك بعبادة ربه أحدًا﴾؟","answer":"جمع بين صحة العمل وإخلاص القصد؛ فلا يقبل العمل حتى يكون صالحًا وخالصًا لله من الشرك والرياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص689، تحت «دلالة الواو في ولا يشرك»","url":""}]},{"id":"s18-212","number":212,"surah":18,"verses":[110],"references":[{"surah":18,"verses":[110]}],"verseLabel":"الكهف: 110","question":"ما سرّ تنكير ﴿أَحَدًا﴾ في قوله ﴿وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا﴾؟","answer":"النكرة في سياق النهي تعم كل أحد، فيكون ختام السورة تأكيدًا لوحدانية الله ونفي كل مشاركة في عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص691، تحت «النكتة من تنكير ﴿أحدًا﴾»","url":""}]},{"id":"s18-246","number":246,"surah":18,"verses":[2],"references":[{"surah":18,"verses":[2]}],"verseLabel":"الكهف: 2","question":"ما سر التعبير بـ«لَدُن» في قوله: ﴿لِّيُنذِرَ بَأْسًا شَدِيدًا مِّن لَّدُنْهُ﴾، وهي تأتي في مواطن اللين والرحمة؟","answer":"هذا هو الموطن الوحيد الذي اقترن فيه البأس والشدة بـ«لدن»، وهو مع ذلك في سياق الرحمة؛ فالكلام على القرآن الذي أُنزل مُنذرًا ومبشرًا: ﴿وَيُبَشِّرَ الْمُؤْمِنِينَ﴾، وهو خير ورحمة في الإنذار والتبشير جميعًا.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج2، ص218.","url":""}]},{"id":"s18-247","number":247,"surah":18,"verses":[17],"references":[{"surah":18,"verses":[17]}],"verseLabel":"الكهف: 17","question":"ما سر التعبير بالماضي في قوله: ﴿إِذَا طَلَعَت تَّزَاوَرُ عَن كَهْفِهِمْ... وَإِذَا غَرَبَت تَّقْرِضُهُمْ﴾؟","answer":"الطلوع والغروب يقعان جملةً واحدة فعبّر عنهما بالماضي، بخلاف قوله: ﴿وَاللَّيْلِ إِذَا يَسْرِ﴾ فالمضارع هناك يفيد الاستمرار والتطاول. وجاء بـ«إذا» لأنها للمقطوع بوقوعه، والطلوع والغروب لا بدّ من وقوعهما.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص62، ص72.","url":""}]},{"id":"s18-248","number":248,"surah":18,"verses":[22],"references":[{"surah":18,"verses":[22]}],"verseLabel":"الكهف: 22","question":"ما سر الواو في قوله: ﴿وَيَقُولُونَ سَبْعَةٌ وَثَامِنُهُمْ كَلْبُهُمْ﴾ دون الجملتين الأوليين؟","answer":"هي الواو الداخلة على الجملة الواقعة صفةً للنكرة، وفائدتها تأكيد لصوق الصفة بالموصوف وأن اتصافه بها ثابت مستقر، فآذنت بأن القائلين «سبعة وثامنهم كلبهم» قالوه عن ثبات علم لا رجمًا بالظن كغيرهم. وهذا التوجيه منقول عن «الكشاف»، والجمهور يعدّونها واو الحال.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج2، ص299.","url":""}]},{"id":"s18-249","number":249,"surah":18,"verses":[23],"references":[{"surah":18,"verses":[23]}],"verseLabel":"الكهف: 23","question":"ما دلالة صيغة اسم الفاعل في قوله: ﴿وَلَا تَقُولَنَّ لِشَيْءٍ إِنِّي فَاعِلٌ ذَٰلِكَ غَدًا﴾، وقد جاء في غيرها: ﴿فَعَّالٌ لِّمَا يُرِيدُ﴾؟","answer":"ورد «فاعل» مرة واحدة في القرآن في هذه الآية، فجاء باسم الفاعل للشيء الواحد: ﴿لِشَيْءٍ﴾. وجاء بصيغة المبالغة «فعّال» في موضعيها للتكثير، لأن ﴿مَا يُرِيدُ﴾ يشمل عموم ما يريد.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص37.","url":""}]},{"id":"s18-250","number":250,"surah":18,"verses":[43],"references":[{"surah":18,"verses":[43]}],"verseLabel":"الكهف: 43","question":"ما سر قوله: ﴿وَلَمْ تَكُن لَّهُ فِئَةٌ... وَمَا كَانَ مُنتَصِرًا﴾، وفي قارون: ﴿فَمَا كَانَ لَهُ مِن فِئَةٍ... وَمَا كَانَ مِنَ الْمُنتَصِرِينَ﴾؟","answer":"في الكهف هَلَكت الجنتان ونجا صاحبهما، وفي القصص خُسف بقارون وداره، فالعقوبة هناك أشد. فجاء في القصص بـ«ما كان» وهي آكد من «لم تكن»، وبـ«مِن» الاستغراقية المؤكدة. ولما كان الحوار في الكهف بين شخصين والمنتصر واحد قال: «منتصرًا»، ولما كان المنتصرون في القصص قوم موسى قال: «من المنتصرين».","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص140–142.","url":""}]},{"id":"s18-251","number":251,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"ما سر ذكر التذكير والإعراض في الكهف: ﴿ذُكِّرَ... فَأَعْرَضَ﴾، والتكذيب والصدوف في الأنعام: ﴿كَذَّبَ بِآيَاتِ اللَّهِ وَصَدَفَ عَنْهَا﴾؟","answer":"الصدوف إعراض شديد، وقد جمع في الأنعام التكذيب والإعراض الشديد، وأتبعه بجزاء أشدّ: ﴿سَنَجْزِي الَّذِينَ يَصْدِفُونَ... سُوءَ الْعَذَابِ﴾. أما في الكهف فذكر التذكير والإعراض ولم يذكر التكذيب، فكان ما في الأنعام أشدّ.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص51–52.","url":""}]},{"id":"s18-252","number":252,"surah":18,"verses":[13],"references":[{"surah":18,"verses":[13]}],"verseLabel":"الكهف: 13","question":"ما دلالة جمع القلة في قوله: ﴿إِنَّهُمْ فِتْيَةٌ آمَنُوا بِرَبِّهِمْ﴾، وجمع الكثرة في يوسف: ﴿وَقَالَ لِفِتْيَانِهِ﴾؟","answer":"«الفِتْيَة» جمع قلة لما بين الثلاثة والعشرة، وأكثر ما قيل في عدّة أصحاب الكهف سبعة وثامنهم كلبهم. أما «الفِتْيان» فجمع كثرة، وجاء في يوسف لأن عمّال العزيز الذين يعملون على الطعام أكثر من عشرة.","sources":[{"label":"فاضل السامرائي، الصرف العربي أحكام ومعان، ص154–155.","url":""}]},{"id":"s18-253","number":253,"surah":18,"verses":[18],"references":[{"surah":18,"verses":[18]}],"verseLabel":"الكهف: 18","question":"ما سر تقديم الفرار على الرعب في قوله: ﴿لَوَلَّيْتَ مِنْهُمْ فِرَارًا وَلَمُلِئْتَ مِنْهُمْ رُعْبًا﴾ مع أن الإنسان يخاف ثم يهرب؟","answer":"الواو لا تفيد الترتيب، والتقديم هنا للأهمية؛ فالمهم ألا يتملّى الرائي في الفتية فيعرفهم، والله أراد حجبهم عن العيون. ثم إن الفرار قد يسبق الرعب، فيفرّ المرء أولًا ثم يتذكر المشهد فيمتلئ رعبًا، والرعب لا يستدعي الهرب دائمًا فقد يُوقف صاحبه فلا يتحرك.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص120–121.","url":""}]},{"id":"s18-254","number":254,"surah":18,"verses":[24],"references":[{"surah":18,"verses":[24]}],"verseLabel":"الكهف: 24","question":"ما سر حذف الياء وتقديم الهداية في قوله: ﴿عَسَىٰ أَن يَهْدِيَنِ رَبِّي﴾، وفي القصص: ﴿عَسَىٰ رَبِّي أَن يَهْدِيَنِي﴾؟","answer":"موسى في القصص خائف فارّ يلتجئ إلى ربه، فقدّم الرب لأنه الملجأ وأظهر الياء دلالة على كمال الالتجاء. أما الكهف فالمقام مقام بيان القول الحق فيما اختلفت فيه الأقوال فقدّم الهداية، وهو مقام إيجاز جاء عرضًا فاجتزأ بالكسرة. ولفظ الهداية تكرر في القصص اثنتي عشرة مرة وفي الكهف خمس مرات.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص86–88.","url":""}]},{"id":"s18-255","number":255,"surah":18,"verses":[31],"references":[{"surah":18,"verses":[31]}],"verseLabel":"الكهف: 31","question":"ما سر ذكر أساور الذهب في قوله: ﴿يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ﴾، وأساور الفضة في سورة الإنسان؟","answer":"عمل المذكورين في الكهف أعلى من عمل المذكورين في الإنسان فكان الجزاء أعلى. ويدل على علوّ الجزاء في الكهف أنه أثنى عليه بقوله: ﴿نِعْمَ الثَّوَابُ وَحَسُنَتْ مُرْتَفَقًا﴾، وذكر الاتكاء على الأرائك وجريان الأنهار من تحتهم، ولم يذكر شيئًا من ذلك في الإنسان.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص212–214.","url":""}]},{"id":"s18-256","number":256,"surah":18,"verses":[31],"references":[{"surah":18,"verses":[31]}],"verseLabel":"الكهف: 31","question":"ما دلالة «مِن» في قوله: ﴿يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ﴾، وفي الإنسان: ﴿وَحُلُّوا أَسَاوِرَ﴾؟","answer":"ذكر «من» أعلى في الجزاء لأنها تدل على كثرة الأساور، كما أن قولك: «كُل من هذا التفاح» أدلّ على الكثرة من «كُل هذا التفاح». وحيث ذُكرت أساور الذهب جاءت «من» مع التحلية، بخلاف أساور الفضة، فكان الجزاء في الكهف أعلى جنسًا وكثرة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص213.","url":""}]},{"id":"s18-257","number":257,"surah":18,"verses":[36],"references":[{"surah":18,"verses":[36]}],"verseLabel":"الكهف: 36","question":"ما سر قوله: ﴿وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّي﴾، وفي فصلت: ﴿وَلَئِن رُّجِعْتُ إِلَىٰ رَبِّي﴾؟","answer":"آية الكهف في حوار بين مؤمن وكافر مشرك بعيد عن حال الإيمان، ولفظ «رُدِدتُ» يحتمل معنى القهر والتعنيف والكراهة ما لا يحتمله «رُجِعتُ»، أما آية فصلت ففي الإنسان عمومًا وهي صالحة للمؤمن والكافر. وهذا التوجيه منقول عن «ملاك التأويل»، وفي «البرهان» للكرماني أن الردّ يتضمن كراهة المردود.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص50–52.","url":""}]},{"id":"s18-258","number":258,"surah":18,"verses":[43],"references":[{"surah":18,"verses":[43]}],"verseLabel":"الكهف: 43","question":"ما سر قوله: ﴿يَنصُرُونَهُ مِن دُونِ اللَّهِ﴾، وفي الملك: ﴿يَنصُرُكُم مِّن دُونِ الرَّحْمَٰنِ﴾؟","answer":"سياق سورة الملك في ذكر النعم التي أنعم الله بها على الناس فناسب ذكر الرحمن، أما السياق في الكهف والقصص ففي العقوبات لا في النعم والرحمة، فناسب ذكر اسم الجلالة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص107–108.","url":""}]},{"id":"s18-259","number":259,"surah":18,"verses":[48],"references":[{"surah":18,"verses":[48]}],"verseLabel":"الكهف: 48","question":"ما سر خلوّ قوله: ﴿لَّقَدْ جِئْتُمُونَا كَمَا خَلَقْنَاكُمْ أَوَّلَ مَرَّةٍ﴾ من «فُرادى» ومن ترك المخوَّل وراء الظهور، وقد ذُكرا في الأنعام؟","answer":"آية الأنعام فيما يحصل عند الموت في الدنيا، والناس يموتون فرادى ويتركون المال للورثة. أما آية الكهف ففي الآخرة حين يُجمع الناس كلهم للحساب: ﴿وَعُرِضُوا عَلَىٰ رَبِّكَ صَفًّا﴾، ولم يبقَ شيء مما كان في الأرض لأنها تُحمل وتُنسف، فلم يناسب ذكر ذلك.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص48–49.","url":""}]},{"id":"s18-260","number":260,"surah":18,"verses":[54],"references":[{"surah":18,"verses":[54]}],"verseLabel":"الكهف: 54","question":"ما سر تأخير «للناس» في قوله: ﴿وَلَقَدْ صَرَّفْنَا فِي هَٰذَا الْقُرْآنِ لِلنَّاسِ﴾، وما سر الختم بقوله: ﴿وَكَانَ الْإِنسَانُ أَكْثَرَ شَيْءٍ جَدَلًا﴾؟","answer":"بُدئت سورة الكهف بالكلام على الكتاب: ﴿الْحَمْدُ لِلَّهِ الَّذِي أَنزَلَ عَلَىٰ عَبْدِهِ الْكِتَابَ﴾ فقدّم القرآن، وبُدئت الإسراء بالكلام على الناس فقدّمهم. وختم بالجدل لما ذُكر قبلها وبعدها من المحاورات، كحوار صاحب الجنتين، ومحاورة موسى والرجل الصالح، ولم يرد لفظ الجدل ولا المحاورة في الإسراء كلها.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص70–71.","url":""}]},{"id":"s18-261","number":261,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"ما سر الفاء في قوله: ﴿مِمَّن ذُكِّرَ بِآيَاتِ رَبِّهِ فَأَعْرَضَ عَنْهَا﴾، وفي السجدة: ﴿ثُمَّ أَعْرَضَ عَنْهَا﴾؟","answer":"الإعراض في الكهف واقع عقب التذكير مباشرة، يدل على ذلك ما بعده: ﴿وَنَسِيَ مَا قَدَّمَتْ يَدَاهُ... إِنَّا جَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً﴾ وذكر أنهم لن يهتدوا أبدًا، فناسبت الفاء الدالة على الترتيب والتعقيب. وليس الأمر كذلك في السجدة فجاءت «ثم» الدالة على التراخي.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص203.","url":""}]},{"id":"s18-262","number":262,"surah":18,"verses":[79],"references":[{"surah":18,"verses":[79]}],"verseLabel":"الكهف: 79","question":"ما دلالة لفظ «السفينة» في قوله: ﴿أَمَّا السَّفِينَةُ فَكَانَتْ لِمَسَاكِينَ﴾ دون «الفُلك»؟","answer":"لم يستعمل القرآن «السفينة» إلا في مركب خاصّ مملوك أو معيّن، كسفينة نوح وسفينة المساكين في الكهف، ومنه قوله: ﴿يَأْخُذُ كُلَّ سَفِينَةٍ غَصْبًا﴾ أي من مالكها. أما «الفلك» فقد تكون خاصة، وقد تكون مطلقة تصلح لجميع الأزمنة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص138.","url":""}]},{"id":"s18-263","number":263,"surah":18,"verses":[79,82],"references":[{"surah":18,"verses":[79,82]}],"verseLabel":"الكهف: 79، 82","question":"ما سر تنوّع الإسناد في قوله: ﴿فَأَرَدتُّ أَنْ أَعِيبَهَا﴾ ثم ﴿فَأَرَدْنَا أَن يُبْدِلَهُمَا﴾ ثم ﴿فَأَرَادَ رَبُّكَ﴾؟","answer":"نسب العَيب إلى نفسه تنزيهًا لله عنه. وفي قتل الغلام جاء بالضمير المشترك لأن العمل مشترك؛ فيه قتل هو في الظاهر سوء، وإبدال خير منه أسنده إلى الله وحده. وأسند إرادة ما في إقامة الجدار من بلوغ اليتيمين أشدّهما إلى الرب سبحانه. وانظر «بدائع الفوائد».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص321.","url":""}]},{"id":"s18-264","number":264,"surah":18,"verses":[103,104],"references":[{"surah":18,"verses":[103,104]}],"verseLabel":"الكهف: 103–104","question":"ما سر التمييز في قوله: ﴿بِالْأَخْسَرِينَ أَعْمَالًا﴾، والاكتفاء في النمل بقوله: ﴿هُمُ الْأَخْسَرُونَ﴾؟","answer":"تردّد ذكر العمل في سياق الكهف في أكثر من موضع: ﴿ضَلَّ سَعْيُهُمْ﴾، ﴿يُحْسِنُونَ صُنْعًا﴾، ﴿فَحَبِطَتْ أَعْمَالُهُمْ﴾، ﴿وَعَمِلُوا الصَّالِحَاتِ﴾، فناسب ذكر الأعمال. ولم يرد في سياق النمل إلا قوله: ﴿زَيَّنَّا لَهُمْ أَعْمَالَهُمْ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص173.","url":""}]},{"id":"s18-265","number":265,"surah":18,"verses":[110],"references":[{"surah":18,"verses":[110]}],"verseLabel":"الكهف: 110","question":"ما سر ذكر الموصوف في قوله: ﴿فَلْيَعْمَلْ عَمَلًا صَالِحًا﴾، والغالب في القرآن: ﴿وَعَمِلَ صَالِحًا﴾؟","answer":"لم يُذكر الموصوف «عملًا» إلا في موضعين: هذه الآية وآية الفرقان، وهما في سياق ذكر الأعمال، بخلاف ما حُذف فيه الموصوف فإنه ليس في سياق الأعمال. وقد تردّد ذكر العمل في خواتيم الكهف كما مرّ في السؤال السابق.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص100.","url":""}]},{"id":"s19-1","number":1,"surah":19,"verses":[1],"references":[{"surah":19,"verses":[1]}],"verseLabel":"مريم: 1","question":"ما دلالة افتتاح السورة بالحروف ﴿كهيعص﴾؟","answer":"يذكر المصدر أقوالًا في الحروف المقطعة، منها تفويض علم حقيقتها إلى الله، ويرجح هنا أنها حروف تنبّه إلى إعجاز القرآن المؤلف من جنس حروف العرب. فلا يجزم بمعنى تفصيلي لكل حرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص704–705، تحت عنوان «بيان المراد بالحروف المقطعة»","url":""}]},{"id":"s19-2","number":2,"surah":19,"verses":[2],"references":[{"surah":19,"verses":[2]}],"verseLabel":"مريم: 2","question":"لماذا استُهلت قصة زكريا بقوله ﴿ذِكْرُ رَحْمَتِ رَبِّكَ﴾؟","answer":"ليستحضر السامع رحمة الله السابقة وكرامته لأوليائه قبل سرد تفاصيل القصص؛ فجاء الافتتاح مهيئًا لتلقي القصة بوصفها أثرًا من آثار رحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص706–707، تحت عنوان «حسن الافتتاح بقوله: ﴿ذِكْرُ﴾»","url":""}]},{"id":"s19-120","number":120,"surah":19,"verses":[2],"references":[{"surah":19,"verses":[2]}],"verseLabel":"مريم: 2","question":"لماذا قيل ﴿رَحْمَتِ رَبِّكَ﴾ في قصة زكريا مع أن الخطاب للنبي ﷺ؟","answer":"في إضافة الرب إلى ضمير النبي ﷺ تنويه بشأنه؛ فالربوبية تتضمن التربية والتكميل، وتنزيل هذه السورة عليه من آثار هذه العناية به، فشمل التكريم متلقي القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص708–709، تحت عنوان «نكتة إضافة الربوبية إلى ضمير الخطاب»","url":""}]},{"id":"s19-121","number":121,"surah":19,"verses":[2],"references":[{"surah":19,"verses":[2]}],"verseLabel":"مريم: 2","question":"لماذا وصف زكريا بالعبودية في قوله ﴿عَبْدَهُ زَكَرِيَّا﴾؟","answer":"تنويهًا بشأنه وتعظيمًا لحاله؛ فالعبودية لله غاية الشرف والكرامة، وفي الوصف إشارة إلى أنها سبيل نيل الهبات والرحمات.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص709، تحت عنوان «سر التعبير بالعبودية»","url":""}]},{"id":"s19-3","number":3,"surah":19,"verses":[3],"references":[{"surah":19,"verses":[3]}],"verseLabel":"مريم: 3","question":"ما دلالة الجمع بين النداء والخفاء في دعاء زكريا؟","answer":"يذكر المصدر أن النداء كناية عن شدة الاحتياج، وأن وصفه بالخفاء يدفع توهم رفع الصوت؛ وهذا أوضح الأوجه عنده. ويذكر وجهًا آخر يجعل الخفاء دالًا على الإخلاص، أما الإخلاص على الوجه الأول فيُفهم من حال زكريا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص713، تحت عنوان «بلاغة الجمع بين النداء والخفاء»","url":""}]},{"id":"s19-4","number":4,"surah":19,"verses":[4],"references":[{"surah":19,"verses":[4]}],"verseLabel":"مريم: 4","question":"ما سرّ التعبير بـ﴿وَهَنَ الْعَظْمُ مِنِّي﴾ لا «ضعف جسمي»؟","answer":"العظم قوام البدن؛ فإذا دب الوهن في أصله دل على بلوغ الضعف غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص722–723، تحت عنوان «بلاغة إسناد الوهن إلى العظم بين الكناية والمجاز»","url":""}]},{"id":"s19-5","number":5,"surah":19,"verses":[4],"references":[{"surah":19,"verses":[4]}],"verseLabel":"مريم: 4","question":"ما سر صورة ﴿وَاشْتَعَلَ الرَّأْسُ شَيْبًا﴾؟","answer":"شبّه انتشار الشيب باشتعال النار، فصور سرعة عمومه وسطوعه في الرأس كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص725–726، تحت عنوان «براعة الاستعارة وقوتها»","url":""}]},{"id":"s19-6","number":6,"surah":19,"verses":[4],"references":[{"surah":19,"verses":[4]}],"verseLabel":"مريم: 4","question":"ما سرّ التعبير بـ﴿وَلَمْ أَكُنْ بِدُعَائِكَ رَبِّ شَقِيًّا﴾؟","answer":"توسل بسابق لطف الله؛ فلم تكن دعواته الماضية سبب خيبة، فرجا استمرار العناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص728، تحت عنوان «غرض الإخبار بما كان»","url":""}]},{"id":"s19-7","number":7,"surah":19,"verses":[5],"references":[{"surah":19,"verses":[5]}],"verseLabel":"مريم: 5","question":"ما سرّ التعبير بـ﴿خِفْتُ الْمَوَالِيَ مِنْ وَرَائِي﴾؟","answer":"خاف ممن يلون أمر قومه بعده أن يضيعوا الدين، لا مجرد فقد وارث لماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص731–732، تحت عنوان «نكتة استعمال مفردة الخوف»","url":""}]},{"id":"s19-8","number":8,"surah":19,"verses":[5],"references":[{"surah":19,"verses":[5]}],"verseLabel":"مريم: 5","question":"لماذا قال زكريا ﴿وَكَانَتِ امْرَأَتِي عَاقِرًا﴾ بصيغة الماضي؟","answer":"للدلالة على أن العقر قديم فيها، وأنها لم تلد منذ زمن؛ ففيه بيان استبعاد حصول الولد بحسب الأسباب العادية، وزيادة الاستعطاف في الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص733–734، تحت عنوان «دلالة التعبير بصيغة الماضي في فعل الكون»","url":""}]},{"id":"s19-122","number":122,"surah":19,"verses":[5],"references":[{"surah":19,"verses":[5]}],"verseLabel":"مريم: 5","question":"ماذا تضيف صيغة اسم الفاعل ﴿عَاقِرًا﴾ إلى وصف امرأة زكريا؟","answer":"تدل، في هذا السياق، على تمكن صفة العقر منها وثبوتها واستمرارها؛ ويؤكد هذا الرسوخ التعبير بالماضي في ﴿كانت﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص760، تحت عنوان «دلالة التعبير بصيغة اسم الفاعل»","url":""}]},{"id":"s19-9","number":9,"surah":19,"verses":[5],"references":[{"surah":19,"verses":[5]}],"verseLabel":"مريم: 5","question":"ما سر طلب زكريا ﴿وَلِيًّا﴾ في هذا المقام؟","answer":"لأنه طلب من يلي أمر الدين ويحفظ الدعوة، لا ولدًا لمجرد الأنس والنسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص736، تحت عنوان «سر التعبير بقوله: ﴿وَلِيًّا﴾»","url":""}]},{"id":"s19-10","number":10,"surah":19,"verses":[6],"references":[{"surah":19,"verses":[6]}],"verseLabel":"مريم: 6","question":"لماذا عُبّر بالإرث في دعاء زكريا ﴿يَرِثُنِي وَيَرِثُ مِنْ آلِ يَعْقُوبَ﴾؟","answer":"يرجح المصدر أن المراد وراثة العلم والدين؛ فاستعير الإرث، الذي أصله انتقال المال، لانتقال هذا الخير المعنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص738، تحت عنوان «بلاغة الاستعارة في مفردة الإرث»","url":""}]},{"id":"s19-123","number":123,"surah":19,"verses":[6],"references":[{"surah":19,"verses":[6]}],"verseLabel":"مريم: 6","question":"لماذا تكرر فعل الإرث في ﴿يَرِثُنِي وَيَرِثُ مِنْ آلِ يَعْقُوبَ﴾؟","answer":"لزيادة العناية بالإرث من آل يعقوب وجعله مقصودًا مستقلًا، بدل الاكتفاء بعطفهم على زكريا تحت فعل واحد؛ وفي ذلك مبالغة في طلب الوارث الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص739، تحت عنوان «نكتة تكرار فعل الإرث»","url":""}]},{"id":"s19-11","number":11,"surah":19,"verses":[6],"references":[{"surah":19,"verses":[6]}],"verseLabel":"مريم: 6","question":"ما سرّ التعبير بـ﴿وَاجْعَلْهُ رَبِّ رَضِيًّا﴾؟","answer":"لم يكتف بوجود الوارث، بل سأل صلاحه وقبول الله له؛ فالذرية نعمة بصلاحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص741، تحت عنوان «نوع الواو ودلالتها في قوله تعالى: ﴿وَاجْعَلْهُ﴾»","url":""}]},{"id":"s19-12","number":12,"surah":19,"verses":[7],"references":[{"surah":19,"verses":[7]}],"verseLabel":"مريم: 7","question":"ما سرّ التعبير بـ﴿لَمْ نَجْعَلْ لَهُ مِنْ قَبْلُ سَمِيًّا﴾؟","answer":"من وجوه التكريم أن الله اختار له اسم يحيى، ولم يسبق أن سُمّي به أحد على ظاهر هذا التوجيه. وفي الاسم المبتكر تشريف للمولود وإكرام لأبيه زكريا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص752–753، تحت عنوان «فائدة اختصاص يحيى بهذا الاسم»","url":""}]},{"id":"s19-13","number":13,"surah":19,"verses":[8],"references":[{"surah":19,"verses":[8]}],"verseLabel":"مريم: 8","question":"ما دلالة سؤال زكريا عن حصول الولد بعد أن بُشّر به؟","answer":"لم يشك في القدرة، وإنما سأل عن كيفية تحقق البشرى مع اجتماع الشيخوخة والعقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص757–758، تحت عنوان «غرض الاستفهام»","url":""}]},{"id":"s19-14","number":14,"surah":19,"verses":[8],"references":[{"surah":19,"verses":[8]}],"verseLabel":"مريم: 8","question":"ما دلالة وصف زكريا حاله بأنه بلغ من الكبر ﴿عِتِيًّا﴾؟","answer":"شُبهت عظام زكريا بالأعواد اليابسة، وأثبت لها العتي، وهو اليبس؛ فتصور الاستعارة ما بلغته شيخوخته من شدة الضعف.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص764، تحت عنوان «بلاغة الاستعارة في: ﴿عِتِيًّا﴾»","url":""}]},{"id":"s19-15","number":15,"surah":19,"verses":[9],"references":[{"surah":19,"verses":[9]}],"verseLabel":"مريم: 9","question":"كيف يفيد قوله ﴿هُوَ عَلَيَّ هَيِّنٌ﴾ كمال القدرة؟","answer":"الهين في الاستعمال المعتاد ما لا يعجز فاعله؛ فأُطلق هنا للدلالة على كمال قدرة الله، وأن خلق يحيى مع عقر أمه وكبر أبيه لا يعجزه ولا يدعو إلى استبعاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص772، تحت عنوان «بلاغة المجاز في مفردة: ﴿هَيِّنٌ﴾»","url":""}]},{"id":"s19-124","number":124,"surah":19,"verses":[9],"references":[{"surah":19,"verses":[9]}],"verseLabel":"مريم: 9","question":"لماذا ذُكّر زكريا بخلقه هو في ﴿وَقَدْ خَلَقْتُكَ مِنْ قَبْلُ﴾ بدل ذكر خلق آدم؟","answer":"لأن عدم زكريا ووجوده أظهر عنده وأجلى، فكان الاحتجاج بما يعرفه من أصل نفسه أقوى في بيان إمكان ما بُشر به؛ وخلقه داخل في الخلق الذي بدأه الله من العدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص773–774، تحت عنوان «توجيه نسبة الخلق من العدم إلى زكريا لا إلى آدم»","url":""}]},{"id":"s19-16","number":16,"surah":19,"verses":[10],"references":[{"surah":19,"verses":[10]}],"verseLabel":"مريم: 10","question":"ما دلالة انحباس كلام زكريا مع وصفه بأنه ﴿سَوِيًّا﴾؟","answer":"انحباس الكلام مع سلامة الجسد علامة خارقة لا تُفسر بمرض أو عجز طبيعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص781، تحت عنوان «بلاغة الاحتراس والتأكيد في تعدد أوجه الإعراب»","url":""}]},{"id":"s19-17","number":17,"surah":19,"verses":[11],"references":[{"surah":19,"verses":[11]}],"verseLabel":"مريم: 11","question":"ماذا أفادت الفاء في ﴿فَخَرَجَ عَلَى قَوْمِهِ مِنَ الْمِحْرَابِ﴾؟","answer":"دلّت على خروجه عقب تحقق الآية التي أُعطيها، وهي ألا يكلم الناس ثلاث ليال سويًا؛ فهي فاء فصيحة تتضمن التعقيب، ثم خرج إلى قومه ليطلب منهم التسبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص788، تحت عنوان «نوع الفاء ودلالتها»","url":""}]},{"id":"s19-18","number":18,"surah":19,"verses":[11],"references":[{"surah":19,"verses":[11]}],"verseLabel":"مريم: 11","question":"ما سرّ التعبير بـ﴿فَأَوْحَى إِلَيْهِمْ﴾ مع أنه لم يتكلم؟","answer":"الوحي هنا إبلاغ بغير الكلام المعتاد، ففسره المصدر بالإشارة، وذكر الكتابة وجهًا آخر. وهو يناسب حال زكريا حين امتنع عليه كلام الناس، فأفهمهم طلب التسبيح بهذه الوسيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص790، تحت عنوان «سر اختيار مفردة الوحي»","url":""}]},{"id":"s19-19","number":19,"surah":19,"verses":[12],"references":[{"surah":19,"verses":[12]}],"verseLabel":"مريم: 12","question":"ما دلالة الأمر ليحيى: ﴿خُذِ الْكِتَابَ بِقُوَّةٍ﴾؟","answer":"القوة جدّ في الفهم والعمل والحفظ، لا مجرد حمل الكتاب أو قراءته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص797، تحت عنوان «دلالة التعبير بشبه الجملة: ﴿بِقُوَّةٍ﴾»","url":""}]},{"id":"s19-20","number":20,"surah":19,"verses":[12],"references":[{"surah":19,"verses":[12]}],"verseLabel":"مريم: 12","question":"ما المراد بـ﴿الْحُكْمَ﴾ في قوله ﴿وَآتَيْنَاهُ الْحُكْمَ﴾؟","answer":"يذكر المصدر أن الحكم أوسع من الحكمة؛ إذ يطلق على الحكمة والنبوة والأحكام والمعرفة بها. ومن تفسيره هنا أن الله أحكم عقل يحيى في صباه وأوحى إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص799، تحت عنوان «سر التعبير بـ: ﴿الْحُكْمَ﴾»","url":""}]},{"id":"s19-125","number":125,"surah":19,"verses":[12],"references":[{"surah":19,"verses":[12]}],"verseLabel":"مريم: 12","question":"لماذا قُيّد إيتاء يحيى الحكم بقوله ﴿صَبِيًّا﴾؟","answer":"لإبراز تعجيل إكرامه؛ فقد آتاه الله استقامة الفكر وقوة إدراك الحقائق في عمر مبكر على غير المعتاد. واختيار ﴿صبيًّا﴾ يحمل في هذا السياق معنى المدح الذي قد لا يؤديه لفظ «صغيرًا».","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص800، تحت عنوان «دلالة التعبير بـ: ﴿صَبِيًّا﴾»","url":""}]},{"id":"s19-21","number":21,"surah":19,"verses":[13],"references":[{"surah":19,"verses":[13]}],"verseLabel":"مريم: 13","question":"ما سرّ اختيار لفظ ﴿حَنَانًا﴾ لا «رحمة» فقط؟","answer":"الحنان رحمة مشوبة بعطف ورقة وإقبال، فناسب قلب النبي البار.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص12، تحت عنوان «سر التعبير بـ: ﴿وَحَنَانًا﴾»","url":""}]},{"id":"s19-22","number":22,"surah":19,"verses":[13],"references":[{"surah":19,"verses":[13]}],"verseLabel":"مريم: 13","question":"ماذا تضيف ﴿مِنْ لَدُنَّا﴾ إلى الحنان الذي أوتيه يحيى؟","answer":"تعظم هذا الحنان بنسبته إلى الله؛ فـ«لدن» تفيد صدوره من عنده وإمداده به، وهي أبلغ وأخص من «عندنا»، وتدل على حنان زائد على المعتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص12–13، تحت عنوان «سر التعبير بـ: ﴿مِنْ لَدُنَّا﴾»","url":""}]},{"id":"s19-126","number":126,"surah":19,"verses":[13],"references":[{"surah":19,"verses":[13]}],"verseLabel":"مريم: 13","question":"ماذا تضيف ﴿زَكَاةً﴾ في وصف يحيى إلى مجرد الطهارة؟","answer":"الزكاة تجمع طهارة النفس وتنميتها بالخيرات والبركات؛ فليست مجرد تنقية من الدنس، بل تنقية مقرونة بالنماء في الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص15، تحت عنوان «الزكاة والطهارة»","url":""}]},{"id":"s19-23","number":23,"surah":19,"verses":[14],"references":[{"surah":19,"verses":[14]}],"verseLabel":"مريم: 14","question":"لماذا نُفي عن يحيى ﴿عَصِيًّا﴾، وعن عيسى ﴿شَقِيًّا﴾؟","answer":"خبر يحيى ثناء من الله عليه، فناسبه نفي المعصية. أما عيسى فيتحدث عن نفسه، فكان نفي الشقاء أدبًا عن تزكية النفس بنفي المعصية، وهو ملائم كذلك لنفي عقوق أمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص21، تحت عنوان «سر اختلاف التعبير: ﴿عَصِيًّا﴾، و﴿شَقِيًّا﴾»","url":""}]},{"id":"s19-127","number":127,"surah":19,"verses":[14],"references":[{"surah":19,"verses":[14]}],"verseLabel":"مريم: 14","question":"لماذا قيل في يحيى ﴿وَلَمْ يَكُنْ﴾، وفي كلام عيسى ﴿وَلَمْ يَجْعَلْنِي﴾؟","answer":"جاء نفي الصفة موافقًا لإثبات الصفات في كل سياق: سبق في يحيى ﴿وَكَانَ تَقِيًّا﴾ فناسبه ﴿وَلَمْ يَكُنْ﴾، وسبق في كلام عيسى ﴿وَجَعَلَنِي نَبِيًّا﴾ فناسبه ﴿وَلَمْ يَجْعَلْنِي﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص21–22، تحت عنوان «التشابه اللفظي»","url":""}]},{"id":"s19-24","number":24,"surah":19,"verses":[15],"references":[{"surah":19,"verses":[15]}],"verseLabel":"مريم: 15","question":"ما دلالة تخصيص الولادة والموت والبعث بالسلام على يحيى؟","answer":"هذه أشد مواطن الوحشة والانتقال، فخصه الله بالأمان فيها كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص31، تحت عنوان «دلالة تخصيص هذه الأوقات بالسلام»","url":""}]},{"id":"s19-25","number":25,"surah":19,"verses":[15,33],"references":[{"surah":19,"verses":[15,33]}],"verseLabel":"مريم: 15، 33","question":"ما سرّ تنكير السلام في يحيى ﴿وَسَلَامٌ عَلَيْهِ﴾ وتعريفه في عيسى ﴿وَالسَّلَامُ عَلَيَّ﴾؟","answer":"نُكّر السلام على يحيى لتفخيمه وتعظيمه، فهو سلام من الله يحفّه في أطوار حياته. ويقابل المصدر ذلك بالسلام المعرّف الوارد على لسان عيسى، مع التنبيه إلى اختلاف جهة صدور الكلام في الموضعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص27، تحت عنوان «دلالة التنكير في: ﴿وَسَلَامٌ﴾»","url":""}]},{"id":"s19-26","number":26,"surah":19,"verses":[16],"references":[{"surah":19,"verses":[16]}],"verseLabel":"مريم: 16","question":"لماذا افتُتحت قصة مريم بالأمر ﴿وَاذْكُرْ﴾؟","answer":"لزيادة الاهتمام بشأن القصة وتشويق السامع إلى تدبرها؛ ففيها دلائل تبين قدرة الله على الخلق وتدعو إلى تأمل ولادة عيسى على غير الأسباب المألوفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص37، تحت عنوان «دلالة افتتاح القصة بفعل الذكر»","url":""}]},{"id":"s19-128","number":128,"surah":19,"verses":[16],"references":[{"surah":19,"verses":[16]}],"verseLabel":"مريم: 16","question":"ماذا أفاد تقييد ذكر مريم بقوله ﴿فِي الْكِتَابِ﴾؟","answer":"نبه إلى أن قصتها مذكورة في القرآن الكريم في مواضع متعددة؛ والمراد تلاوة خبرها القرآني المحفوظ، لا مجرد الحديث عنها في كلام آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص37، تحت عنوان «دلالة التعبير بشبه الجملة: ﴿فِي الْكِتَابِ﴾»","url":""}]},{"id":"s19-129","number":129,"surah":19,"verses":[16],"references":[{"surah":19,"verses":[16]}],"verseLabel":"مريم: 16","question":"لماذا قال ﴿وَاذْكُرْ فِي الْكِتَابِ مَرْيَمَ﴾، والمقصود ذكر قصتها؟","answer":"حُذف المضاف إيجازًا لظهور المراد؛ فالتقدير ذكر نبأ مريم أو قصتها، لأن المقصود تذكير السامع بشأنها وما وقع لها، لا ذكر ذاتها مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص38، تحت عنوان «بلاغة حذف المضاف في قوله: ﴿مَرْيَمَ﴾»","url":""}]},{"id":"s19-27","number":27,"surah":19,"verses":[16],"references":[{"surah":19,"verses":[16]}],"verseLabel":"مريم: 16","question":"ما دلالة وصف مكان اعتزال مريم بأنه ﴿شَرْقِيًّا﴾؟","answer":"يحدد الوصف جهة خلوتها، ويذكر المصدر مناسبة المشرق لطلوع الأنوار وإشارة ذلك إلى الروح الآتي إليها، وفيه بشارة وتمهيد لميلاد عيسى؛ فهو وجه بياني يذكره المصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص41، تحت عنوان «دلالة وصف المكان بالشرقي»","url":""}]},{"id":"s19-130","number":130,"surah":19,"verses":[16],"references":[{"surah":19,"verses":[16]}],"verseLabel":"مريم: 16","question":"لماذا عُبّر عن اعتزال مريم أهلها بلفظ ﴿انْتَبَذَتْ﴾؟","answer":"الانتباذ يتضمن معنى الطرح والبعد؛ فيصور أنها تنحت عن مخالطة أهلها طلبًا للخلوة والانصراف إلى العبادة، فهو أبلغ في تصوير اعتزالها من مجرد ذكر البعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص39، تحت عنوان «سر التعبير بالانتباذ»","url":""}]},{"id":"s19-28","number":28,"surah":19,"verses":[17],"references":[{"surah":19,"verses":[17]}],"verseLabel":"مريم: 17","question":"ما سرّ التعبير بـ﴿فَاتَّخَذَتْ مِنْ دُونِهِمْ حِجَابًا﴾؟","answer":"دلّ الاتخاذ على اجتهادها في إحكام خلوتها؛ فلم تكتف بالاعتزال، بل نصبت حجابًا تستتر به. ويذكر المصدر أن هذه العزلة هيأتها لتلقي أمر ربها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص44–45، تحت عنوان «دلالة التعبير بالاتخاذ في قوله: ﴿فَاتَّخَذَتْ﴾»","url":""}]},{"id":"s19-29","number":29,"surah":19,"verses":[17],"references":[{"surah":19,"verses":[17]}],"verseLabel":"مريم: 17","question":"ما دلالة تمثل الروح لمريم ﴿بَشَرًا سَوِيًّا﴾؟","answer":"وُصف باعتدال الخلق وحسن الهيئة لتألفه العين وتتمكن مريم من سماع كلامه؛ فلو ظهر بصورته الملائكية لنفرت ولم تقدر على استماع رسالته. وفي هذا الظهور ابتلاء أظهر ورعها وعفافها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص50، تحت عنوان «دلالة وصفه بكونه: ﴿سَوِيًّا﴾»","url":""}]},{"id":"s19-30","number":30,"surah":19,"verses":[18],"references":[{"surah":19,"verses":[18]}],"verseLabel":"مريم: 18","question":"لماذا استعاذت مريم باسم ﴿الرَّحْمَنِ﴾ في مقام الخوف؟","answer":"استحضرت ما عهدته من رحمة الله وعطفه، واستجلبت آثار هذه الرحمة في دفع ما خافته؛ فاسم الرحمن يلائم رجاء الحماية واللطف.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص53–54، تحت عنوان «سر استعاذتها بصفة الرحمن»","url":""}]},{"id":"s19-131","number":131,"surah":19,"verses":[18],"references":[{"surah":19,"verses":[18]}],"verseLabel":"مريم: 18","question":"ما دلالة قول مريم ﴿إِنْ كُنْتَ تَقِيًّا﴾ لمن ظهر في خلوتها؟","answer":"استثارت تقواه وذكرته بالله؛ فمن كان يتقي الله كان له وازع يمنعه من التعرض لها. فالعبارة تستدعي الخشية في مقام احتماء المستجير.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص55، تحت عنوان «سر تخصيص الاستعاذة بالتقوى»","url":""}]},{"id":"s19-31","number":31,"surah":19,"verses":[19],"references":[{"surah":19,"verses":[19]}],"verseLabel":"مريم: 19","question":"ما سرّ وصف الغلام بـ﴿زَكِيًّا﴾؟","answer":"ليطمئنها أن الولد طاهر النفس مبارك، لا وصمة فيه رغم غرابة مولده.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص62، تحت «سر الوصف بقوله زكيًّا»","url":""}]},{"id":"s19-32","number":32,"surah":19,"verses":[20],"references":[{"surah":19,"verses":[20]}],"verseLabel":"مريم: 20","question":"ما دلالة قولها: ﴿وَلَمْ أَكُ بَغِيًّا﴾ بعد نفي مساس البشر؟","answer":"نفت الطريقين: الزواج المشروع والفاحشة، فاستحال الحمل بحسب الأسباب المعتادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص69، تحت عنوان «دلالة الواو في: ﴿وَلَمْ أَكُ بَغِيًّا﴾»","url":""}]},{"id":"s19-33","number":33,"surah":19,"verses":[21],"references":[{"surah":19,"verses":[21]}],"verseLabel":"مريم: 21","question":"لماذا وُصف عيسى بأنه ﴿آيَةً لِلنَّاسِ﴾؟","answer":"لأن خلقه من غير أب علامة على كمال قدرة الله على الخلق والبعث؛ فمن قدر على إيجاده بهذه الكيفية قدر على إحياء الموتى.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص80، تحت عنوان «دلالة التعبير بـ: ﴿آيَةً﴾»","url":""}]},{"id":"s19-132","number":132,"surah":19,"verses":[21],"references":[{"surah":19,"verses":[21]}],"verseLabel":"مريم: 21","question":"لماذا وُصف عيسى بأنه ﴿رَحْمَةً مِنَّا﴾؟","answer":"جعله الله رحمة للعباد بما يهتدون به من إرشاده؛ فهو هاد إلى الحق ودليل عليه، ومن اقتدى به واتبعه كان ذلك نجاة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص81، تحت عنوان «دلالة وصف عيسى بالرحمة»","url":""}]},{"id":"s19-34","number":34,"surah":19,"verses":[21],"references":[{"surah":19,"verses":[21]}],"verseLabel":"مريم: 21","question":"ما دلالة ختام البشارة بـ﴿وَكَانَ أَمْرًا مَقْضِيًّا﴾؟","answer":"جاءت الجملة مستأنفة لقطع المحاورة بعد بيان الغرض من خلق عيسى؛ فقد قُدّر الأمر وحُتم، فلا بد من وقوعه، مهما بدا مستبعدًا بحسب الأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص82، تحت عنوان «دلالة الواو في: ﴿وَكَانَ أَمْرًا مَقْضِيًّا﴾»","url":""}]},{"id":"s19-35","number":35,"surah":19,"verses":[22],"references":[{"surah":19,"verses":[22]}],"verseLabel":"مريم: 22","question":"ما دلالة تصوير انفراد مريم بحملها بقوله ﴿فَانْتَبَذَتْ بِهِ مَكَانًا قَصِيًّا﴾؟","answer":"الانتباذ بعدٌ مع انفراد؛ فقد تنحت إلى ناحية بعيدة عن أهلها اتقاء ما يعرضها له الحمل من القيل والقال. وفي اعتزالها وهي حامل تحتاج إلى المعونة تصوير لشدة معاناتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص86–87، تحت عنوان «سر التعبير بالانتباذ في: ﴿فَانْتَبَذَتْ﴾»","url":""}]},{"id":"s19-36","number":36,"surah":19,"verses":[23],"references":[{"surah":19,"verses":[23]}],"verseLabel":"مريم: 23","question":"ما دلالة ذكر ﴿جِذْعِ النَّخْلَةِ﴾ في مشهد المخاض؟","answer":"ألجأها المخاض إلى جذع النخلة لتستند إليه عند شدة الولادة، ثم خُص الجذع تمهيدًا للكرامة التي ظهرت بتساقط الرطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص94، تحت عنوان «سر تخصيص جذع النخلة»","url":""}]},{"id":"s19-37","number":37,"surah":19,"verses":[23],"references":[{"surah":19,"verses":[23]}],"verseLabel":"مريم: 23","question":"لماذا تمنت مريم الموت مع سبق بشارتها بالغلام الزكي؟","answer":"يذكر المصدر أنها استحيت من الناس وخافت اتهامهم، أو خافت وقوعهم في المعصية بما يقولونه عنها؛ فاشتداد الأمر وخوف التهمة هما باعث التمني المذكور في هذا التوجيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص96–97، تحت عنوان «سر تمني مريم الموت بعد بشارة جبريل لها»","url":""}]},{"id":"s19-133","number":133,"surah":19,"verses":[23],"references":[{"surah":19,"verses":[23]}],"verseLabel":"مريم: 23","question":"ماذا أضاف وصف ﴿مَنْسِيًّا﴾ بعد قول مريم ﴿نَسْيًا﴾؟","answer":"زاد في تصوير زوال الذكر؛ فالنسي ما شأنه أن ينسى، ثم وصفته بأنه منسي بالفعل، فكأنها تمنت ألا يبقى لها ذكر بين أهلها من شدة ما ألم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص97، تحت عنوان «دلالة الوصف بـ: ﴿مَنْسِيًّا﴾»","url":""}]},{"id":"s19-38","number":38,"surah":19,"verses":[24],"references":[{"surah":19,"verses":[24]}],"verseLabel":"مريم: 24","question":"كيف تتصل عبارة ﴿مِنْ تَحْتِهَا﴾ بالخلاف فيمن نادى مريم؟","answer":"في قراءة كسر الميم تكون «مِن» حرف جر يحدد جهة النداء، ويُذكر للمنادي عيسى أو جبريل. وفي قراءة فتحها تكون «مَن» اسمًا لمن حصل تحتها، ويفسره المصدر بعيسى؛ فلا يلزم من كل وجه تعيين المنادي أو حمل العبارة وحدها على انفصال المولود.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص100، تحت عنوان «دلالة تعدد القراءات في: ﴿مِنْ تَحْتِهَا﴾»","url":""}]},{"id":"s19-134","number":134,"surah":19,"verses":[24],"references":[{"surah":19,"verses":[24]}],"verseLabel":"مريم: 24","question":"ماذا أفادت الفاء في ﴿فَنَادَاهَا﴾ عقب تمني مريم الموت؟","answer":"رتبت النداء على ما قالته، وأفادت مجيء التطمين على الفور بعد حزنها؛ فبادرها النداء بالتسلية وتطييب القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص99، تحت عنوان «دلالة الفاء في: ﴿فَنَادَاهَا﴾»","url":""}]},{"id":"s19-39","number":39,"surah":19,"verses":[24],"references":[{"surah":19,"verses":[24]}],"verseLabel":"مريم: 24","question":"ما المراد بـ﴿سَرِيًّا﴾ ولماذا اختير؟","answer":"السري قيل: جدول الماء الجاري تحتها، وقيل: عيسى، أي السيد الشريف؛ والقول الأول هو قول جمهور المفسرين في الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص98–99، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s19-40","number":40,"surah":19,"verses":[25],"references":[{"surah":19,"verses":[25]}],"verseLabel":"مريم: 25","question":"ما دلالة أمر مريم بهز جذع النخلة مع قدرتـه تعالى على رزقها بلا هز؟","answer":"أمرها بهز الجذع، مع أن المعتاد أن هزه لا يُسقط الثمر؛ وفي تأكيد تعلق الهز به إظهار للكرامة بأدنى سبب. فكان منها فعل السبب المأمور به، وحصول الرزق بفضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص108، تحت عنوان «دلالة الباء في: ﴿بِجِذْعِ﴾»","url":""}]},{"id":"s19-41","number":41,"surah":19,"verses":[25],"references":[{"surah":19,"verses":[25]}],"verseLabel":"مريم: 25","question":"ما سرّ وصف الرطب بـ﴿جَنِيًّا﴾؟","answer":"أي قد طاب وصلح للاجتناء؛ فالوصف يدل على اكتمال نضجه وكمال الانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص111، تحت عنوان «دلالة التعبير بـ: ﴿جَنِيًّا﴾»","url":""}]},{"id":"s19-135","number":135,"surah":19,"verses":[25],"references":[{"surah":19,"verses":[25]}],"verseLabel":"مريم: 25","question":"لماذا ذُكر الرطب في رزق مريم دون التمر؟","answer":"لأن السياق سياق إكرام وتسلية، فناسبه الثمر في صورة تشتهيها النفس وتسر العين؛ ويذكر المصدر أن لين الرطب يناسب حالها بعد آلام المخاض.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص110–111، تحت عنوان «سر التعبير بـ: ﴿رُطَبًا﴾»","url":""}]},{"id":"s19-42","number":42,"surah":19,"verses":[26],"references":[{"surah":19,"verses":[26]}],"verseLabel":"مريم: 26","question":"ما دلالة الجمع لمريم بين ﴿فَكُلِي وَاشْرَبِي وَقَرِّي عَيْنًا﴾؟","answer":"جمعت الواو لها ما يقوي البدن ويريح النفس: الطعام والشراب وقرة العين، فشمل الإحسان ظاهرها وباطنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص115، تحت عنوان «دلالة العطف بالواو في: ﴿وَاشْرَبِي وَقَرِّي﴾»","url":""}]},{"id":"s19-136","number":136,"surah":19,"verses":[26],"references":[{"surah":19,"verses":[26]}],"verseLabel":"مريم: 26","question":"لماذا ذُكر الطعام والشراب قبل قرة العين في خطاب مريم؟","answer":"يذكر المصدر أن ترتيب التسلية ارتقى من تقوية البدن إلى طمأنينة النفس؛ فإذا تهيأت بالغذاء كان ذلك تمهيدًا لسكون القلب وراحة البال.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص115–116، تحت عنوان «سر تقديم دفع ضرر الجوع والعطش على دفع ضرر الخوف»","url":""}]},{"id":"s19-43","number":43,"surah":19,"verses":[26],"references":[{"surah":19,"verses":[26]}],"verseLabel":"مريم: 26","question":"ما دلالة تفسير نذر الصوم بقول مريم: ﴿فَلَنْ أُكَلِّمَ الْيَوْمَ إِنْسِيًّا﴾؟","answer":"الفاء للسببية؛ فامتناعها عن الكلام مترتب على نذرها. ويذكر المصدر أن إعراضها عن المجادلة يتيح أن يتكلم عنها المولود، وكلامه أقطع للحجة من كلام تقوله هي فيقبل الرد والجدال.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص120، تحت عنوان «معنى الفاء ودلالتها في: ﴿فَلَنْ﴾»","url":""}]},{"id":"s19-137","number":137,"surah":19,"verses":[26],"references":[{"surah":19,"verses":[26]}],"verseLabel":"مريم: 26","question":"كيف جُمِع بين أمر مريم أن تقول نذرها وصومها عن الكلام؟","answer":"ظاهر الأمر يبيح لها التلفظ بصيغة النذر، وهو قول الجمهور المذكور في المصدر. وقيل: المراد الإبلاغ بالإشارة لأن المنع يشمل الكلام، وقيل: أخّرت إعلان نذرها حتى أتت قومها؛ فهذه أوجه في كيفية إبلاغ النذر، لا في إباحة مجادلتهم بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص121–122، تحت عنوان «النهي عن الكلام بقول تقوله مريم»","url":""}]},{"id":"s19-44","number":44,"surah":19,"verses":[27],"references":[{"surah":19,"verses":[27]}],"verseLabel":"مريم: 27","question":"ما سرّ التعبير بـ﴿فَأَتَتْ بِهِ قَوْمَهَا تَحْمِلُهُ﴾؟","answer":"التصريح بحمله يرسم شجاعتها في مواجهة القوم بالآية نفسها بدل إخفائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص127–128، تحت عنوان «سر تقييد الفعل ﴿فَأَتَتْ﴾ بالجملة الحالية ﴿تَحْمِلُهُ﴾»","url":""}]},{"id":"s19-45","number":45,"surah":19,"verses":[27],"references":[{"surah":19,"verses":[27]}],"verseLabel":"مريم: 27","question":"ما دلالة وصف قوم مريم ما رأوه بـ﴿شَيْئًا فَرِيًّا﴾؟","answer":"وصفوا ما رأوه بأنه أمر عظيم منكر، و«فريًّا» تحتمل الشنيع المستنكر أو المفترى. فحكى التعبير شدة صدمتهم واستعظامهم، وما بنوه على ظاهر الحال من اتهام لمريم قبل ظهور براءتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص130، تحت عنوان «سر تقييد المفعول به بالصفة ﴿فَرِيًّا﴾»","url":""}]},{"id":"s19-46","number":46,"surah":19,"verses":[28],"references":[{"surah":19,"verses":[28]}],"verseLabel":"مريم: 28","question":"ما دلالة نداء مريم بـ﴿يَا أُخْتَ هَارُونَ﴾ في مقام اللوم؟","answer":"استدعوا بهذه الإضافة صورة الصلاح المعروفة في أهلها للمبالغة في لومها على ما توهموه؛ فكأنهم يبرزون التناقض بين نسبها الطاهر وما نسبوه إليها من فعل منكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص136، تحت عنوان «سر التعبير بالمنادى مضافًا: ﴿يَا أُخْتَ هَارُونَ﴾»","url":""}]},{"id":"s19-47","number":47,"surah":19,"verses":[29],"references":[{"surah":19,"verses":[29]}],"verseLabel":"مريم: 29","question":"ما دلالة اكتفاء مريم بالإشارة إلى عيسى عند مواجهة قومها؟","answer":"بادرت بالإشارة إلى عيسى فور تعييرهم لها، ليَنطق ببراءتها؛ ففي التعقيب بالفاء تصوير لسرعة ردها، ولكمال تهيئة الله لها واستعدادها لمواجهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص143–144، تحت عنوان «معنى الفاء ودلالتها في ﴿فَأَشَارَتْ إِلَيْهِ﴾»","url":""}]},{"id":"s19-48","number":48,"surah":19,"verses":[30],"references":[{"surah":19,"verses":[30]}],"verseLabel":"مريم: 30","question":"ما دلالة افتتاح كلام عيسى بقوله: ﴿إِنِّي عَبْدُ اللَّهِ﴾؟","answer":"بدأ بـ﴿إني عبد الله﴾ لإثبات عبوديته لله من أول كلامه، وفي ذلك ردّ على من غلا فيه وادعى له الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص149، تحت عنوان «غرض التعبير بمقول القول جملة اسمية مؤكدة»","url":""}]},{"id":"s19-49","number":49,"surah":19,"verses":[30],"references":[{"surah":19,"verses":[30]}],"verseLabel":"مريم: 30","question":"ما سرّ التعبير بـ﴿آتَانِيَ الْكِتَابَ وَجَعَلَنِي نَبِيًّا﴾ بصيغة الماضي؟","answer":"لتحقق الوعد في علم الله حتى عُبر عن المستقبل كأنه وقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص150، تحت عنوان «دلالة التعبير بالماضي ﴿آتَانِي﴾»","url":""}]},{"id":"s19-50","number":50,"surah":19,"verses":[31],"references":[{"surah":19,"verses":[31]}],"verseLabel":"مريم: 31","question":"ما سرّ التعبير بـ﴿مُبَارَكًا أَيْنَ مَا كُنْتُ﴾؟","answer":"عمّم الشرط بركته في أي مكان يحل فيه، فمن جالسه أو التقى به ناله من نفعه؛ فليست بركته مقصورة على بقعة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص154، تحت عنوان «الغرض من التعبير بالشرط ﴿أَيْنَ مَا كُنْتُ﴾»","url":""}]},{"id":"s19-51","number":51,"surah":19,"verses":[31],"references":[{"surah":19,"verses":[31]}],"verseLabel":"مريم: 31","question":"ما دلالة تقييد الوصية بالصلاة والزكاة بـ﴿مَا دُمْتُ حَيًّا﴾؟","answer":"يدل القيد على ملازمته العبادة في حياته، ويشرح المصدر الاستغراق هنا بأنه عرفي يراد به الكثرة؛ فالوصية تعود إلى إقراره بالعبودية، وإيتاء الكتاب والنبوة ترقٍّ في هذه العبودية لا خروج منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص156–157، تحت عنوان «الغرض من التعبير بالقيد ﴿حَيًّا﴾»","url":""}]},{"id":"s19-52","number":52,"surah":19,"verses":[32],"references":[{"surah":19,"verses":[32]}],"verseLabel":"مريم: 32","question":"ما صلة قوله ﴿وَلَمْ يَجْعَلْنِي جَبَّارًا شَقِيًّا﴾ ببرّ عيسى بأمه؟","answer":"عطف نفي الجبروت يؤكد البر المذكور قبله؛ فالمعنى أنه متواضع خاضع لأمه، لا قاسيًا متكبرًا مضيعًا لحقها. وعُبر عما يدل عليه البر من حسن المعاملة بطريق نفي ضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص160–161، تحت عنوان «دلالة العطف»","url":""}]},{"id":"s19-138","number":138,"surah":19,"verses":[32],"references":[{"surah":19,"verses":[32]}],"verseLabel":"مريم: 32","question":"ما العلاقة بين وصف الجبار بالشقاء في كلام عيسى؟","answer":"الجبار متكبر متسلط غليظ في معاملة الناس، فيجلب لنفسه بغضهم وشقاءه بمعاداتهم، فضلًا عن سوء عاقبته في الآخرة. فنفي الجبروت يتصل بنفي ما يجره من الشقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص161، تحت عنوان «الغرض من تنكير المفعول الثاني ﴿جَبَّارًا﴾»","url":""}]},{"id":"s19-53","number":53,"surah":19,"verses":[33],"references":[{"surah":19,"verses":[33]}],"verseLabel":"مريم: 33","question":"ما سرّ تعبير عيسى بـ﴿وَالسَّلَامُ عَلَيَّ﴾؟","answer":"حكى عيسى ما جعله الله له من السلام والأمان في مواطن الولادة والموت والبعث. وقيل: اللام للعهد بسلام يحيى السابق، والأظهر عند المصدر أنها للجنس، مبالغة في تعلق السلام به.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص163، تحت عنوان «دلالة الواو واللام في ﴿وَالسَّلَامُ﴾»","url":""}]},{"id":"s19-54","number":54,"surah":19,"verses":[34],"references":[{"surah":19,"verses":[34]}],"verseLabel":"مريم: 34","question":"ما دلالة الاستئناف بقوله ﴿ذَلِكَ عِيسَى﴾ بعد كلامه؟","answer":"جاء اسم الإشارة لتمييز حقيقة عيسى وصفاته الصحيحة، ردًا على اختلاف اليهود والنصارى فيه؛ فكأن من وصفوه بغير صفته لا يعرفونه، فعُرّف لهم بحقيقته لتمييزها من الأوصاف الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص167، تحت عنوان «دلالة الاستئناف في ﴿ذَلِكَ عِيسَى﴾»","url":""}]},{"id":"s19-55","number":55,"surah":19,"verses":[34],"references":[{"surah":19,"verses":[34]}],"verseLabel":"مريم: 34","question":"ما سرّ وصف خبره بـ﴿قَوْلَ الْحَقِّ﴾؟","answer":"إضافة القول إلى الحق تؤكد صدقه وثبوته من كل جانب، في مقابلة امتراء المختلفين في عيسى ونسبهم إليه ما ليس من صفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص168، تحت عنوان «سر الإضافة في ﴿قَوْلَ الْحَقِّ﴾»","url":""}]},{"id":"s19-56","number":56,"surah":19,"verses":[35],"references":[{"surah":19,"verses":[35]}],"verseLabel":"مريم: 35","question":"ما دلالة نفي اتخاذ الولد عن الله بصيغة ﴿مَا كَانَ لِلَّهِ﴾؟","answer":"تفيد الصيغة أن اتخاذ الولد لا يليق بالله ولا يصح في حقه، فهي نفي بالغ قائم على منافاة ذلك لكمال الألوهية، لا مجرد إخبار بأنه لم يقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص173، تحت عنوان «دلالة التعبير بالكون المنفي بـ: ﴿مَا﴾»","url":""}]},{"id":"s19-139","number":139,"surah":19,"verses":[35],"references":[{"surah":19,"verses":[35]}],"verseLabel":"مريم: 35","question":"ما دلالة التعبير بالمصدر المؤول ﴿أَنْ يَتَّخِذَ﴾ في نفي الولد عن الله؟","answer":"يفيد نفي اتخاذه الولد في أي زمن من الأزمان؛ فينفي التعبير احتمال أن يتخذ سبحانه ولدًا في وقت ما. ويذكر المصدر أن المضارع ينزهه عن تجدد ما يفتقر معه إلى الولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص173–174، تحت عنوان «إيثار التعبير بالمصدر المؤول ﴿أَنْ يَتَّخِذَ﴾»","url":""}]},{"id":"s19-57","number":57,"surah":19,"verses":[35],"references":[{"surah":19,"verses":[35]}],"verseLabel":"مريم: 35","question":"ما دلالة تعقيب نفي الولد بقوله: ﴿إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ﴾؟","answer":"ميلاد عيسى بلا أب أثر لكلمة القدرة، لا دليل بنوة؛ فالخالق لا يحتاج إلى التوالد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص176، تحت عنوان «الغرض من التعبير بجواب الشرط أسلوب قصر»","url":""}]},{"id":"s19-58","number":58,"surah":19,"verses":[36],"references":[{"surah":19,"verses":[36]}],"verseLabel":"مريم: 36","question":"ما سرّ التعبير بـ﴿هَذَا صِرَاطٌ مُسْتَقِيمٌ﴾ بعد الأمر بالعبادة؟","answer":"أشير بـ﴿هذا﴾ إلى توحيد الله وعبادته المذكورين قبله، وجُعلا صراطًا واضحًا مستقيمًا يوصل سالكه إلى الحق بلا اعوجاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص182، تحت عنوان «الغرض من التعبير بالمسند إليه اسم إشارة للقريب ﴿هَذَا﴾»","url":""}]},{"id":"s19-59","number":59,"surah":19,"verses":[37],"references":[{"surah":19,"verses":[37]}],"verseLabel":"مريم: 37","question":"ما سرّ التعبير هنا بـ﴿فَوَيْلٌ لِلَّذِينَ كَفَرُوا﴾، وفي الزخرف ﴿فَوَيْلٌ لِلَّذِينَ ظَلَمُوا﴾؟","answer":"فُصّلت قصة عيسى في مريم، وذُكرت فيها مقالة نسبة الولد إلى الله، فناسب وصف أصحابها بالكفر؛ وأُجملت في الزخرف فجيء بوصف الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص189–190، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s19-60","number":60,"surah":19,"verses":[39],"references":[{"surah":19,"verses":[39]}],"verseLabel":"مريم: 39","question":"ما دلالة تسمية يوم القيامة ﴿يَوْمَ الْحَسْرَةِ﴾؟","answer":"لكثرة ما يقع يوم الحساب من تحسر المجرمين على ما فرطوا فيه من أسباب النجاة؛ فكأن اليوم اختص بالحسرة لشدة ظهورها فيه. وهذا بالنسبة إليهم، وإن كان يوم فرح للصالحين.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص201، تحت عنوان «سر إضافة اليوم إلى ﴿الْحَسْرَةِ﴾»","url":""}]},{"id":"s19-61","number":61,"surah":19,"verses":[40],"references":[{"surah":19,"verses":[40]}],"verseLabel":"مريم: 40","question":"ما سرّ التعبير بـ﴿إِنَّا نَحْنُ نَرِثُ الْأَرْضَ وَمَنْ عَلَيْهَا﴾؟","answer":"صُدرت الجملة بـ«إنّ» لتأكيد فناء الدنيا بمخلوقاتها ورجوعها إلى خالقها؛ فجاء الخبر مؤكدًا في خطاب المشركين الذين ينكرون الجزاء، وفيه زجر عن الاغترار بما يزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص208، تحت عنوان «دلالة تصدير الجملة بحرف التأكيد»","url":""}]},{"id":"s19-62","number":62,"surah":19,"verses":[41],"references":[{"surah":19,"verses":[41]}],"verseLabel":"مريم: 41","question":"ما دلالة وصف إبراهيم بـ﴿صِدِّيقًا﴾؟","answer":"جاءت صيغة المبالغة «فعيل» للدلالة على شدة اتصافه بالصدق؛ فصدقه راسخ في القول والعمل والإذعان للحق، ومن شواهده تصديقه أمر ربه وامتثاله له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص217، تحت عنوان «إيثار صيغة المبالغة في ﴿صِدِّيقًا﴾»","url":""}]},{"id":"s19-140","number":140,"surah":19,"verses":[41],"references":[{"surah":19,"verses":[41]}],"verseLabel":"مريم: 41","question":"لماذا قُدّم وصف إبراهيم بالصديقية على وصفه بالنبوة؟","answer":"يذكر المصدر أن التقديم يدفع توهم حصر الصديقية في النبوة؛ فكل نبي صديق، وليس كل صديق نبيًا. ففي الانتقال إلى النبوة بيان لمرتبة أخص بعد إثبات كمال الصدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص218، تحت عنوان «نكتة وصف إبراهيم بالصديقية قبل النبوة»","url":""}]},{"id":"s19-63","number":63,"surah":19,"verses":[42,43,44,45],"references":[{"surah":19,"verses":[42,43,44,45]}],"verseLabel":"مريم: 42-45","question":"ما سر تكرار إبراهيم نداء ﴿يَا أَبَتِ﴾ في حججه لأبيه؟","answer":"ليغلف التصحيح العقدي بالبر واللطف، فلا يحول إنكار الباطل إلى قسوة على الوالد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص227، تحت عنوان «سر تكرار النداء ﴿يَا أَبَتِ﴾»","url":""}]},{"id":"s19-64","number":64,"surah":19,"verses":[42],"references":[{"surah":19,"verses":[42]}],"verseLabel":"مريم: 42","question":"ما سرّ التعبير بـ﴿لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ﴾؟","answer":"بدأ بأوضح تناقض حسي: المعبود العاجز عن الإدراك والنفع لا يستحق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص221، تحت عنوان «بلاغة الاستفهام في الآية»","url":""}]},{"id":"s19-65","number":65,"surah":19,"verses":[43],"references":[{"surah":19,"verses":[43]}],"verseLabel":"مريم: 43","question":"ما سرّ التعبير بـ﴿قَدْ جَاءَنِي مِنَ الْعِلْمِ مَا لَمْ يَأْتِكَ﴾؟","answer":"لم يدع إحاطة العلم، بل ذكر القدر الذي خصه الله به، فجمع الحجة والتواضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص227، 228، 229، تحت «معنى حرف الجر في الآية»","url":""}]},{"id":"s19-66","number":66,"surah":19,"verses":[43],"references":[{"surah":19,"verses":[43]}],"verseLabel":"مريم: 43","question":"ما سرّ وصف الطريق بـ﴿صِرَاطًا سَوِيًّا﴾؟","answer":"السوي مستوٍ لا عوج فيه، يناسب عرض الابن طريقًا مأمونًا لأبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص230، تحت عنوان «دلالة وصف الصراط بقوله: ﴿سَوِيًّا﴾»","url":""}]},{"id":"s19-67","number":67,"surah":19,"verses":[44],"references":[{"surah":19,"verses":[44]}],"verseLabel":"مريم: 44","question":"ما سرّ التعبير بـ﴿لَا تَعْبُدِ الشَّيْطَانَ﴾ مع أن أباه يعبد الأصنام؟","answer":"لأن طاعة وسوسته أفضت إلى عبادة الأصنام، فنُسبت العبادة إلى الشيطان باعتباره سببها. وفي ذلك كشف لقبح الانقياد له وراء التعلق بالأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص233–234، تحت عنوان «سر العدول عن (الأصنام) إلى ﴿الشَّيْطَانَ﴾»","url":""}]},{"id":"s19-68","number":68,"surah":19,"verses":[45],"references":[{"surah":19,"verses":[45]}],"verseLabel":"مريم: 45","question":"لماذا قال إبراهيم لأبيه ﴿أَنْ يَمَسَّكَ عَذَابٌ﴾ دون «يصيبك»؟","answer":"من التوجيهات التي يذكرها المصدر أن المس أقل تمكنًا من الإصابة، فاختير تلطفًا في الإنذار وتقليلًا لدرجة ما يخوفه منه، بما يلائم شفقته على أبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص242، تحت عنوان «نكتة إيثار الفعل ﴿يَمَسَّكَ﴾ دون (يصيبك)»","url":""}]},{"id":"s19-141","number":141,"surah":19,"verses":[45],"references":[{"surah":19,"verses":[45]}],"verseLabel":"مريم: 45","question":"ما دلالة تقييد العذاب بكونه ﴿مِنَ الرَّحْمَنِ﴾ في إنذار إبراهيم لأبيه؟","answer":"يذكر المصدر وجهين: أن العذاب لا ينافي الرحمة بل قد يكون رحمة بالعباد، وأن ذكر الرحمن يغلظ الإنذار؛ فإذا حل العذاب ممن شأنه الرحمة دل ذلك على فظاعة جرم المعذَّب. فاستحضار الرحمة لا يعني انتفاء العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص243، تحت عنوان «نكتة تقييد العذاب بكونه ﴿مِنَ الرَّحْمَنِ﴾»","url":""}]},{"id":"s19-142","number":142,"surah":19,"verses":[45],"references":[{"surah":19,"verses":[45]}],"verseLabel":"مريم: 45","question":"كيف أبقى قول إبراهيم لأبيه ﴿إِنِّي أَخَافُ﴾ باب الرجاء في نجاته؟","answer":"يحمل الأكثرون الخوف هنا على ظاهره، فلا يجزم إبراهيم بعذاب أبيه؛ فقد يؤمن فيكون من أهل الثواب. وفي هذا أدب مع الله وإبقاء للرجاء في نفس الأب ليتخلص من العذاب بترك عبادة الأوثان.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص241–242، تحت عنوان «توجيه معنى الفعل ﴿أَخَافُ﴾ في الآية»","url":""}]},{"id":"s19-69","number":69,"surah":19,"verses":[46],"references":[{"surah":19,"verses":[46]}],"verseLabel":"مريم: 46","question":"كيف قابل أبو إبراهيم لطف ابنه في دعوته؟","answer":"قابل اللطف والرفق بالفظاظة والتهديد؛ فتوعده بالرجم والهجر، وخاطبه باسمه «يا إبراهيم» بدل خطاب البنوة الذي يقابل «يا أبت». فتظهر شدة الجفاء في مقابلة لين الابن.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص252، تحت عنوان «تفاوت الأسلوب بين كلام إبراهيم وكلام أبيه»","url":""}]},{"id":"s19-143","number":143,"surah":19,"verses":[46],"references":[{"surah":19,"verses":[46]}],"verseLabel":"مريم: 46","question":"ما دلالة ﴿مَلِيًّا﴾ في أمر أبي إبراهيم ﴿وَاهْجُرْنِي مَلِيًّا﴾؟","answer":"معناها طويلًا، فتدل على هجر ممتد؛ ويذكر المصدر أنها قد تكون وصفًا لمصدر محذوف، أي هجرًا مليًا، أو لزمان محذوف، أي زمانًا طويلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص257، تحت عنوان «إعراب كلمة ﴿مَلِيًّا﴾ وتوجيهها»","url":""}]},{"id":"s19-70","number":70,"surah":19,"verses":[47],"references":[{"surah":19,"verses":[47]}],"verseLabel":"مريم: 47","question":"ما دلالة جواب إبراهيم لأبيه: ﴿سَلَامٌ عَلَيْكَ﴾؟","answer":"قابل التهديد بالأمان وترك المقابلة بالسوء؛ فالمعنى أنك سالم من أذاي. وفي ذلك لطف وبر حتى عند اختلاف الاعتقاد وشدة الجفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص261–262، تحت عنوان «نكتة التنكير في لفظ ﴿سَلَامٌ﴾»","url":""}]},{"id":"s19-71","number":71,"surah":19,"verses":[48],"references":[{"surah":19,"verses":[48]}],"verseLabel":"مريم: 48","question":"ما دلالة ﴿عَسَى﴾ في قول إبراهيم ﴿عَسَى أَلَّا أَكُونَ بِدُعَاءِ رَبِّي شَقِيًّا﴾؟","answer":"عبّر بالرجاء إظهارًا للتواضع وحسن الأدب؛ فالثواب والإجابة تفضل من الله، لا استحقاق يوجبه العبد على ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص271، تحت عنوان «دلالة ﴿عَسَى﴾ في الآية»","url":""}]},{"id":"s19-144","number":144,"surah":19,"verses":[48],"references":[{"surah":19,"verses":[48]}],"verseLabel":"مريم: 48","question":"لماذا عبّر إبراهيم برجاء نفي الشقاء بدل التصريح برجاء السعادة؟","answer":"في هذا العدول تعريض بأن قومه أشقياء بدعاء آلهتهم؛ فإعلان رجائه في عبادة ربه يتضمن إظهار خيبة عبادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص271–272، تحت عنوان «سر العدول عن التصريح برجاء السعادة إلى نفي الشقاء»","url":""}]},{"id":"s19-72","number":72,"surah":19,"verses":[49],"references":[{"surah":19,"verses":[49]}],"verseLabel":"مريم: 49","question":"ما سرّ التعبير بـ﴿وَكُلًّا جَعَلْنَا نَبِيًّا﴾ بعد ذكر إسحاق ويعقوب؟","answer":"أكد أن الهبة لم تكن ذرية فحسب، بل امتداد نبوة ورسالة بعد الاعتزال لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص279، تحت عنوان «معنى الواو في قوله ﴿وَكُلًّا جَعَلْنَا﴾»","url":""}]},{"id":"s19-73","number":73,"surah":19,"verses":[50],"references":[{"surah":19,"verses":[50]}],"verseLabel":"مريم: 50","question":"ما وجه التعبير باللسان في قوله ﴿وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ﴾؟","answer":"أُريد باللسان الكلام والثناء الذي يصدر به؛ فذُكرت الآلة وأُريد ما يحصل بها، وهو مجاز يفسره المصدر بعلاقة السببية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص286–287، تحت عنوان «بلاغة المجاز في ذكر اللسان»","url":""}]},{"id":"s19-145","number":145,"surah":19,"verses":[50],"references":[{"surah":19,"verses":[50]}],"verseLabel":"مريم: 50","question":"ما دلالة وصف لسان الصدق بأنه ﴿عَلِيًّا﴾؟","answer":"يصوّر الوصف شرف الثناء وظهوره؛ فالعلو مستعار لعدم الخفاء، لأن ما علا وارتفع كان أبين وأظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص287، تحت عنوان «نكتة وصف اللسان بكونه ﴿عَلِيًّا﴾»","url":""}]},{"id":"s19-74","number":74,"surah":19,"verses":[51],"references":[{"surah":19,"verses":[51]}],"verseLabel":"مريم: 51","question":"ما الذي تفيده قراءتا ﴿مُخْلَصًا﴾ في وصف موسى؟","answer":"قراءة فتح اللام تفيد أن الله اصطفاه واجتباه، وقراءة كسرها تفيد إخلاصه لله في أعماله وأقواله. والمعنيان متلازمان في التوجيه المذكور: اصطفاه الله، وأخلص هو العبادة والعمل له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص292، تحت عنوان «إيثار التعبير بلفظ ﴿مُخْلَصًا﴾»","url":""}]},{"id":"s19-146","number":146,"surah":19,"verses":[51],"references":[{"surah":19,"verses":[51]}],"verseLabel":"مريم: 51","question":"لماذا جُمع لموسى الوصفان ﴿رَسُولًا نَبِيًّا﴾؟","answer":"جُمعا تأكيدًا لشرف وصفه وبيانًا لعظم أثر رسالته؛ ويوجه المصدر ذلك بأن الرسول بالمعنى الشرعي أخص من النبي، فيكون الجمع بينهما تنويهًا برسالته ونبوته معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص293، تحت عنوان «علة وصف موسى بكونه ﴿رَسُولًا نَبِيًّا﴾»","url":""}]},{"id":"s19-75","number":75,"surah":19,"verses":[52],"references":[{"surah":19,"verses":[52]}],"verseLabel":"مريم: 52","question":"ما سرّ التعبير بـ﴿وَقَرَّبْنَاهُ نَجِيًّا﴾؟","answer":"المناجاة خطاب خاص، والتقريب يبرز رفعة منزلة موسى وتشريفه بالكلام. ويشرح المصدر قربه بأنه قرب رتبة وإكرام، مصوّرًا بالقرب الذي يختص به المناجي.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص304، تحت عنوان «بلاغة الاستعارة في ﴿وَقَرَّبْنَاهُ نَجِيًّا﴾»","url":""}]},{"id":"s19-76","number":76,"surah":19,"verses":[53],"references":[{"surah":19,"verses":[53]}],"verseLabel":"مريم: 53","question":"لماذا عُبّر عن إشراك هارون مع موسى بلفظ الهبة؟","answer":"لأن إشراكه معه كان محض فضل من الله وعطاءً لا مقابل له ولا استحقاق؛ وفي لفظ الهبة تعظيم لهذه النعمة، إذ ضم الله أخاه إليه بالنبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص305، تحت عنوان «إيثار لفظ الهبة، دون غيره»","url":""}]},{"id":"s19-147","number":147,"surah":19,"verses":[53],"references":[{"surah":19,"verses":[53]}],"verseLabel":"مريم: 53","question":"ما دلالة اللام في ﴿وَوَهَبْنَا لَهُ﴾ عند ذكر هارون؟","answer":"اللام للاختصاص وللأجل؛ فهذه الهبة لأجل موسى لإعانته. ويذكر المصدر أنها، بخلاف النداء والتقريب السابقين، كانت بعد طلب وسؤال من موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص305–306، تحت عنوان «دلالة اللام في قوله: ﴿لَهُ﴾»","url":""}]},{"id":"s19-77","number":77,"surah":19,"verses":[54],"references":[{"surah":19,"verses":[54]}],"verseLabel":"مريم: 54","question":"لماذا خُصّ إسماعيل بوصف ﴿صَادِقَ الْوَعْدِ﴾؟","answer":"لكمال اشتهاره بهذه الصفة، فمدح بما غلب عليه من الوفاء. ويشمل ذلك وعده لله وللناس، ومنه وفاؤه لأبيه بما وعده من الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص314، تحت عنوان «سر إيثار صفة (صدق الوعد)»","url":""}]},{"id":"s19-148","number":148,"surah":19,"verses":[54],"references":[{"surah":19,"verses":[54]}],"verseLabel":"مريم: 54","question":"ما دلالة مجيء ﴿صَادِقَ﴾ اسم فاعل في وصف إسماعيل؟","answer":"يدل على رسوخ الصدق فيه حتى صار خُلُقًا ملازمًا له؛ فهو يزاول الوفاء بالوعد باستمرار، وليس وصفًا عارضًا في واقعة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص314–315، تحت عنوان «نكتة المجيء بالمسند اسم فاعل»","url":""}]},{"id":"s19-78","number":78,"surah":19,"verses":[55],"references":[{"surah":19,"verses":[55]}],"verseLabel":"مريم: 55","question":"لماذا خُصّ أهل إسماعيل بأمره بالصلاة في قوله ﴿وَكَانَ يَأْمُرُ أَهْلَهُ﴾؟","answer":"لشدة عنايته بإصلاح الأقربين؛ يبدأ المرء بتكميل نفسه ومن هو أقرب الناس إليه. ويذكر المصدر أن المراد قد يكون أهله خاصة، أو قومه باعتبارهم أهلًا له، فالمقصود إبراز العناية بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص316–317، تحت عنوان «نكتة اختصاص المفعول ﴿أَهْلَهُ﴾»","url":""}]},{"id":"s19-79","number":79,"surah":19,"verses":[57],"references":[{"surah":19,"verses":[57]}],"verseLabel":"مريم: 57","question":"ما دلالة قوله في إدريس: ﴿وَرَفَعْنَاهُ مَكَانًا عَلِيًّا﴾؟","answer":"ورد في رفع إدريس قولان مشهوران: رفع المنزلة والذكر، ورفع المكان حقيقة؛ فإطلاق ﴿مكانًا عليًا﴾ يحتمل رفعة القدر ورفعة المكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص328، تحت عنوان «بلاغة الاستعارة في: ﴿وَرَفَعْنَاهُ مَكَانًا﴾»","url":""}]},{"id":"s19-80","number":80,"surah":19,"verses":[58],"references":[{"surah":19,"verses":[58]}],"verseLabel":"مريم: 58","question":"ما سرّ التعبير بـ﴿خَرُّوا سُجَّدًا وَبُكِيًّا﴾؟","answer":"جمع التعبير بين الخضوع الظاهر وخشوع القلب؛ فالسجود يصور وضع الجباه، و«بكيًّا» تدل على التأثر الباطن، فتتكامل هيئة الجسد وحال القلب عند تلاوة الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص343، تحت عنوان «سر إيثار صيغة ﴿سُجَّدًا﴾»","url":""}]},{"id":"s19-81","number":81,"surah":19,"verses":[59],"references":[{"surah":19,"verses":[59]}],"verseLabel":"مريم: 59","question":"ما دلالة اقتران إضاعة الصلاة باتباع الشهوات؟","answer":"جاء اتباع الشهوات عقب إضاعة الصلاة؛ لأن تضييع أعظم الصلات بالله يفتح طريق الانقياد للشهوات، فجمع النص أصل التفريط وأثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص352، 353، 354، تحت «دلالة العطف»","url":""}]},{"id":"s19-82","number":82,"surah":19,"verses":[59],"references":[{"surah":19,"verses":[59]}],"verseLabel":"مريم: 59","question":"ما دلالة التعبير بـ﴿غَيًّا﴾ في وعيد من أضاعوا الصلاة واتبعوا الشهوات؟","answer":"يرد الغي بمعنى الضلال والخيبة؛ وهو هنا وعيد بعاقبة سيئة تنفر منها النفوس، تقابل ما طلبوه من لذة الشهوات.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص356، تحت عنوان «سر إيثار التعبير بالغيّ، ودلالة تنكيره»","url":""}]},{"id":"s19-149","number":149,"surah":19,"verses":[59],"references":[{"surah":19,"verses":[59]}],"verseLabel":"مريم: 59","question":"لماذا عُبّر عن جزاء مضيعي الصلاة ومتّبعي الشهوات بقوله ﴿يَلْقَوْنَ﴾؟","answer":"يصور اللقاء موافاتهم الجزاء الذي استحقوه بأعمالهم؛ فكأن العاقبة تأتيهم ويلتقون بها بعد أن غفلوا عنها وانشغلوا بلذة الشهوات.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص355، تحت عنوان «سر التعبير بالفعل ﴿يَلْقَوْنَ﴾»","url":""}]},{"id":"s19-83","number":83,"surah":19,"verses":[60],"references":[{"surah":19,"verses":[60]},{"surah":25,"verses":[70]}],"verseLabel":"مريم: 60؛ الفرقان: 70","question":"ما سرّ التعبير في الفرقان بـ﴿وَعَمِلَ عَمَلًا صَالِحًا﴾، وفي مريم بـ﴿وَعَمِلَ صَالِحًا﴾؟","answer":"في مريم اكتُفي بالوصف «صالحًا» دون التصريح بموصوفه. أما في الفرقان فذُكر «عملًا» مع فعله تأكيدًا لضرورة سعي التائب في الأعمال الصالحة المخالفة لسيئاته السابقة؛ فاجتماع الفعل ومصدره يقوي التوكيد ويلائم مقام التوبة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص238، تحت عنوان «نكتة التعبير بالمفعول ﴿عَمَلًا﴾»","url":""}]},{"id":"s19-84","number":84,"surah":19,"verses":[61],"references":[{"surah":19,"verses":[61]}],"verseLabel":"مريم: 61","question":"ما دلالة وصف الجنات بأنها مما وعد الرحمن عباده ﴿بِالْغَيْبِ﴾؟","answer":"وُعدوا بجنات لم يروها؛ فآمنوا بالغيب اعتمادًا على وعد الله. وفي القيد تنويه بصدق إيمانهم واختبار لهم بما غاب عن مشاهدتهم، مع كون الجنات مهيأة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص370–371، تحت عنوان «فائدة التقييد بشبه الجملة في: ﴿بِالْغَيْبِ﴾»","url":""}]},{"id":"s19-85","number":85,"surah":19,"verses":[61],"references":[{"surah":19,"verses":[61]}],"verseLabel":"مريم: 61","question":"ما سرّ التعبير بـ﴿إِنَّهُ كَانَ وَعْدُهُ مَأْتِيًّا﴾ لا «آتيا»؟","answer":"صوّر الوعد كأنه مقصد يأتيه أهله ويصلون إليه، مبالغة في تحقق الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص372–373، تحت عنوان «دلالة صيغة اسم المفعول ﴿مَأْتِيًّا﴾ دون غيرها»","url":""}]},{"id":"s19-86","number":86,"surah":19,"verses":[62],"references":[{"surah":19,"verses":[62]}],"verseLabel":"مريم: 62","question":"ما دلالة الاستثناء في ﴿لَا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَامًا﴾؟","answer":"يرجح المصدر الاستثناء المنقطع: لا يسمعون لغوًا، لكن يسمعون سلامًا؛ فالسلام ليس من اللغو. ويذكر وجه الاتصال بتفسير اللغو بمطلق الكلام، فيكون ما يسمعونه سلامًا. والمقصود تنزيه خطاب أهل الجنة عن الكلام المؤذي والباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص374–375، تحت عنوان «معنى الاستثناء ودلالته»","url":""}]},{"id":"s19-87","number":87,"surah":19,"verses":[63],"references":[{"surah":19,"verses":[63]}],"verseLabel":"مريم: 63","question":"لماذا أُشير إلى الجنة باسم الإشارة للبعيد في ﴿تِلْكَ الْجَنَّةُ﴾؟","answer":"للإيذان بعلو مرتبتها وبُعد منزلتها في الشرف؛ فالبعد هنا يعظم شأن الجنة وما أعد الله فيها لعباده.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص379، تحت عنوان «نكتة التعبير باسم الإشارة للبعيد»","url":""}]},{"id":"s19-88","number":88,"surah":19,"verses":[64],"references":[{"surah":19,"verses":[64]}],"verseLabel":"مريم: 64","question":"ما دلالة قول الملائكة: ﴿وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ﴾؟","answer":"تنفي استقلالها بالنزول وترد تأخر الوحي أو مجيئه إلى تدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص387، تحت عنوان «معنى الاستثناء ودلالته»","url":""}]},{"id":"s19-89","number":89,"surah":19,"verses":[65],"references":[{"surah":19,"verses":[65]}],"verseLabel":"مريم: 65","question":"ما سرّ التعبير بـ﴿هَلْ تَعْلَمُ لَهُ سَمِيًّا﴾؟","answer":"ينفي أن يكون لله نظير يماثله أو يستحق أن يُعبد معه. ويذكر المصدر أيضًا تفسير السمي بالمشارك في الاسم المختص به، كاسم «الله»؛ فالمقصود تقرير تفرده واستحقاقه العبادة، لا جعل مجرد الاشتراك في لفظ صفة مماثلةً له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص401–402، تحت عنوان «سر التعبير بـ﴿سَمِيًّا﴾ دون غيرها»","url":""}]},{"id":"s19-90","number":90,"surah":19,"verses":[66],"references":[{"surah":19,"verses":[66]}],"verseLabel":"مريم: 66","question":"لماذا جاء زمن الموت بعد همزة الاستفهام في إنكار البعث: ﴿أَإِذَا مَا مِتُّ﴾؟","answer":"لأن موضع استبعاده هو وقوع الحياة بعد الموت؛ فتقديم الظرف بعد همزة الإنكار يسلط الإنكار على هذا الوقت الذي يتوهم أن الإحياء بعده محال.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص406، تحت عنوان «سر إيلاء الظرف همزة الاستفهام في ﴿أَإِذَا﴾»","url":""}]},{"id":"s19-150","number":150,"surah":19,"verses":[66],"references":[{"surah":19,"verses":[66]}],"verseLabel":"مريم: 66","question":"لماذا اقترنت ﴿سَوْفَ﴾ باللام في حكاية إنكار البعث: ﴿لَسَوْفَ أُخْرَجُ حَيًّا﴾؟","answer":"حُكي وعد البعث مؤكدًا باللام كما يسمعه المنكر من الرسول والمؤمنين، ثم أُدخل عليه الإنكار؛ فالتأكيد في الكلام المحكي لا يدل على إقرار المنكر بالبعث، بل يبرز جحوده للوعد المؤكد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص407، تحت عنوان «دلالة اقتران سوف باللام»","url":""}]},{"id":"s19-91","number":91,"surah":19,"verses":[67],"references":[{"surah":19,"verses":[67]}],"verseLabel":"مريم: 67","question":"ما دلالة الاحتجاج على منكر البعث بأنه خُلق من قبل ﴿وَلَمْ يَكُ شَيْئًا﴾؟","answer":"ذكّره بخلقه الأول من العدم ليبطل استبعاد الإعادة؛ فالذي أوجده ولم يكن شيئًا لا يعجز عن بعثه. والاحتجاج يرد المنكر إلى أصل وجوده الذي يغفل عن دلالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص412–413، تحت عنوان «موقع جملة ﴿وَلَمْ يَكُ شَيْئًا﴾ ودلالته»","url":""}]},{"id":"s19-92","number":92,"surah":19,"verses":[68],"references":[{"surah":19,"verses":[68]}],"verseLabel":"مريم: 68","question":"ما دلالة جمع الكافرين مع الشياطين في الحشر؟","answer":"يجمع الحشر بين المشركين والشياطين الذين أغووهم، فتظهر الصلة بين إضلال الشياطين واتباع الكافرين لهم. ويذكر المصدر في الواو العطف، ويجيز معنى المصاحبة، بما يزيد تصوير مهانتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص417–418، تحت عنوان «دلالة الواو في قوله: ﴿وَالشَّيَاطِينَ﴾»","url":""}]},{"id":"s19-93","number":93,"surah":19,"verses":[68],"references":[{"surah":19,"verses":[68]}],"verseLabel":"مريم: 68","question":"ما سرّ التعبير بـ﴿ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّا﴾؟","answer":"«جثيا» على الركب تصور ذلهم وعجزهم وهم ينتظرون الحكم حول النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص419، تحت عنوان «سر التقييد بالحال ﴿جِثِيًّا﴾»","url":""}]},{"id":"s19-94","number":94,"surah":19,"verses":[69],"references":[{"surah":19,"verses":[69]}],"verseLabel":"مريم: 69","question":"ما دلالة التفضيل بـ﴿أَشَدُّ﴾ في نزع أهل العتو من كل شيعة؟","answer":"يدل على تمييز الأشد عصيانًا وتمردًا من كل طائفة؛ فليس أهل العتو سواءً، ويختص الأشد منهم بشدة العذاب، مع اشتراكهم في أصل الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص425–426، تحت عنوان «دلالة التعبير بالتفضيل ﴿أَشَدُّ﴾»","url":""}]},{"id":"s19-95","number":95,"surah":19,"verses":[71],"references":[{"surah":19,"verses":[71]}],"verseLabel":"مريم: 71","question":"ما سرّ التعبير بـ﴿وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا﴾؟","answer":"التعبير باسم الفاعل يدل على ثبوت الورود واستقراره، ثم تختلف العاقبة: فإما نجاة وحسن مصير، وإما بقاء وسوء مصير. فيقرر حتمية المشهد ويبعث على الخوف من عاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص435، تحت عنوان «سر التعبير باسم الفاعل ﴿وَارِدُهَا﴾»","url":""}]},{"id":"s19-96","number":96,"surah":19,"verses":[72],"references":[{"surah":19,"verses":[72]}],"verseLabel":"مريم: 72","question":"ما سرّ التعبير بـ﴿وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا﴾؟","answer":"تصور إعادة الجثو بقاء الظالمين في النار جاثين على ركبهم عاجزين عن الحركة من شدة الهول؛ أما الجثو السابق حول جهنم فكان في مقام الإحضار وانتظار الحساب. فلكل موضع ما يزيد تصوير المهانة والذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص443، تحت عنوان «سر إعادة لفظ ﴿جِثِيًّا﴾»","url":""}]},{"id":"s19-97","number":97,"surah":19,"verses":[73],"references":[{"surah":19,"verses":[73]}],"verseLabel":"مريم: 73","question":"ما دلالة تفاخر الكافرين بـ﴿خَيْرٌ مَقَامًا وَأَحْسَنُ نَدِيًّا﴾؟","answer":"جمعوا التفاخر بحسن المقام وحسن المجلس، يتوهمون أن ما لهم من سعة المعيشة وزينة المجالس يدل على أفضليتهم. وفي حكاية قولهم كشف لنظرتهم القاصرة وتهكمهم بفقراء المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص450، تحت عنوان «دلالة العطف بالواو: ﴿وَأَحْسَنُ نَدِيًّا﴾»","url":""}]},{"id":"s19-98","number":98,"surah":19,"verses":[74],"references":[{"surah":19,"verses":[74]}],"verseLabel":"مريم: 74","question":"لماذا قُدّم ﴿أَثَاثًا﴾ على ﴿رِئْيًا﴾ في وصف متاع الأمم السابقة؟","answer":"الأثاث متاع البيت، والرئي الزينة والمنظر الحسن. قُدّم المتاع لأنه أعم وأغلب، ثم عُطف عليه حسن المنظر الذي يقوم به؛ فرتب الأصل وما يتبعه من الزينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص457، تحت عنوان «غرض تقديم ﴿أَثَاثًا﴾ على ﴿وَرِئْيًا﴾»","url":""}]},{"id":"s19-99","number":99,"surah":19,"verses":[75],"references":[{"surah":19,"verses":[75]}],"verseLabel":"مريم: 75","question":"ما دلالة صيغة الأمر في ﴿فَلْيَمْدُدْ لَهُ الرَّحْمَنُ مَدًّا﴾؟","answer":"استُعمل الأمر في معنى تحقيق الخبر والتهديد: سيمد له في الإمهال حتى يعاين العاقبة. ويذكر المصدر وجه الدعاء بطول الإمهال؛ وفي الحالين لا تكون الصيغة وعدًا بالرضا، بل وعيدًا للمستمر في ضلاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص464، تحت عنوان «دلالة اللام في ﴿فَلْيَمْدُدْ﴾»","url":""}]},{"id":"s19-100","number":100,"surah":19,"verses":[76],"references":[{"surah":19,"verses":[76]}],"verseLabel":"مريم: 76","question":"ما دلالة وصف الباقيات الصالحات بأنها ﴿خَيْرٌ ثَوَابًا وَخَيْرٌ مَرَدًّا﴾؟","answer":"تكرار «خير» يزيد بيان أفضلية ثواب الصالحات وعاقبتها وتأكيدها. وفي مقابلة أهلها بالكافرين تهكم بعاقبة الكفر وتحسير لأصحابه على مفاخرتهم بزينة الدنيا؛ فحسن المآل للعمل الصالح، لا لما اغتروا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص477، تحت عنوان «وجه عقد مفاضلة بين النقيضين وتأكيده بالتكرير»","url":""}]},{"id":"s19-101","number":101,"surah":19,"verses":[77],"references":[{"surah":19,"verses":[77]}],"verseLabel":"مريم: 77","question":"ما سرّ التعبير بـ﴿أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا﴾؟","answer":"الاستفهام يعجب من جرأته على الجمع بين الكفر والقطع بأنه سيؤتى مالًا وولدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص483، تحت عنوان «سر إيثار التعريف بالاسم الموصول»","url":""}]},{"id":"s19-102","number":102,"surah":19,"verses":[78],"references":[{"surah":19,"verses":[78]}],"verseLabel":"مريم: 78","question":"ما دلالة الاستفهام في ﴿أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِنْدَ الرَّحْمَنِ عَهْدًا﴾؟","answer":"حصر مستند دعواه في علم الغيب أو عهد من الله، وكلاهما معدوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص491، تحت عنوان «بلاغة حصر أقسام المعرفة»","url":""}]},{"id":"s19-103","number":103,"surah":19,"verses":[79],"references":[{"surah":19,"verses":[79]}],"verseLabel":"مريم: 79","question":"ما دلالة المضارع في ﴿سَنَكْتُبُ مَا يَقُولُ﴾؟","answer":"يدل على استمرار إثبات قوله عليه ما دام قوله مستمرًا؛ فما تلفظ به محفوظ، ويظهر له ويحاسب عليه، فلا يضيع بتجدد الزمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص495، تحت عنوان «دلالة التعبير بالمضارع ﴿سَنَكْتُبُ﴾»","url":""}]},{"id":"s19-151","number":151,"surah":19,"verses":[79],"references":[{"surah":19,"verses":[79]}],"verseLabel":"مريم: 79","question":"كيف قابل قوله ﴿وَنَمُدُّ لَهُ مِنَ الْعَذَابِ مَدًّا﴾ زعم الكافر أنه سيؤتى مالًا وولدًا؟","answer":"قوبل ما ادعاه من الإمداد بالمال والولد بإمداده بالعذاب وزيادته؛ فكان الجزاء موافقًا لجرأته في دعواه. وإسناد المد إلى ضمير العظمة يزيد الوعيد تفخيمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص498، تحت عنوان «بلاغة إسناد فعل (المدّ) إلى نون العظمة»","url":""}]},{"id":"s19-104","number":104,"surah":19,"verses":[80],"references":[{"surah":19,"verses":[80]}],"verseLabel":"مريم: 80","question":"ما دلالة الجمع بين ﴿وَنَرِثُهُ مَا يَقُولُ﴾ و﴿وَيَأْتِينَا فَرْدًا﴾؟","answer":"عُطف إتيانه منفردًا على نزع ما ادعاه من المال والولد؛ فيأتي يوم القيامة معزولًا عما ظنه عزًا وقوة، لا يملك شيئًا مما زعم أنه سيؤتاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص502–503، تحت عنوان «معنى الواو في جملة ﴿وَيَأْتِينَا فَرْدًا﴾»","url":""}]},{"id":"s19-105","number":105,"surah":19,"verses":[81,82],"references":[{"surah":19,"verses":[81,82]}],"verseLabel":"مريم: 81-82","question":"ما دلالة انقلاب ما طلبوه من الآلهة ﴿عِزًّا﴾ إلى ﴿ضِدًّا﴾؟","answer":"يؤول ما رجوا به الرفعة والمنعة إلى الذلة والصغار؛ فالتعبير بالضد كناية عن انقلاب حالهم إلى خلاف ما كانوا يؤملونه من العز.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص518، تحت عنوان «بلاغة الكناية عن الصفة»","url":""}]},{"id":"s19-152","number":152,"surah":19,"verses":[81,82],"references":[{"surah":19,"verses":[81,82]}],"verseLabel":"مريم: 81-82","question":"إلى من يعود الضمير في ﴿سَيَكْفُرُونَ بِعِبَادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدًّا﴾؟","answer":"يذكر المصدر وجهين: عوده إلى المعبودين، فيتبرؤون من عبادة المشركين لهم، وعوده إلى العابدين، فينكرون أنهم عبدوا تلك الآلهة. ويعرض الوجهين باعتبار ما يحتمله السياق، دون حصره في أحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص515، تحت عنوان «مرجع الضمير في ﴿سَيَكْفُرُونَ﴾، وفي ﴿بِعِبَادَتِهِمْ﴾، وفي ﴿وَيَكُونُونَ﴾»","url":""}]},{"id":"s19-106","number":106,"surah":19,"verses":[83],"references":[{"surah":19,"verses":[83]}],"verseLabel":"مريم: 83","question":"ما سرّ التعبير بـ﴿تَؤُزُّهُمْ أَزًّا﴾؟","answer":"يصور المضارع تجدد إزعاج الشياطين لهم وتهييجهم إلى المعاصي مرة بعد أخرى؛ فكلما فتروا عاودتهم الإثارة، فيستمر دفعهم إلى الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص532، تحت عنوان «دلالة التعبير بالمضارع ﴿تَؤُزُّهُمْ﴾»","url":""}]},{"id":"s19-107","number":107,"surah":19,"verses":[84],"references":[{"surah":19,"verses":[84]}],"verseLabel":"مريم: 84","question":"ما سرّ التعبير بـ﴿إِنَّمَا نَعُدُّ لَهُمْ عَدًّا﴾؟","answer":"يؤكد المصدر «عدًّا» إحصاء أنفاسهم وأعمارهم وأعمالهم حتى يستوفوا آجالهم، من غير زيادة ولا نقص؛ فليس تأخير عقوبتهم نسيانًا لهم، إذ لا يخفى على الله شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص538، تحت عنوان «نكتة القيد بالمفعول المطلق ﴿عَدًّا﴾»","url":""}]},{"id":"s19-108","number":108,"surah":19,"verses":[85,86],"references":[{"surah":19,"verses":[85,86]}],"verseLabel":"مريم: 85-86","question":"ما دلالة حشر المتقين ﴿وَفْدًا﴾ وسوق المجرمين ﴿وِرْدًا﴾؟","answer":"تقابل الآيتان بين وفادة المتقين على الرحمن في كرامة، وسوق المجرمين إلى النار في إهانة؛ فالسوق يشعر بالإكراه، ويصورهم كالأنعام العطاش التي تساق إلى الماء، فإذا مصيرهم جهنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص543، تحت عنوان «نكتة إيثار الفعل ﴿وَنَسُوقُ﴾»","url":""}]},{"id":"s19-109","number":109,"surah":19,"verses":[87],"references":[{"surah":19,"verses":[87]}],"verseLabel":"مريم: 87","question":"ما دلالة تقييد الشفاعة باتخاذ ﴿عِنْدَ الرَّحْمَنِ عَهْدًا﴾؟","answer":"قيدت الشفاعة بالعهد عند الرحمن؛ أي بالإيمان والتوحيد وما يأذن الله به، فنفى أن تملكها الآلهة أو تنال بمجرد الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص548، تحت عنوان «بلاغة تقييد الاتخاذ بالعندية»","url":""}]},{"id":"s19-110","number":110,"surah":19,"verses":[88],"references":[{"surah":19,"verses":[88]}],"verseLabel":"مريم: 88","question":"ما دلالة مجيء حكاية ﴿اتَّخَذَ الرَّحْمَنُ وَلَدًا﴾ بعد حكاية اتخاذ الآلهة؟","answer":"عُطفت حكاية دعوى الولد على حكاية اتخاذ الآلهة تتميمًا لعرض أقوالهم الباطلة؛ فالجنايتان تشتركان في الضلالة، وجاءت الثانية بعد جناية عبادة الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص554–555، تحت عنوان «بلاغة عطف القصة على القصة»","url":""}]},{"id":"s19-111","number":111,"surah":19,"verses":[89],"references":[{"surah":19,"verses":[89]}],"verseLabel":"مريم: 89","question":"ما سرّ وصف قولهم بالولد بـ﴿شَيْئًا إِدًّا﴾؟","answer":"الإد الأمر الفظيع المنكر الذي يثقل سماعه، فناسب أثره الكوني في الآيات التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص561، تحت عنوان «بلاغة الوصف بـ﴿إِدًّا﴾»","url":""}]},{"id":"s19-112","number":112,"surah":19,"verses":[90],"references":[{"surah":19,"verses":[90]}],"verseLabel":"مريم: 90","question":"ما دلالة تصوير السماوات تكاد تتفطر والأرض تنشق والجبال تخر عند دعوى الولد؟","answer":"يصور المشهد عظم هذه المقالة وشناعتها؛ فكأن السماوات والأرض والجبال لا تقوى على حملها وتوشك أن تتصدع من هولها. وفي فعل المقاربة تهويل للقول وتنفير من الاستهانة به، من غير أن يدل على وقوع هذا التداعي بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص562، تحت عنوان «بلاغة التعبير بفعل المقاربة (كاد)»","url":""}]},{"id":"s19-113","number":113,"surah":19,"verses":[92],"references":[{"surah":19,"verses":[92]}],"verseLabel":"مريم: 92","question":"ما دلالة نفي الانبغاء في ﴿وَمَا يَنْبَغِي لِلرَّحْمَنِ أَنْ يَتَّخِذَ وَلَدًا﴾؟","answer":"يدل على استحالة اتخاذ الولد في حق الله، لا مجرد نفي وقوعه؛ فالولد يشبه أباه ويحتاج إليه، والله منزّه عن الحاجة والمماثلة، ومخلوقاته عباد له لا تشاركه ألوهيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص574–575، تحت عنوان «بلاغة نفي الانبغاء»","url":""}]},{"id":"s19-153","number":153,"surah":19,"verses":[92],"references":[{"surah":19,"verses":[92]}],"verseLabel":"مريم: 92","question":"لماذا أُظهر اسم ﴿الرَّحْمَنِ﴾ في نفي اتخاذ الولد بدل الاكتفاء بالضمير؟","answer":"فيه إشعار بعلة الحكم: كل موجود سواه مفتقر إلى رحمته، إما نعمة أو منعَم عليه، والجميع عباده. فلا يجانس المخلوق خالقه حتى يتوهم اتخاذه ولدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص575–576، تحت عنوان «بلاغة وضع الظاهر موضع المضمر»","url":""}]},{"id":"s19-114","number":114,"surah":19,"verses":[93],"references":[{"surah":19,"verses":[93]}],"verseLabel":"مريم: 93","question":"ما سرّ التعبير بـ﴿إِلَّا آتِي الرَّحْمَنِ عَبْدًا﴾؟","answer":"يقرر وصف العبودية خضوع الجميع لله وعدم استقلالهم عنه بشيء؛ حتى من نُسبت إليهم البنوة يأتونه عبادًا، فلا تثبت لهم ألوهية ولا بنوة كما زعم المبطلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص578، تحت عنوان «بلاغة التعبير بمفردة ﴿عَبْدًا﴾»","url":""}]},{"id":"s19-115","number":115,"surah":19,"verses":[94],"references":[{"surah":19,"verses":[94]}],"verseLabel":"مريم: 94","question":"ما دلالة الجمع بين ﴿أَحْصَاهُمْ وَعَدَّهُمْ عَدًّا﴾؟","answer":"العد سرد الأشياء واحدًا بعد آخر، أما الإحصاء فيشمل العد مع الحصر والضبط والحفظ. فالجمع بينهما يقرر إحاطةً لا يفوتها شيء، وليس مجرد معرفة عدد إجمالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص583، تحت عنوان «الإحصاء والعدّ»","url":""}]},{"id":"s19-116","number":116,"surah":19,"verses":[95],"references":[{"surah":19,"verses":[95]}],"verseLabel":"مريم: 95","question":"ما سرّ التعبير بـ﴿وَكُلُّهُمْ آتِيهِ يَوْمَ الْقِيَامَةِ فَرْدًا﴾؟","answer":"يأتي كل إنسان يوم القيامة منفردًا، لا ينفعه ما اغتر به من أعوان أو أنصار أو مال أو ولد؛ فلا يملك لنفسه نفعًا، فضلًا عن أن يحميه غيره مما يستحقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص582، تحت عنوان «دلالة القيد بالحال ﴿فَرْدًا﴾»","url":""}]},{"id":"s19-117","number":117,"surah":19,"verses":[96],"references":[{"surah":19,"verses":[96]}],"verseLabel":"مريم: 96","question":"ما دلالة اختيار لفظ ﴿وُدًّا﴾ في وعد المؤمنين؟","answer":"يجمع الود المحبة والألفة والقبول والطمأنينة في المعاملة والصحبة؛ فلا يقتصر على الميل الباطن، بل يتصل بحسن الصلة والخلو من إرادة المكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص590، تحت عنوان «نكتة التعبير بلفظ ﴿وُدًّا﴾»","url":""}]},{"id":"s19-154","number":154,"surah":19,"verses":[96],"references":[{"surah":19,"verses":[96]}],"verseLabel":"مريم: 96","question":"لماذا اختير اسم ﴿الرَّحْمَنُ﴾ في وعد المؤمنين بأن يجعل لهم ودًّا؟","answer":"للإيذان بأن جعل الود لهم أثر من آثار رحمته؛ وفي الاسم تذكير بعظم هذه النعمة ومصدرها، وهو ملائم لما غلب على السورة من ذكر الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص590، تحت عنوان «إيثار التعبير بصفة الرحمن»","url":""}]},{"id":"s19-118","number":118,"surah":19,"verses":[97],"references":[{"surah":19,"verses":[97]}],"verseLabel":"مريم: 97","question":"ما دلالة حذف متعلق التيسير في ﴿فَإِنَّمَا يَسَّرْنَاهُ بِلِسَانِكَ﴾؟","answer":"يفيد عموم التيسير: تيسير قراءة القرآن وذكره والنطق به بالعربية، وتبليغه وفهمه وحفظه؛ ليبشر الرسول به المتقين وينذر المعاندين. فلا يقتصر التيسير على وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص595، تحت عنوان «فائدة حذف متعلّق الفعل ﴿يَسَّرْنَاهُ﴾»","url":""}]},{"id":"s19-119","number":119,"surah":19,"verses":[98],"references":[{"surah":19,"verses":[98]}],"verseLabel":"مريم: 98","question":"ما دلالة ختام السورة بـ﴿هَلْ تُحِسُّ مِنْهُمْ مِنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزًا﴾؟","answer":"جمع نفي رؤيتهم ونفي سماع صوتهم الخفي كناية عن استئصالهم وهلاكهم؛ فانتفاء ما يدل على وجودهم يصور زوالهم الكامل بعد قوتهم وتجبرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص610، تحت عنوان «بلاغة الكناية في الآية»","url":""}]},{"id":"s19-155","number":155,"surah":19,"verses":[3,4],"references":[{"surah":19,"verses":[3,4]}],"verseLabel":"مريم: 3، 4","question":"ما سر ذكر فعل القول بعد النداء في قوله: ﴿إِذْ نَادَىٰ رَبَّهُ نِدَاءً خَفِيًّا قَالَ رَبِّ﴾، والاكتفاء بالنداء في الأنبياء: ﴿إِذْ نَادَىٰ رَبَّهُ رَبِّ لَا تَذَرْنِي فَرْدًا﴾؟","answer":"تبسّط زكريا في مريم وفصّل؛ فذكر وهن عظمه واشتعال رأسه شيبًا، وأن امرأته عاقر، وخوفه الموالي من بعده، وطلب أن يكون الوليّ رضيًّا، فاقتضى ذلك التوكيد والإلحاح فذكر فعل القول. وأوجز في الأنبياء فاكتفى بالنداء، وكما تبسّط زكريا في مريم تبسّط الرب في الجواب، ولما أوجز هناك أوجز.","sources":[{"label":"فاضل السامرائي، الجملة العربية تأليفها وأقسامها، ص215–216.","url":""}]},{"id":"s19-156","number":156,"surah":19,"verses":[10],"references":[{"surah":19,"verses":[10]}],"verseLabel":"مريم: 10","question":"ما سر قوله في مريم: ﴿أَلَّا تُكَلِّمَ النَّاسَ ثَلَاثَ لَيَالٍ سَوِيًّا﴾، وفي آل عمران: ﴿ثَلَاثَةَ أَيَّامٍ﴾؟","answer":"حسُن ذكر الليل في مريم لأن النداء فيها خفيّ، والليل أنسب للإخفاء والنهار للإظهار. وذكر فيها شيخوخته ووهن عظمه وبلوغه من الكبر عتيًّا، والضعف أشبه بالليل وسكونه، وذكر طلبه وارثًا يرثه بعد موته، والموت ليل طويل. ولم يذكر شيئًا من ذلك في آل عمران فذكر الأيام.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص115–117.","url":""}]},{"id":"s19-157","number":157,"surah":19,"verses":[18],"references":[{"surah":19,"verses":[18]}],"verseLabel":"مريم: 18","question":"ما سر استعاذة مريم بالرحمن في قولها: ﴿إِنِّي أَعُوذُ بِالرَّحْمَٰنِ مِنكَ﴾، وقول موسى: ﴿أَعُوذُ بِاللَّهِ أَنْ أَكُونَ مِنَ الْجَاهِلِينَ﴾؟","answer":"استعاذت بالرحمن ليرحمها ويقيها السوء، وذلك مناسب لجوّ الرحمة الذي يشيع في السورة. أما سياق البقرة فسياق عقوبة ومسخ وتنكيل، ولا تناسب الرحمةُ ذاك، فقال: «أعوذ بالله».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص253.","url":""}]},{"id":"s19-158","number":158,"surah":19,"verses":[26],"references":[{"surah":19,"verses":[26]}],"verseLabel":"مريم: 26","question":"ما دلالة لفظ «الصوم» في قولها: ﴿إِنِّي نَذَرْتُ لِلرَّحْمَٰنِ صَوْمًا﴾؟","answer":"خصّ القرآن كلمة «الصوم» بمعنى الصمت، ولم يرد بمعنى العبادة المعروفة إلا «الصيام»، ولذا قالت بعده: ﴿فَلَنْ أُكَلِّمَ الْيَوْمَ إِنسِيًّا﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص72.","url":""}]},{"id":"s19-159","number":159,"surah":19,"verses":[29],"references":[{"surah":19,"verses":[29]}],"verseLabel":"مريم: 29","question":"ما دلالة «المَهْد» في قوله: ﴿كَيْفَ نُكَلِّمُ مَن كَانَ فِي الْمَهْدِ صَبِيًّا﴾ مقابل «المِهَاد»؟","answer":"المَهْد مهد الصبي، وهو الموضع الذي يُهيّأ له ويُوطّأ لينام فيه، أما المِهاد فهو الفراش الواسع، كقوله: ﴿أَلَمْ نَجْعَلِ الْأَرْضَ مِهَادًا﴾، والمهاد أجمع من المهد.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص62.","url":""}]},{"id":"s19-160","number":160,"surah":19,"verses":[31],"references":[{"surah":19,"verses":[31]}],"verseLabel":"مريم: 31","question":"ما سر قوله: ﴿وَأَوْصَانِي بِالصَّلَاةِ وَالزَّكَاةِ﴾ بـ«أوصى» دون «وصّى»؟","answer":"«وصّى» بالتشديد تأتي في القرآن في الدين والأمور المعنوية، و«أوصى» في الأمور المادية كالمواريث. ولم ترد «أوصى» في أمر معنوي إلا في هذا الموطن، لأن الصلاة اقترنت بالزكاة، والزكاة أمر مادي يتعلق بالأموال.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص14.","url":""}]},{"id":"s19-161","number":161,"surah":19,"verses":[65],"references":[{"surah":19,"verses":[65]}],"verseLabel":"مريم: 65","question":"ما دلالة «اصطبر» دون «اصبر» في قوله: ﴿فَاعْبُدْهُ وَاصْطَبِرْ لِعِبَادَتِهِ﴾؟","answer":"أمره بالاصطبار لا بمجرّد الصبر ليدلّ على ثِقل العبادة وأنها تحتاج إلى اصطبار، فالفعل أثقل من الترك، والأمر بالعبادة أمر بفعل دائم.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص178.","url":""}]},{"id":"s19-162","number":162,"surah":19,"verses":[85],"references":[{"surah":19,"verses":[85]}],"verseLabel":"مريم: 85","question":"ما سر قوله: ﴿يَوْمَ نَحْشُرُ الْمُتَّقِينَ إِلَى الرَّحْمَٰنِ وَفْدًا﴾، وفي الزمر: ﴿وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا﴾؟","answer":"الحشر الجمع، والوفد لا بدّ أن يكتمل أفراده، فهم يُجمعون قبل أن يُذهب بهم إلى الرحمن لتكريمهم. أما في الزمر فالسوق جماعات لم تكتمل بعد، حتى إذا اكتملوا جُمعوا وذُهب بهم إلى الرحمن وفدًا.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص81.","url":""}]},{"id":"s19-163","number":163,"surah":19,"verses":[8],"references":[{"surah":19,"verses":[8]}],"verseLabel":"مريم: 8","question":"ما دلالة «الكِبَر» بفتح الباء في قوله: ﴿وَقَدْ بَلَغْتُ مِنَ الْكِبَرِ عِتِيًّا﴾؟","answer":"«الكِبَر» بفتح الباء نقيض الصِّغَر، وخصّه القرآن بالكبر في السنّ، كهذه الآية وقوله: ﴿إِمَّا يَبْلُغَنَّ عِندَكَ الْكِبَرَ﴾. أما «الكِبْر» بسكون الباء فللأمور المعنوية كالتكبّر: ﴿إِن فِي صُدُورِهِمْ إِلَّا كِبْرٌ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص21.","url":""}]},{"id":"s19-164","number":164,"surah":19,"verses":[14,32],"references":[{"surah":19,"verses":[14,32]}],"verseLabel":"مريم: 14، 32","question":"ما سر قوله في يحيى: ﴿وَلَمْ يَكُن جَبَّارًا عَصِيًّا﴾، وقول عيسى: ﴿وَلَمْ يَجْعَلْنِي جَبَّارًا شَقِيًّا﴾؟","answer":"الكلام على يحيى إخبار من الله عنه، وكلام عيسى عن نفسه، فنسب النعمة إلى ربه اعترافًا بالفضل وأدبًا في الكلام. ولا يصلح أن يقول: «ولم أكن» لأن هذا القول بعد الولادة مباشرة وليس له ماضٍ في الدنيا، ولا «ولا أكون» لأن المستقبل غيب. ولما ذكر أنه جعله نبيًّا مباركًا ناسبه نفي الشقاء.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص149–150.","url":""}]},{"id":"s19-165","number":165,"surah":19,"verses":[36],"references":[{"surah":19,"verses":[36]}],"verseLabel":"مريم: 36","question":"ما سر قوله: ﴿وَإِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ﴾ بلا ضمير فصل، وفي الزخرف: ﴿إِنَّ اللَّهَ هُوَ رَبِّي وَرَبُّكُمْ﴾؟","answer":"آية الزخرف قيلت في سياق عبادة عيسى واتخاذه إلهًا وموازنة المشركين بينه وبين آلهتهم: ﴿أَآلِهَتُنَا خَيْرٌ أَمْ هُوَ﴾، فناسب تأكيد الربوبية وقصرها بضمير الفصل. ولم يرد في آيتي آل عمران ومريم من ذكر آلهتهم ما ورد هناك فلم يحتج إليه. وفي «ملاك التأويل» نحو هذا التوجيه.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص150–151.","url":""}]},{"id":"s19-166","number":166,"surah":19,"verses":[45],"references":[{"surah":19,"verses":[45]}],"verseLabel":"مريم: 45","question":"ما سر قول إبراهيم: ﴿إِنِّي أَخَافُ أَن يَمَسَّكَ عَذَابٌ مِّنَ الرَّحْمَٰنِ﴾، وفي الأنعام: ﴿إِنْ أَتَاكُمْ عَذَابُ اللَّهِ﴾؟","answer":"التحذير في الأنعام أشدّ؛ فالإتيان أشدّ من المسّ، وزاد هناك ﴿بَغْتَةً أَوْ جَهْرَةً﴾ وذكر الإهلاك. أما في مريم فنكّر العذاب وجعله من الرحمن المتّصف بالرحمة، لأن إبراهيم ذكر الرحمن قبلها، والسورة أكثر السور ذكرًا لهذا الاسم، وهو بعدها يعده بالاستغفار، والمغفرة تُطلب من الرحمن.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص44–45؛ وج1، ص119.","url":""}]},{"id":"s19-167","number":167,"surah":19,"verses":[64],"references":[{"surah":19,"verses":[64]}],"verseLabel":"مريم: 64","question":"ما سر ذكر الملك في قوله: ﴿لَهُ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا﴾، وذكر العلم في آية الكرسي: ﴿يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ﴾؟","answer":"سياق آية مريم في الملك، فقد ذكر قبلها أنه يرزق أهل الجنة بكرة وعشيًّا ويُورثها من كان تقيًّا، والذي يرزق ويورث مالك، وقال بعدها: ﴿رَبُّ السَّمَاوَاتِ وَالْأَرْضِ﴾ أي مالكهما. أما آية الكرسي ففي سياق العلم: ﴿وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص198.","url":""}]},{"id":"s20-1","number":1,"surah":20,"verses":[1],"references":[{"surah":20,"verses":[1]}],"verseLabel":"طه: 1","question":"ما دلالة افتتاح السورة بـ﴿طه﴾، وهل يُجزم بأنها اسم للنبي؟","answer":"يذكر المصدر أن جمهور المفسرين يعدون «طه» من الحروف المقطعة، ويرجح هذا القول. ويورد أقوالًا أخرى في تفسيرها؛ لذلك لا يصح الجزم من هذا الموضع بأنها اسم للنبي أو نداء له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص625، تحت «شرح المفردات»، المدخل (1): ﴿طه﴾","url":""}]},{"id":"s20-2","number":2,"surah":20,"verses":[2],"references":[{"surah":20,"verses":[2]}],"verseLabel":"طه: 2","question":"ما سرّ التعبير بـ﴿مَا أَنْزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَى﴾؟","answer":"لم ينزل القرآن ليكون سببًا لشقاء الرسول؛ وإنما يجتهد في تبليغه والتذكير به والعبادة دون أن يبلغ بنفسه حد الشقاء. وما يلحقه من جهد في ذلك لا يجعل الوحي عَنتًا، بل هو سبب سعادته وسعادة من اهتدى به.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص631، تحت عنوان «فائدة الجملة الخبرية في الآية»","url":""}]},{"id":"s20-3","number":3,"surah":20,"verses":[3],"references":[{"surah":20,"verses":[3]}],"verseLabel":"طه: 3","question":"ما نكتة اختيار لفظ ﴿تَذْكِرَةً﴾ في مطلع سورة طه؟","answer":"التذكرة ترد الشيء إلى الذهن بعد نسيانه وتديم حفظه؛ فالقرآن يوقظ ما استقر في الفطرة من التوحيد، ويزيل ما عرض لها من الغفلة والشرك، ويذكر بملة إبراهيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص633، تحت عنوان «نكتة التعبير بلفظ ﴿تَذْكِرَةً﴾»","url":""}]},{"id":"s20-141","number":141,"surah":20,"verses":[3],"references":[{"surah":20,"verses":[3]}],"verseLabel":"طه: 3","question":"ما وجها الاستثناء في ﴿مَا أَنْزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَى إِلَّا تَذْكِرَةً لِمَنْ يَخْشَى﴾؟","answer":"يذكر المصدر وجهين: استثناء مفرغ من أعم أحوال إنزال القرآن، بتقدير «ما أنزلناه إلا تذكرة»، فيفيد القصر؛ واستثناء منقطع، لأن التذكرة ليست من جنس الشقاء، أي: لكن أنزلناه تذكرة لمن يخشى، فلا يفيد القصر على هذا الوجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص632، تحت عنوان «معنى الاستثناء في ﴿إِلَّا﴾»","url":""}]},{"id":"s20-4","number":4,"surah":20,"verses":[4],"references":[{"surah":20,"verses":[4]}],"verseLabel":"طه: 4","question":"ما دلالة نسبة تنزيل القرآن إلى ﴿مِمَّنْ خَلَقَ الْأَرْضَ وَالسَّمَاوَاتِ الْعُلَا﴾؟","answer":"تعظم صلة الموصول منزّل القرآن بذكر خلق الأرض والسماوات؛ فمن أنزل هذا الكتاب هو صاحب العظمة والقدرة، وفي ذلك إشعار بنصره رسوله وتأييده في التبليغ، وإلزام بإفراده بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص640، تحت عنوان «بلاغة التعبير في قوله: ﴿مِمَّنْ خَلَقَ﴾»","url":""}]},{"id":"s20-142","number":142,"surah":20,"verses":[4],"references":[{"surah":20,"verses":[4]}],"verseLabel":"طه: 4","question":"ما نكتة وصف السماوات بـ﴿الْعُلَا﴾ في مطلع سورة طه؟","answer":"هو وصف كاشف يؤكد ضخامة السماوات وعلوها، ويزيد تقرير عظمة خالقها وقدرته. وفي مقابلتها بالأرض إشعار بشرف العالم العلوي، مع مراعاة فواصل الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص643، تحت عنوان «نكتة وصف السماوات بـ﴿الْعُلَا﴾»","url":""}]},{"id":"s20-5","number":5,"surah":20,"verses":[5],"references":[{"surah":20,"verses":[5]}],"verseLabel":"طه: 5","question":"ما مناسبة اسم ﴿الرَّحْمَنُ﴾ في ﴿الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى﴾؟","answer":"يفيد أن خلق الأرض والسماوات وما يتصل بتدبير الملك جارٍ برحمة الله؛ ففي اختيار الاسم جمع بين عظمة الملك وشمول الرحمة ومصالح الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص645، تحت عنوان «نكتة التعبير بوصف الرحمن دون غيره»","url":""}]},{"id":"s20-6","number":6,"surah":20,"verses":[6],"references":[{"surah":20,"verses":[6]}],"verseLabel":"طه: 6","question":"ما دلالة الجمع بين ﴿مَا فِي السَّمَاوَاتِ﴾ و﴿مَا تَحْتَ الثَّرَى﴾؟","answer":"كرر «ما» لبيان شمول ملك الله لكل شيء، مع اختلاف أجناس المخلوقات في السماوات والأرض وبينهما وتحت الثرى؛ فلا يخرج شيء من ظاهر الكون أو خفيه عن ملكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص650، تحت عنوان «نكتة تتابع التعبير بـ(ما) في الآية»","url":""}]},{"id":"s20-7","number":7,"surah":20,"verses":[7],"references":[{"surah":20,"verses":[7]}],"verseLabel":"طه: 7","question":"ما دلالة الجمع بين ﴿السِّرَّ وَأَخْفَى﴾ في بيان علم الله؟","answer":"اسم التفضيل يبين أن وراء السر ما هو أشد خفاء، وحذف المفضل عليه يعمم كل ما هو أخفى من السر. فيشمل علم الله حديث النفس وما لم يخطر بالبال مما يكون لاحقًا؛ فلا تقف إحاطته عند ما يسره الإنسان بلسانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص659، تحت عنوان «نكتة التعبير باسم التفضيل ﴿وَأَخْفَى﴾»","url":""}]},{"id":"s20-8","number":8,"surah":20,"verses":[8],"references":[{"surah":20,"verses":[8]}],"verseLabel":"طه: 8","question":"ما سرّ التعبير بـ﴿لَهُ الْأَسْمَاءُ الْحُسْنَى﴾؟","answer":"تقديم «له» يفيد اختصاص الله بالأسماء الحسنى على وجه الكمال؛ فقد يشترك غيره في مجرد الاسم، لكن حقيقة معناه لا تبلغ في المخلوق كمالها الذي يختص به الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص664، تحت عنوان «بلاغة التقديم في قوله: ﴿لَهُ الْأَسْمَاءُ الْحُسْنَى﴾»","url":""}]},{"id":"s20-9","number":9,"surah":20,"verses":[9],"references":[{"surah":20,"verses":[9]}],"verseLabel":"طه: 9","question":"ما دلالة الاستفهام في ﴿وَهَلْ أَتَاكَ حَدِيثُ مُوسَى﴾ في سورة طه؟","answer":"ليس طلبًا لجواب، بل يقرر الخبر ويشوق إلى سماعه وينبه إلى عظم شأنه؛ فيتهيأ السامع للإصغاء إلى القصة والاعتبار بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص669–670، تحت عنوان «بلاغة الاستفهام المجازي في الآية»","url":""}]},{"id":"s20-10","number":10,"surah":20,"verses":[10],"references":[{"surah":20,"verses":[10]}],"verseLabel":"طه: 10","question":"ما سرّ التعبير في قول موسى بـ﴿آنَسْتُ نَارًا﴾ لا «رأيت»؟","answer":"الإيناس هنا رؤية بينة لا شبهة فيها، ومعها شعور بالأنس والسكون إلى النار في وحشة الليل وشدة البرد؛ لذلك اتصل بها رجاؤه أن يجد قبسًا أو دلالة على الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص675–676، تحت عنوان «نكتة العدول إلى لفظ ﴿آنَسْتُ﴾»","url":""}]},{"id":"s20-11","number":11,"surah":20,"verses":[10],"references":[{"surah":20,"verses":[10]}],"verseLabel":"طه: 10","question":"لماذا قُدّم القبس في قول موسى في طه، وقُدّم الخبر في النمل والقصص؟","answer":"في طه يناسب تقديم القبس حال موسى وأهله في السفر والبرد، رجاء الانتفاع بالنار. وفي النمل قُدم الخبر، وهو المطلوب الأعم، إذ لم يتقدم ذكر مشقة السفر؛ وفي القصص ناسبه ما سبق من حديث موسى ورحلته وأخبارها. فلكل ترتيب مناسبته في سياق السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص682، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s20-143","number":143,"surah":20,"verses":[10],"references":[{"surah":20,"verses":[10]}],"verseLabel":"طه: 10","question":"ما المراد بـ﴿هُدًى﴾ في قول موسى: ﴿أَوْ أَجِدُ عَلَى النَّارِ هُدًى﴾؟","answer":"يتسع الهدى لما يدل على الطريق: طريق أو مرشد أو علامة؛ فموسى يرجو ما يخرجه من ضلال الطريق. ويذكر المصدر احتمال إرادة شخص هادٍ، مع ترجيح المعنى الأعم الذي يشمل وجوه الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص679، تحت عنوان «نكتة التعبير بلفظ ﴿هُدًى﴾ وتنكيرها»","url":""}]},{"id":"s20-144","number":144,"surah":20,"verses":[10],"references":[{"surah":20,"verses":[10]}],"verseLabel":"طه: 10","question":"ما الفرق بين «قبس» في طه و«شهاب قبس» في النمل و«جذوة» في القصص؟","answer":"القبس أعم: جزء يؤخذ من النار للانتفاع به، والجذوة قطعة من الحطب فيها نار، والشهاب لهب النار. فذكر الشهاب والجذوة يلائم التصريح بالاصطلاء في النمل والقصص، وذكر القبس في طه يلائم مطلق الانتفاع دون التصريح بالاصطلاء؛ فلا تتعارض هذه الأوصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص681، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s20-12","number":12,"surah":20,"verses":[11],"references":[{"surah":20,"verses":[11]}],"verseLabel":"طه: 11","question":"ما معنى الفاء في ﴿فَلَمَّا أَتَاهَا نُودِيَ يَا مُوسَى﴾؟","answer":"تفيد الترتيب والتعقيب: مضى موسى إلى النار عقب إخبار أهله بعزمه على ذلك، وتعقيب كل شيء بحسب وقته وحاله، فلا يلزم منه نفي زمن السير.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص687، تحت عنوان «معنى الفاء في قوله ﴿فَلَمَّا﴾»","url":""}]},{"id":"s20-145","number":145,"surah":20,"verses":[11],"references":[{"surah":20,"verses":[11]}],"verseLabel":"طه: 11","question":"ما دلالة ﴿لَمَّا﴾ في ﴿فَلَمَّا أَتَاهَا نُودِيَ يَا مُوسَى﴾؟","answer":"تربط النداء بوقت إتيانه النار؛ فبعد أن سار إليها بلغ الموضع المبارك، فكان النداء عند وصوله تكريمًا وتشريفًا. وقد أوجز السياق بحذف ذكر السير المفهوم مما قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص687، تحت عنوان «بلاغة التعبير بـ﴿فَلَمَّا﴾»","url":""}]},{"id":"s20-146","number":146,"surah":20,"verses":[11],"references":[{"surah":20,"verses":[11]}],"verseLabel":"طه: 11","question":"ما نكتة بناء ﴿نُودِيَ﴾ لما لم يسم فاعله في قصة موسى بطه؟","answer":"إبهام المنادي يشوق إلى معرفته، ثم يأتي ﴿إِنِّي أَنَا رَبُّكَ﴾ فيتمكن العلم به في النفس. ويصور التعبير حال موسى حين سمع النداء قبل أن يعرف مناديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص687–688، تحت عنوان «نكتة بناء الفعل ﴿نُودِيَ﴾»","url":""}]},{"id":"s20-13","number":13,"surah":20,"verses":[12],"references":[{"surah":20,"verses":[12]}],"verseLabel":"طه: 12","question":"ما دلالة أمر موسى بخلع نعليه في الوادي المقدس؟","answer":"يشرح المصدر خلع النعلين بأنه تعظيم للموضع الذي يسمع فيه موسى كلام الله، وإظهار للخضوع والتواضع. وتعقيب الأمر بقوله «إنك بالواد المقدس طوى» يبين مناسبة الخلع لبركة المكان وتقديسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص690، تحت عنوان «دلالة التعبير بالفعل ﴿فَاخْلَعْ﴾»","url":""}]},{"id":"s20-14","number":14,"surah":20,"verses":[12],"references":[{"surah":20,"verses":[12]},{"surah":79,"verses":[16]}],"verseLabel":"طه: 12؛ النازعات: 16","question":"ما دلالة وصف الوادي الذي نودي فيه موسى بـ﴿الْمُقَدَّسِ﴾؟","answer":"يدل الوصف على أنه موضع مطهر مبارك مشرف؛ وقد ازداد تشريفًا بوقوع النداء والتكليم والوحي فيه. وصيغة «المقدس» تؤكد غاية التطهير والمبالغة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج65، ص778، تحت عنوان «نكتة وصف الوادي بالمقدس»","url":""}]},{"id":"s20-147","number":147,"surah":20,"verses":[12],"references":[{"surah":20,"verses":[12]},{"surah":79,"verses":[16]}],"verseLabel":"طه: 12؛ النازعات: 16","question":"ما المراد بـ﴿طُوًى﴾ في وصف الوادي الذي نودي فيه موسى؟","answer":"هو اسم الوادي على قول جمهور المفسرين؛ فذكره بعد «الواد المقدس» يعيّن الموضع ويوضحه. ويذكر المصدر أقوالًا أخرى، فلا تعرض التسمية باعتبارها القول الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص691–692، تحت عنوان «دلالة التعبير بـ﴿طُوًى﴾»","url":""}]},{"id":"s20-15","number":15,"surah":20,"verses":[13],"references":[{"surah":20,"verses":[13]}],"verseLabel":"طه: 13","question":"ما دلالة تقديم ﴿أَنَا﴾ على الفعل في ﴿وَأَنَا اخْتَرْتُكَ﴾؟","answer":"يقوي الإخبار باختيار الله موسى ويثبت قلبه؛ لأن غرابة هذا الخبر والمناجاة قد تعرض النفس للشك. فالمقصود تقوية الحكم ودفع الشك، لا إفادة التخصيص في هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص694، تحت عنوان «دلالة تقديم المسند إليه على المسند الفعلي في ﴿وَأَنَا اخْتَرْتُكَ﴾»","url":""}]},{"id":"s20-148","number":148,"surah":20,"verses":[13],"references":[{"surah":20,"verses":[13]}],"verseLabel":"طه: 13","question":"ما دلالة الفاء في ﴿فَاسْتَمِعْ لِمَا يُوحَى﴾ بعد ﴿وَأَنَا اخْتَرْتُكَ﴾؟","answer":"ترتب الأمر بالاستماع على الاختيار؛ فمن أثر اختيار موسى أن يتلقى ما يوحيه الله إليه ويصغي له. فالفاء تصل الاصطفاء بمقتضاه من تلقي الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص696، تحت عنوان «معنى الفاء ودلالتها في ﴿فَاسْتَمِعْ﴾»","url":""}]},{"id":"s20-16","number":16,"surah":20,"verses":[14],"references":[{"surah":20,"verses":[14]}],"verseLabel":"طه: 14","question":"ما دلالة توالي المؤكدات في ﴿إِنَّنِي أَنَا اللَّهُ لَا إِلَهَ إِلَّا أَنَا﴾؟","answer":"تقوي المؤكدات الخبر وتدفع ما قد يعرض للنفس من الشك عند غرابة المناجاة؛ فيعلم موسى أن المتكلم هو الله. ويقرر النفي والاستثناء انفراده بالألوهية، فتثبت المعرفة التي ينبني عليها الأمر بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص703، تحت عنوان «بلاغة توالي المؤكدات في الآية الكريمة»","url":""}]},{"id":"s20-17","number":17,"surah":20,"verses":[14],"references":[{"surah":20,"verses":[14]}],"verseLabel":"طه: 14","question":"ما سرّ التعبير بـ﴿وَأَقِمِ الصَّلَاةَ لِذِكْرِي﴾؟","answer":"على وجه التعليل، المعنى: أقم الصلاة لأجل ذكري؛ فإنها تذكر العبد بخالقه وتشعره بأنه واقف بين يديه للمناجاة. فالأمر بإقامتها يربط الذكر بالعبادة العملية التي يتحقق فيها كماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص710–711، تحت عنوان «معنى اللام ودلالتها في ﴿لِذِكْرِي﴾»","url":""}]},{"id":"s20-18","number":18,"surah":20,"verses":[15],"references":[{"surah":20,"verses":[15]}],"verseLabel":"طه: 15","question":"ما سرّ التعبير عن الساعة بـ﴿أَكَادُ أُخْفِيهَا﴾؟","answer":"يعرض المصدر العبارة على أسلوب العرب في المبالغة في كتمان السر، كقولهم «أخفيته من نفسي»، أي بلغ إخفاؤه الغاية. والمقصود إخفاء وقت الساعة مع القطع بإتيانها؛ ليبقى الناس على حذر واستعداد، لا أن شيئًا يخفى على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص718، تحت عنوان «دلالة التعبير بالمضارع في قوله: ﴿أَكَادُ﴾»","url":""}]},{"id":"s20-19","number":19,"surah":20,"verses":[16],"references":[{"surah":20,"verses":[16]}],"verseLabel":"طه: 16","question":"ما سرّ التعبير بـ﴿فَلَا يَصُدَّنَّكَ عَنْهَا مَنْ لَا يُؤْمِنُ بِهَا﴾؟","answer":"جاء النهي في ظاهره عن صد الكافر موسى عن الساعة، وهو في معناه نهي لموسى عن الانصراف عنها وعن أسباب ذلك. فالنهي عن السبب ومباديه مبالغة في لزوم الإيمان والعمل والاستعداد، وأكد الفعل بنون التوكيد الثقيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص725–726، تحت عنوان «دلالة النهي في قوله: ﴿فَلَا يَصُدَّنَّكَ﴾»","url":""}]},{"id":"s20-20","number":20,"surah":20,"verses":[17],"references":[{"surah":20,"verses":[17]}],"verseLabel":"طه: 17","question":"ما دلالة سؤال الله موسى: ﴿وَمَا تِلْكَ بِيَمِينِكَ﴾ مع علمه بها؟","answer":"هو استفهام تقريري يثبت في نفس موسى أن ما يمسكه عصاه المألوفة، حتى إذا انقلبت حية تيقن أنها العصا نفسها. وفي استمرار المكالمة طمأنة لقلبه وإيناس له في مقام الإصغاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص735، تحت عنوان «بلاغة الاستفهام ﴿وَمَا﴾»","url":""}]},{"id":"s20-21","number":21,"surah":20,"verses":[18],"references":[{"surah":20,"verses":[18]}],"verseLabel":"طه: 18","question":"ما دلالة بسط موسى جوابه وذكر منافع العصا في مقام المناجاة؟","answer":"بسط موسى الجواب وذكر المسند إليه مع إمكان الاستغناء عنه؛ لما وجده من لذة المناجاة، فاغتنم مقام الخطاب وأطال الجواب بما يلائم الأدب. كما أجاب بما يوضح مقصوده من اتخاذ العصا ومنافعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص737، تحت عنوان «نكتة التعبير بالضمير المنفصل ﴿هِيَ﴾»","url":""}]},{"id":"s20-22","number":22,"surah":20,"verses":[18],"references":[{"surah":20,"verses":[18]}],"verseLabel":"طه: 18","question":"ما دلالة لفظ ﴿أَهُشُّ﴾ في قول موسى: ﴿وَأَهُشُّ بِهَا عَلَى غَنَمِي﴾؟","answer":"الهش هنا خبط أغصان الشجر بالعصا ليسقط ورقها فتأكله الغنم. وفي اللفظ معنى اللين والرفق، فيصور عناية موسى بغنمه ولطفه بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص741، تحت عنوان «دلالة التعبير ﴿وَأَهُشُّ﴾»","url":""}]},{"id":"s20-149","number":149,"surah":20,"verses":[18],"references":[{"surah":20,"verses":[18]}],"verseLabel":"طه: 18","question":"ما دلالة المضارع في ﴿أَتَوَكَّأُ عَلَيْهَا وَأَهُشُّ بِهَا عَلَى غَنَمِي﴾؟","answer":"يفيد التجدد والتكرر؛ فالاتكاء في المشي ورعاية الغنم وإطعامها أعمال تتكرر، واستخدام العصا فيها مستمر. فجاء المضارع مناسبًا لهذه المنافع المتجددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص740، تحت عنوان «دلالة التعبير بالمضارع في قوله: ﴿وَأَهُشُّ﴾ و: ﴿أَتَوَكَّأُ﴾»","url":""}]},{"id":"s20-23","number":23,"surah":20,"verses":[20],"references":[{"surah":20,"verses":[20]}],"verseLabel":"طه: 20","question":"ما دلالة وصف العصا بعد تحولها بأنها ﴿حَيَّةٌ تَسْعَى﴾؟","answer":"وصفها بالسعي يثبت أنها حية كاملة الحياة والحركة، وليست صورة جامدة ولا تخييلًا. والمضارع يستحضر حركتها المتجددة كأن السامع يراها الآن، فيتأكد انقلاب العصا حقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص751، تحت عنوان «نكتة التعبير بالمضارع ﴿تَسْعَى﴾ بعد الماضي ﴿فَأَلْقَاهَا﴾»","url":""}]},{"id":"s20-24","number":24,"surah":20,"verses":[21],"references":[{"surah":20,"verses":[21]}],"verseLabel":"طه: 21","question":"ما دلالة تعدية ﴿سَنُعِيدُهَا سِيرَتَهَا الْأُولَى﴾ دون ذكر «إلى»؟","answer":"إفضاء الفعل مباشرة إلى مفعوله، دون «إلى سيرتها»، يصور تحقق العودة سريعًا بلا مهلة؛ فكما انقلبت العصا حية تُرد إلى هيئتها المألوفة عصًا. وفي ذلك بيان لقدرة الله على الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص754، تحت عنوان «نكتة تعدية الفعل بنفسه دون تعديته بالحرف (إلى)»","url":""}]},{"id":"s20-25","number":25,"surah":20,"verses":[22],"references":[{"surah":20,"verses":[22]}],"verseLabel":"طه: 22","question":"ما سرّ وصف اليد بأنها تخرج ﴿بَيْضَاءَ مِنْ غَيْرِ سُوءٍ﴾؟","answer":"لو اقتصر على «بيضاء» لأمكن توهم البرص أو عيب في اليد؛ فجاء «من غير سوء» لينفي ذلك ويبين أن البياض آية خارقة للعادة، لا مرضًا ولا عيبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص764، تحت عنوان «نكتة الإطناب بالاحتراس في قوله: ﴿مِنْ غَيْرِ سُوءٍ﴾»","url":""}]},{"id":"s20-26","number":26,"surah":20,"verses":[23],"references":[{"surah":20,"verses":[23]}],"verseLabel":"طه: 23","question":"ما سرّ التعبير بـ﴿لِنُرِيَكَ مِنْ آيَاتِنَا الْكُبْرَى﴾؟","answer":"علل إظهار العصا واليد بإراءة موسى بعض آيات الله الكبرى أولًا؛ ليعلم قدرته ويقوى قلبه قبل مناظرة فرعون. فالمعجزتان تهيئة له لما سيظهره بعد ذلك في مقام التحدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص767، تحت عنوان «معنى اللام ودلالتها في ﴿لِنُرِيَكَ﴾»","url":""}]},{"id":"s20-27","number":27,"surah":20,"verses":[24],"references":[{"surah":20,"verses":[24]}],"verseLabel":"طه: 24","question":"ما وجه تعليل الأمر بالذهاب إلى فرعون بقوله: ﴿إِنَّهُ طَغَى﴾؟","answer":"الجملة جواب عن سؤال مقدر: لماذا أذهب إلى فرعون؟ فقد تجاوز حد الكفر والتجبر حتى ادعى الربوبية، فكان طغيانه علة لإرساله إليه بالدعوة والإنذار. وفي بيان ذلك تهيئة لموسى لما يلقاه من صعوبة المهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص773، تحت عنوان «علة فصل قوله: ﴿إِنَّهُ طَغَى﴾ عن سابقه»","url":""}]},{"id":"s20-28","number":28,"surah":20,"verses":[25],"references":[{"surah":20,"verses":[25]}],"verseLabel":"طه: 25","question":"ما دلالة بدء موسى دعاءه بـ﴿رَبِّ اشْرَحْ لِي صَدْرِي﴾؟","answer":"قدم طلب شرح الصدر ليزول من نفسه ما يعوق الإقدام على المهمة، ويتسع قلبه لتحمل أعباء الرسالة وأذى الناس بحلم وصبر؛ فتهيئة النفس تسبق ما طلبه من أسباب حسن التبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص779، تحت عنوان «سر تقديم سؤال الشرح على غيره مما سُئل»","url":""}]},{"id":"s20-29","number":29,"surah":20,"verses":[26],"references":[{"surah":20,"verses":[26]}],"verseLabel":"طه: 26","question":"ما دلالة طلب موسى ﴿وَيَسِّرْ لِي أَمْرِي﴾ عقب تكليفه بالرسالة؟","answer":"الأمر هنا دعاء يظهر افتقار موسى إلى الله وتضرعه؛ طلب أن يسهل عليه القيام بأعباء الرسالة وتحمل واجباتها، فالمطلوب الإعانة على أداء ما كلف به.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص781، تحت عنوان «الغرض من التعبير بفعل الأمر: ﴿وَيَسِّرْ﴾»","url":""}]},{"id":"s20-30","number":30,"surah":20,"verses":[27,28],"references":[{"surah":20,"verses":[27,28]}],"verseLabel":"طه: 27-28","question":"ما الغرض من تنكير ﴿عُقْدَةً﴾ في دعاء موسى: ﴿وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي﴾؟","answer":"من الأوجه المذكورة أنه سأل حل ما يمنع الناس من فهمه، لا بلوغ غاية الفصاحة؛ لأن غرضه التبليغ الذي يقتضيه البيان المفهوم. ويذكر المصدر أيضًا وجه التعظيم لشدة العقدة وثقلها، فلا يحصر التنكير في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص783، تحت عنوان «الغرض من تنكير ﴿عُقْدَةً﴾ وتوجيه المراد بها»","url":""}]},{"id":"s20-31","number":31,"surah":20,"verses":[29,30,31,32],"references":[{"surah":20,"verses":[29,30,31,32]}],"verseLabel":"طه: 29-32","question":"لماذا وصف موسى هارون بالأخوة عند طلبه وزيرًا يعينه في الدعوة؟","answer":"جعل طلبه مشفوعًا بعلته؛ فهو يريد وزيرًا مخلصًا أمينًا يكون محل ثقته، وهارون معروف عنده بأصالة الرأي. فذكر الأخوة يبرز سبب اختيار هذا المعين ومؤازرته، لا مجرد طلب أي وزير.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص792، تحت عنوان «بلاغة الإطناب بذكر وصف الأخوة بعد قوله: ﴿هَارُونَ﴾»","url":""}]},{"id":"s20-32","number":32,"surah":20,"verses":[33,34],"references":[{"surah":20,"verses":[33,34]}],"verseLabel":"طه: 33-34","question":"ما دلالة «كي» في جعل التسبيح والذكر غاية لطلب موسى مؤازرة هارون؟","answer":"جعل موسى التسبيح والذكر غاية لطلبه أن يكون هارون وزيرًا له، وأن يشد به أزره ويشاركه في أمره؛ فالمؤازرة مطلوبة للإعانة على عبادة الله والإكثار منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص796، تحت عنوان «معنى ﴿كَيْ﴾ ودلالتها في قوله: ﴿كَيْ نُسَبِّحَكَ﴾»","url":""}]},{"id":"s20-150","number":150,"surah":20,"verses":[33,34],"references":[{"surah":20,"verses":[33,34]}],"verseLabel":"طه: 33-34","question":"ما الغرض من تكرير ﴿كَثِيرًا﴾ في ﴿كَيْ نُسَبِّحَكَ كَثِيرًا وَنَذْكُرَكَ كَثِيرًا﴾؟","answer":"يخص كلًّا من التسبيح والذكر بالكثرة: تنزيهًا كثيرًا في زمان كثير، وثناءً بصفات الكمال كثيرًا في وقت كثير. فالتكرير مع دلالة اللفظ على الكثرة يبالغ في طلب كثرة لا يحدها حد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص797–798، تحت عنوان «الغرض من تكرير ﴿كَثِيرًا﴾ في الموضعين»","url":""}]},{"id":"s20-33","number":33,"surah":20,"verses":[35],"references":[{"surah":20,"verses":[35]}],"verseLabel":"طه: 35","question":"ما الغرض من تقديم ﴿بِنَا﴾ على ﴿بَصِيرًا﴾ في دعاء موسى؟","answer":"يفيد تقوية الخبر وتأكيد إحاطة علم الله بحالهما؛ فإشعار التقديم بالتخصيص هنا للمبالغة في التأكيد، لا لقصر بصر الله عليهما. كما يراعي هذا التقديم فواصل الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص800، تحت عنوان «الغرض من تقديم شبه الجملة على الخبر في قوله: ﴿إِنَّكَ كُنْتَ بِنَا بَصِيرًا﴾»","url":""}]},{"id":"s20-151","number":151,"surah":20,"verses":[35],"references":[{"surah":20,"verses":[35]}],"verseLabel":"طه: 35","question":"ما دلالة الماضي ﴿كُنْتَ﴾ في قول موسى: ﴿إِنَّكَ كُنْتَ بِنَا بَصِيرًا﴾؟","answer":"يقوي التعبير بالماضي ثبوت الخبر وتحققه واستمراره في الزمن الماضي، ويجتمع مع توكيد الجملة بـ«إن». فلا يعرض بصر الله بحالهما أمرًا مستحدثًا عند الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص799–800، تحت عنوان «دلالة التعبير بفعل الكون ماضيًا: ﴿كُنْتَ﴾»","url":""}]},{"id":"s20-34","number":34,"surah":20,"verses":[36],"references":[{"surah":20,"verses":[36]}],"verseLabel":"طه: 36","question":"لماذا قيل لموسى: ﴿أُوتِيتَ سُؤْلَكَ﴾ بدلًا من «أوتيت ما سألت»؟","answer":"«ما سألت» تخصص العطاء بما طلبه في هذا المقام، أما «سؤلك» فتشمل مطالبه فيه وما قبله وما بعده، كما يبين المصدر؛ فالتعبير أوسع في بيان شمول الإجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص12، تحت عنوان «سر العدول عن (أوتيت ما سألت) إلى ﴿أُوتِيتَ سُؤْلَكَ﴾»","url":""}]},{"id":"s20-152","number":152,"surah":20,"verses":[36],"references":[{"surah":20,"verses":[36]}],"verseLabel":"طه: 36","question":"ما دلالة ﴿قَدْ﴾ في قوله لموسى: ﴿قَدْ أُوتِيتَ سُؤْلَكَ﴾؟","answer":"تؤكد «قد» مع الماضي تحقق الإجابة فتطمئن موسى إلى قبول دعائه. ويذكر المصدر فيها أيضًا التقريب، أي قرب الإجابة، والتوقع؛ لأنها جاءت جوابًا لسؤاله وتطلعه إلى ما سأل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص11–12، تحت عنوان «دلالة التعبير بحرف التحقيق»","url":""}]},{"id":"s20-35","number":35,"surah":20,"verses":[37],"references":[{"surah":20,"verses":[37]}],"verseLabel":"طه: 37","question":"ما دلالة تذكير موسى بالمنة عليه ﴿مَرَّةً أُخْرَى﴾؟","answer":"«أخرى» بمعنى غير هذه المنة، وقد تكون سابقة لها في الزمن. يذكره الله بحفظه وكفالته عند ولادته ليطمئن إلى استمرار العناية به بعد تأهيله للرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص16، تحت عنوان «نكتة مجيء قوله: ﴿مَرَّةً﴾ نكرة موصوفة ﴿أُخْرَى﴾»","url":""}]},{"id":"s20-153","number":153,"surah":20,"verses":[37],"references":[{"surah":20,"verses":[37]}],"verseLabel":"طه: 37","question":"ما بلاغة إجمال المنة على موسى في ﴿مَرَّةً أُخْرَى﴾ قبل تفصيلها؟","answer":"الإجمال قبل التفصيل يؤكد المعنى بذكره مرتين، إحداهما مجملة والأخرى مفصلة، ويشوق السامع إلى معرفة تفاصيل النعمة التي أُجملت له.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص16، تحت عنوان «بلاغة الإطناب بالتفصيل بعد الإجمال في قوله: ﴿مَرَّةً أُخْرَى﴾»","url":""}]},{"id":"s20-36","number":36,"surah":20,"verses":[38],"references":[{"surah":20,"verses":[38]}],"verseLabel":"طه: 38","question":"ما دلالة تسمية ما أُلقي إلى أم موسى ﴿وَحْيًا﴾؟","answer":"من أوجه الوحي هنا إلهام أم موسى بما تصنع بولدها وإلقاء اليقين في قلبها؛ إذ لا يكون إقدامها على هذا الأمر المعتاد الخوف منه بتدبير بشري مجرد. وتسميته وحيًا لا تجعله وحي نبوة، فقد ورد الوحي لغير الأنبياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص21–22، تحت عنوان «سر التعبير بالوحي في قوله: ﴿أَوْحَيْنَا﴾»","url":""}]},{"id":"s20-37","number":37,"surah":20,"verses":[39],"references":[{"surah":20,"verses":[39]}],"verseLabel":"طه: 39","question":"لماذا تكرر الأمر بالقذف في ﴿اقْذِفِيهِ فِي التَّابُوتِ فَاقْذِفِيهِ فِي الْيَمِّ﴾؟","answer":"لتعدد المعنى: القذف الأول وضع موسى في التابوت، والثاني الإلقاء في اليم على حقيقة معنى القذف. ويذكر المصدر احتمال عود الضمير الثاني إلى التابوت أو إلى موسى، والقصد في الحالين إنفاذ الأمر المتعلق بموسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص33–34، تحت عنوان «سر تكرار الأمر بالقذف»","url":""}]},{"id":"s20-38","number":38,"surah":20,"verses":[39],"references":[{"surah":20,"verses":[39]}],"verseLabel":"طه: 39","question":"ما سرّ التعبير بـ﴿وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِنِّي﴾؟","answer":"صور تعلق المحبة به بالإلقاء: خلق الله له المحبة في القلوب من غير سبب عادي، حتى أحبه فرعون وامرأته. ففي التعبير بيان عناية الله ورعايته له، وأن هذه المحبة مقدرة منه تتجاوز أسباب البشر المعتادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص42–43، تحت عنوان «سر التعبير بالإلقاء في قوله: ﴿وَأَلْقَيْتُ﴾»","url":""}]},{"id":"s20-39","number":39,"surah":20,"verses":[40],"references":[{"surah":20,"verses":[40]}],"verseLabel":"طه: 40","question":"ما سرّ التعبير بـ﴿فَرَجَعْنَاكَ إِلَى أُمِّكَ كَيْ تَقَرَّ عَيْنُهَا﴾؟","answer":"إسناد الرجوع إلى أمه يمهد لذكر قرة عينها؛ فالنعمة مشتركة بينهما: عادت هي إلى رضاعه وكفالته، وهو عاد إلى حنانها وتربيتها. وهكذا جمع تفضل الله بين رعاية موسى وإسعاد أمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص63، تحت عنوان «سر إسناد الرجوع إلى أم موسى في السياق»","url":""}]},{"id":"s20-40","number":40,"surah":20,"verses":[41],"references":[{"surah":20,"verses":[41]}],"verseLabel":"طه: 41","question":"ما دلالة اختيار الاصطناع دون الصنع في ﴿وَاصْطَنَعْتُكَ لِنَفْسِي﴾؟","answer":"الاصطناع أبلغ في الإكرام من الصنع؛ فالزيادة في بنائه تقوي المعنى. وهو يدل هنا على اختيار موسى وتقريبه وجعله من خواصه سبحانه، فيبرز العناية الخاصة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص85، تحت عنوان «سر التعبير بالاصطناع دون الصنع»","url":""}]},{"id":"s20-154","number":154,"surah":20,"verses":[41],"references":[{"surah":20,"verses":[41]}],"verseLabel":"طه: 41","question":"ما دلالة اللام في ﴿لِنَفْسِي﴾ من قوله: ﴿وَاصْطَنَعْتُكَ لِنَفْسِي﴾؟","answer":"هي لام الأجل؛ أي جعلتك قائمًا بأمري من إقامة الحجة وتبليغ الرسالة. فتكون حركاتك وسكناتك في ذلك لي، لا لنفسك ولا لأحد سواي، وهو معنى إخلاص المهمة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص85، تحت عنوان «دلالة اللام في شبه الجملة: ﴿لِنَفْسِي﴾»","url":""}]},{"id":"s20-41","number":41,"surah":20,"verses":[42],"references":[{"surah":20,"verses":[42]}],"verseLabel":"طه: 42","question":"ما سرّ التعبير بـ﴿وَلَا تَنِيَا فِي ذِكْرِي﴾؟","answer":"يوجه التعبير إلى استغراق أوقاتهما بالذكر؛ فهو يقوي فؤاديهما بالطمأنينة فلا يهابانه. ومن يلازم ذكر الله ولا يفتر عنه يستحضر معيته ويثبت قلبه عند مواجهة فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص92، تحت عنوان «دلالة التعبير بالظرفية ﴿فِي﴾»","url":""}]},{"id":"s20-42","number":42,"surah":20,"verses":[43,44],"references":[{"surah":20,"verses":[43,44]}],"verseLabel":"طه: 43-44","question":"ما دلالة أمر موسى وهارون بالقول اللين لفرعون؟","answer":"القول اللين أقرب إلى القلب وأدعى إلى الإصغاء والقبول؛ فالمقصود اهتداء المدعو. وقد جاء عرض الدعوة على فرعون بصيغة العرض والمشورة، حتى لا تدفعه الحماقة إلى التجبر والعناد عند الإغلاظ عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص103، تحت عنوان «بلاغة التعبير بالقول اللين في دعوة فرعون والطغاة»","url":""}]},{"id":"s20-43","number":43,"surah":20,"verses":[44],"references":[{"surah":20,"verses":[44]}],"verseLabel":"طه: 44","question":"إلى من يرجع الترجي في ﴿لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى﴾؟","answer":"يرجع الترجي إلى موسى وهارون: اذهبا على رجائكما وطمعكما في انتفاع فرعون؛ ليجدا في دعوته ويباشرا الأمر باهتمام. ولا يرجع إلى تردد في علم الله؛ فهو يعلم ما كان وما سيكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص104، تحت عنوان «دلالة الترجي في قوله: ﴿لَعَلَّهُ﴾»","url":""}]},{"id":"s20-44","number":44,"surah":20,"verses":[45],"references":[{"surah":20,"verses":[45]}],"verseLabel":"طه: 45","question":"ما سر اختيار ﴿يَفْرُطَ عَلَيْنَا﴾ في خوف موسى وهارون من فرعون؟","answer":"يفيد أن يعاجلهما فرعون بالعقوبة فلا يتأنى لسماع ما يعرضانه عليه. فالخوف من مبادرته بالأذى قبل إتمام البيان، لا من مجرد حصول العقوبة بعد استيفاء سماع الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص111–112، تحت عنوان «سر التعبير بالفعل ﴿يَفْرُطَ﴾ دون غيره»","url":""}]},{"id":"s20-155","number":155,"surah":20,"verses":[45],"references":[{"surah":20,"verses":[45]}],"verseLabel":"طه: 45","question":"ما دلالة ذكر ﴿أَنْ يَطْغَى﴾ بعد ﴿أَنْ يَفْرُطَ عَلَيْنَا﴾؟","answer":"يعرض المصدر الانتقال على أنه من الأشد إلى الأضعف: يخافان المعاجلة بالعقاب، ويرجوان ألا يقع منه الطغيان عليهما أصلًا، فضلًا عن صورته الأشد. فالمقصود نفي الأذى من أصله، ولا يفسر الترتيب هنا بأنه زيادة في الأذى بعد وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص113، تحت عنوان «دلالة ذكر ﴿أَنْ يَطْغَى﴾ بعد ﴿أَنْ يَفْرُطَ﴾»","url":""}]},{"id":"s20-45","number":45,"surah":20,"verses":[46],"references":[{"surah":20,"verses":[46]}],"verseLabel":"طه: 46","question":"ما سرّ التعبير بـ﴿إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَى﴾؟","answer":"جمع السمع والرؤية لأن المواجهة بين الرسولين وفرعون تشتمل على القول والفعل؛ فيناسب السمع القول، والرؤية الفعل. وفي هذا تأكيد حفظ خاص مستمر لهما من أذى فرعون وعدوانه، يثبت قلبيهما عند الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص120، تحت عنوان «دلالة الجمع بين السمع والرؤية»","url":""}]},{"id":"s20-46","number":46,"surah":20,"verses":[47],"references":[{"surah":20,"verses":[47]}],"verseLabel":"طه: 47","question":"ما الغرض من ختام خطاب موسى وهارون لفرعون بـ﴿وَالسَّلَامُ عَلَى مَنِ اتَّبَعَ الْهُدَى﴾؟","answer":"هي جملة جامعة تدعوه إلى الإيمان والانقياد، وتبشر من اتبع الهدى بالسلامة في الدنيا والآخرة. كما تحذر من عاقبة التكذيب والإعراض؛ فربط السلامة باتباع الهدى يحمل الوعد والتحذير في خطاب موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص137، تحت عنوان «سر ختام تكليفات الله موسى وهارون بالتحية»","url":""}]},{"id":"s20-47","number":47,"surah":20,"verses":[49],"references":[{"surah":20,"verses":[49]}],"verseLabel":"طه: 49","question":"ما دلالة التثنية في ﴿فَمَنْ رَبُّكُمَا﴾ وتخصيص موسى بالنداء في ﴿يَا مُوسَى﴾؟","answer":"الخطاب موجه إلى موسى وهارون معًا، ثم خص موسى بالنداء؛ لأنه الأصل في الرسالة والمتولي للكلام، وهارون تابع له ومعين. ويذكر المصدر وجوهًا أخرى، منها معرفة فرعون السابقة بموسى حين تربى عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص148–149، تحت عنوان «دلالة تثنية خطاب فرعون لهما، وتخصيص موسى بالنداء»","url":""}]},{"id":"s20-48","number":48,"surah":20,"verses":[50],"references":[{"surah":20,"verses":[50]}],"verseLabel":"طه: 50","question":"ما دلالة تعريف موسى ربه بأنه ﴿أَعْطَى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَى﴾؟","answer":"جمع الجواب في ألفاظ قليلة إعطاء كل شيء خلقه وهدايته إلى الانتفاع بما أُعطي. فعرّف موسى ربه بآثار صنعه وتدبيره، وسلك طريق الاستدلال والإرشاد بعبارة موجزة جامعة تبلغ بالحجة غايتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص159، تحت عنوان «بلاغة الإيجاز في جواب موسى لفرعون»","url":""}]},{"id":"s20-49","number":49,"surah":20,"verses":[51],"references":[{"surah":20,"verses":[51]}],"verseLabel":"طه: 51","question":"ما دلالة انتقال فرعون إلى السؤال: ﴿فَمَا بَالُ الْقُرُونِ الْأُولَى﴾؟","answer":"لما قامت الحجة عليه أراد التشغيب بنقل الحديث إلى مصير القرون السابقة: فإن قيل إنهم في عذاب ثارت أبناؤهم، وإن قيل إنهم في سلام اتخذ ذلك حجة لدينهم. فهو عدول عن الاعتناء بالخلق الأول إلى سؤال تعجيز وتشغيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص164، تحت عنوان «دلالة احتجاج فرعون بالقرون الأولى»","url":""}]},{"id":"s20-50","number":50,"surah":20,"verses":[52],"references":[{"surah":20,"verses":[52]}],"verseLabel":"طه: 52","question":"كيف صرف جواب موسى ﴿عِلْمُهَا عِنْدَ رَبِّي﴾ الحوار عن تشغيب فرعون؟","answer":"فوض تفاصيل أحوال الأمم الماضية إلى علم الله، ولم يسترسل في بحث لا يخدم مقام دعوة الأحياء. فصرف فرعون عن الاشتغال بما لا يجدي، مع إثبات أن علم الله محيط بالتفاصيل التي لا يعلمها موسى كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص168، تحت عنوان «بلاغة الاستئناف البياني في قوله: ﴿قَالَ عِلْمُهَا﴾»","url":""}]},{"id":"s20-51","number":51,"surah":20,"verses":[52],"references":[{"surah":20,"verses":[52]}],"verseLabel":"طه: 52","question":"ما دلالة الجمع بين ﴿لَا يَضِلُّ رَبِّي وَلَا يَنْسَى﴾؟","answer":"استوعب الجمع الآفات التي تخل بالعلم: الغلط في المعلومات هو الضلال، وزوالها هو النسيان. فنفيهما معًا كناية عن كمال العلم وسلامته من الخطأ والذهاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص173–174، تحت عنوان «بلاغة الجمع بين الضلال والنسيان»","url":""}]},{"id":"s20-52","number":52,"surah":20,"verses":[53],"references":[{"surah":20,"verses":[53]}],"verseLabel":"طه: 53","question":"ما سرّ وصف الأرض بـ﴿مَهْدًا﴾؟","answer":"شبّهها بمهد الطفل المهيأ للسكون والحياة، فاستحضر نعمة التهيئة لا مجرد الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص181، 182، 189، تحت «التشبيه البليغ في وصف الأرض بالمهد»","url":""}]},{"id":"s20-53","number":53,"surah":20,"verses":[54],"references":[{"surah":20,"verses":[54]}],"verseLabel":"طه: 54","question":"ما دلالة ختام دلائل النبات بـ﴿لِأُولِي النُّهَى﴾؟","answer":"سميت العقول نهى لأنها تنهى أصحابها عن اتباع الباطل وارتكاب القبائح. فخصت الآيات أصحاب العقول الناهية عن الأباطيل لأنهم المنتفعون بها، وفي ذلك تعريض بمن لم يعتبر بالدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص196، تحت عنوان «سر استعمال النهى عوض عن العقول والألباب»","url":""}]},{"id":"s20-54","number":54,"surah":20,"verses":[55],"references":[{"surah":20,"verses":[55]}],"verseLabel":"طه: 55","question":"ما وجه اتصال ذكر خلق الإنسان وبعثه بذكر إخراج النبات من الأرض؟","answer":"كلاهما يتضمن إخراج أجسام لطيفة من التربة الكثيفة؛ فذكر خلق الإنسان بعد إخراج النبات يلائم السياق، وخروج الموتى يشبه خروج النبات، وفي ذلك تقريب لدليل الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص200، تحت عنوان «براعة الاتساق السياقي»","url":""}]},{"id":"s20-55","number":55,"surah":20,"verses":[56],"references":[{"surah":20,"verses":[56]}],"verseLabel":"طه: 56","question":"ما سرّ التعبير بـ﴿وَلَقَدْ أَرَيْنَاهُ آيَاتِنَا كُلَّهَا﴾؟","answer":"الجمع المضاف المؤكد يفيد العموم، والمراد هنا استغراق الآيات المعهودة من آيات موسى التي أراها الله فرعون. فالمقصود استيفاء البيان في هذا المقام، وليس أن فرعون رأى كل آية لله على الإطلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص208، تحت عنوان «دلالة الجمع المضاف المؤكد»","url":""}]},{"id":"s20-56","number":56,"surah":20,"verses":[57],"references":[{"surah":20,"verses":[57]}],"verseLabel":"طه: 57","question":"ما سر إضافة السحر إلى ضمير موسى في قول فرعون: ﴿بِسِحْرِكَ﴾؟","answer":"الإضافة للتقليل والتهوين؛ قصد فرعون تحقير ما أتى به موسى، وزعم أن ما عنده ليس إلا سحرًا يسيرًا يمكن أن يأتي بمثله. فهي محاولة لإضعاف أثر الآية في نفوس الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص219، تحت عنوان «سر إضافة السحر إلى ضمير موسى»","url":""}]},{"id":"s20-57","number":57,"surah":20,"verses":[58],"references":[{"surah":20,"verses":[58]}],"verseLabel":"طه: 58","question":"ما دلالة اتساع صيغة ﴿مَوْعِدًا﴾ في طلب فرعون من موسى؟","answer":"تحتمل الصيغة زمان الوعد ومكانه، كما تحتمل المصدر؛ فذكر يوم الزينة يرجح جهة الزمان، وذكر مكانًا سوى جهة المكان، ووصفه بعدم الإخلاف يلائم المواعدة. وهي صيغة موجزة تتسع لهذه المعاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص223، تحت عنوان «دلالة صيغة (مفعل) واتساع معناها»","url":""}]},{"id":"s20-156","number":156,"surah":20,"verses":[58],"references":[{"surah":20,"verses":[58]}],"verseLabel":"طه: 58","question":"لماذا كررت ﴿لَا﴾ في ﴿لَا نُخْلِفُهُ نَحْنُ وَلَا أَنْتَ﴾؟","answer":"لتأكيد عدم الإخلاف من كل جانب بالنص على الطرفين؛ فعدم إخلاف أحدهما لا يستلزم وفاء الآخر. وفي هذا إظهار من فرعون لحرصه على إنجاز الوعد وعزمه على إتمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص224، تحت عنوان «فائدة تكرار (لا) النافية»","url":""}]},{"id":"s20-157","number":157,"surah":20,"verses":[58],"references":[{"surah":20,"verses":[58]}],"verseLabel":"طه: 58","question":"ما دلالة وصف مكان اللقاء بين موسى وفرعون بأنه ﴿سُوًى﴾؟","answer":"من معانيه مكان تتساوى مسافته بين الفريقين، أو مكان مستو ظاهر بلا ارتفاع وانخفاض، بحيث يشاهد الحاضرون ما يجري. ويذكر المصدر أيضًا دلالة معنوية على العدل والإنصاف وتساوي الطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص226–227، تحت عنوان «دلالة الوصف بـ﴿سُوًى﴾»","url":""}]},{"id":"s20-58","number":58,"surah":20,"verses":[59],"references":[{"surah":20,"verses":[59]}],"verseLabel":"طه: 59","question":"لماذا اختار موسى ﴿يَوْمُ الزِّينَةِ﴾ موعدًا للمواجهة؟","answer":"ليكون الأمر مشهودًا على رؤوس الأشهاد ويشيع ظهوره بين الحاضرين؛ فاختيار يوم اجتماعهم يظهر ثقته، ويتيح تبليغ الدعوة لأكبر جمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص233، تحت عنوان «سر اختيار يوم الزينة»","url":""}]},{"id":"s20-158","number":158,"surah":20,"verses":[59],"references":[{"surah":20,"verses":[59]}],"verseLabel":"طه: 59","question":"لماذا اختير وقت ﴿ضُحًى﴾ لحشر الناس في مواجهة موسى للسحرة؟","answer":"لأنه أول النهار، فإن امتدت المناظرة بقي للناس متسع لمصالحهم، وهو وقت مظنة انتباههم ونشاطهم. كما أنه وقت ظاهر جلي يصلح لإظهار الآيات ووضوح المشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص234، تحت عنوان «نكتة اختيار الظرف ﴿ضُحًى﴾»","url":""}]},{"id":"s20-59","number":59,"surah":20,"verses":[60],"references":[{"surah":20,"verses":[60]}],"verseLabel":"طه: 60","question":"ما دلالة الفاء في ﴿فَجَمَعَ كَيْدَهُ﴾ بعد تولي فرعون؟","answer":"تفيد التعقيب؛ انصرف فرعون فأسرع في استجماع كيده وإعداد خطته للموعد. فتصور الفاء مباشرة الإعداد بعد الانصراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص239–240، تحت عنوان «دلالة العطف بالفاء في: ﴿فَجَمَعَ كَيْدَهُ﴾»","url":""}]},{"id":"s20-159","number":159,"surah":20,"verses":[60],"references":[{"surah":20,"verses":[60]}],"verseLabel":"طه: 60","question":"لماذا سمّي ما أعده فرعون للموعد ﴿كَيْدَهُ﴾؟","answer":"يلائم لفظ الكيد ما يحضره فرعون من السحر؛ فهو إحكام للاحتيال في إعداد الخطة، والسحر قائم على التمويه والخداع. وإسناده إليه يربط هذا التدبير بصاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص240، تحت عنوان «سر اختيار لفظ ﴿كَيْدَهُ﴾ وإسناده إلى الضمير»","url":""}]},{"id":"s20-160","number":160,"surah":20,"verses":[60],"references":[{"surah":20,"verses":[60]}],"verseLabel":"طه: 60","question":"ما دلالة ﴿ثُمَّ﴾ في ﴿فَجَمَعَ كَيْدَهُ ثُمَّ أَتَى﴾؟","answer":"تفيد التراخي الزمني بين التحضير للموعد والإتيان إليه؛ فتجهيز ما جمعه وإعداده للمواجهة يستغرق وقتًا، بخلاف التعقيب الذي أفادته الفاء قبل جمع الكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص240، تحت عنوان «نكتة العطف بـ﴿ثُمَّ﴾»","url":""}]},{"id":"s20-60","number":60,"surah":20,"verses":[61],"references":[{"surah":20,"verses":[61]}],"verseLabel":"طه: 61","question":"لماذا افتتح موسى نصحه للسحرة بقوله: ﴿وَيْلَكُمْ﴾؟","answer":"هو إنذار شديد يصدر عن شفقة وحرص على هدايتهم؛ يسترعي أسماعهم للموعظة، ولا يقصد به الدعاء عليهم بالهلاك ابتداءً. فحذرهم من سوء العاقبة إن استمروا في الافتراء، ليجتنبوا أسبابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص242، تحت عنوان «نكتة التعبير بلفظ ﴿وَيْلَكُمْ﴾ دون سواه»","url":""}]},{"id":"s20-161","number":161,"surah":20,"verses":[61],"references":[{"surah":20,"verses":[61]}],"verseLabel":"طه: 61","question":"ما دلالة اختيار فعل السحت في ﴿فَيُسْحِتَكُمْ بِعَذَابٍ﴾؟","answer":"أصل السحت الاستئصال والفناء والإذهاب؛ فالتعبير يصور عذابًا مستأصلًا ينقطع به الأثر، وهو كناية عن المبالغة في الإهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص243، تحت عنوان «دلالة التعبير بفعل السحت»","url":""}]},{"id":"s20-162","number":162,"surah":20,"verses":[61],"references":[{"surah":20,"verses":[61]}],"verseLabel":"طه: 61","question":"ما موقع ﴿وَقَدْ خَابَ مَنِ افْتَرَى﴾ من نهي موسى عن الافتراء؟","answer":"تساق الجملة لتعليل النهي: اجتنبوا الكذب على الله، فقد خاب من افترى قبلكم. ويجوز أن تكون اعتراضية تقرر ما قبلها، فيقوى التحذير بذكر عاقبة المفتري.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص244، تحت عنوان «موقع جملة: ﴿وَقَدْ خَابَ مَنِ افْتَرَى﴾ مما قبلها»","url":""}]},{"id":"s20-61","number":61,"surah":20,"verses":[62],"references":[{"surah":20,"verses":[62]}],"verseLabel":"طه: 62","question":"ما دلالة الجمع بين تنازع السحرة أمرهم وإسرارهم النجوى؟","answer":"عطف إسرار النجوى على التنازع يبين اجتماع اختلاف الرأي مع كتمان الحديث؛ فتنازعهم وتشاورهم كانا محكومين بالسرية، لا مجادلة معلنة أمام الحاضرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص251، تحت عنوان «موقع جملة: ﴿وَأَسَرُّوا﴾ مما قبلها»","url":""}]},{"id":"s20-62","number":62,"surah":20,"verses":[63],"references":[{"surah":20,"verses":[63]}],"verseLabel":"طه: 63","question":"ما دلالة توكيد اتهام موسى وهارون في قولهم: ﴿إِنْ هَذَانِ لَسَاحِرَانِ﴾؟","answer":"افتتحوا القول بالتوكيد ليثبتوا اتهام موسى وهارون بالسحر عند من يخامره الشك في صحة دعوتهما. فجعلوا ما ظهر من المعجزة سحرًا؛ لأنهم كانوا يطلقون السحر على خوارق العادات.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص259، تحت عنوان «دلالة استهلال القول بـ(إن)»","url":""}]},{"id":"s20-63","number":63,"surah":20,"verses":[64],"references":[{"surah":20,"verses":[64]}],"verseLabel":"طه: 64","question":"ما دلالة إجماع الكيد في قوله تعالى: ﴿فَأَجْمِعُوا كَيْدَكُمْ﴾؟","answer":"إجماع الكيد إحكام للعزم واستجماع للهمم وتوحيد للتدبير بعد التنازع؛ فانتقلوا من شتات الرأي والتردد إلى قصد واحد وإرادة مجتمعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص264، تحت عنوان «دلالة إجماع الكيد»","url":""}]},{"id":"s20-163","number":163,"surah":20,"verses":[64],"references":[{"surah":20,"verses":[64]}],"verseLabel":"طه: 64","question":"ما دلالة تقييد إتيان السحرة بالحال ﴿صَفًّا﴾؟","answer":"يصور مجيئهم مصطفين في هيئة متماسكة منظمة؛ ليكون ذلك أهيب في نفوس المشاهدين وأقوى في إظهار اجتماعهم. وتنكير ﴿صفًّا﴾ يشعر بعظمة ذلك الصف وكماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص265–266، تحت عنوان «دلالة التقييد بالحال ﴿صَفًّا﴾»","url":""}]},{"id":"s20-64","number":64,"surah":20,"verses":[65],"references":[{"surah":20,"verses":[65]}],"verseLabel":"طه: 65","question":"ما دلالة تخيير السحرة موسى بين أن يلقي أو يكونوا أول من ألقى؟","answer":"أبدى قولهم ﴿نَكُونَ أَوَّلَ مَنْ أَلْقَى﴾ رغبتهم في السبق وثقتهم بسحرهم؛ إذ أرادوا أن يكون لأول مشهد أثر قوي في أعين الجمهور، وظنوا أن ما يلقونه سيحمل موسى على التحدي بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص274، تحت عنوان «نكتة اختيار لفظ ﴿أَوَّلَ﴾ وفائدته»","url":""}]},{"id":"s20-65","number":65,"surah":20,"verses":[66],"references":[{"surah":20,"verses":[66]}],"verseLabel":"طه: 66","question":"ما نكتة بناء ﴿يُخَيَّلُ﴾ للمفعول في وصف سحر السحرة؟","answer":"حذف الفاعل الظاهر يقلل من شأن القوى الخفية التي قامت بالتخييل، في مقابل وضوح مصدر معجزة موسى وأنها من عند الله؛ فلا يبرز النص فاعل التخييل ولا يعظمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص278، تحت عنوان «نكتة بناء فعل ﴿يُخَيَّلُ﴾ للمفعول»","url":""}]},{"id":"s20-164","number":164,"surah":20,"verses":[66],"references":[{"surah":20,"verses":[66]}],"verseLabel":"طه: 66","question":"ما دلالة ﴿مِنْ﴾ في قوله: ﴿مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى﴾؟","answer":"هي سببية؛ أي إن تخيل موسى حركة الحبال والعصي وقع بسبب سحرهم وفعلهم، فصرح التركيب بمصدر ذلك التخييل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص279، تحت عنوان «نوع ﴿مِنْ﴾ ومعناها»","url":""}]},{"id":"s20-66","number":66,"surah":20,"verses":[67],"references":[{"surah":20,"verses":[67]}],"verseLabel":"طه: 67","question":"ما دلالة تصوير خوف موسى بقوله: ﴿فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً﴾؟","answer":"كانت خيفة موسى عارضة مما رأى من مشهد غير مألوف، وهي من مقتضى البشرية لا نقص فيها. وقيل: خشي أن ينصرف الناس قبل ظهور الحق؛ فجاءه التثبيت والأمر بالإلقاء ليزول الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص286، تحت عنوان «دلالة لفظ ﴿خِيفَةً﴾»","url":""}]},{"id":"s20-67","number":67,"surah":20,"verses":[68],"references":[{"surah":20,"verses":[68]}],"verseLabel":"طه: 68","question":"ما دلالة تثبيت موسى بقوله: ﴿إِنَّكَ أَنْتَ الْأَعْلَى﴾؟","answer":"اجتمعت في الجملة مؤكدات منها ﴿إن﴾ وتكرير الضمير وتعريف ﴿الأعلى﴾؛ لتقرير غلبة موسى ورفع ما عرض له من الخوف، مهما عظم السحر في أعين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص289–290، تحت عنوان «بلاغة اجتماع التوكيدات»","url":""}]},{"id":"s20-68","number":68,"surah":20,"verses":[69],"references":[{"surah":20,"verses":[69]}],"verseLabel":"طه: 69","question":"ما سرّ التعبير بـ﴿تَلْقَفْ مَا صَنَعُوا﴾ لا «عصيهم»؟","answer":"عبر عن الحبال والعصي بالموصول ﴿ما صنعوا﴾ لتهوين شأنها مع استيعاب كل ما أعدوه وأحكموه؛ فالمعجزة تلقف جميع مصنوعهم الكثير ولا تبقي منه شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص298–299، تحت عنوان «نكتة التعبير عن العصي والحبال بالاسم الموصول»","url":""}]},{"id":"s20-69","number":69,"surah":20,"verses":[69],"references":[{"surah":20,"verses":[69]}],"verseLabel":"طه: 69","question":"ما سرّ التعبير بـ﴿وَلَا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى﴾؟","answer":"﴿حَيْثُ أَتَى﴾ كناية عن عموم نفي الفلاح في كل مكان وزمان؛ فالساحر لا يدرك فلاحًا حقيقيًا أينما توجه، ولو تنقل في البلاد واستجمع أسباب القوة والشهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص302، تحت عنوان «بلاغة الكناية»","url":""}]},{"id":"s20-70","number":70,"surah":20,"verses":[70],"references":[{"surah":20,"verses":[70]}],"verseLabel":"طه: 70","question":"ما سرّ التعبير بـ﴿فَأُلْقِيَ السَّحَرَةُ سُجَّدًا﴾ لا «فسجدوا»؟","answer":"بني فعل الإلقاء للمجهول لتصوير قوة خارجة عن إرادتهم ألقتهم إلى الأرض ساجدين؛ وفي ذلك إبراز لقوة المعجزة وسرعة استجابتهم للإيمان بلا تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص306، تحت عنوان «فائدة بناء فعل الإلقاء للمجهول»","url":""}]},{"id":"s20-71","number":71,"surah":20,"verses":[71],"references":[{"surah":20,"verses":[71]}],"verseLabel":"طه: 71","question":"ما دلالة قول فرعون: ﴿إِنَّهُ لَكَبِيرُكُمُ الَّذِي عَلَّمَكُمُ السِّحْرَ﴾؟","answer":"زعم فرعون أن موسى معلم السحرة الأكبر ورئيسهم؛ ليصور إيمانهم كأنه تواطؤ ومؤامرة سبقت اللقاء، ويصرف الناس عن دلالة المعجزة التي ألزمتهم السجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص317، تحت عنوان «دلالة اختيار مفردة ﴿لَكَبِيرُكُم﴾»","url":""}]},{"id":"s20-72","number":72,"surah":20,"verses":[72],"references":[{"surah":20,"verses":[72]}],"verseLabel":"طه: 72","question":"ما سر التعبير بالإيثار في قول السحرة: ﴿لَنْ نُؤْثِرَكَ عَلَى مَا جَاءَنَا مِنَ الْبَيِّنَاتِ﴾؟","answer":"الإيثار اختيار وتفضيل بين أمرين؛ فأعلن السحرة أنهم لا يقدمون طاعة فرعون ومنافع الدنيا الزائلة على البينات التي شاهدوها، لأن منافع الدنيا لا تعارض منافع الآخرة ومضارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص330–331، تحت عنوان «دلالة اختيار مفردة الإيثار»","url":""}]},{"id":"s20-73","number":73,"surah":20,"verses":[72],"references":[{"surah":20,"verses":[72]}],"verseLabel":"طه: 72","question":"ما غرض الأمر في قول السحرة لفرعون: ﴿فَاقْضِ مَا أَنْتَ قَاضٍ﴾؟","answer":"خرج الأمر عن معناه الظاهر إلى التسوية وعدم المبالاة: افعل ما تريد وأنفذ وعيدك؛ فلن يردنا ذلك عن الإيمان. وفيه إظهار لاستخفافهم بتهديده بعد أن ثبت اليقين في قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص334–335، تحت عنوان «غرض الأمر وبلاغته»","url":""}]},{"id":"s20-165","number":165,"surah":20,"verses":[72],"references":[{"surah":20,"verses":[72]}],"verseLabel":"طه: 72","question":"ما دلالة القصر في قول السحرة: ﴿إِنَّمَا تَقْضِي هَذِهِ الْحَيَاةَ الدُّنْيَا﴾؟","answer":"قصروا سلطان فرعون وحكمه على الحياة الدنيا؛ فلا يتجاوزها إلى الآخرة. وفي ذلك تهوين لوعيده وتقوية للنفوس المؤمنة برجاء الجزاء الباقي عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص335، تحت عنوان «بلاغة القصر ودلالته»","url":""}]},{"id":"s20-74","number":74,"surah":20,"verses":[73],"references":[{"surah":20,"verses":[73]}],"verseLabel":"طه: 73","question":"ما دلالة إضافة الخطايا إلى ضمير الجمع في قول السحرة: ﴿خَطَايَانَا﴾؟","answer":"نسب السحرة الخطايا إلى أنفسهم اعترافًا صريحًا بها واستعظامًا لها وطلبًا للمغفرة، فلم يبرئوا أنفسهم مما وقع منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص342، تحت عنوان «فائدة الإضافة إلى ضمير الجمع»","url":""}]},{"id":"s20-166","number":166,"surah":20,"verses":[73],"references":[{"surah":20,"verses":[73]}],"verseLabel":"طه: 73","question":"ما دلالة قول السحرة لفرعون: ﴿وَمَا أَكْرَهْتَنَا عَلَيْهِ مِنَ السِّحْرِ﴾؟","answer":"صرحوا بأن فرعون أكرههم على ممارسة السحر، فجمعوا الاعتراف بما وقع منهم وبيان تسلطه عليهم. واختيار لفظ الإكراه يبين أن فعل السحر خالف رغبتهم الأصلية، مع طلبهم المغفرة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص343–344، تحت عنوان «براعة استعمال مفردة الإكراه»","url":""}]},{"id":"s20-75","number":75,"surah":20,"verses":[73],"references":[{"surah":20,"verses":[73]}],"verseLabel":"طه: 73","question":"ما دلالة ختام كلام السحرة بـ﴿وَاللَّهُ خَيْرٌ وَأَبْقَى﴾؟","answer":"جاءت ﴿وَاللَّهُ خَيْرٌ وَأَبْقَى﴾ تذييلًا جامعًا: ما عند الله خير من منفعة فرعون وأبقى منها، وجزاؤه خير وأدوم من وعيد فرعون وعذابه؛ فاختصرت العبارة خلاصة موقفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص344، تحت عنوان «بلاغة التذييل»","url":""}]},{"id":"s20-76","number":76,"surah":20,"verses":[74],"references":[{"surah":20,"verses":[74]},{"surah":87,"verses":[12,13]}],"verseLabel":"طه: 74؛ الأعلى: 12–13","question":"ما سرّ التعبير بـ﴿لَا يَمُوتُ فِيهَا وَلَا يَحْيَى﴾؟","answer":"في الموضعين نفي لراحتي الموت والحياة النافعة: لا يموت المعذب فيستريح، ولا يحيا حياة ينتفع بها. وجاء التعبير في طه في سياق جزاء المجرم، وفي الأعلى وصفًا لحال من يصلى النار الكبرى؛ فالمعنى واحد مع اختلاف السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص351–352، تحت عنوان «توجيه التشابه اللفظي»","url":""}]},{"id":"s20-77","number":77,"surah":20,"verses":[75],"references":[{"surah":20,"verses":[75]}],"verseLabel":"طه: 75","question":"ما سرّ التعبير بـ﴿قَدْ عَمِلَ الصَّالِحَاتِ﴾ بعد الإيمان؟","answer":"تفيد ﴿قد﴾ تحقيق وقوع العمل الصالح والاهتمام به؛ فالمؤمن إنما يستحق الدرجات العالية إذا تحقق منه العمل الصالح، لا بمجرد الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص353، تحت عنوان «دلالة حرف التحقيق»","url":""}]},{"id":"s20-78","number":78,"surah":20,"verses":[77],"references":[{"surah":20,"verses":[77]}],"verseLabel":"طه: 77","question":"ما سرّ وصف الطريق في البحر بـ﴿يَبَسًا﴾؟","answer":"اختير ﴿يَبَسًا﴾ للدلالة على أن الطريق في قاع البحر صار يابسًا جافًا، لا طين فيه ولا ماء، فكان آمنًا سهل السلوك لبني إسرائيل؛ وفي ذلك تمام المعجزة والطمأنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص371–372، تحت عنوان «سر إيثار مفردة ﴿يَبَسًا﴾ دون سواها»","url":""}]},{"id":"s20-79","number":79,"surah":20,"verses":[77],"references":[{"surah":20,"verses":[77]}],"verseLabel":"طه: 77","question":"ما دلالة التعبير بالدرك في قوله: ﴿لَا تَخَافُ دَرَكًا﴾؟","answer":"الدرك مصدر من إدراك العدو ولحاقه؛ فنفى الله عن موسى وقومه خوف أن يصل إليهم فرعون وجنوده من خلفهم، وفي اللفظ طمأنة من جهة المطاردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص375–376، تحت عنوان «دلالة التعبير بالدرك مادة وصيغة»","url":""}]},{"id":"s20-167","number":167,"surah":20,"verses":[77],"references":[{"surah":20,"verses":[77]}],"verseLabel":"طه: 77","question":"ما سر حذف مفعول ﴿تَخْشَى﴾ في قوله: ﴿وَلَا تَخْشَى﴾؟","answer":"حذف المفعول لإفادة العموم: لا تخشى شيئًا من مخاطر البحر ولا غيره. فبعد الأمان الخاص من لحاق العدو جاء الأمان الشامل من سائر المخاوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص377، تحت عنوان «سر حذف مفعول ﴿تَخْشَى﴾»","url":""}]},{"id":"s20-80","number":80,"surah":20,"verses":[78],"references":[{"surah":20,"verses":[78]}],"verseLabel":"طه: 78","question":"ما سرّ التعبير بـ﴿فَغَشِيَهُمْ مِنَ الْيَمِّ مَا غَشِيَهُمْ﴾؟","answer":"أبهم الموصول في ﴿مَا غَشِيَهُمْ﴾ للتهويل والتفخيم؛ فما غمر فرعون وجنوده من اليم أمر عظيم لا يحيط الوصف بكنهه، فكأن ما وقع أعظم من أن يفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص383، تحت عنوان «نوع ﴿مَا﴾ وأثرها في تهويل المشهد»","url":""}]},{"id":"s20-81","number":81,"surah":20,"verses":[79],"references":[{"surah":20,"verses":[79]}],"verseLabel":"طه: 79","question":"ما سرّ التعبير بـ﴿وَأَضَلَّ فِرْعَوْنُ قَوْمَهُ وَمَا هَدَى﴾؟","answer":"نفت ﴿وَمَا هَدَى﴾ عن فرعون الهداية صراحة، مؤكدة ما قبلها من إثبات إضلاله لقومه. وفي ذلك رد على زعمه أنه يهديهم سبيل الرشاد: أضلهم ولم يهدهم إلى خير قط.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص386، تحت عنوان «دلالة نفي الهدى بـ﴿وَمَا﴾»","url":""}]},{"id":"s20-82","number":82,"surah":20,"verses":[80],"references":[{"surah":20,"verses":[80]}],"verseLabel":"طه: 80","question":"ما نكتة إيقاع المواعدة على بني إسرائيل في قوله: ﴿وَوَاعَدْنَاكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ﴾؟","answer":"أوقعت المواعدة على بني إسرائيل مع أن المباشر لها موسى؛ لأن منافعها عادت إليهم، إذ كانت التوراة لهدايتهم وإصلاح شأنهم، فاتصل الوعد بهم تبعًا لنبيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص396، تحت عنوان «نكتة إيقاع المواعدة على بني إسرائيل»","url":""}]},{"id":"s20-168","number":168,"surah":20,"verses":[80],"references":[{"surah":20,"verses":[80]}],"verseLabel":"طه: 80","question":"ما نكتة ترتيب المنن في قوله: ﴿أَنْجَيْنَاكُمْ﴾ ثم ﴿وَوَاعَدْنَاكُمْ﴾ ثم ﴿وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَى﴾؟","answer":"رتبت المنن بحسب المقام: بدأ بالإنجاء من العدو لأنه دفع لأعظم الضرر، ثم المواعدة وإنزال التوراة لأنها نعمة الدين والهداية، ثم المن والسلوى لأنهما نعمة البدن والمعاش.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص399، تحت عنوان «نكتة ترتيب المنن الثلاث»","url":""}]},{"id":"s20-83","number":83,"surah":20,"verses":[81],"references":[{"surah":20,"verses":[81]}],"verseLabel":"طه: 81","question":"ما دلالة إطلاق الطغيان دون تقييد في قوله: ﴿وَلَا تَطْغَوْا فِيهِ﴾؟","answer":"أطلق الطغيان ليعم كل مجاوزة للحد في النعمة: من كفرانها وترك شكرها واستعمالها في المعصية والبطر بها. فكل صورة من تجاوز الحد فيها داخلة في النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص402–403، تحت عنوان «دلالة إطلاق الطغيان دون تقييده»","url":""}]},{"id":"s20-169","number":169,"surah":20,"verses":[81],"references":[{"surah":20,"verses":[81]}],"verseLabel":"طه: 81","question":"ما دلالة الفاء في قوله: ﴿فَيَحِلَّ عَلَيْكُمْ غَضَبِي﴾؟","answer":"الفاء سببية؛ فحلول الغضب مترتب على الطغيان في النعمة ومسبب عنه. وفي الربط بها تحذير من أن مجاوزة الحد تستدعي العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص404، تحت عنوان «دلالة الفاء في ﴿فَيَحِلَّ﴾»","url":""}]},{"id":"s20-170","number":170,"surah":20,"verses":[81],"references":[{"surah":20,"verses":[81]}],"verseLabel":"طه: 81","question":"ما بلاغة استعارة الحلول في قوله: ﴿فَيَحِلَّ عَلَيْكُمْ غَضَبِي﴾؟","answer":"استعير الحلول، وهو النزول والإقامة، لإصابة الغضب والعذاب؛ فصور العقوبة كأنها تنزل بالمخاطبين وتحيط بهم، مبالغة في التهديد والتخويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص404، تحت عنوان «بلاغة الاستعارة في لفظ الحلول»","url":""}]},{"id":"s20-84","number":84,"surah":20,"verses":[82],"references":[{"surah":20,"verses":[82]}],"verseLabel":"طه: 82","question":"ما سرّ التعبير بـ﴿وَإِنِّي لَغَفَّارٌ﴾ بصيغة المبالغة؟","answer":"جاء ﴿غفّار﴾ على صيغة المبالغة للدلالة على كثرة مغفرة الله وعظمتها؛ فمهما عظم ذنب من تاب فإن مغفرة الله أوسع، وفي الصيغة تطمين للتائب وفتح لباب الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص409، تحت عنوان «لطيفة التعبير بصيغة ﴿لَغَفَّارٌ﴾»","url":""}]},{"id":"s20-85","number":85,"surah":20,"verses":[83],"references":[{"surah":20,"verses":[83]}],"verseLabel":"طه: 83","question":"ما دلالة سؤال موسى: ﴿وَمَا أَعْجَلَكَ عَنْ قَوْمِكَ﴾؟","answer":"﴿ما﴾ استفهامية إنكارية تحمل عتابًا لطيفًا لموسى على تعجله بمفارقة قومه قبل الإذن. وصيغة الاستفهام أرفق من التصريح باللوم، وفيها تنبيه إلى ما ترتب على غيبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص416، تحت عنوان «دلالة ﴿مَا﴾ في قوله تعالى: ﴿وَمَا أَعْجَلَكَ﴾»","url":""}]},{"id":"s20-86","number":86,"surah":20,"verses":[84],"references":[{"surah":20,"verses":[84]}],"verseLabel":"طه: 84","question":"ما سر اختيار مفردة العجلة في قول موسى: ﴿وَعَجِلْتُ إِلَيْكَ رَبِّ﴾؟","answer":"وصف موسى ذهابه بالعجلة لأنها كانت مسارعة محمودة إلى طاعة الله وطلب رضاه، لا استعجالًا مذمومًا؛ فالعجلة إلى الخير خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص421، تحت عنوان «سر اختيار مفردة العجلة»","url":""}]},{"id":"s20-171","number":171,"surah":20,"verses":[84],"references":[{"surah":20,"verses":[84]}],"verseLabel":"طه: 84","question":"ما دلالة تقييد العجلة بـ﴿إِلَيْكَ﴾ في قول موسى: ﴿وَعَجِلْتُ إِلَيْكَ رَبِّ﴾؟","answer":"قيد العجلة بالاتجاه إلى الله لبيان إخلاص القصد وأن مسارعته كانت إليه وإلى رضاه وحده. وتقديم الجار والمجرور يلائم مقام الاعتذار ويؤكد حسن الباعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص422، تحت عنوان «دلالة تقييد العجلة بالجار والمجرور ﴿إِلَيْكَ﴾»","url":""}]},{"id":"s20-172","number":172,"surah":20,"verses":[84],"references":[{"surah":20,"verses":[84]}],"verseLabel":"طه: 84","question":"ما دلالة تعليل موسى عجلته بقوله: ﴿لِتَرْضَى﴾؟","answer":"جعل موسى غاية عجلته طلب رضا الله، فبين أن باعثه الاجتهاد في الطاعة لا مخالفة الأمر. والتعبير بالرضا يستصحب رجاء قبول الاعتذار واستمرار رضا ربه عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص423–424، تحت عنوان «دلالة التعبير بالرضا»","url":""}]},{"id":"s20-87","number":87,"surah":20,"verses":[85],"references":[{"surah":20,"verses":[85]}],"verseLabel":"طه: 85","question":"ما سر إسناد فتنة قوم موسى إلى الله في قوله: ﴿فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ﴾؟","answer":"أسندت الفتنة إلى الله لأنه مقدر أسباب الاختبار وخالقها، ليتميز الثابت من المستعد للانحراف. أما إضلالهم فأسند إلى السامري لأنه السبب المباشر الذي دعاهم إلى عبادة العجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص426، تحت عنوان «سر إسناد فتنتهم إلى الله تعالى»","url":""}]},{"id":"s20-173","number":173,"surah":20,"verses":[85],"references":[{"surah":20,"verses":[85]}],"verseLabel":"طه: 85","question":"ما دلالة استعمال مفردة الفتنة دون الابتلاء في قوله: ﴿فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ﴾؟","answer":"الفتنة أشد من مطلق الاختبار؛ فهي ابتلاء شاق يكشف ما في النفوس ويميز الثابت من الضعيف. وقد ناسب اللفظ عظم اختبار بني إسرائيل بالعجل في غيبة موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص427، تحت عنوان «دلالة استعمال مفردة الفتنة دون الابتلاء»","url":""}]},{"id":"s20-88","number":88,"surah":20,"verses":[86],"references":[{"surah":20,"verses":[86]}],"verseLabel":"طه: 86","question":"ما دلالة الجمع بين ﴿غَضْبَانَ أَسِفًا﴾ في وصف رجوع موسى؟","answer":"جمع الوصفان انفعالين في نفس موسى: غضبًا شديدًا لله على انحراف قومه، وأسفًا وحزنًا على ما انتهوا إليه. فاجتمعت قوة الإنكار وألم الرحمة بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص435، تحت عنوان «سر الجمع بين صيغتي ﴿غَضْبَانَ﴾ و﴿أَسِفًا﴾»","url":""}]},{"id":"s20-89","number":89,"surah":20,"verses":[87],"references":[{"surah":20,"verses":[87]}],"verseLabel":"طه: 87","question":"ما دلالة اختلاف القراءات في قولهم: ﴿حُمِّلْنَا أَوْزَارًا﴾؟","answer":"قراءة التخفيف تفيد أنهم حملوا الأوزار مع أنفسهم، وقراءة التشديد تفيد أن موسى حملهم إياها أو أن الله ألزمهم حكمها. فتعدد القراءات يثري تصوير التبعة التي اعتذروا بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص454، تحت عنوان «توجيه القراءات في قولهم: ﴿حُمِّلْنَا﴾»","url":""}]},{"id":"s20-174","number":174,"surah":20,"verses":[87],"references":[{"surah":20,"verses":[87]}],"verseLabel":"طه: 87","question":"ما سر التعبير بالأوزار دون الأحمال في قولهم: ﴿حُمِّلْنَا أَوْزَارًا﴾؟","answer":"الأوزار توحي بثقل الحلي حسًّا، وبالتبعة والإثم معنى؛ فاختيرت بدل الأحمال لتجمع ثقل ما حملوه وثقل ما ترتب عليه من عذر ومسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص455–456، تحت عنوان «سر التعبير بالأوزار دون الأحمال»","url":""}]},{"id":"s20-90","number":90,"surah":20,"verses":[88],"references":[{"surah":20,"verses":[88]}],"verseLabel":"طه: 88","question":"ما دلالة وصف العجل بأنه ﴿جَسَدًا لَهُ خُوَارٌ﴾؟","answer":"الجسد أخص من الجسم، ويطلق هنا على صورة العجل الجامدة التي لا روح فيها ولا عقل. ففضح الوصف عبادتهم جسمًا له خوار، لكنه خال من حقيقة الحياة والإدراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص468، تحت عنوان «الجسم والجسد»","url":""}]},{"id":"s20-91","number":91,"surah":20,"verses":[89],"references":[{"surah":20,"verses":[89]}],"verseLabel":"طه: 89","question":"ما سرّ التعبير بـ﴿أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًا وَلَا يَمْلِكُ لَهُمْ ضَرًّا وَلَا نَفْعًا﴾؟","answer":"قدم عجز العجل عن إجابة عابديه لأنه أظهر في إبطال ألوهيته وأسبق إلى الحس، ثم نفى عنه ملك الضر والنفع ليبين عجزه التام عن التصرف. فجمع عجز التواصل وعجز التأثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص476–477، تحت عنوان «علة تقديم نفي إرجاع القول على ملك الضر والنفع»","url":""}]},{"id":"s20-92","number":92,"surah":20,"verses":[90],"references":[{"surah":20,"verses":[90]}],"verseLabel":"طه: 90","question":"ما بلاغة القصر في قول هارون: ﴿إِنَّمَا فُتِنْتُمْ بِهِ﴾؟","answer":"قصر هارون أمر العجل على كونه فتنة واختبارًا، لا ربًّا يستحق العبادة. وهو قصر قلب يواجه اعتقادهم الباطل بحقيقة حاله ويدعوهم إلى الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص483، تحت عنوان «بلاغة القصر بـ﴿إِنَّمَا﴾ ونوعه وغرضه»","url":""}]},{"id":"s20-175","number":175,"surah":20,"verses":[90],"references":[{"surah":20,"verses":[90]}],"verseLabel":"طه: 90","question":"ما فائدة إيثار اسم ﴿الرَّحْمَنُ﴾ في قول هارون: ﴿وَإِنَّ رَبَّكُمُ الرَّحْمَنُ﴾؟","answer":"ذكر اسم الرحمن تذكيرًا لبني إسرائيل بسابق رحمة الله وإحسانه إليهم وإنجائه لهم، وترقيقًا لقلوبهم كي يرجعوا إلى ربهم الحق ويتركوا العجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص485، تحت عنوان «فائدة إيثار اسم الرحمن»","url":""}]},{"id":"s20-93","number":93,"surah":20,"verses":[91],"references":[{"surah":20,"verses":[91]}],"verseLabel":"طه: 91","question":"ما دلالة النفي بـ﴿لَنْ﴾ في قولهم: ﴿لَنْ نَبْرَحَ عَلَيْهِ عَاكِفِينَ﴾؟","answer":"دل النفي بـ﴿لن﴾ على تأكيد امتناعهم في المستقبل عن مفارقة عبادة العجل، فكشف شدة إصرارهم على الباطل ورفضهم نصح هارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص491، تحت عنوان «دلالة النفي بـ﴿لَنْ﴾»","url":""}]},{"id":"s20-176","number":176,"surah":20,"verses":[91],"references":[{"surah":20,"verses":[91]}],"verseLabel":"طه: 91","question":"ما دلالة ﴿حَتَّى﴾ في قولهم: ﴿حَتَّى يَرْجِعَ إِلَيْنَا مُوسَى﴾؟","answer":"جعلوا رجوع موسى غاية لاستمرار عكوفهم على العجل؛ فسوّفوا ترك الباطل إلى حضوره، وفي ذلك عناد وتهرب من الاستجابة لهارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص493، تحت عنوان «دلالة التعبير بحرف الجر ﴿حَتَّى﴾»","url":""}]},{"id":"s20-94","number":94,"surah":20,"verses":[92],"references":[{"surah":20,"verses":[92]}],"verseLabel":"طه: 92","question":"ما دلالة نداء موسى هارون باسمه في مقام العتاب؟","answer":"ناداه باسمه ﴿يا هارون﴾ في مقام التوبيخ والعتاب، لا بوصف الأخوة؛ لأن المقام يقتضي إظهار الجدية واستحضار مسؤوليته عن القوم حين استخلفه موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص495–496، تحت عنوان «فائدة النداء لأخيه بـ﴿يا﴾ واسمه»","url":""}]},{"id":"s20-177","number":177,"surah":20,"verses":[92],"references":[{"surah":20,"verses":[92]}],"verseLabel":"طه: 92","question":"ما بلاغة الاستفهام في قول موسى لهارون: ﴿مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوا﴾؟","answer":"الاستفهام مجازي غرضه الإنكار على هارون وسؤاله عن المانع من المبادرة إلى معالجة ضلال القوم واتباع أمر موسى؛ فهو عتاب يحمل معنى التوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص496، تحت عنوان «بلاغة التعبير بالاستفهام المجازي»","url":""}]},{"id":"s20-178","number":178,"surah":20,"verses":[92],"references":[{"surah":20,"verses":[92]}],"verseLabel":"طه: 92","question":"ما دلالة إضافة الأمر إلى ضمير المتكلم في قول موسى: ﴿أَفَعَصَيْتَ أَمْرِي﴾؟","answer":"أضاف موسى الأمر إلى نفسه لأنه الأمر الذي عهد به إلى هارون بأمر الله عند استخلافه؛ فإضافته تستحضر العهد والمسؤولية وتشدّد الإنكار على مخالفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص500، تحت عنوان «دلالة إضافة الأمر لضمير المتكلم»","url":""}]},{"id":"s20-95","number":95,"surah":20,"verses":[94],"references":[{"surah":20,"verses":[94]}],"verseLabel":"طه: 94","question":"ما سرّ التعبير في قول هارون ﴿يَا ابْنَ أُمَّ﴾؟","answer":"استعطف هارون موسى بندائه ﴿يا ابن أم﴾ بدل ﴿يا أخي﴾؛ لأن ذكر الأم أبلغ في استدعاء الرقة والرحمة، ولا سيما في لحظة الغضب الشديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص504، تحت عنوان «فائدة النداء بـ﴿ابْنَ أُمَّ﴾ دون ﴿يا أخي﴾»","url":""}]},{"id":"s20-96","number":96,"surah":20,"verses":[94],"references":[{"surah":20,"verses":[94]}],"verseLabel":"طه: 94","question":"ما دلالة اعتذار هارون بخشيته أن يقول موسى: ﴿فَرَّقْتَ بَيْنَ بَنِي إِسْرَائِيلَ﴾؟","answer":"جاءت جملة ﴿إني خشيت﴾ تعليلًا لترك هارون قتال عابدي العجل؛ فقد خشي أن يؤدي الاشتباك إلى تفريق بني إسرائيل وتمزيق جماعتهم قبل عودة موسى، مع بقائه منكرًا لشركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص505، تحت عنوان «نكتة فصل جملة ﴿إِنِّي خَشِيتُ﴾»","url":""}]},{"id":"s20-97","number":97,"surah":20,"verses":[95],"references":[{"surah":20,"verses":[95]}],"verseLabel":"طه: 95","question":"ما دلالة الفاء في انتقال موسى إلى سؤال السامري: ﴿فَمَا خَطْبُكَ يَا سَامِرِيُّ﴾؟","answer":"تفيد الفاء التعقيب والسببية؛ فبعد سؤال القوم وهارون وسماع جوابهما انتقل موسى إلى السامري، لأنه المتسبب المباشر في الفتنة وصناعة العجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص512، تحت عنوان «معنى الفاء في ﴿فَمَا﴾»","url":""}]},{"id":"s20-179","number":179,"surah":20,"verses":[95],"references":[{"surah":20,"verses":[95]}],"verseLabel":"طه: 95","question":"ما سر إيثار لفظ ﴿الْخَطْبُ﴾ دون الشأن في سؤال موسى للسامري؟","answer":"اختير ﴿الخطب﴾ لأنه يستعمل في الأمر العظيم المكروه؛ فناسب فظاعة فعل السامري وشناعته، وأشعر من أول السؤال بعظم الجريمة التي سيحاسب عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص513، تحت عنوان «سر إيثار لفظ الخطب دون الشأن»","url":""}]},{"id":"s20-98","number":98,"surah":20,"verses":[96],"references":[{"surah":20,"verses":[96]}],"verseLabel":"طه: 96","question":"ما دلالة ادعاء السامري: ﴿بَصُرْتُ بِمَا لَمْ يَبْصُرُوا بِهِ﴾؟","answer":"ادعى السامري علمًا اختص به دون قومه، وعبر عنه بالبصر مجازًا ليصوره معرفة يقينية كالمشاهدة؛ فكان في كلامه تعظيم لدعواه وإظهار للثقة بما زعمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص519، تحت عنوان «بلاغة المجاز في التعبير عن العلم بلفظ البصر»","url":""}]},{"id":"s20-99","number":99,"surah":20,"verses":[96],"references":[{"surah":20,"verses":[96]}],"verseLabel":"طه: 96","question":"ما دلالة الفاء في قول السامري: ﴿فَنَبَذْتُهَا﴾؟","answer":"عطفت الفاء نبذ القبضة على قبضها، فصورت سرعة إلقائها واستعمالها عقب أخذها، وربطت الفعل بنتيجة ما سبقه في اعتراف السامري.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص521، تحت عنوان «معنى الفاء في قوله: ﴿فَنَبَذْتُهَا﴾»","url":""}]},{"id":"s20-180","number":180,"surah":20,"verses":[96],"references":[{"surah":20,"verses":[96]}],"verseLabel":"طه: 96","question":"ما دلالة إسناد التسويل إلى نفس السامري في قوله: ﴿وَكَذَلِكَ سَوَّلَتْ لِي نَفْسِي﴾؟","answer":"أسند السامري التسويل إلى نفسه اعترافًا بأن هواه زيّن له الفعل القبيح حتى رآه حسنًا؛ فكشفت العبارة أن باعث صنع العجل كان حرص النفس ورغبتها فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص522–523، تحت عنوان «دلالة التعبير بالتسويل مادة وصيغة»","url":""}]},{"id":"s20-100","number":100,"surah":20,"verses":[97],"references":[{"surah":20,"verses":[97]}],"verseLabel":"طه: 97","question":"ما دلالة عقوبة السامري بقوله: ﴿أَنْ تَقُولَ لَا مِسَاسَ﴾؟","answer":"صيغ النهي عن مخالطة السامري في صورة خبر يلازمه: ﴿لا مساس﴾؛ فدل على ثبوت العقوبة ودوامها، وأنه لا يمس أحدًا ولا يمسه أحد، مبالغة في عزله عن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص530، تحت عنوان «غرض التعبير عن النهي عن المساس بالإخبار عنه»","url":""}]},{"id":"s20-101","number":101,"surah":20,"verses":[97],"references":[{"surah":20,"verses":[97]}],"verseLabel":"طه: 97","question":"ما دلالة إلقاء فتات العجل ﴿فِي الْيَمِّ﴾؟","answer":"جعل البحر ظرفًا لنسف فتات العجل حتى تتفرق أجزاؤه في الماء ولا تبقى منه بقية يمكن جمعها أو تعظيمها؛ فكان ذلك أبلغ في استئصال الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص539، تحت عنوان «دلالة التعبير بالظرفية في شبه الجملة»","url":""}]},{"id":"s20-102","number":102,"surah":20,"verses":[98],"references":[{"surah":20,"verses":[98]}],"verseLabel":"طه: 98","question":"ما نكتة فصل قوله: ﴿وَسِعَ كُلَّ شَيْءٍ عِلْمًا﴾ عما قبله؟","answer":"جاءت الجملة مستقلة جوابًا عن سؤال مقدر: كيف يكون إله الناس واحدًا؟ فقررت أن الإله الحق محيط علمه بكل شيء، وبذلك تم الدليل على وحدانيته وبطلان عبادة العجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص545، تحت عنوان «نكتة فصل قوله: ﴿وَسِعَ كُلَّ شَيْءٍ عِلْمًا﴾»","url":""}]},{"id":"s20-181","number":181,"surah":20,"verses":[98],"references":[{"surah":20,"verses":[98]}],"verseLabel":"طه: 98","question":"ما فائدة لفظ العموم ﴿كُلَّ﴾ في قوله: ﴿وَسِعَ كُلَّ شَيْءٍ عِلْمًا﴾؟","answer":"أفاد لفظ ﴿كل﴾ شمول علم الله لجميع الأشياء بلا استثناء؛ فلا تخفى عليه خافية، وفي هذا كمال يختص به الإله الحق وينفي الألوهية عما سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص546، تحت عنوان «فائدة التعبير بلفظ العموم ﴿كُلّ﴾»","url":""}]},{"id":"s20-103","number":103,"surah":20,"verses":[99],"references":[{"surah":20,"verses":[99]}],"verseLabel":"طه: 99","question":"ما دلالة تقييد الذكر بقوله: ﴿مِنْ لَدُنَّا﴾؟","answer":"دل القيد ﴿من لدنا﴾ على أن القرآن صادر من عند الله خاصة، فزاد الذكر تشريفًا وتعظيمًا ووثّق صدقه وهدايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص555، تحت عنوان «فائدة القيد بالجار والمجرور ﴿مِنْ لَدُنَّا﴾»","url":""}]},{"id":"s20-182","number":182,"surah":20,"verses":[99],"references":[{"surah":20,"verses":[99]}],"verseLabel":"طه: 99","question":"ما سر التعبير بـ﴿ذِكْرًا﴾ وتنكيره في قوله: ﴿وَقَدْ آتَيْنَاكَ مِنْ لَدُنَّا ذِكْرًا﴾؟","answer":"سمي القرآن ذكرًا لما فيه من التذكير والعظة والشرف، ونُكّر اللفظ للتعظيم؛ فهو ذكر عظيم القدر كثير النفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص556، تحت عنوان «سر التعبير بـ﴿ذِكْرًا﴾ وفائدة تنكيره وتأخيره عن الجار والمجرور»","url":""}]},{"id":"s20-104","number":104,"surah":20,"verses":[100],"references":[{"surah":20,"verses":[100]}],"verseLabel":"طه: 100","question":"ما بلاغة تصوير عقوبة المعرض بقوله: ﴿يَحْمِلُ يَوْمَ الْقِيَامَةِ وِزْرًا﴾؟","answer":"صوّرت الآية تبعة الإعراض وعقوبته في هيئة حمل ثقيل يلازم صاحبه يوم القيامة، فقرّبت مشقة الجزاء وشدة وطأته بصورة محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص561، تحت عنوان «بلاغة التمثيل في قوله: ﴿يَحْمِلُ﴾»","url":""}]},{"id":"s20-105","number":105,"surah":20,"verses":[102],"references":[{"surah":20,"verses":[102]}],"verseLabel":"طه: 102","question":"ما دلالة وصف المجرمين عند الحشر بأنهم ﴿زُرْقًا﴾؟","answer":"اختير ﴿زرقًا﴾ لتصوير المجرمين يوم الحشر في هيئة مفزعة قبيحة، فقيل بزرقة عيونهم من شدة الهول، وقيل بما يظهر عليهم من أثر الخوف والعطش؛ فالوصف علامة عذابهم وإجرامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص574، تحت عنوان «نكتة إيثار لفظ ﴿زُرْقًا﴾ على غيره»","url":""}]},{"id":"s20-106","number":106,"surah":20,"verses":[103,104],"references":[{"surah":20,"verses":[103,104]}],"verseLabel":"طه: 103-104","question":"ما نكتة إيثار ﴿يَتَخَافَتُونَ﴾ في وصف كلام المجرمين يوم القيامة؟","answer":"يصوّر التخافت خفض أصواتهم وتسررهم من شدة الهول والخوف؛ فلا يملكون الجهر، ويتبادلون الكلام في صوت خفي يناسب ذلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص575، تحت عنوان «نكتة إيثار لفظ ﴿يَتَخَافَتُونَ﴾ عما سواه»","url":""}]},{"id":"s20-183","number":183,"surah":20,"verses":[103,104],"references":[{"surah":20,"verses":[103,104]}],"verseLabel":"طه: 103-104","question":"ما بلاغة الإيجاز في قولهم: ﴿إِنْ لَبِثْتُمْ إِلَّا عَشْرًا﴾؟","answer":"حذف المعدود وأبقى العدد ﴿عشرًا﴾ إيجازًا، لأن المقام يدل عليه؛ وفي تقديرهم المدة بعشر تصوير لاستقصار زمن الدنيا أو القبور أمام هول القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص576–577، تحت عنوان «بلاغة الإيجاز في ذكر العدد ﴿عَشْرًا﴾»","url":""}]},{"id":"s20-184","number":184,"surah":20,"verses":[103,104],"references":[{"surah":20,"verses":[103,104]}],"verseLabel":"طه: 103-104","question":"ما نكتة إسناد القول ﴿إِنْ لَبِثْتُمْ إِلَّا يَوْمًا﴾ إلى أمثل المجرمين؟","answer":"نسب القول إلى أمثلهم، أي أرجحهم عقلًا وطريقة، لأن تقديره أقرب في نظرهم إلى الصواب؛ ومع ذلك لم يقدّر المدة إلا يومًا، مبالغة في استقصارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص580–581، تحت عنوان «نكتة إسناد القول إلى أمثلهم»","url":""}]},{"id":"s20-107","number":107,"surah":20,"verses":[105],"references":[{"surah":20,"verses":[105]}],"verseLabel":"طه: 105","question":"ما دلالة توكيد مصير الجبال بقوله: ﴿يَنْسِفُهَا رَبِّي نَسْفًا﴾؟","answer":"جاء ﴿نسفًا﴾ مفعولًا مطلقًا مؤكدًا للفعل، فأفاد تحقق تفتيت الجبال واستئصالها التام حتى لا يبقى من أثبت معالم الأرض شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص590، تحت عنوان «دلالة التعبير بالمفعول المطلق ﴿نَسْفًا﴾»","url":""}]},{"id":"s20-108","number":108,"surah":20,"verses":[107],"references":[{"surah":20,"verses":[107]}],"verseLabel":"طه: 107","question":"ما سرّ وصف الأرض بـ﴿لَا تَرَى فِيهَا عِوَجًا وَلَا أَمْتًا﴾؟","answer":"جمع النفي بين ﴿عوجًا﴾ و﴿أمتًا﴾ ليزيل عن الأرض الانخفاض والارتفاع معًا؛ فالطباق بينهما يستوعب طرفي التضاريس ويصور استواءها التام بعد نسف الجبال.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص593، تحت عنوان «بديع الطباق بين ﴿الْعِوَجِ﴾ و﴿الْأَمْتِ﴾»","url":""}]},{"id":"s20-109","number":109,"surah":20,"verses":[108],"references":[{"surah":20,"verses":[108]}],"verseLabel":"طه: 108","question":"ما سر إسناد الخشوع إلى الأصوات في ﴿وَخَشَعَتِ الْأَصْوَاتُ لِلرَّحْمَنِ﴾؟","answer":"أُسند الخشوع إلى الأصوات مجازًا لأن أثر ذل أصحابها ظهر في خفضها وخفوتها؛ فصوّر الخشوع بأبرز مظهر مسموع منه حتى لا يكاد يبقى إلا الهمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص599، تحت عنوان «بلاغة المجاز في نسبة الخشوع إلى الأصوات»","url":""}]},{"id":"s20-110","number":110,"surah":20,"verses":[109],"references":[{"surah":20,"verses":[109]}],"verseLabel":"طه: 109","question":"ما دلالة تقييد نفع الشفاعة بإذن الرحمن ورضاه؟","answer":"جمع العطف شرطين لنفع الشفاعة: إذن الرحمن للشافع أن يتكلم، ورضاه عن قوله وشفاعته. فلا تنفع الشفاعة بذاتها ولا يستقل بها صاحبها، بل الأمر كله لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص604–605، تحت عنوان «فائدة عطف ﴿رَضِيَ﴾ على ﴿أَذِنَ﴾»","url":""}]},{"id":"s20-112","number":112,"surah":20,"verses":[111],"references":[{"surah":20,"verses":[111]}],"verseLabel":"طه: 111","question":"ما بلاغة إسناد العنت إلى الوجوه في قوله: ﴿وَعَنَتِ الْوُجُوهُ﴾؟","answer":"أُسند الخضوع والذل إلى الوجوه مجازًا لأنها موضع ظهور آثارهما، وعُبّر بها عن أصحابها؛ فصوّر الاستسلام العام لله في هيئة بادية على الوجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص612، تحت عنوان «بلاغة المجاز في إسناد العنت للوجوه»","url":""}]},{"id":"s20-113","number":113,"surah":20,"verses":[112],"references":[{"surah":20,"verses":[112]}],"verseLabel":"طه: 112","question":"ما دلالة الجمع بين نفي الظلم والهضم في ﴿فَلَا يَخَافُ ظُلْمًا وَلَا هَضْمًا﴾؟","answer":"عُطف الهضم على الظلم لأنهما جانبان مختلفان من الجور: الظلم أن يُحمّل الإنسان سيئة لم يعملها، والهضم أن يُنقص من حسناته؛ فنفت الآية الزيادة عليه والنقص من حقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص618، تحت عنوان «بلاغة عطف ﴿هَضْمًا﴾ على ﴿ظُلْمًا﴾»","url":""}]},{"id":"s20-114","number":114,"surah":20,"verses":[113],"references":[{"surah":20,"verses":[113]}],"verseLabel":"طه: 113","question":"ما سر إيثار الفعل ﴿صَرَّفْنَا﴾ في قوله: ﴿وَكَذَلِكَ أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا وَصَرَّفْنَا فِيهِ مِنَ الْوَعِيدِ﴾؟","answer":"دل ﴿صرفنا﴾ على تنويع الوعيد وتكريره في أساليب متعددة، لتقوم الحجة وتفتح للنفوس طرقًا مختلفة تردعها وتورثها التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص623، تحت عنوان «سر إيثار الفعل ﴿صَرَّفْنَا﴾ في السياق»","url":""}]},{"id":"s20-185","number":185,"surah":20,"verses":[113],"references":[{"surah":20,"verses":[113]}],"verseLabel":"طه: 113","question":"ما سر العدول إلى قوله: ﴿أَوْ يُحْدِثُ لَهُمْ ذِكْرًا﴾؟","answer":"عبّر بإحداث الذكر لا بمجرد التذكير لأن آيات الوعيد قد تنشئ في النفس تذكرًا جديدًا وآثارًا متجددة، بعد غفلة أو نسيان، فتحمل صاحبها على الاتعاظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص625، تحت عنوان «سر العدول عن ﴿يُذَكِّرُهُمْ﴾ إلى ﴿يُحْدِثُ لَهُمْ ذِكْرًا﴾»","url":""}]},{"id":"s20-115","number":115,"surah":20,"verses":[114],"references":[{"surah":20,"verses":[114]}],"verseLabel":"طه: 114","question":"ما سرّ التعبير بـ﴿وَلَا تَعْجَلْ بِالْقُرْآنِ مِنْ قَبْلِ أَنْ يُقْضَى إِلَيْكَ وَحْيُهُ﴾؟","answer":"نُهي النبي ﷺ عن مبادرة جبريل بتلاوة القرآن قبل تمام الوحي، مع شدة حرصه على حفظه؛ ليكون التلقي أولًا كاملًا مطمئنًا، ثم تأتي القراءة والترديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص634–635، تحت عنوان «النهي في الآية عن التعجل بالقرآن»","url":""}]},{"id":"s20-116","number":116,"surah":20,"verses":[114],"references":[{"surah":20,"verses":[114]}],"verseLabel":"طه: 114","question":"ما دلالة عطف الأمر ﴿وَقُلْ رَبِّ زِدْنِي عِلْمًا﴾ على النهي عن العجلة بالقرآن؟","answer":"وصلت الواو بين النهي والأمر لتدل على أن ترك العجلة لا يعني فتور طلب العلم؛ بل يضبط الشوق بحسن التلقي، ثم يوجهه إلى سؤال الله الزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص637، تحت عنوان «دلالة الواو وعطف النهي بالأمر»","url":""}]},{"id":"s20-186","number":186,"surah":20,"verses":[114],"references":[{"surah":20,"verses":[114]}],"verseLabel":"طه: 114","question":"ما سر إيثار طلب الزيادة من العلم في قوله: ﴿رَبِّ زِدْنِي عِلْمًا﴾؟","answer":"أُمر بطلب الزيادة من العلم لأن العلم لا ينتهي إلى حد يستغني معه العبد عن تعليم ربه؛ وفيه تشريف للعلم، وحث على دوام التعلم مع التواضع لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص638، تحت عنوان «سر إيثار طلب الزيادة من العلم»","url":""}]},{"id":"s20-117","number":117,"surah":20,"verses":[115],"references":[{"surah":20,"verses":[115]}],"verseLabel":"طه: 115","question":"ما بلاغة التعبير بالنسيان في قوله: ﴿فَنَسِيَ﴾ عن آدم؟","answer":"يجوز أن يكون النسيان حقيقيًا، أو مجازًا عن ترك العهد وعدم مراعاته؛ وفي التعبير إظهار لضعف الإنسان من غير أن يكون عذرًا يرفع تبعة المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص648، تحت عنوان «بلاغة التعبير بالنسيان بين الحقيقة والمجاز»","url":""}]},{"id":"s20-187","number":187,"surah":20,"verses":[115],"references":[{"surah":20,"verses":[115]}],"verseLabel":"طه: 115","question":"ما دلالة استعمال لفظ ﴿الْعَزْمِ﴾ في قوله: ﴿وَلَمْ نَجِدْ لَهُ عَزْمًا﴾؟","answer":"العزم قوة الثبات على الأمر؛ فنفيه يصور أن آدم لم يثبت على الوفاء بالعهد عند وسوسة إبليس، لا أنه تعمد الإصرار على المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص650، تحت عنوان «دلالة استعمال لفظ العزم دون غيره»","url":""}]},{"id":"s20-188","number":188,"surah":20,"verses":[115],"references":[{"surah":20,"verses":[115]}],"verseLabel":"طه: 115","question":"ما دلالة تقديم خاتمة قصة آدم في قوله: ﴿وَلَقَدْ عَهِدْنَا إِلَى آدَمَ مِنْ قَبْلُ فَنَسِيَ﴾؟","answer":"قدمت خلاصة القصة قبل تفصيل أحداثها تمهيدًا للعبرة وإجمالًا لما سيشرح؛ فتهيأ السامع لقصة الضعف والمخالفة ثم الاجتباء والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص651، تحت عنوان «دلالة تقديم ذكر خاتمة قصة آدم على أحداثها»","url":""}]},{"id":"s20-118","number":118,"surah":20,"verses":[116],"references":[{"surah":20,"verses":[116]}],"verseLabel":"طه: 116","question":"ما سرّ التعبير بـ﴿أَبَى﴾ في موقف إبليس؟","answer":"اختير ﴿أبى﴾ لأن الإباء امتناع عن قبول الأمر مع رفض واستكبار، لا مجرد ترك للسجود ولا نسيان له؛ ففضح موقف إبليس النفسي من الأمر الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص660، تحت عنوان «سر التعبير بالإباء دون غيره من مرادفاته»","url":""}]},{"id":"s20-119","number":119,"surah":20,"verses":[117],"references":[{"surah":20,"verses":[117]}],"verseLabel":"طه: 117","question":"ما سرّ تسمية إبليس ﴿عَدُوٌّ لَكَ وَلِزَوْجِكَ﴾ قبل الوسوسة؟","answer":"أُخبر آدم وزوجه بعداوة إبليس قبل وسوسته ليعرفا حقيقة الناصح المزيف ويحذرا إغراءه؛ فإذا أتاهما قامت عليهما الحجة بالتحذير السابق من عدوهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص668، تحت عنوان «علة الإخبار عن إبليس بأنه عدو لآدم وزوجه ابتداء»","url":""}]},{"id":"s20-120","number":120,"surah":20,"verses":[117],"references":[{"surah":20,"verses":[117]}],"verseLabel":"طه: 117","question":"ما سرّ التعبير بـ﴿فَلَا يُخْرِجَنَّكُمَا مِنَ الْجَنَّةِ فَتَشْقَى﴾ فأفرد الشقاء؟","answer":"أفرد ﴿فتشقى﴾ بعد تثنية ﴿يخرجنكما﴾ لأن آدم هو المخاطب الأول، ولأن تعب تحصيل المعاش بعد الخروج يبرز في حقه؛ كما أن شقاء أحد الزوجين يمتد أثره إلى الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص671، تحت عنوان «سر إسناد ﴿فَتَشْقَى﴾ إلى الضمير المفرد العائد على آدم»","url":""}]},{"id":"s20-121","number":121,"surah":20,"verses":[118,119],"references":[{"surah":20,"verses":[118,119]}],"verseLabel":"طه: 118-119","question":"ما نكتة العدول عن التصريح بنعيم الجنة إلى نفي نقائضه؟","answer":"وُصف نعيم الجنة بنفي الجوع والعري والظمأ والضحى لأن زوال هذه الآفات أبلغ في إشعار آدم بالأمن وكمال الكفاية، ويزيد التحذير من فقدانها بالخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص677، تحت عنوان «نكتة العدول عن التصريح بالنعم إلى نفي نقائضها»","url":""}]},{"id":"s20-189","number":189,"surah":20,"verses":[118,119],"references":[{"surah":20,"verses":[118,119]}],"verseLabel":"طه: 118-119","question":"ما سر تخصيص الجوع والعري والظمأ والضحى بالذكر في نعيم الجنة؟","answer":"جمعت المذكورات أصول الحاجة البدنية: الطعام بنفي الجوع، والكسوة بنفي العري، والشراب بنفي الظمأ، والكن أو الظل بنفي الضحى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص681، تحت عنوان «سر تخصيص المذكورات الأربع»","url":""}]},{"id":"s20-122","number":122,"surah":20,"verses":[120],"references":[{"surah":20,"verses":[120]}],"verseLabel":"طه: 120","question":"ما دلالة إضافة الشجرة إلى الخلد في قول إبليس: ﴿شَجَرَةِ الْخُلْدِ﴾؟","answer":"أضاف الشجرة إلى الخلد زعمًا أنها سبب البقاء الدائم؛ فزيّن المعصية لآدم بإثارة رغبته في دوام الحياة وعدم الفناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص690، تحت عنوان «دلالة إضافة الشجرة إلى الخلد»","url":""}]},{"id":"s20-190","number":190,"surah":20,"verses":[120],"references":[{"surah":20,"verses":[120]}],"verseLabel":"طه: 120","question":"ما فائدة عطف ﴿وَمُلْكٍ لَا يَبْلَى﴾ على ﴿شَجَرَةِ الْخُلْدِ﴾؟","answer":"جمع إبليس في إغرائه بين رغبتين: الخلود في الحياة، ودوام السلطان والنعيم؛ فزاد بالعطف بابًا آخر من الترغيب في المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص691، تحت عنوان «فائدة عطف ﴿وَمُلْكٍ لَا يَبْلَى﴾ على ما قبله»","url":""}]},{"id":"s20-191","number":191,"surah":20,"verses":[120],"references":[{"surah":20,"verses":[120]}],"verseLabel":"طه: 120","question":"ما بلاغة إطلاق البِلى على الملك في قوله: ﴿وَمُلْكٍ لَا يَبْلَى﴾؟","answer":"استعير البِلى، وهو تآكل الثوب، للملك الذي يضعف ويزول؛ فنفيه صوّر الملك المزعوم ثابتًا لا ينقص ولا يفنى، وهو من تزيين إبليس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص691، تحت عنوان «بلاغة المجاز في إطلاق البلى على الملك»","url":""}]},{"id":"s20-123","number":123,"surah":20,"verses":[121],"references":[{"surah":20,"verses":[121]}],"verseLabel":"طه: 121","question":"ما دلالة الفاء في قوله: ﴿فَبَدَتْ لَهُمَا سَوْآتُهُمَا﴾؟","answer":"ربطت الفاء ظهور سوآتهما بالأكل من الشجرة، فصورت سرعة تعاقب أثر المخالفة على فعلها وانكشاف ما كان مستورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص698، تحت عنوان «معنى الفاء في ﴿فَبَدَتْ﴾»","url":""}]},{"id":"s20-192","number":192,"surah":20,"verses":[121],"references":[{"surah":20,"verses":[121]}],"verseLabel":"طه: 121","question":"ما سر إيثار لفظ ﴿سَوْآتُهُمَا﴾ في قصة آدم وزوجه؟","answer":"اختيرت السوأة لأنها ما يسوء الإنسان انكشافه ويحرص على ستره؛ فناسب اللفظ شعورهما بالخجل ومسارعتهما إلى تغطية ما ظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص699، تحت عنوان «سر إيثار التعبير بلفظ ﴿سَوْآتُهُمَا﴾»","url":""}]},{"id":"s20-124","number":124,"surah":20,"verses":[121],"references":[{"surah":20,"verses":[121]}],"verseLabel":"طه: 121","question":"ما نكتة التعبير بـ﴿طَفِقَا﴾ في ستر آدم وزوجه سوآتهما؟","answer":"دل ﴿طفقا﴾ على الشروع السريع والاستمرار في الفعل، فصوّر مبادرتهما إلى الستر فور انكشاف سوآتهما وشدة حرصهما عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص699، تحت عنوان «نكتة التعبير بالفعل ﴿طَفِقَا﴾»","url":""}]},{"id":"s20-125","number":125,"surah":20,"verses":[122],"references":[{"surah":20,"verses":[122]}],"verseLabel":"طه: 122","question":"ما سر التعبير باجتباء آدم في قوله: ﴿ثُمَّ اجْتَبَاهُ رَبُّهُ﴾؟","answer":"الاجتباء اصطفاء واختيار مع تقريب؛ فدل على أن الله أعاد آدم إلى مقام القرب بعد زلته، وفتح له باب الرحمة والإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص703، تحت عنوان «سر التعبير بالفعل ﴿اجْتَبَاهُ﴾»","url":""}]},{"id":"s20-193","number":193,"surah":20,"verses":[122],"references":[{"surah":20,"verses":[122]}],"verseLabel":"طه: 122","question":"ما فائدة تكرار لفظ ﴿رَبُّهُ﴾ عند اجتباء آدم؟","answer":"أُظهر وصف الربوبية في مقام الاجتباء لإبراز رعاية الله لعبده وتربيته ورحمته بعد الزلة؛ فالمقام مقام إصلاح وقبول لا يأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص704، تحت عنوان «فائدة تكرار لفظ ﴿رَبُّهُ﴾ في الاجتباء»","url":""}]},{"id":"s20-194","number":194,"surah":20,"verses":[122],"references":[{"surah":20,"verses":[122]}],"verseLabel":"طه: 122","question":"ما سر الجمع بين التوبة والهداية في قوله: ﴿فَتَابَ عَلَيْهِ وَهَدَى﴾؟","answer":"جمع له بين قبول رجوعه ومحو أثر زلته بالتوبة، وبين توفيقه إلى طريق الخير والثبات عليه بالهداية؛ فتمت له الرحمة والإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص704، تحت عنوان «سر الجمع بين التوبة والهداية»","url":""}]},{"id":"s20-126","number":126,"surah":20,"verses":[123],"references":[{"surah":20,"verses":[123]}],"verseLabel":"طه: 123","question":"ما دلالة الجملة الحالية: ﴿بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ﴾؟","answer":"بيّنت الجملة أن الهبوط إلى الأرض يقع مصحوبًا بالعداوة، ولا سيما عداوة الشيطان للإنسان وما ينشأ عنها من صراع وضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص711، تحت عنوان «دلالة التقييد بالجملة الحالية بعد التقييد بالحال الصريحة»","url":""}]},{"id":"s20-127","number":127,"surah":20,"verses":[123],"references":[{"surah":20,"verses":[123]}],"verseLabel":"طه: 123","question":"ما سرّ التعبير بـ﴿فَمَنِ اتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشْقَى﴾؟","answer":"جمع الوعد بين نفي الضلال ونفي الشقاء؛ فمن اتبع هدى الله سلم من الانحراف في طريقه، ونجا من سوء العاقبة المترتب عليه، فاجتمع له الهدى والسعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص714، تحت عنوان «دلالة الجمع بين نفي الضلال ونفي الشقاء»","url":""}]},{"id":"s20-128","number":128,"surah":20,"verses":[124],"references":[{"surah":20,"verses":[124]}],"verseLabel":"طه: 124","question":"ما دلالة وصف معيشة المعرض عن الذكر بأنها ﴿ضَنْكًا﴾؟","answer":"جاء ﴿ضنكًا﴾ مصدرًا يوصف به للمبالغة، فصوّر معيشة المعرض شديدة الضيق ملازمة له؛ ويدخل فيها ضيق القلب ولو اتسع ظاهر رزقه، كما تشمل وجوهًا من عذاب الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص722، تحت عنوان «بلاغة المصدر ﴿ضَنْكًا﴾ باعتباره لفظًا فريدًا»","url":""}]},{"id":"s20-129","number":129,"surah":20,"verses":[125,126],"references":[{"surah":20,"verses":[125,126]}],"verseLabel":"طه: 125-126","question":"ما دلالة استفهام الأعمى يوم القيامة: ﴿لِمَ حَشَرْتَنِي أَعْمَى وَقَدْ كُنْتُ بَصِيرًا﴾؟","answer":"استفهم متعجبًا مستنكرًا ما آل إليه، وجعل بصره السابق موضع احتجاج؛ فكشف السؤال جهله بسبب الجزاء وعجزه عن الدفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص723، تحت عنوان «دلالة الاستفهام في الآية»","url":""}]},{"id":"s20-130","number":130,"surah":20,"verses":[127],"references":[{"surah":20,"verses":[127]}],"verseLabel":"طه: 127","question":"ما نكتة التعبير بـ﴿أَسْرَفَ﴾ في قوله: ﴿وَكَذَلِكَ نَجْزِي مَنْ أَسْرَفَ﴾؟","answer":"اختير الإسراف لأنه مجاوزة الحد، فجمع ما وقعوا فيه من إفراط في الكفر والتكذيب والإعراض، وبيّن أن الجزاء ناشئ عن تجاوزهم حدود الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص735، تحت عنوان «نكتة التعبير بـ﴿أَسْرَفَ﴾ مادة وصيغة»","url":""}]},{"id":"s20-195","number":195,"surah":20,"verses":[127],"references":[{"surah":20,"verses":[127]}],"verseLabel":"طه: 127","question":"ما نكتة التعبير بـ﴿أَشَدُّ﴾ في قوله: ﴿وَلَعَذَابُ الْآخِرَةِ أَشَدُّ﴾؟","answer":"جاء اسم التفضيل ﴿أشد﴾ ليقارن عذاب الآخرة بما يعاينه المكذبون من عقوبات الدنيا، فيقرر أن عذابها أعظم قوة وأبلغ إيلامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص739، تحت عنوان «نكتة التعبير بـ﴿أَشَدُّ﴾ دون شديد»","url":""}]},{"id":"s20-196","number":196,"surah":20,"verses":[127],"references":[{"surah":20,"verses":[127]}],"verseLabel":"طه: 127","question":"ما بلاغة وصف عذاب الآخرة بأنه ﴿أَبْقَى﴾؟","answer":"وصفه بأنه ﴿أبقى﴾ ليبين دوام عذاب الآخرة وعدم انقطاعه، فيجتمع فيه مع شدة الألم طول المكث بخلاف عقوبة الدنيا الزائلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص740، تحت عنوان «بلاغة وصف العذاب بقوله: ﴿وَأَبْقَى﴾»","url":""}]},{"id":"s20-131","number":131,"surah":20,"verses":[128],"references":[{"surah":20,"verses":[128]}],"verseLabel":"طه: 128","question":"ما دلالة تخصيص ﴿أُولِي النُّهَى﴾ بالانتفاع بآيات هلاك القرون؟","answer":"وصفهم بأولي النهى لأن عقولهم تنهاهم عن الباطل وتردعهم عن سلوك طريق المكذبين؛ فهم الذين يتجاوزون مجرد المرور بمساكن الهالكين إلى الاتعاظ بعاقبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص759، تحت عنوان «سر التعبير بـ﴿أُولِي النُّهَى﴾ دون أولي الألباب»","url":""}]},{"id":"s20-132","number":132,"surah":20,"verses":[129],"references":[{"surah":20,"verses":[129]}],"verseLabel":"طه: 129","question":"ما نكتة التعبير بـ﴿لِزَامًا﴾ في قوله: ﴿لَكَانَ لِزَامًا﴾؟","answer":"دل ﴿لزامًا﴾ على عذاب لازم لا يفارق المكذبين، وجاء بالمصدر للمبالغة في تحقق اللزوم؛ ولولا كلمة الإمهال السابقة لعاجلهم هذا الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص768، تحت عنوان «نكتة التعبير بـ﴿لِزَامًا﴾ مادة وصيغة»","url":""}]},{"id":"s20-133","number":133,"surah":20,"verses":[130],"references":[{"surah":20,"verses":[130]}],"verseLabel":"طه: 130","question":"ما فائدة عطف التسبيح على الأمر بالصبر في قوله: ﴿فَاصْبِرْ عَلَى مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ﴾؟","answer":"عطف التسبيح على الصبر لأن ذكر الله والصلاة زاد يعين الرسول على احتمال أذى المكذبين، وينقل القلب من الانشغال بأقوالهم إلى الثناء على ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص776، تحت عنوان «فائدة عطف التسبيح على الأمر بالصبر»","url":""}]},{"id":"s20-197","number":197,"surah":20,"verses":[130],"references":[{"surah":20,"verses":[130]}],"verseLabel":"طه: 130","question":"ما بلاغة التعبير عن الصلاة بالتسبيح في قوله: ﴿وَسَبِّحْ بِحَمْدِ رَبِّكَ﴾؟","answer":"عُبّر عن الصلاة بالتسبيح لأنها مشتملة عليه، ولأن تنزيه الله وحمده روح عبادتها؛ فذكر أبرز مقاصدها وأشرف أجزائها وأراد العبادة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص778، تحت عنوان «بلاغة المجاز في التعبير عن الصلاة بالتسبيح»","url":""}]},{"id":"s20-198","number":198,"surah":20,"verses":[130],"references":[{"surah":20,"verses":[130]}],"verseLabel":"طه: 130","question":"ما فائدة عطف ﴿وَأَطْرَافَ النَّهَارِ﴾ بعد ذكر أوقات التسبيح؟","answer":"أكمل العطف استيعاب أوقات الصلاة والذكر في جوانب النهار، فضم إلى ما قبل طلوع الشمس وقبل غروبها سائر الأطراف المناسبة للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص784، تحت عنوان «فائدة عطف ﴿وَأَطْرَافَ النَّهَارِ﴾»","url":""}]},{"id":"s20-134","number":134,"surah":20,"verses":[131],"references":[{"surah":20,"verses":[131]}],"verseLabel":"طه: 131","question":"ما بلاغة النهي عن مد العينين في قوله: ﴿لَا تَمُدَّنَّ عَيْنَيْكَ﴾؟","answer":"صوّر مد العينين إطالة النظر المصحوب بالإعجاب والتطلع إلى ما في أيدي المترفين، فنهى عن تعلق القلب بزينة لا تدوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص793، تحت عنوان «بلاغة المجاز في قوله: ﴿لَا تَمُدَّنَّ عَيْنَيْكَ﴾»","url":""}]},{"id":"s20-199","number":199,"surah":20,"verses":[131],"references":[{"surah":20,"verses":[131]}],"verseLabel":"طه: 131","question":"ما بلاغة وصف متاع الدنيا بأنه ﴿زَهْرَةَ الْحَيَاةِ الدُّنْيَا﴾؟","answer":"شبّه زينة الدنيا بزهرة حسنة المنظر سريعة الذبول؛ فهي تفتن عند إقبالها، لكن جمالها عارض وعمرها قصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص798، تحت عنوان «بلاغة التشبيه في قوله: ﴿زَهْرَةَ الْحَيَاةِ الدُّنْيَا﴾»","url":""}]},{"id":"s20-200","number":200,"surah":20,"verses":[131],"references":[{"surah":20,"verses":[131]}],"verseLabel":"طه: 131","question":"ما سر التعبير بالفتنة في قوله: ﴿لِنَفْتِنَهُمْ فِيهِ﴾؟","answer":"سمّى ما مُتعوا به فتنة لأنه اختبار يكشف موقفهم: أيشكرون المنعم ويستعملون النعمة في طاعته، أم يغترون بها ويعرضون؟","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص800، تحت عنوان «سر التعبير بالفتنة في قوله: ﴿لِنَفْتِنَهُمْ فِيهِ﴾»","url":""}]},{"id":"s20-135","number":135,"surah":20,"verses":[131],"references":[{"surah":20,"verses":[131]}],"verseLabel":"طه: 131","question":"ما سر التعبير بـ﴿رِزْقُ رَبِّكَ﴾ بعد النهي عن التطلع إلى زهرة الدنيا؟","answer":"قابل زهرة الدنيا الزائلة برزق منسوب إلى الرب، ليطمئن الرسول والمؤمن إلى أن ما يمنحه الله من هداية وقناعة وثواب خير من متاع المفتونين وأدوم أثرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص801، تحت عنوان «سر التعبير بالرزق دون غيره»","url":""}]},{"id":"s20-136","number":136,"surah":20,"verses":[132],"references":[{"surah":20,"verses":[132]}],"verseLabel":"طه: 132","question":"ما دلالة تخصيص الأهل بالأمر في قوله: ﴿وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ﴾؟","answer":"خُص الأهل لأنهم أولى الناس بالرعاية والتعليم، ولأن إصلاح البيت بالصلاة يجعل الدعوة سلوكًا معاشًا يبدأ من أقرب الدوائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص12، تحت عنوان «دلالة الإتيان بلفظ ﴿أَهْلَكَ﴾»","url":""}]},{"id":"s20-201","number":201,"surah":20,"verses":[132],"references":[{"surah":20,"verses":[132]}],"verseLabel":"طه: 132","question":"ما دلالة صيغة ﴿وَاصْطَبِرْ عَلَيْهَا﴾ في الأمر بالصلاة؟","answer":"صيغة الاصطبار أقوى من مطلق الصبر؛ فهي تدل على معالجة النفس ومداومة احتمال مشقة المحافظة على الصلاة وأمر الأهل بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص13، تحت عنوان «دلالة صيغة ﴿وَاصْطَبِرْ﴾»","url":""}]},{"id":"s20-137","number":137,"surah":20,"verses":[132],"references":[{"surah":20,"verses":[132]}],"verseLabel":"طه: 132","question":"ما نكتة تنكير ﴿رِزْقًا﴾ في قوله: ﴿لَا نَسْأَلُكَ رِزْقًا﴾؟","answer":"نُكّر الرزق في سياق النفي ليفيد العموم: لا يطلب الله من عبده شيئًا من الرزق، وإنما يطلب منه العبادة والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص15، تحت عنوان «نكتة تنكير ﴿رِزْقًا﴾»","url":""}]},{"id":"s20-202","number":202,"surah":20,"verses":[132],"references":[{"surah":20,"verses":[132]}],"verseLabel":"طه: 132","question":"ما نكتة تقديم ﴿نَحْنُ﴾ في قوله: ﴿نَحْنُ نَرْزُقُكَ﴾؟","answer":"قُدّم الضمير لتقوية الحكم وإبراز أن الله هو المتكفل بالرزق، فيزول وهم أن الاشتغال بالصلاة يضيّع المعاش.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص17، تحت عنوان «نكتة تقديم المسند في قوله: ﴿نَحْنُ نَرْزُقُكَ﴾»","url":""}]},{"id":"s20-138","number":138,"surah":20,"verses":[133],"references":[{"surah":20,"verses":[133]}],"verseLabel":"طه: 133","question":"ما نكتة العدول من قولهم: ﴿بِآيَةٍ مِنْ رَبِّهِ﴾ إلى وصف القرآن بأنه ﴿الْبَيِّنَةُ﴾؟","answer":"طلبوا آية مقترحة تعنتًا، فواجههم القرآن بوصفه البينة: حجة ظاهرة جامعة لما في الصحف الأولى، لا مجرد علامة حسية عابرة؛ فظهر أن اعتراضهم ليس لنقص الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص27، تحت عنوان «نكتة اختيار البينة بدل آية»","url":""}]},{"id":"s20-139","number":139,"surah":20,"verses":[134],"references":[{"surah":20,"verses":[134]}],"verseLabel":"طه: 134","question":"ما بلاغة التعبير بالشرط في قولهم: ﴿لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ﴾؟","answer":"صيغ كلامهم في صورة شرط ليصور العذر الذي كانوا سيتعللون به لو عوجلوا بالعذاب قبل الرسالة، وقد قطع إرسال الرسول هذا الاعتذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص31، تحت عنوان «بلاغة التعبير بالجملة الشرطية»","url":""}]},{"id":"s20-203","number":203,"surah":20,"verses":[134],"references":[{"surah":20,"verses":[134]}],"verseLabel":"طه: 134","question":"ما سر الجمع بين الذل والخزي في قوله: ﴿مِنْ قَبْلِ أَنْ نَذِلَّ وَنَخْزَى﴾؟","answer":"جمعوا بين الذل، وهو الهوان والقهر، والخزي، وهو الفضيحة والعار؛ فاستوعب التعبير سوء حالهم ظاهرًا وباطنًا لو نزل بهم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص38، تحت عنوان «سر التعبير بالذل والخزي عن الهلاك»","url":""}]},{"id":"s20-140","number":140,"surah":20,"verses":[135],"references":[{"surah":20,"verses":[135]}],"verseLabel":"طه: 135","question":"ما بلاغة ربط ختام سورة طه بمطلعها؟","answer":"افتتحت السورة ببيان أن القرآن تذكرة لا سبب شقاء، وختمت بأن العاقبة ستكشف أهل الصراط السوي والمهتدين؛ فجمع الطرفان بين وظيفة الوحي وظهور ثمرة اتباعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص49، تحت عنوان «بلاغة ربط ختام السورة بمطلعها»","url":""}]},{"id":"s20-204","number":204,"surah":20,"verses":[40],"references":[{"surah":20,"verses":[40]}],"verseLabel":"طه: 40","question":"ما سر قوله: ﴿هَلْ أَدُلُّكُمْ عَلَىٰ مَن يَكْفُلُهُ﴾، وفي القصص: ﴿عَلَىٰ أَهْلِ بَيْتٍ يَكْفُلُونَهُ لَكُمْ﴾؟","answer":"ذكر في القصص امرأة فرعون وهي أهل بيته، وذكر ﴿آلُ فِرْعَوْنَ﴾ وأصل «آل» أهل، فناسب أن تدلّ أهلَ بيت فرعون على أهل بيت، وليس في طه شيء من ذلك. ثم إن القصة هنا أوجز، فناسب الإيجازَ الإيجاز. ولفظ «أهل» في القصص أكثر، و«مَن» في طه أكثر.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص122–124.","url":""}]},{"id":"s20-205","number":205,"surah":20,"verses":[78],"references":[{"surah":20,"verses":[78]}],"verseLabel":"طه: 78","question":"ما سر الباء في قوله: ﴿فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِ﴾، والواو في يونس: ﴿فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُ﴾؟","answer":"الواو تدل نصًّا على أن فرعون كان مع جنوده متّبعًا لموسى وقومه، والباء تحتمل ذلك وتحتمل أنه أرسل جنوده ولم يخرج معهم. وسياق يونس يذكر بطش فرعون وبغيه وغرقه وحده، وسياق طه يذكر غرق الجند: ﴿فَغَشِيَهُم﴾، ثم قال: ﴿وَأَضَلَّ فِرْعَوْنُ قَوْمَهُ﴾ فكان موجِّهًا لهم.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص143–145.","url":""}]},{"id":"s20-206","number":206,"surah":20,"verses":[94],"references":[{"surah":20,"verses":[94]}],"verseLabel":"طه: 94","question":"ما سر ذكر حرف النداء في قوله: ﴿قَالَ يَا ابْنَ أُمَّ لَا تَأْخُذْ بِلِحْيَتِي﴾، وحذفه في الأعراف: ﴿قَالَ ابْنَ أُمَّ﴾؟","answer":"سياق الأعراف سياق إيجاز وعجلة، فقد أخذ موسى برأس أخيه يجره إليه، فأراد هارون الإسراع في البيان فحذف «يا». أما سياق طه فسياق تبسّط وسؤال وأخذ ورد ولوم، فجاء بـ«يا» متودّدًا يحاول كسر حدة غضبه.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص323–324.","url":""}]},{"id":"s20-207","number":207,"surah":20,"verses":[110],"references":[{"surah":20,"verses":[110]}],"verseLabel":"طه: 110","question":"ما سر نفي الإحاطة بذاته في قوله: ﴿وَلَا يُحِيطُونَ بِهِ عِلْمًا﴾، ونفيها بعلمه في آية الكرسي: ﴿وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ﴾؟","answer":"آية طه جاءت بعد ذكر العجل الذي اتخذه بنو إسرائيل إلهًا، وقد أحاطوا به علمًا لأنهم صنعوه بأيديهم من الذهب، أما الله فلا يُحاط به علمًا، فنفى الإحاطة بذاته. وآية الكرسي في سياق العلم، فنفى الإحاطة بشيء من علمه.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص199.","url":""}]},{"id":"s20-208","number":208,"surah":20,"verses":[2],"references":[{"surah":20,"verses":[2]}],"verseLabel":"طه: 2","question":"ما سر ذكر «القرآن» دون «الكتاب» بعد الحرفين في قوله: ﴿طه ۝ مَا أَنزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَىٰ﴾؟","answer":"السور المفتتحة بالحروف المقطعة إذا ذُكر فيها القرآن وحده بعد الحروف تردّد لفظ القرآن فيها أكثر من لفظ الكتاب. وهكذا طه: ورد فيها لفظ القرآن ثلاث مرات ولفظ الكتاب مرة واحدة، فناسب الافتتاحُ جوَّ السورة، وهذا من عجائب التعبير ودقيقه.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص250.","url":""}]},{"id":"s20-209","number":209,"surah":20,"verses":[11],"references":[{"surah":20,"verses":[11]}],"verseLabel":"طه: 11","question":"ما سر قوله: ﴿فَلَمَّا أَتَاهَا نُودِيَ يَا مُوسَىٰ﴾، وفي النمل: ﴿فَلَمَّا جَاءَهَا نُودِيَ﴾؟","answer":"ألفاظ الإتيان في طه أكثر منها في النمل، فقد وردت فيها خمس عشرة مرة، نحو ﴿فَأْتِيَاهُ﴾ و﴿ثُمَّ ائْتُوا صَفًّا﴾ و﴿حَيْثُ أَتَىٰ﴾. وألفاظ المجيء في النمل ثماني مرات وفي طه أربع، فوُضع كل لفظ في الموضع الذي يغلب فيه. وفي «البرهان» للكرماني نحو هذا التوجيه.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص243–244؛ من أسرار البيان القرآني، ص183.","url":""}]},{"id":"s20-210","number":210,"surah":20,"verses":[15],"references":[{"surah":20,"verses":[15]}],"verseLabel":"طه: 15","question":"ما سر قوله: ﴿إِنَّ السَّاعَةَ آتِيَةٌ أَكَادُ أُخْفِيهَا﴾ بلا لام، وفي غافر: ﴿إِنَّ السَّاعَةَ لَآتِيَةٌ﴾؟","answer":"الخطاب في طه لموسى عليه السلام، وهو غير منكر للساعة فاكتفى بتوكيدها بـ«إنّ». أما آية غافر فقيلت في سياق المنكرين، وعُقّبت بقوله: ﴿وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ﴾، وجوّ السورة في الكلام على الساعة، فزاد التوكيد باللام.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص170–171.","url":""}]},{"id":"s20-211","number":211,"surah":20,"verses":[33,34],"references":[{"surah":20,"verses":[33,34]}],"verseLabel":"طه: 33–34","question":"ما سر تقديم التسبيح على الذكر في قوله: ﴿كَيْ نُسَبِّحَكَ كَثِيرًا ۝ وَنَذْكُرَكَ كَثِيرًا﴾؟","answer":"الذكر أعم من التسبيح، والأصل تقديم الأعم. لكن موسى كان في حال خوف من فرعون، كما قال: ﴿إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَا أَوْ أَن يَطْغَىٰ﴾، والتسبيح يُنجّي من الغم والكرب، كما نجّى يونس: ﴿فَلَوْلَا أَنَّهُ كَانَ مِنَ الْمُسَبِّحِينَ﴾، فقدّمه.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص29.","url":""}]},{"id":"s20-212","number":212,"surah":20,"verses":[40],"references":[{"surah":20,"verses":[40]}],"verseLabel":"طه: 40","question":"ما سر قوله: ﴿فَرَجَعْنَاكَ إِلَىٰ أُمِّكَ﴾، وفي القصص: ﴿فَرَدَدْنَاهُ إِلَىٰ أُمِّهِ﴾؟","answer":"ذكر في القصص فراغ فؤاد أم موسى وكادت تُبدي به، فاشتد الأمر عليها فناسب «الرد» الأثقل لفظًا بالتضعيف. وذكر في طه مننه على موسى، ولا يناسبها ذكر عذاب أمه، فجاء بـ«رجع» الأخف. ثم إن «رجع» ورد في طه ولم يرد فيها «ردّ»، و«رددناه» يوافق ﴿إِنَّا رَادُّوهُ إِلَيْكِ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص53–55.","url":""}]},{"id":"s20-213","number":213,"surah":20,"verses":[46],"references":[{"surah":20,"verses":[46]}],"verseLabel":"طه: 46","question":"ما سر تقديم السمع على الرؤية في قوله: ﴿لَا تَخَافَا إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَىٰ﴾؟","answer":"مدى السمع أقل من مدى الرؤية، فالذي يسمعك يكون في العادة قريبًا منك، بخلاف الذي يراك فقد يكون بعيدًا. فلما خافا من فرعون قدّم السمع إشعارًا بالقرب منهما والمعيّة لهما، وإن كان الله لا يند عن سمعه شيء.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص56.","url":""}]},{"id":"s20-214","number":214,"surah":20,"verses":[53],"references":[{"surah":20,"verses":[53]}],"verseLabel":"طه: 53","question":"ما سر قوله: ﴿وَسَلَكَ لَكُمْ فِيهَا سُبُلًا﴾، وفي الزخرف: ﴿وَجَعَلَ لَكُمْ فِيهَا سُبُلًا﴾؟","answer":"المقام في طه مقام تلطف ولين مع فرعون: ﴿فَقُولَا لَهُ قَوْلًا لَّيِّنًا﴾، و«سلك» أيسر من «جعل»، فقد ذلّل لهم السبل لسلوكها. والمقام في الزخرف مقام تقريع وبيان قدرة. ثم إن فعل الجعل ورد في الزخرف اثنتي عشرة مرة وفي طه ثلاث مرات، فناسب كل فعل موطنه.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص64–65؛ التعبير القرآني، ص246.","url":""}]},{"id":"s20-215","number":215,"surah":20,"verses":[67],"references":[{"surah":20,"verses":[67]}],"verseLabel":"طه: 67","question":"ما سر تأخير الفاعل في قوله: ﴿فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مُّوسَىٰ﴾؟","answer":"ليس لمراعاة الفاصلة وحدها؛ فتقديم ﴿فِي نَفْسِهِ﴾ يدل على أن الخوف بقي في نفسه ولم يظهر أمام الملأ، وذلك مهم في هذا الموقف، وموسى معلوم لو لم يُذكر. وهو إيضاح بعد إبهام شاع في السورة، وبناؤه موافق للآية قبله: ﴿يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَىٰ﴾.","sources":[{"label":"فاضل السامرائي، الجملة العربية تأليفها وأقسامها، ص49–54.","url":""}]},{"id":"s20-216","number":216,"surah":20,"verses":[70],"references":[{"surah":20,"verses":[70]}],"verseLabel":"طه: 70","question":"ما سر تقديم هارون في قوله: ﴿آمَنَّا بِرَبِّ هَارُونَ وَمُوسَىٰ﴾، وفي الشعراء: ﴿رَبِّ مُوسَىٰ وَهَارُونَ﴾؟","answer":"ليس للفاصلة وحدها؛ فالقصة في طه مبنية على التثنية، فقد جعل هارون شريكًا لموسى في أمره، وخاطبهما فرعون معًا ونسبهما إلى السحر. وذكر فيها خوف موسى، أما الشعراء فمبنية على الإفراد وإبراز قوة موسى، فاقتضى ذلك المغايرة بين الموضعين.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص226–228.","url":""}]},{"id":"s20-217","number":217,"surah":20,"verses":[77],"references":[{"surah":20,"verses":[77]}],"verseLabel":"طه: 77","question":"ما سر عطف الخشية على الخوف في قوله: ﴿لَّا تَخَافُ دَرَكًا وَلَا تَخْشَىٰ﴾؟","answer":"المعنى: لا تخاف أن يدرككم فرعون وجنوده من خلفكم، ولا تخشى أن يغرقكم البحر من أمامكم. والخشية أعظم الخوف، فاختيرت للغرق لأنه أعظم من إدراك فرعون. وهذا التوجيه منقول عن «روح المعاني».","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص139.","url":""}]},{"id":"s20-218","number":218,"surah":20,"verses":[77,78],"references":[{"surah":20,"verses":[77,78]}],"verseLabel":"طه: 77–78","question":"ما سر ذكر «البحر» في قوله: ﴿فَاضْرِبْ لَهُمْ طَرِيقًا فِي الْبَحْرِ يَبَسًا﴾، ثم «اليم» في قوله: ﴿فَغَشِيَهُم مِّنَ الْيَمِّ مَا غَشِيَهُمْ﴾؟","answer":"استعمل القرآن «اليم» في مقام الخوف والإغراق والعقوبة، كقوله: ﴿فَاقْذِفِيهِ فِي الْيَمِّ﴾ و﴿فَأَغْرَقْنَاهُمْ فِي الْيَمِّ﴾، ولم يستعمله في النجاة. أما «البحر» فعام في النعم والنجاة والإغراق، فجعل البحر هنا لنجاة موسى وقومه واليم لغرق فرعون وجنده.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص44–45.","url":""}]},{"id":"s20-219","number":219,"surah":20,"verses":[128],"references":[{"surah":20,"verses":[128]}],"verseLabel":"طه: 128","question":"ما سر الفاء في قوله: ﴿أَفَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا قَبْلَهُم﴾، والواو و«مِن» في السجدة: ﴿أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِن قَبْلِهِم﴾؟","answer":"ذكر في طه العقوبات في الدنيا مع عقوبة الآخرة: ﴿فَإِنَّ لَهُ مَعِيشَةً ضَنكًا﴾، فجاء بالفاء ربطًا بما قبلها، أما السجدة فأخّرت الأمر إلى يوم القيامة. وجاء بـ«من» الدالة على ابتداء الغاية في السجدة لأنه بدأ بهلاك الأقرب، أما في طه فذكر قوم موسى وهم قبل الرسول بمدة طويلة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص201–202.","url":""}]},{"id":"s20-220","number":220,"surah":20,"verses":[130],"references":[{"surah":20,"verses":[130]}],"verseLabel":"طه: 130","question":"ما سر قوله: ﴿وَقَبْلَ غُرُوبِهَا﴾ بالضمير، وفي ق: ﴿وَقَبْلَ الْغُرُوبِ﴾؟","answer":"في طه تنصيص على غروب الشمس بذكر الضمير العائد عليها، وأما ﴿الْغُرُوبِ﴾ في ق فيدل عليه بالسياق، فأُخرج مخرج العموم وإن أريد به الخصوص. وسياق طه أُخرج مخرج الخصوص وهو ألصق بالشمس، ولذا قال فيها: ﴿وَمِنْ آنَاءِ اللَّيْلِ﴾ أي ساعاته، وفي ق: ﴿وَمِنَ اللَّيْلِ﴾ وهو أعم.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص126–127.","url":""}]},{"id":"s21-1","number":1,"surah":21,"verses":[1],"references":[{"surah":21,"verses":[1]}],"verseLabel":"الأنبياء: 1","question":"ما دلالة التعبير بالاقتراب في قوله: ﴿اقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ﴾؟","answer":"دل الاقتراب على قرب الحساب وتحقق وقوعه، وحث على الاستعداد له؛ فكل آت قريب وإن استبعده الغافلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص65، تحت عنوان «دلالة التعبير بالاقتراب»","url":""}]},{"id":"s21-106","number":106,"surah":21,"verses":[1],"references":[{"surah":21,"verses":[1]}],"verseLabel":"الأنبياء: 1","question":"ما بلاغة إسناد الاقتراب إلى الحساب في قوله: ﴿اقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ﴾؟","answer":"جُعل الحساب نفسه مقبلًا يقترب من الناس، فحوّل المعنى الزمني إلى مشهد متحرك يداهم الغافلين ويزيد الإحساس بسرعة مجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص65، تحت عنوان «بلاغة إسناد الاقتراب إلى الحساب»","url":""}]},{"id":"s21-2","number":2,"surah":21,"verses":[1],"references":[{"surah":21,"verses":[1]}],"verseLabel":"الأنبياء: 1","question":"ما نكتة التعبير بحرف الظرفية في قوله: ﴿فِي غَفْلَةٍ﴾؟","answer":"جعلتهم ﴿في﴾ الغفلة كأنها ظرف يحيط بهم، فصوّر تمكنها منهم واستغراقهم فيها مع اقتراب الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص68–69، تحت عنوان «نكتة التعبير بحرف الظرفية»","url":""}]},{"id":"s21-107","number":107,"surah":21,"verses":[1],"references":[{"surah":21,"verses":[1]}],"verseLabel":"الأنبياء: 1","question":"ما غرض تقديم ﴿فِي غَفْلَةٍ﴾ على قوله: ﴿مُعْرِضُونَ﴾؟","answer":"قدّم شبه الجملة لإبراز إحاطة الغفلة بهم، ثم جاء الإعراض فعلًا ناشئًا عنها؛ فجمع بين فساد الداخل وصدود الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص69، تحت عنوان «غرض تقديم شبه الجملة»","url":""}]},{"id":"s21-3","number":3,"surah":21,"verses":[2],"references":[{"surah":21,"verses":[2]}],"verseLabel":"الأنبياء: 2","question":"ما فائدة إضافة الذكر إلى ربهم في قوله: ﴿مِنْ ذِكْرٍ مِنْ رَبِّهِمْ مُحْدَثٍ﴾؟","answer":"إضافة الذكر إلى ﴿ربهم﴾ تذكّرهم بأن المنزل هو الذي خلقهم وربّاهم ويتولى إصلاحهم؛ فكان الأولى أن يتلقوا ذكره بالطاعة لا باللعب والإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص72، تحت عنوان «فائدة إضافة الذكر إلى الضمير»","url":""}]},{"id":"s21-4","number":4,"surah":21,"verses":[2],"references":[{"surah":21,"verses":[2]}],"verseLabel":"الأنبياء: 2","question":"ما دلالة اجتماع الاستماع واللعب في قوله تعالى: ﴿اسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ﴾؟","answer":"الواو للحال؛ فكانوا يستمعون القرآن في حال لعب ولهو، فجمع المشهد بين حضور الصوت وغياب الانتفاع، وكشف أن استماعهم لم يكن طلبًا للهدى بل استهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص74، تحت عنوان «نوع الواو ودلالتها في قوله: ﴿وَهُمْ يَلْعَبُونَ﴾»","url":""}]},{"id":"s21-5","number":5,"surah":21,"verses":[3],"references":[{"surah":21,"verses":[3]}],"verseLabel":"الأنبياء: 3","question":"ما بلاغة إسناد اللهو إلى القلوب في قوله: ﴿لَاهِيَةً قُلُوبُهُمْ﴾؟","answer":"أُسند اللهو إلى القلوب لأنها محل القصد والفهم، فدل على أن انصرافهم لم يكن حركة ظاهرة فحسب، بل غفلة استولت على باطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص81، تحت عنوان «بلاغة المجاز المرسل»","url":""}]},{"id":"s21-108","number":108,"surah":21,"verses":[3],"references":[{"surah":21,"verses":[3]}],"verseLabel":"الأنبياء: 3","question":"ما نكتة تقديم اللعب على لهو القلوب في قوله: ﴿وَهُمْ يَلْعَبُونَ لَاهِيَةً قُلُوبُهُمْ﴾؟","answer":"ذُكر اللعب الظاهر أولًا لأنه المشاهد، ثم كشف النص سببه الأعمق وهو لهو القلوب؛ فانتقل من السلوك إلى الدافع الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص81، تحت عنوان «نكتة تقديم اللعب على اللهو»","url":""}]},{"id":"s21-6","number":6,"surah":21,"verses":[3],"references":[{"surah":21,"verses":[3]}],"verseLabel":"الأنبياء: 3","question":"ما بلاغة الكناية في قوله: ﴿وَأَسَرُّوا النَّجْوَى﴾؟","answer":"كَنَى إسرار النجوى عن شدة حرصهم على كتمان تدبيرهم وعداوتهم، لكن القرآن كشف حديثهم الخفي، فظهر إحاطة علم الله بما يسرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص82، تحت عنوان «بلاغة الكناية في اختيار فعل ﴿وَأَسَرُّوا﴾»","url":""}]},{"id":"s21-7","number":7,"surah":21,"verses":[3],"references":[{"surah":21,"verses":[3]}],"verseLabel":"الأنبياء: 3","question":"ما غرض الاستفهام في قولهم: ﴿هَلْ هَذَا إِلَّا بَشَرٌ مِثْلُكُمْ﴾؟","answer":"الاستفهام إنكاري قصدوا به نفي النبوة عن الرسول لمجرد بشريته، وفيه تعجيب أتباعهم منه وتنفيرهم من قبول دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص85، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s21-109","number":109,"surah":21,"verses":[3],"references":[{"surah":21,"verses":[3]}],"verseLabel":"الأنبياء: 3","question":"كيف ردت السورة شبهة امتناع إرسال رسول من البشر؟","answer":"ردت بأن سنة الله في الرسل السابقين أنهم رجال يوحى إليهم؛ فالبشرية ليست مناقضة للرسالة، بل هي الأصل الذي يتيح للناس الاقتداء بالرسول وفهم خطابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص112، تحت عنوان «معنى الواو ودلالتها في قوله: ﴿وَمَا أَرْسَلْنَا﴾»","url":""}]},{"id":"s21-8","number":8,"surah":21,"verses":[4],"references":[{"surah":21,"verses":[4]}],"verseLabel":"الأنبياء: 4","question":"ما سر العدول من ﴿النجوى﴾ إلى ﴿القول﴾ في قوله تعالى: ﴿رَبِّي يَعْلَمُ الْقَوْلَ فِي السَّمَاءِ وَالْأَرْضِ﴾؟","answer":"القول أعم من النجوى، فيشمل ما يجهرون به وما يسرونه. فالعدول إليه يدخل نجواهم في علم الله الشامل، وينبه إلى أنه يعلم السر والجهر على السواء، ويحذرهم مما سيقولونه أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص93–94، تحت عنوان «فائدة العدول عن ﴿النجوى﴾ إلى لفظ ﴿القول﴾»","url":""}]},{"id":"s21-9","number":9,"surah":21,"verses":[5],"references":[{"surah":21,"verses":[5]}],"verseLabel":"الأنبياء: 5","question":"ما دلالة تنقلهم بين ﴿أَضْغَاثُ أَحْلَامٍ﴾ و﴿افْتَرَاهُ﴾ و﴿شَاعِرٌ﴾؟","answer":"تكرار ﴿بل﴾ يحكي انتقالهم بين أقوال متضاربة في القرآن، ويكشف اضطرابهم وترددهم في الاعتراض عليه. ويذكر المبحث احتمال صدور هذه الأوصاف من فريق واحد أو من فرق مختلفة؛ فلا يلزم أن يكون كل قائل قد قالها جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص99–100، تحت عنوان «نوع ﴿بل﴾ ونكتة تكرارها في سياق واحد»","url":""}]},{"id":"s21-10","number":10,"surah":21,"verses":[6],"references":[{"surah":21,"verses":[6]}],"verseLabel":"الأنبياء: 6","question":"ما دلالة الاستفهام في قوله تعالى: ﴿مَا آمَنَتْ قَبْلَهُمْ مِنْ قَرْيَةٍ أَهْلَكْنَاهَا أَفَهُمْ يُؤْمِنُونَ﴾؟","answer":"الاستفهام ينكر ظن أنهم سيؤمنون إذا أُعطوا الآية التي اقترحوها؛ فالأمم المهلكة قبلهم لم تؤمن بما اقترحت. وبذلك يكشف تعنت الطلب، لا نقص الدليل القائم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص107، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s21-11","number":11,"surah":21,"verses":[7,25],"references":[{"surah":21,"verses":[7,25]}],"verseLabel":"الأنبياء: 7، 25","question":"ما سر مجيء ﴿وَمَا أَرْسَلْنَا قَبْلَكَ﴾ بلا «من» في الآية 7، ومجيء ﴿وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ﴾ في الآية 25؟","answer":"حُذفت ﴿من﴾ في الآية السابعة لأن السياق متصل بذكر القرى والرسل السابقين من غير حاجة إلى مزيد استغراق، وأُثبتت في الآية الخامسة والعشرين لتؤكد ابتداء الامتداد من الزمن السابق وعموم كل رسول أرسل قبل محمد ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص113، تحت عنوان «توجيه المتشابه اللفظي بالحذف والذكر»","url":""}]},{"id":"s21-13","number":13,"surah":21,"verses":[8],"references":[{"surah":21,"verses":[8]}],"verseLabel":"الأنبياء: 8","question":"ما فائدة تقييد الجسد بقوله: ﴿لَا يَأْكُلُونَ الطَّعَامَ﴾؟","answer":"النفي لم يتجه إلى كون الرسل أجسادًا، وإنما نفى أن يكونوا أجسادًا لا تأكل؛ فالقيد يقرر بشريتهم وحاجتهم إلى الطعام ويرد توهم الملكية.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص123، تحت عنوان «فائدة التقييد بالوصف»","url":""}]},{"id":"s21-110","number":110,"surah":21,"verses":[8],"references":[{"surah":21,"verses":[8]}],"verseLabel":"الأنبياء: 8","question":"ما فائدة عطف قوله: ﴿وَمَا كَانُوا خَالِدِينَ﴾ على بشرية الرسل؟","answer":"أضاف العطف نفيًا آخر: فكما أن الرسل يأكلون الطعام فهم أيضًا يموتون؛ وبذلك رد على من استبعد الرسالة لبشرية الرسول أو انتظر خلوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص124، تحت عنوان «معنى الواو وفائدة العطف بين الجمل»","url":""}]},{"id":"s21-14","number":14,"surah":21,"verses":[9],"references":[{"surah":21,"verses":[9]}],"verseLabel":"الأنبياء: 9","question":"ما دلالة ﴿ثُمَّ﴾ في قوله تعالى: ﴿ثُمَّ صَدَقْنَاهُمُ الْوَعْدَ﴾؟","answer":"يحتمل أن تكون ﴿ثم﴾ للتراخي الرتبي، لإبراز شأن إنجاز الوعد ونجاة الرسل وهلاك مكذبيهم؛ ويحتمل أن تكون للتراخي الزمني، إذ طال تكذيب الأقوام وصبر الرسل قبل تحقق الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص124، تحت عنوان «نوع ﴿ثم﴾ ودلالتها في السياق»","url":""}]},{"id":"s21-15","number":15,"surah":21,"verses":[10],"references":[{"surah":21,"verses":[10]}],"verseLabel":"الأنبياء: 10","question":"ما فائدة تقديم ﴿فِيهِ﴾ في قوله: ﴿فِيهِ ذِكْرُكُمْ﴾؟","answer":"قُدّم شبه الجملة للاهتمام بالكتاب والتنبيه إلى أن موضع شرفهم وموعظتهم وخبرهم الحق هو هذا القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص132، تحت عنوان «فائدة تقديم شبه الجملة»","url":""}]},{"id":"s21-111","number":111,"surah":21,"verses":[10],"references":[{"surah":21,"verses":[10]}],"verseLabel":"الأنبياء: 10","question":"ما نكتة إضافة الذكر إلى ضمير المخاطبين في قوله: ﴿ذِكْرُكُمْ﴾؟","answer":"أضيف الذكر إليهم لاستمالتهم إلى القرآن؛ فهو يتضمن شرفهم ورفعة شأنهم إن آمنوا به، كما يتضمن ما يوقظهم ويعظهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص132، تحت عنوان «نكتة إضافة الذكر إلى ضميرهم»","url":""}]},{"id":"s21-16","number":16,"surah":21,"verses":[11],"references":[{"surah":21,"verses":[11]}],"verseLabel":"الأنبياء: 11","question":"ما دلالة الصورة في قوله تعالى: ﴿وَكَمْ قَصَمْنَا مِنْ قَرْيَةٍ﴾؟","answer":"أصل القصم كسر الشيء الصلب، واستعير لإهلاك أهل القرى الجبارين الذين كانوا في قوة ومنعة. فالصورة لا تكتفي بالإخبار عن هلاكهم، بل تجسد شدة الإهلاك واستئصال قوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص138، تحت عنوان «بلاغة الاستعارة في لفظ القصم»","url":""}]},{"id":"s21-17","number":17,"surah":21,"verses":[12],"references":[{"surah":21,"verses":[12]}],"verseLabel":"الأنبياء: 12","question":"ما دلالة ﴿إِذَا﴾ في قوله تعالى: ﴿إِذَا هُمْ مِنْهَا يَرْكُضُونَ﴾؟","answer":"هي للمفاجأة؛ فبمجرد إحساسهم بالبأس بادروا إلى الهرب من غير توقف. وبهذا تصور الآية انقلاب حالهم بغتة وشدة الفزع الذي حملهم على الفرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص143، تحت عنوان «معنى ﴿إذا﴾ في: ﴿إذا هم منها يركضون﴾»","url":""}]},{"id":"s21-18","number":18,"surah":21,"verses":[13],"references":[{"surah":21,"verses":[13]}],"verseLabel":"الأنبياء: 13","question":"ما دلالة الأمر بالرجوع في قوله تعالى: ﴿لَا تَرْكُضُوا وَارْجِعُوا إِلَى مَا أُتْرِفْتُمْ فِيهِ﴾؟","answer":"أُمروا بالرجوع إلى ترفهم السابق على سبيل التهكم والتقريع، بعدما دفعهم العذاب إلى الفرار؛ فصار تذكيرهم بعزهم ونعيمهم السابق إظهارًا لما انتهوا إليه من ذلة وهوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص146–147، تحت عنوان «إيثار التعبير بفعل الرجوع أمرًا: ﴿وارجعوا﴾»","url":""}]},{"id":"s21-19","number":19,"surah":21,"verses":[15],"references":[{"surah":21,"verses":[15]}],"verseLabel":"الأنبياء: 15","question":"ما سر تسمية قولهم ﴿يَا وَيْلَنَا إِنَّا كُنَّا ظَالِمِينَ﴾ بـ﴿دَعْوَاهُمْ﴾؟","answer":"سمي دعوى لأنهم يدعون بالويل والثبور على أنفسهم، مقرّين بأنهم ظلموا في حياتهم السابقة. ولفظ الدعوى هنا يجمع نداءهم بالهلاك واعترافهم بالظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص158، تحت عنوان «إيثار التعبير بلفظ الدعوى، ومرجع ضميرها»","url":""}]},{"id":"s21-20","number":20,"surah":21,"verses":[15],"references":[{"surah":21,"verses":[15]}],"verseLabel":"الأنبياء: 15","question":"ما دلالة الصورة في قوله تعالى: ﴿حَصِيدًا خَامِدِينَ﴾؟","answer":"شُبّهوا بزرع استُؤصل بالحصاد، وبنار انطفأت ولم يبق منها إلا الجمر المنطفئ؛ فجمعت الصورة بين استئصالهم وسكونهم بعد الحياة والحركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص160، تحت عنوان «بلاغة التعبير بقوله: ﴿حصيدًا خامدين﴾»","url":""}]},{"id":"s21-21","number":21,"surah":21,"verses":[16],"references":[{"surah":21,"verses":[16]}],"verseLabel":"الأنبياء: 16","question":"ما دلالة نفي اللعب في قوله تعالى: ﴿وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ وَمَا بَيْنَهُمَا لَاعِبِينَ﴾؟","answer":"اللعب فعل لا يقصد به مقصد صحيح ولا تراعى فيه الحكمة، فنفيه ينزه الخلق عن العبث. فالسماوات والأرض خُلقتا بحكمة، وجُعلتا مجالًا لمعاش الإنسان ودليلًا يقوده إلى معرفة خالقه وعبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص166، تحت عنوان «التعبير بلفظ (اللعب) ودلالته»","url":""}]},{"id":"s21-22","number":22,"surah":21,"verses":[17],"references":[{"surah":21,"verses":[17]}],"verseLabel":"الأنبياء: 17","question":"ما دلالة ﴿لَوْ﴾ في قوله: ﴿لَوْ أَرَدْنَا أَنْ نَتَّخِذَ لَهْوًا﴾؟","answer":"جاءت ﴿لو﴾ لامتناع الجواب لامتناع الشرط؛ فنفت أصل إرادة اتخاذ اللهو، وتنزه الله عن العبث الذي توهمه المبطلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص168، تحت عنوان «دلالة ﴿لَوْ﴾ في قوله: ﴿لَوْ أَرَدْنَا﴾»","url":""}]},{"id":"s21-112","number":112,"surah":21,"verses":[17],"references":[{"surah":21,"verses":[17]}],"verseLabel":"الأنبياء: 17","question":"ما معنى ﴿مِنْ﴾ في قوله: ﴿مِنْ لَدُنَّا﴾؟","answer":"يفيد ﴿من لدنا﴾ أنه ـ على الفرض الممتنع ـ يكون من جهة غيب الله واختصاصه، لا مما يزعمونه من الصاحبة والولد من خلقه؛ وفي ذلك إبطال لمقالتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص172، تحت عنوان «معنى ﴿مِنْ﴾ في قوله: ﴿مِنْ لَدُنَّا﴾»","url":""}]},{"id":"s21-23","number":23,"surah":21,"verses":[18],"references":[{"surah":21,"verses":[18]}],"verseLabel":"الأنبياء: 18","question":"ما دلالة الصورة في قوله تعالى: ﴿بَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ﴾؟","answer":"صُوّر الحق والباطل، وهما معنيان، في صورة محسوسة يتجلى فيها القذف والدمغ؛ لتجسيد غلبة الحق وإبطاله للباطل إبطالًا تامًّا، كإصابة جسم قوي شيئًا ضعيفًا فيحطمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص179، تحت عنوان «بلاغة الاستعارة في فعل القذف والدمغ»","url":""}]},{"id":"s21-24","number":24,"surah":21,"verses":[18],"references":[{"surah":21,"verses":[18]}],"verseLabel":"الأنبياء: 18","question":"ما بلاغة التعبير بالدمغ في قوله: ﴿فَيَدْمَغُهُ﴾؟","answer":"صوّر إصابة الحق للباطل بضربة تبلغ الدماغ فتقضي عليه، فدل على قوة الحجة واستئصال الباطل لا مجرد إضعافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص181، تحت عنوان «بلاغة التعبير بفعل الدمغ واختياره هنا»","url":""}]},{"id":"s21-113","number":113,"surah":21,"verses":[18],"references":[{"surah":21,"verses":[18]}],"verseLabel":"الأنبياء: 18","question":"ما دلالة ﴿إِذَا﴾ في قوله: ﴿فَإِذَا هُوَ زَاهِقٌ﴾؟","answer":"جاءت ﴿إذا﴾ الفجائية لتصوّر سرعة زوال الباطل عند صدمة الحق؛ فما إن يصيبه حتى يظهر هالكًا مضمحلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص182، تحت عنوان «معنى ﴿إِذَا﴾ في قوله: ﴿فَإِذَا هُوَ زَاهِقٌ﴾»","url":""}]},{"id":"s21-25","number":25,"surah":21,"verses":[19],"references":[{"surah":21,"verses":[19]}],"verseLabel":"الأنبياء: 19","question":"ما دلالة عطف ﴿وَلَا يَسْتَحْسِرُونَ﴾ على قوله: ﴿لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِ﴾؟","answer":"جمع العطف نفي مانعين من العبادة: فلا يترفع الملائكة عنها استكبارًا، ولا ينقطعون عنها تعبًا وعجزًا؛ فعبادتهم طوعية دائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص191، تحت عنوان «دلالة العطف في قوله: ﴿وَلَا يَسْتَحْسِرُونَ﴾ ومعناها»","url":""}]},{"id":"s21-114","number":114,"surah":21,"verses":[19],"references":[{"surah":21,"verses":[19]}],"verseLabel":"الأنبياء: 19","question":"ما بلاغة صيغة الاستفعال في قوله: ﴿يَسْتَحْسِرُونَ﴾؟","answer":"تفيد صيغة الاستفعال بلوغ غاية الإعياء وطلب الراحة بعد شدة التعب؛ فنفيها أبلغ في بيان دوام نشاط الملائكة في العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص191–192، تحت عنوان «بلاغة التعبير بـ﴿يَسْتَحْسِرُونَ﴾ على صيغة الاستفعال»","url":""}]},{"id":"s21-26","number":26,"surah":21,"verses":[20],"references":[{"surah":21,"verses":[20]}],"verseLabel":"الأنبياء: 20","question":"ما سر تخصيص الليل والنهار بالذكر في قوله: ﴿يُسَبِّحُونَ اللَّيْلَ وَالنَّهَارَ﴾؟","answer":"ذُكر الليل والنهار لاستيعاب الزمن كله، أي إن تسبيح الملائكة متصل في جميع الأوقات لا يختص بساعة دون أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص193، تحت عنوان «سر تخصيص الليل والنهار بالذكر»","url":""}]},{"id":"s21-115","number":115,"surah":21,"verses":[20],"references":[{"surah":21,"verses":[20]}],"verseLabel":"الأنبياء: 20","question":"ما دلالة المضارع في قوله: ﴿لَا يَفْتُرُونَ﴾؟","answer":"دل المضارع على تجدد نفي الفتور واستمراره؛ فهم يواصلون التسبيح من غير ضعف ولا انقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص193، تحت عنوان «إيثار التعبير بالمضارع ﴿يَفْتُرُونَ﴾»","url":""}]},{"id":"s21-27","number":27,"surah":21,"verses":[21],"references":[{"surah":21,"verses":[21]}],"verseLabel":"الأنبياء: 21","question":"ما سر تقييد الآلهة بكونها ﴿مِنَ الْأَرْضِ﴾؟","answer":"ذكّر القيد بحقيقة الأصنام؛ فهي مصنوعة من مواد أرضية وموضوعة في الأرض، وفي ذلك تحقير لها وتوبيخ لمن رفعها إلى مقام الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص201، تحت عنوان «سر تقييد وصف الآلهة بكونها ﴿مِنَ الْأَرْضِ﴾»","url":""}]},{"id":"s21-116","number":116,"surah":21,"verses":[21],"references":[{"surah":21,"verses":[21]}],"verseLabel":"الأنبياء: 21","question":"ما سر إيثار ﴿يُنْشِرُونَ﴾ في وصف الآلهة المزعومة؟","answer":"الإنشار إحياء الموتى وبعثهم، فاختير لاستحضار أعظم آثار القدرة الإلهية على سبيل التهكم بعجز الأصنام؛ فهي لا تملك بعث ميت فكيف تكون آلهة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص202، تحت عنوان «إيثار التعبير بالفعل ﴿يُنْشِرُونَ﴾ دون غيره»","url":""}]},{"id":"s21-28","number":28,"surah":21,"verses":[22],"references":[{"surah":21,"verses":[22]}],"verseLabel":"الأنبياء: 22","question":"ما دلالة التعبير بـ﴿لَفَسَدَتَا﴾ في قوله تعالى: ﴿لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا﴾؟","answer":"الفساد خروج الشيء عن الصلاح والاعتدال؛ فتعدد الآلهة يقتضي اختلال تدبير السماوات والأرض. ولما استقام الكون على نظام محكم دل انتظامه على وحدانية مدبره.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص207، تحت عنوان «دلالة التعبير بلفظ الفساد دون غيره»","url":""}]},{"id":"s21-29","number":29,"surah":21,"verses":[23],"references":[{"surah":21,"verses":[23]}],"verseLabel":"الأنبياء: 23","question":"ما بلاغة نفي السؤال عن الله وإثباته للمخلوقين في قوله: ﴿لَا يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُونَ﴾؟","answer":"نفي سؤال المحاسبة والاعتراض عن الله كناية عن كمال حكمته وملكه، وإثباته للمخلوقين يقرر عبوديتهم ومسؤوليتهم؛ فبرز الفرق بين الخالق والمخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص214، تحت عنوان «بلاغة الكناية في فعل السؤال»","url":""}]},{"id":"s21-30","number":30,"surah":21,"verses":[24],"references":[{"surah":21,"verses":[24]}],"verseLabel":"الأنبياء: 24","question":"ما دلالة الأمر في قوله تعالى: ﴿هَاتُوا بُرْهَانَكُمْ﴾؟","answer":"الأمر للتعجيز وإلزام الحجة؛ فقد طُلب منهم أن يقدموا دليلًا على استحقاق آلهتهم العبادة، وهم عاجزون عن ذلك، فظهر بطلان دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص221، تحت عنوان «سر التعبير بفعل الأمر وبيانه»","url":""}]},{"id":"s21-31","number":31,"surah":21,"verses":[25],"references":[{"surah":21,"verses":[25]}],"verseLabel":"الأنبياء: 25","question":"ما فائدة التعبير بالمصدر المؤول في قوله: ﴿أَنَّهُ لَا إِلَهَ إِلَّا أَنَا﴾؟","answer":"جعل مضمون الوحي حقيقة ثابتة جامعة لدعوة جميع الرسل: لا معبود بحق إلا الله؛ فاختلاف الشرائع لا يغير أصل التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص238، تحت عنوان «فائدة التعبير بالمصدر المؤول»","url":""}]},{"id":"s21-117","number":117,"surah":21,"verses":[25],"references":[{"surah":21,"verses":[25]}],"verseLabel":"الأنبياء: 25","question":"ما دلالة الفاء في قوله: ﴿فَاعْبُدُونِ﴾ بعد تقرير التوحيد؟","answer":"فرّعت الفاء الأمر بالعبادة على انفراد الله بالألوهية؛ فما دام هو الإله وحده فهو المستحق وحده للطاعة والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص239–240، تحت عنوان «معنى الفاء ودلالتها في ﴿فَاعْبُدُونِ﴾»","url":""}]},{"id":"s21-32","number":32,"surah":21,"verses":[26],"references":[{"surah":21,"verses":[26]}],"verseLabel":"الأنبياء: 26","question":"ما سر الاعتراض بـ﴿سُبْحَانَهُ﴾ بعد قولهم: ﴿اتَّخَذَ الرَّحْمَنُ وَلَدًا﴾؟","answer":"جاء التنزيه اعتراضًا فوريًا يرد الدعوى قبل تفصيل إبطالها؛ لأن اتخاذ الولد يقتضي الحاجة والمشابهة، والله منزه عنهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص245، تحت عنوان «سر التعبير بجملة الاعتراض ﴿سُبْحَانَهُ﴾»","url":""}]},{"id":"s21-118","number":118,"surah":21,"verses":[26],"references":[{"surah":21,"verses":[26]}],"verseLabel":"الأنبياء: 26","question":"ما بلاغة الإضراب بـ﴿بَلْ﴾ في قوله: ﴿بَلْ عِبَادٌ مُكْرَمُونَ﴾؟","answer":"أبطلت ﴿بل﴾ دعوى البنوة وانتقلت إلى الحقيقة المقابلة: الملائكة عباد أكرمهم الله، وعبوديتهم تنافي أن يكونوا أولادًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص245، تحت عنوان «بلاغة الإضراب بـ﴿بَلْ﴾»","url":""}]},{"id":"s21-33","number":33,"surah":21,"verses":[27],"references":[{"surah":21,"verses":[27]}],"verseLabel":"الأنبياء: 27","question":"ما فائدة الجملة الخبرية: ﴿لَا يَسْبِقُونَهُ بِالْقَوْلِ﴾؟","answer":"قررت الجملة ثبات أدب الملائكة وطاعتهم؛ فلا يقولون شيئًا قبل أمر الله أو إذنه، بل يتبع قولهم قوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص251، تحت عنوان «فائدة الجملة الخبرية»","url":""}]},{"id":"s21-119","number":119,"surah":21,"verses":[27],"references":[{"surah":21,"verses":[27]}],"verseLabel":"الأنبياء: 27","question":"لماذا خُص نفي سبق الملائكة بالقول دون العمل؟","answer":"خُص القول لأنه أسرع صدورًا وأخف مؤونة من العمل؛ فإذا لم يسبقوه به كانوا عن سبقه بالفعل أبعد، فكان النفي أبلغ في الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص251، تحت عنوان «نكتة تخصيص نفي السبق بالقول دون العمل»","url":""}]},{"id":"s21-34","number":34,"surah":21,"verses":[28],"references":[{"surah":21,"verses":[28]}],"verseLabel":"الأنبياء: 28","question":"ما بلاغة الطباق في قوله: ﴿يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ﴾؟","answer":"جمع الطرفان أحوال الملائكة كلها في علم الله، ماضيها ومستقبلها أو ظاهرها وخفيها، فدل الطباق على الإحاطة التامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص258، تحت عنوان «بديع الطباق»","url":""}]},{"id":"s21-120","number":120,"surah":21,"verses":[28],"references":[{"surah":21,"verses":[28]}],"verseLabel":"الأنبياء: 28","question":"ما فائدة عطف قوله: ﴿وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَى﴾؟","answer":"أضاف العطف أن شفاعة الملائكة ليست مستقلة؛ فهي مقصورة على من رضي الله عنه، فبطل تعلق المشركين بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص258–259، تحت عنوان «فائدة عطف جملة القصر في قوله: ﴿وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَى﴾»","url":""}]},{"id":"s21-35","number":35,"surah":21,"verses":[30],"references":[{"surah":21,"verses":[30]}],"verseLabel":"الأنبياء: 30","question":"ما دلالة التعبير بـ﴿كَانَتَا رَتْقًا فَفَتَقْنَاهُمَا﴾؟","answer":"الرتق هو الالتئام دون فرجة، والتعبير بالمصدر يصوّر السماوات والأرض كشيء واحد ملتصق، مبالغةً في اتحادهما قبل الفتق. وذكر المبحث أيضًا تفسير الرتق بانحباس المطر والنبات، والفتق بنزول المطر وخروج النبات؛ فلا يُحصر المعنى في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص278–279، تحت عنوان «سر التعبير بلفظ ﴿رتقًا﴾»","url":""}]},{"id":"s21-36","number":36,"surah":21,"verses":[30],"references":[{"surah":21,"verses":[30]}],"verseLabel":"الأنبياء: 30","question":"ما دلالة ﴿مِنَ الْمَاءِ﴾ في قوله ﴿وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ﴾؟","answer":"تحتمل ﴿من﴾ السببية، أي جعلنا بسبب الماء كل شيء حيًّا، وتحتمل ابتداء الغاية، أي جعلنا مبدأ خلق كل شيء حي من الماء. يجمع الوجهان الدلالة على ارتباط الحياة بالماء، من جهة نشأتها أو قيامها به.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص283، تحت عنوان «معنى ﴿من﴾ ودلالتها»","url":""}]},{"id":"s21-37","number":37,"surah":21,"verses":[31],"references":[{"surah":21,"verses":[31]}],"verseLabel":"الأنبياء: 31","question":"ما سرّ التعبير عن الجبال بـ﴿رَوَاسِيَ﴾ في قوله ﴿وَجَعَلْنَا فِي الْأَرْضِ رَوَاسِيَ﴾؟","answer":"حُذف الموصوف، أي الجبال، وأقيمت صفته ﴿رواسي﴾ مقامه؛ للإشعار بعظم صفة الرسوخ وثبات الجبال، وأن هذه الصفة نفسها آية تستحق الاعتبار، في مقام تعداد دلائل القدرة والوحدانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص289–290، تحت عنوان «الغرض من حذف الموصوف وذكر الصفة»","url":""}]},{"id":"s21-38","number":38,"surah":21,"verses":[32],"references":[{"surah":21,"verses":[32]}],"verseLabel":"الأنبياء: 32","question":"ما بلاغة تشبيه السماء بالسقف في قوله: ﴿سَقْفًا مَحْفُوظًا﴾؟","answer":"شبهت السماء بالسقف تشبيهًا بليغًا لعلوها وإحاطتها بمن تحتها وما في ذلك من الرعاية والحماية، مع عظم خلقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص299–300، تحت عنوان «بلاغة التشبيه»","url":""}]},{"id":"s21-121","number":121,"surah":21,"verses":[32],"references":[{"surah":21,"verses":[32]}],"verseLabel":"الأنبياء: 32","question":"ما غرض حذف متعلق ﴿مَحْفُوظًا﴾ في وصف السماء؟","answer":"عمم الحذف وجوه الحفظ، فيشمل حفظها من السقوط والزوال والانهدام، وحفظها من استراق الشياطين للسمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص300، تحت عنوان «الغرض من حذف متعلق المشتق»","url":""}]},{"id":"s21-39","number":39,"surah":21,"verses":[33],"references":[{"surah":21,"verses":[33]}],"verseLabel":"الأنبياء: 33","question":"ما سرّ تصوير حركة الشمس والقمر بقوله ﴿كُلٌّ فِي فَلَكٍ يَسْبَحُونَ﴾؟","answer":"استُعيرت السباحة لجريان الأجرام في أفلاكها؛ تقريبًا لحركتها في الفضاء إلى حركة السابح المحسوسة، فهي تجري في نظام ثابت ولا تخرج عن مجاريها. وليس المقصود مساواة سرعة الأجرام بسرعة السابح، بل بيان كيفية الجريان بصورة يعرفها المخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص311–312، تحت عنوان «بلاغة الاستعارة»","url":""}]},{"id":"s21-40","number":40,"surah":21,"verses":[34],"references":[{"surah":21,"verses":[34]}],"verseLabel":"الأنبياء: 34","question":"ما سرّ الرد على المتربصين بموت النبي بقوله ﴿وَمَا جَعَلْنَا لِبَشَرٍ مِنْ قَبْلِكَ الْخُلْدَ﴾؟","answer":"يبطل توهمهم أن موته يحقق لهم ما يرجون؛ فالموت جارٍ عليه وعليهم، ولا يخلدون بعده. وفيه حجة من جنس ما تمنّوه: سلّم لهم وقوع موته، ثم بيّن أن ذلك لا ينفعهم، إذ قد يموتون قبله، ولن يُعصموا هم من الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص318، تحت عنوان «بديع القول بالموجب»","url":""}]},{"id":"s21-41","number":41,"surah":21,"verses":[35],"references":[{"surah":21,"verses":[35]}],"verseLabel":"الأنبياء: 35","question":"ما دلالة الواو في قوله في الأنبياء: ﴿وَإِلَيْنَا تُرْجَعُونَ﴾؟","answer":"الواو للاستئناف، تقرر حقيقة الرجوع إلى الله بعد ذكر الموت والابتلاء، وتبرز استقلال هذا الإنذار وأهميته.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص332، تحت عنوان «دلالة الواو في ﴿وَإِلَيْنَا﴾»","url":""}]},{"id":"s21-122","number":122,"surah":21,"verses":[35],"references":[{"surah":21,"verses":[35]}],"verseLabel":"الأنبياء: 35","question":"ما دلالة ﴿ثُمَّ﴾ في قوله في العنكبوت: ﴿ثُمَّ إِلَيْنَا تُرْجَعُونَ﴾؟","answer":"تحتمل ثم التراخي الزماني بعد الموت، والأظهر التراخي الرتبي لإبراز عظم الرجوع والجزاء وما فيه من تحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج42، ص598، تحت عنوان «نوع حرف التراخي ودلالته»","url":""}]},{"id":"s21-42","number":42,"surah":21,"verses":[35],"references":[{"surah":21,"verses":[35]}],"verseLabel":"الأنبياء: 35","question":"ما دلالة الجمع بين الشر والخير في قوله ﴿وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةً﴾؟","answer":"الطباق يجمع وجهي الابتلاء: ما يسوء الإنسان وما يسره، كالفقر والغنى، والمرض والصحة، والشدة والرخاء. فهو يدفع توهم أن الشر وحده ابتلاء، وأن الخير إكرام لا اختبار فيه؛ فكلاهما مما يُمتحن به العبد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص329–330، تحت عنوان «الغرض من التعبير بأسلوب الطباق»","url":""}]},{"id":"s21-43","number":43,"surah":21,"verses":[36],"references":[{"surah":21,"verses":[36]}],"verseLabel":"الأنبياء: 36","question":"ما سرّ إظهار ﴿الَّذِينَ كَفَرُوا﴾ في ﴿وَإِذَا رَآكَ الَّذِينَ كَفَرُوا﴾ بالأنبياء، وإضمارهم في ﴿وَإِذَا رَأَوْكَ﴾ بالفرقان؟","answer":"في الأنبياء لم يتقدم ذكرٌ يختص بالكفار المعاصرين للنبي المستهزئين به؛ فلو أُضمروا لعاد الضمير إلى عموم ﴿الذين كفروا﴾ في الآية 30، وهو غير المقصود هنا. أما الفرقان فسبق فيها ذكر المعترضين على تنزيل القرآن في الآية 32، وهم معلومون، فناسب الإخبار عنهم بالضمير إيجازًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص349–350، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s21-44","number":44,"surah":21,"verses":[37],"references":[{"surah":21,"verses":[37]}],"verseLabel":"الأنبياء: 37","question":"ما سرّ التعبير بـ﴿خُلِقَ الْإِنْسَانُ مِنْ عَجَلٍ﴾؟","answer":"صُوّرت شدة ملازمة العجلة للإنسان حتى كأنها المادة التي خُلق منها؛ فهو يستعجل حصول المحبوب ودفع المكروه. وهذا تصوير مبالغ فيه للطبع الغالب، لا بيان لمادة خلقه حقيقةً.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص355–356، تحت عنوان «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s21-45","number":45,"surah":21,"verses":[37],"references":[{"surah":21,"verses":[37]}],"verseLabel":"الأنبياء: 37","question":"ما دلالة النهي في ﴿سَأُرِيكُمْ آيَاتِي فَلَا تَسْتَعْجِلُونِ﴾؟","answer":"إن كان الخطاب للكفار المستهزئين، فالنهي زجر وتهديد: سيأتيهم ما يستعجلونه من العقاب. وإن كان للمؤمنين المستعجلين عقاب الكفار، فهو نهي عن العجلة يتضمن الأمر بالصبر وكف النفس عن مقتضاها؛ وقد ذكر المبحث الوجهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص359، تحت عنوان «بلاغة النهي عن الاستعجال ودلالته»","url":""}]},{"id":"s21-46","number":46,"surah":21,"verses":[39],"references":[{"surah":21,"verses":[39]}],"verseLabel":"الأنبياء: 39","question":"ما سرّ تخصيص الوجوه والظهور في ﴿لَا يَكُفُّونَ عَنْ وُجُوهِهِمُ النَّارَ وَلَا عَنْ ظُهُورِهِمْ﴾؟","answer":"الوجه أشرف الأعضاء، والظهر من أشدها وأقواها؛ وذكرهما معًا يشير إلى القدّام والخلف، فينبّه على إحاطة النار بالأجساد وعجزهم عن دفعها من أي جانب. وفي عجزهم عن حماية هاتين الجهتين دلالة على شدة العجز عن غيرهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص374–375، تحت عنوان «سر تخصيص الوجوه والظهور بالذكر»","url":""}]},{"id":"s21-47","number":47,"surah":21,"verses":[40],"references":[{"surah":21,"verses":[40]}],"verseLabel":"الأنبياء: 40","question":"ما نكتة تقييد إتيان العذاب بالحال ﴿بَغْتَةً﴾؟","answer":"المباغتة أشد وقعًا لأنها تسلبهم فرصة الاستعداد والدفع، فينزل العذاب وهم غافلون عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص380، تحت عنوان «نكتة تقييد الإتيان بالحال ﴿بَغْتَةً﴾»","url":""}]},{"id":"s21-123","number":123,"surah":21,"verses":[40],"references":[{"surah":21,"verses":[40]}],"verseLabel":"الأنبياء: 40","question":"ما دلالة التعبير بـ﴿فَتَبْهَتُهُمْ﴾ عقب مجيء العذاب؟","answer":"تصور البهتة دهشة تحيرهم وتقطع حجتهم، وتفيد الفاء أنها تعقب المباغتة مباشرة وتنشأ عنها بلا مهلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص381، تحت عنوان «دلالة التعبير بقوله: ﴿فَتَبْهَتُهُمْ﴾»","url":""}]},{"id":"s21-48","number":48,"surah":21,"verses":[42],"references":[{"surah":21,"verses":[42]}],"verseLabel":"الأنبياء: 42","question":"ما سر التعبير بـ﴿يَكْلَؤُكُمْ﴾ في قوله: ﴿مَنْ يَكْلَؤُكُمْ﴾؟","answer":"الكلاءة حفظ مصحوب بالرعاية والوقاية من الآفة، فهي أخص من مطلق الحفظ؛ ونفى الاستفهام وجود من يقيهم عذاب الرحمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص398، تحت عنوان «سر التعبير بـ﴿يَكْلَؤُكُمْ﴾ مادة وصيغة»","url":""}]},{"id":"s21-124","number":124,"surah":21,"verses":[42],"references":[{"surah":21,"verses":[42]}],"verseLabel":"الأنبياء: 42","question":"ما بلاغة الجمع بين الليل والنهار في قوله: ﴿بِاللَّيْلِ وَالنَّهَارِ﴾؟","answer":"استوعب الطباق جميع الأوقات وما يختص بكل منها من أخطار، فدل على افتقارهم الدائم إلى حفظ الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص398–399، تحت عنوان «بلاغة الطباق بين الليل والنهار»","url":""}]},{"id":"s21-50","number":50,"surah":21,"verses":[45],"references":[{"surah":21,"verses":[45]}],"verseLabel":"الأنبياء: 45","question":"ما دلالة القصر في ﴿إِنَّمَا أُنْذِرُكُمْ بِالْوَحْيِ﴾؟","answer":"يقصر إنذار النبي على كونه بطريق الوحي من الله، لا وعيدًا صادرًا من عند نفسه. فهو رد على توهم المكذبين أن لهم أن يطالبوه بتعيين أجل العذاب أو أن يعجزوه بالإعراض والسخرية؛ إذ هو مبلّغ لوحي الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص425–426، تحت عنوان «دلالة أسلوب القصر ﴿إنما﴾»","url":""}]},{"id":"s21-51","number":51,"surah":21,"verses":[46],"references":[{"surah":21,"verses":[46]}],"verseLabel":"الأنبياء: 46","question":"ما سر إيثار لفظ المس في قوله: ﴿مَسَّتْهُمْ﴾؟","answer":"المس أخف درجات الإصابة، فاختير لتقليل المقدار المفروض وإظهار أن أدنى إصابة من العذاب تكفي لإفزاعهم وإقرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص438–439، تحت عنوان «إيثار لفظ المس في قوله: ﴿مَسَّتْهُمْ﴾»","url":""}]},{"id":"s21-125","number":125,"surah":21,"verses":[46],"references":[{"surah":21,"verses":[46]}],"verseLabel":"الأنبياء: 46","question":"ما سر التعبير بـ﴿نَفْحَةٌ﴾ مادة وبناء؟","answer":"النفحة في أصلها هبوب يسير، وبناء المرة يصورها دفعة واحدة؛ فاجتمع في اللفظ تقليل المقدار والمدة مع تهويل أثرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص439–440، تحت عنوان «سر التعبير بـ﴿نَفْحَةٌ﴾ مادة وبناء»","url":""}]},{"id":"s21-126","number":126,"surah":21,"verses":[46],"references":[{"surah":21,"verses":[46]}],"verseLabel":"الأنبياء: 46","question":"ما فائدة تنكير ﴿نَفْحَةٌ﴾ في سياق العذاب؟","answer":"زاد التنكير معنى التقليل: أي نفحة واحدة غير معينة من العذاب، فإذا أوقعت هذا الأثر فكيف بالعذاب كله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص440–441، تحت عنوان «فائدة تنكير ﴿نَفْحَةٌ﴾»","url":""}]},{"id":"s21-52","number":52,"surah":21,"verses":[47],"references":[{"surah":21,"verses":[47]}],"verseLabel":"الأنبياء: 47","question":"ما سر توحيد ﴿الْقِسْطَ﴾ ووصف الموازين به؟","answer":"جاء القسط مصدرًا مفردًا للمبالغة، فكأن الموازين هي العدل نفسه، أو التقدير: ذوات القسط؛ فلا ينافي إفراد الوصف جمع الموازين.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص454، تحت عنوان «سر توحيد ﴿الْقِسْطَ﴾ والوصف به»","url":""}]},{"id":"s21-53","number":53,"surah":21,"verses":[47],"references":[{"surah":21,"verses":[47]}],"verseLabel":"الأنبياء: 47","question":"ما دلالة تنكير ﴿حَبَّةٍ﴾ في قوله ﴿مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ﴾؟","answer":"الخردل في غاية الصغر، وذكر حبة واحدة منه ثم تنكيرها يبالغ في التقليل والدقة. والمقصود تصوير إحاطة العلم ودقة الحساب، فلا يُغادَر من أعمال الناس شيء مهما صغر.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص461، تحت عنوان «وجه تنكير ﴿حبة﴾»","url":""}]},{"id":"s21-54","number":54,"surah":21,"verses":[48],"references":[{"surah":21,"verses":[48]}],"verseLabel":"الأنبياء: 48","question":"ما سر إيثار لفظ ﴿الْفُرْقَانَ﴾ على الكتاب أو التوراة؟","answer":"الفرقان ما يفرق بين الحق والباطل، وهو أوسع من اسم الكتاب؛ فيشمل التوراة وما أيد الله به موسى وهارون من حجج فارقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص472–473، تحت عنوان «إيثار لفظ ﴿الْفُرْقَانَ﴾ على الكتاب والتوراة»","url":""}]},{"id":"s21-127","number":127,"surah":21,"verses":[48],"references":[{"surah":21,"verses":[48]}],"verseLabel":"الأنبياء: 48","question":"ما نكتة تعريف ﴿الْفُرْقَانَ﴾ وتنكير ﴿ضِيَاءً وَذِكْرًا﴾؟","answer":"عُرّف الفرقان للعهد أو الكمال في الفصل، ونُكّر الضياء والذكر للتعظيم والتفخيم؛ فهو نور عظيم وتذكير جليل للمتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص474، تحت عنوان «نكتة تعريف ﴿الْفُرْقَانَ﴾ وتنكير ﴿ضِيَاءً﴾ و﴿ذِكْرًا﴾»","url":""}]},{"id":"s21-55","number":55,"surah":21,"verses":[49],"references":[{"surah":21,"verses":[49]}],"verseLabel":"الأنبياء: 49","question":"ما معنى الباء في قوله: ﴿يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ﴾؟","answer":"الباء للملابسة أو الحال؛ أي يخشون ربهم ملتبسين بالغيب، في خلواتهم أو مع غيبته عن أبصارهم، فتدل على صدق الخشية بعيدًا عن الرياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص483، تحت عنوان «معنى الباء في ﴿بِالْغَيْبِ﴾»","url":""}]},{"id":"s21-56","number":56,"surah":21,"verses":[51],"references":[{"surah":21,"verses":[51]}],"verseLabel":"الأنبياء: 51","question":"ما سر إيثار لفظ ﴿رُشْدَهُ﴾ في شأن إبراهيم؟","answer":"الرشد صلاح واستقامة وثبات على الحق، وهو أوسع من مجرد الاهتداء؛ فدل على كمال ما أوتيه إبراهيم من صواب النظر والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص501–502، تحت عنوان «إيثار لفظ الرشد»","url":""}]},{"id":"s21-128","number":128,"surah":21,"verses":[51],"references":[{"surah":21,"verses":[51]}],"verseLabel":"الأنبياء: 51","question":"ما دلالة ﴿مِنْ قَبْلُ﴾ في قوله: ﴿آتَيْنَا إِبْرَاهِيمَ رُشْدَهُ مِنْ قَبْلُ﴾؟","answer":"تحتمل قبل إيتاء موسى وهارون الفرقان، أو قبل نبوة إبراهيم حين وفق للاستدلال؛ وفي الحالين تبرز سبقه المبكر إلى الرشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص503، تحت عنوان «دلالة ﴿مِنْ﴾ مع ﴿قَبْلُ﴾»","url":""}]},{"id":"s21-57","number":57,"surah":21,"verses":[52],"references":[{"surah":21,"verses":[52]}],"verseLabel":"الأنبياء: 52","question":"ما سر إيثار لفظ ﴿التَّمَاثِيلَ﴾ لمعبودات قوم إبراهيم؟","answer":"سماها بحقيقتها: صورًا جامدة لا أرواح فيها، ولم يجارهم في تسميتها آلهة، فحقرها وأبطل استحقاقها العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص513–514، تحت عنوان «إيثار لفظ التماثيل»","url":""}]},{"id":"s21-129","number":129,"surah":21,"verses":[52],"references":[{"surah":21,"verses":[52]}],"verseLabel":"الأنبياء: 52","question":"ما دلالة تقديم ﴿لَهَا﴾ في قوله: ﴿أَنْتُمْ لَهَا عَاكِفُونَ﴾؟","answer":"أفاد التقديم الاختصاص وركز الإنكار على تخصيص هذه التماثيل بالعكوف والعبادة مع أنها لا تستحقهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص515، تحت عنوان «وجه تقديم شبه الجملة على الخبر»","url":""}]},{"id":"s21-58","number":58,"surah":21,"verses":[53],"references":[{"surah":21,"verses":[53]}],"verseLabel":"الأنبياء: 53","question":"لماذا جاء جواب قوم إبراهيم في الأنبياء بلا ﴿بَلْ﴾: ﴿وَجَدْنَا آبَاءَنَا لَهَا عَابِدِينَ﴾؟","answer":"جاءت الجملة جوابًا مباشرًا عن سؤاله عن سبب عكوفهم على التماثيل، فكشفوا أن مستندهم تقليد الآباء، ولذلك فصلت بلا إضراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص519، تحت عنوان «نكتة فصل الآية عن سابقتها»","url":""}]},{"id":"s21-130","number":130,"surah":21,"verses":[53],"references":[{"surah":21,"verses":[53]}],"verseLabel":"الأنبياء: 53","question":"ما غرض ﴿بَلْ﴾ في نظير الآية من سورة الشعراء؟","answer":"أضربوا بها عن جواب سؤال إبراهيم عن سمع الأصنام ونفعها وضرها لما عجزوا عنه، وانتقلوا إلى الاحتجاج بتقليد الآباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص688، تحت عنوان «غرض الإضراب عن الجواب»","url":""}]},{"id":"s21-59","number":59,"surah":21,"verses":[54],"references":[{"surah":21,"verses":[54]}],"verseLabel":"الأنبياء: 54","question":"ما سرّ الجمع بين الآباء والأبناء في ﴿لَقَدْ كُنْتُمْ أَنْتُمْ وَآبَاؤُكُمْ فِي ضَلَالٍ مُبِينٍ﴾؟","answer":"جُمع الفريقان لاشتراكهما في الخطأ والضلال؛ فلا عذر للأبناء في تقليد آبائهم، ولا عذر للآباء في سنّ عبادة ما لا يستحق العبادة. وهو إبطال للاحتجاج بالتقليد، وتنبيه إلى أن كثرة المتمسكين بالباطل لا تصيّره حقًّا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص527، تحت عنوان «دلالة العطف في قوله ﴿أنتم وآباؤكم﴾ بالواو»","url":""}]},{"id":"s21-60","number":60,"surah":21,"verses":[57],"references":[{"surah":21,"verses":[57]}],"verseLabel":"الأنبياء: 57","question":"ما بلاغة القسم بقوله: ﴿وَتَاللَّهِ﴾؟","answer":"أكد القسم عزم إبراهيم على إزالة المنكر وتحطيم الأصنام، وفي تاء القسم إيحاء بالتعجب من تيسير هذا الأمر الشاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص556–557، تحت عنوان «بلاغة القسم بقوله: ﴿وَتَاللَّهِ﴾»","url":""}]},{"id":"s21-131","number":131,"surah":21,"verses":[57],"references":[{"surah":21,"verses":[57]}],"verseLabel":"الأنبياء: 57","question":"ما سر إيثار فعل الكيد في قوله: ﴿لَأَكِيدَنَّ أَصْنَامَكُمْ﴾؟","answer":"الكيد تدبير خفي محكم يستثمر الفرصة؛ فصوّر عزمه على خطة عملية تكشف عجز الأصنام وتلزم قومه الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص558، تحت عنوان «إيثار فعل الكيد»","url":""}]},{"id":"s21-61","number":61,"surah":21,"verses":[58],"references":[{"surah":21,"verses":[58]}],"verseLabel":"الأنبياء: 58","question":"ما سرّ استثناء كبير الأصنام في ﴿فَجَعَلَهُمْ جُذَاذًا إِلَّا كَبِيرًا لَهُمْ﴾؟","answer":"أبقاه ليكون شاهدًا على عجز معبوداتهم: فلو استحق العبادة لرجعوا إليه في معرفة من حطّمها، لكنه لا ينطق باسم الفاعل، ولم يدافع عن الأصنام التي يزعمون مشاركتها له في الألوهية. فصار بقاؤه جزءًا من الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص568، تحت عنوان «نكتة استثناء ﴿كبيرًا﴾»","url":""}]},{"id":"s21-62","number":62,"surah":21,"verses":[60],"references":[{"surah":21,"verses":[60]}],"verseLabel":"الأنبياء: 60","question":"ما نكتة التعبير بلفظ ﴿فَتًى﴾ وتنكيره في وصف إبراهيم؟","answer":"يحتمل التنكير أنهم لم يعرفوه، أو قصدوا الازدراء بحداثة سنه وتقليل شأنه؛ فكلا الوجهين يصور نظرهم إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص580، تحت عنوان «نكتة التعبير بلفظ ﴿فَتًى﴾ وفائدة تنكيره»","url":""}]},{"id":"s21-132","number":132,"surah":21,"verses":[60],"references":[{"surah":21,"verses":[60]}],"verseLabel":"الأنبياء: 60","question":"ما بلاغة بناء ﴿يُقَالُ لَهُ إِبْرَاهِيمُ﴾ للمجهول؟","answer":"ناسب البناء للمجهول حكاية اسم شخص غير معروف عند بعضهم أو غير ذي منزلة في نظرهم، مع توجيه الاهتمام إلى الاسم لا إلى قائله.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص581، تحت عنوان «بلاغة التعبير بالفعل ﴿يُقَالُ﴾ مادة وصيغة»","url":""}]},{"id":"s21-63","number":63,"surah":21,"verses":[63],"references":[{"surah":21,"verses":[63]}],"verseLabel":"الأنبياء: 63","question":"ما المراد بخبر إبراهيم: ﴿بَلْ فَعَلَهُ كَبِيرُهُمْ هَذَا﴾؟","answer":"سيق الخبر لتبكيتهم وإلزامهم الحجة لا لإثبات أن الصنم حطمها حقيقة؛ فهو يردهم إلى التناقض في عبادتها مع علمهم بعجزها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص593–594، تحت عنوان «المراد بالخبر في ﴿فَعَلَهُ كَبِيرُهُمْ﴾»","url":""}]},{"id":"s21-133","number":133,"surah":21,"verses":[63],"references":[{"surah":21,"verses":[63]}],"verseLabel":"الأنبياء: 63","question":"ما بلاغة الأمر في قوله: ﴿فَاسْأَلُوهُمْ إِنْ كَانُوا يَنْطِقُونَ﴾؟","answer":"الأمر للتعجيز والتهكم؛ فسؤال الأصنام يكشف عجزها عن النطق، ومن ثم عجزها عن الفعل وبطلان عبادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص594–595، تحت عنوان «بلاغة الأمر: ﴿فَاسْأَلُوهُمْ﴾»","url":""}]},{"id":"s21-64","number":64,"surah":21,"verses":[64],"references":[{"surah":21,"verses":[64]}],"verseLabel":"الأنبياء: 64","question":"ما بلاغة الاستعارة في قوله: ﴿فَرَجَعُوا﴾؟","answer":"استعير الرجوع الحسي لعودهم إلى التأمل بعد غفلة، فصوّر انتقال عقولهم من الاتهام إلى الاعتراف ببطلان موقفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص599–600، تحت عنوان «بلاغة الاستعارة في الفعل ﴿فَرَجَعُوا﴾»","url":""}]},{"id":"s21-134","number":134,"surah":21,"verses":[64],"references":[{"surah":21,"verses":[64]}],"verseLabel":"الأنبياء: 64","question":"ما معنى ﴿إِلَى أَنْفُسِهِمْ﴾ في قوله: ﴿فَرَجَعُوا إِلَى أَنْفُسِهِمْ﴾؟","answer":"أي راجع كل واحد نفسه، أو رجع بعضهم إلى بعض بالمناقشة؛ وفي الوجهين انتهوا إلى الاعتراف بأنهم الظالمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص600، تحت عنوان «معنى ﴿إِلَى أَنْفُسِهِمْ﴾ وفائدته»","url":""}]},{"id":"s21-65","number":65,"surah":21,"verses":[65],"references":[{"surah":21,"verses":[65]}],"verseLabel":"الأنبياء: 65","question":"ما دلالة الصورة في ﴿ثُمَّ نُكِسُوا عَلَى رُءُوسِهِمْ﴾؟","answer":"الوجه الأظهر في المبحث أنها استعارة تمثيلية لارتدادهم إلى الباطل بعد إقرارهم بالحق: صُوّر انقلاب رأيهم كتحول المنتصب على قدميه إلى منكوس على رأسه، تشنيعًا لشأنهم. وذُكر أيضًا وجه الإطراق الحقيقي خجلًا وانكسارًا، فلا تُعرض الاستعارة باعتبارها الوجه الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص603–604، تحت عنوان «بلاغة التمثيل المركب»","url":""}]},{"id":"s21-66","number":66,"surah":21,"verses":[68],"references":[{"surah":21,"verses":[68]}],"verseLabel":"الأنبياء: 68","question":"ما دلالة فصل قولهم: ﴿قَالُوا حَرِّقُوهُ﴾ عما قبله؟","answer":"جاء الفصل كجواب عن سؤال يثيره انكشاف عجزهم: ماذا صنعوا بإبراهيم؟ فكان انتقالهم إلى التحريق دليل إفلاسهم من الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص622، تحت عنوان «علة فصل الجملة في صدر الآية»","url":""}]},{"id":"s21-135","number":135,"surah":21,"verses":[68],"references":[{"surah":21,"verses":[68]}],"verseLabel":"الأنبياء: 68","question":"ما دلالة عطف ﴿وَانْصُرُوا آلِهَتَكُمْ﴾ على الأمر بتحريق إبراهيم؟","answer":"سموا انتقامهم للأصنام نصرًا لها، فافتضح ضعفها: المعبود الحق ينصر عابديه، أما أصنامهم فتحتاج إلى أن ينصروها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص623، تحت عنوان «دلالة عطف ﴿وَانْصُرُوا آلِهَتَكُمْ﴾»","url":""}]},{"id":"s21-67","number":67,"surah":21,"verses":[69],"references":[{"surah":21,"verses":[69]}],"verseLabel":"الأنبياء: 69","question":"ما سرّ الجمع بين ﴿بَرْدًا﴾ و﴿سَلَامًا﴾ في خطاب النار؟","answer":"قد يكون البرد نفسه ضارًّا إذا اشتد، فجاء ﴿سلامًا﴾ احتراسًا من هذا الاحتمال؛ لتكون النار على إبراهيم بردًا مأمون الأذى، لا حرّ فيها يحرقه ولا قرّ يؤذيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص628، تحت عنوان «نكتة الجمع بين كونها بردًا وسلامًا»","url":""}]},{"id":"s21-68","number":68,"surah":21,"verses":[70],"references":[{"surah":21,"verses":[70]}],"verseLabel":"الأنبياء: 70","question":"ما سرّ وصفهم بـ﴿الْأَخْسَرِينَ﴾ في الأنبياء، وبـ﴿الْأَسْفَلِينَ﴾ في الصافات؟","answer":"في الأنبياء غلب سياق الكيد المتبادل، فناسبه الخسران بعد أن انقلب كيدهم عليهم. وفي الصافات سبق بناء البنيان وإرادة إلقائه في الجحيم، فناسب تصوير ما أرادوه له من السقوط بقوله ﴿الأسفلين﴾؛ إذ صارت السفالة لهم ورفعه الله عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص634–635، تحت عنوان «نكتة إيثار لفظ ﴿الأخسرين﴾ على ﴿الأسفلين﴾»","url":""}]},{"id":"s21-69","number":69,"surah":21,"verses":[71],"references":[{"surah":21,"verses":[71]}],"verseLabel":"الأنبياء: 71","question":"ما نكتة إيثار ﴿فِيهَا﴾ على «حولها» في وصف الأرض المباركة؟","answer":"جعلت ﴿فيها﴾ البركة مستقرة مستوعبة للأرض نفسها، بما فيها من الخيرات وبما ظهر فيها من الأنبياء والشرائع.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص639، تحت عنوان «نكتة إيثار ﴿فِيهَا﴾ على حولها»","url":""}]},{"id":"s21-136","number":136,"surah":21,"verses":[71],"references":[{"surah":21,"verses":[71]}],"verseLabel":"الأنبياء: 71","question":"ما سر التعبير بـ﴿لِلْعَالَمِينَ﴾ في قوله: ﴿الَّتِي بَارَكْنَا فِيهَا لِلْعَالَمِينَ﴾؟","answer":"دل اللفظ على امتداد نفع بركتها وأنبيائها وشرائعها إلى الناس عامة، لا إلى أهل تلك الأرض وحدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص639، تحت عنوان «إيثار لفظ ﴿لِلْعَالَمِينَ﴾ مادة وصيغة»","url":""}]},{"id":"s21-70","number":70,"surah":21,"verses":[73],"references":[{"surah":21,"verses":[73]}],"verseLabel":"الأنبياء: 73","question":"ما دلالة تقييد هداية الأئمة بقوله ﴿بِأَمْرِنَا﴾؟","answer":"ربط الهداية بأمر الله يبين أن إرشاد الأنبياء صادر عن الوحي ومقترن بطاعة الله وأمره ونهيه، لا عن رأي منفصل؛ فإمامتهم تبليغ للهداية الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص655، تحت عنوان «دلالة الارتباط بين الهداية وأمر الله»","url":""}]},{"id":"s21-71","number":71,"surah":21,"verses":[74],"references":[{"surah":21,"verses":[74]}],"verseLabel":"الأنبياء: 74","question":"ما بلاغة إضافة السوء إلى القوم في قوله: ﴿قَوْمَ سَوْءٍ﴾؟","answer":"أضيفوا إلى السوء مبالغة في ذمهم، حتى صار السوء لكثرة قبائحهم كأنه الوصف الذي ينتسبون إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص680، تحت عنوان «بلاغة إضافة السوء إلى القوم في قوله: ﴿قَوْمَ سَوْءٍ﴾»","url":""}]},{"id":"s21-137","number":137,"surah":21,"verses":[74],"references":[{"surah":21,"verses":[74]}],"verseLabel":"الأنبياء: 74","question":"ما نكتة وصف قوم لوط بـ﴿فَاسِقِينَ﴾؟","answer":"الفسق خروج عن أمر الله، وجاء الوصف بالاسم ليدل على رسوخ هذا الخروج وثباته فيهم، لا وقوع معصية عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص680، تحت عنوان «نكتة التعبير بلفظ ﴿فَاسِقِينَ﴾»","url":""}]},{"id":"s21-72","number":72,"surah":21,"verses":[76],"references":[{"surah":21,"verses":[76]}],"verseLabel":"الأنبياء: 76","question":"ما دلالة الفاء في ﴿فَاسْتَجَبْنَا لَهُ﴾ بعد نداء نوح؟","answer":"ترتب الاستجابة على النداء وتؤكد اتصالها به؛ فقد جاءت عقب تضرعه إلى ربه، من غير فصل في النظم. وفي هذا تسلية للنبي ووعد للمستغيثين بالله بالنصر والعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص691، تحت عنوان «نكتة استخدام حرف (الفاء) في الآية»","url":""}]},{"id":"s21-73","number":73,"surah":21,"verses":[78],"references":[{"surah":21,"verses":[78]}],"verseLabel":"الأنبياء: 78","question":"ما سرّ تصوير حكم داود وسليمان في الحرث بالمضارع ﴿يَحْكُمَانِ﴾؟","answer":"يحكي المضارع الحالة الماضية ويستحضر صورتها، فكأن المخاطب يشاهد حكمهما في القضية وقت وقوعه. وهذا أدعى إلى تصور أحداث القصة والتفاعل مع أشخاصها ومواقفها من مجرد الإخبار المجرد عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص709، تحت عنوان «أثر صيغة المضارع ﴿يحكمان﴾ في سياق الآية»","url":""}]},{"id":"s21-74","number":74,"surah":21,"verses":[79],"references":[{"surah":21,"verses":[79]}],"verseLabel":"الأنبياء: 79","question":"ما سرّ تعقيب ﴿فَفَهَّمْنَاهَا سُلَيْمَانَ﴾ بقوله ﴿وَكُلًّا آتَيْنَا حُكْمًا وَعِلْمًا﴾؟","answer":"هو احتراس يدفع توهم أن تخصيص سليمان بالتفهيم ينتقص حكم داود أو علمه؛ فكلاهما أوتي حكمًا وعلمًا، وإن كان فهم سليمان في هذه القضية أصوب وأرفق بالخصمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص723، تحت عنوان «بلاغة الاحتراس في الآية الكريمة»","url":""}]},{"id":"s21-75","number":75,"surah":21,"verses":[80],"references":[{"surah":21,"verses":[80]}],"verseLabel":"الأنبياء: 80","question":"ما بلاغة لفظ ﴿صَنْعَةَ﴾ في تعليم داود؟","answer":"الصنعة حرفة تقوم على الإتقان والمهارة، فدل اللفظ على تعليم داود عملًا محكمًا نافعًا لا مجرد فعل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص734–735، تحت عنوان «بلاغة لفظ ﴿صَنْعَةَ﴾ في الآية الكريمة»","url":""}]},{"id":"s21-138","number":138,"surah":21,"verses":[80],"references":[{"surah":21,"verses":[80]}],"verseLabel":"الأنبياء: 80","question":"ما سر اختيار ﴿لَبُوسٍ﴾ دون «لباس»؟","answer":"اللبوس ما يلبس للوقاية، وغلب هنا على دروع الحديد؛ فناسب مقام الحرب والحماية من البأس أكثر من لفظ اللباس العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص735، تحت عنوان «سر اختيار لفظ ﴿لَبُوسٍ﴾ دون لباس في الآية»","url":""}]},{"id":"s21-76","number":76,"surah":21,"verses":[81],"references":[{"surah":21,"verses":[81]}],"verseLabel":"الأنبياء: 81","question":"كيف يجتمع وصف ريح سليمان بـ﴿عَاصِفَةً﴾ ووصفها في موضع آخر بالرخاء؟","answer":"العصف يصف قوة الهبوب وسرعته، والرخاء يصف لين انقيادها أو حالًا أخرى منها؛ فهي قوية في عملها مطيعة لسليمان بحسب إرادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص745–746، تحت عنوان «دلالة لفظي ﴿عَاصِفَةً﴾ و﴿رُخَاءً﴾»","url":""}]},{"id":"s21-139","number":139,"surah":21,"verses":[81],"references":[{"surah":21,"verses":[81]}],"verseLabel":"الأنبياء: 81","question":"ما نكتة تقييد جريان الريح بقوله: ﴿بِأَمْرِهِ﴾؟","answer":"يبين القيد أن قوة الريح لا تخرجها عن التسخير؛ فهي تجري حيث يريد سليمان وبإذنه، لا حركة مضطربة مستقلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص747، تحت عنوان «نكتة التقييد بالجار والمجرور ﴿بِأَمْرِهِ﴾»","url":""}]},{"id":"s21-77","number":77,"surah":21,"verses":[83],"references":[{"surah":21,"verses":[83]}],"verseLabel":"الأنبياء: 83","question":"ما نكتة قول أيوب: ﴿مَسَّنِيَ الضُّرُّ﴾ دون «أصابني»؟","answer":"المس أخف الإصابة، فصوّر أيوب بلاءه به تأدبًا مع الله وصبرًا، من غير تهويل للشكوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص766، تحت عنوان «نكتة ذكر المس دون الإصابة»","url":""}]},{"id":"s21-140","number":140,"surah":21,"verses":[83],"references":[{"surah":21,"verses":[83]}],"verseLabel":"الأنبياء: 83","question":"ما بلاغة التعريض في قول أيوب: ﴿وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ﴾؟","answer":"ذكر حاله وأثنى على رحمة ربه، فعرّض بطلب الشفاء من غير تصريح؛ وفي ذلك أدب وتفويض وثقة بالرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص768، تحت عنوان «بلاغة التعريض»","url":""}]},{"id":"s21-78","number":78,"surah":21,"verses":[84],"references":[{"surah":21,"verses":[84]}],"verseLabel":"الأنبياء: 84","question":"ما بلاغة قوله في الأنبياء: ﴿رَحْمَةً مِنْ عِنْدِنَا﴾؟","answer":"تنوّه ﴿عندنا﴾ بقرب الرحمة وخصوص عناية الله بأيوب، وتفخم ما خصه به من كشف الضر وإعادة أهله إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص775، تحت عنوان «بلاغة استعمال عند دون لدن»","url":""}]},{"id":"s21-79","number":79,"surah":21,"verses":[87],"references":[{"surah":21,"verses":[87]}],"verseLabel":"الأنبياء: 87","question":"ما سرّ ذكر يونس بلقب ﴿ذَا النُّونِ﴾ بدل اسمه؟","answer":"النون الحوت، واللقب يعرّف بيونس من خلال الحادثة التي اختص بها. وهو مناسب لمقام التنويه بصبره والتجائه إلى الله في بطن الحوت، فيجمع التعريف بالشخص والتذكير بشأنه في المحنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص787–788، تحت عنوان «نكتة ذكر اللقب ﴿ذا النون﴾ دون الاسم (يونس)»","url":""}]},{"id":"s21-80","number":80,"surah":21,"verses":[87],"references":[{"surah":21,"verses":[87]}],"verseLabel":"الأنبياء: 87","question":"ما دلالة ﴿لَنْ نَقْدِرَ عَلَيْهِ﴾ في قصة يونس؟","answer":"المعنى أن يونس ظن ألا يضيّق الله عليه أو يقدّر عليه العقوبة لخروجه باجتهاده، لا أنه ظن العجز عن القدرة عليه؛ وكان الأولى أن يستأذن ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص791، تحت عنوان «نكتة استعمال الفعل ﴿نَقْدِرَ﴾»","url":""}]},{"id":"s21-81","number":81,"surah":21,"verses":[87],"references":[{"surah":21,"verses":[87]}],"verseLabel":"الأنبياء: 87","question":"ما غرض ذكر التنزيه بعد التوحيد في دعاء يونس؟","answer":"بدأ بإفراد الله بالألوهية، ثم نزهه عن كل نقص أو ظلم؛ فجمع بين إثبات الكمال ونفي النقص قبل عرض حاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص794–795، تحت عنوان «غرض ذكر التنزيه بعد التوحيد»","url":""}]},{"id":"s21-141","number":141,"surah":21,"verses":[87],"references":[{"surah":21,"verses":[87]}],"verseLabel":"الأنبياء: 87","question":"ما بلاغة قوله: ﴿إِنِّي كُنْتُ مِنَ الظَّالِمِينَ﴾ في دعاء يونس؟","answer":"الجملة اعتراف صريح بالتقصير وتعليل لطلب المغفرة والنجاة، فجمعت التوبة والانكسار بعد الثناء على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص795، تحت عنوان «بلاغة جملة التعليل»","url":""}]},{"id":"s21-82","number":82,"surah":21,"verses":[88],"references":[{"surah":21,"verses":[88]}],"verseLabel":"الأنبياء: 88","question":"ما بلاغة الكاف في قوله: ﴿وَكَذَلِكَ نُنْجِي الْمُؤْمِنِينَ﴾؟","answer":"شبه إنجاء المؤمنين بإنجاء يونس، فنقلت الكاف القصة من واقعة خاصة إلى سنة عامة تبشر أهل الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص799، تحت عنوان «بلاغة استعمال الكاف»","url":""}]},{"id":"s21-142","number":142,"surah":21,"verses":[88],"references":[{"surah":21,"verses":[88]}],"verseLabel":"الأنبياء: 88","question":"ما سر اختيار وصف ﴿الْمُؤْمِنِينَ﴾ في وعد النجاة؟","answer":"خُصوا لأن الإيمان أصل الأعمال المقبولة وسبب الالتجاء الصادق، وفي الوصف تبشير لهم وتعريض بالمكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص802، تحت عنوان «توجيه اختيار وصف ﴿الْمُؤْمِنِينَ﴾»","url":""}]},{"id":"s21-83","number":83,"surah":21,"verses":[89],"references":[{"surah":21,"verses":[89]}],"verseLabel":"الأنبياء: 89","question":"ما بلاغة الجملة الاسمية: ﴿وَأَنْتَ خَيْرُ الْوَارِثِينَ﴾؟","answer":"تفيد الجملة ثبات هذا الكمال لله، وجاءت استسلامًا وتفويضًا بعد طلب الولد: فإن لم يعط فالوارث الباقي هو الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص14–15، تحت عنوان «بلاغة الجملة الاسمية»","url":""}]},{"id":"s21-143","number":143,"surah":21,"verses":[89],"references":[{"surah":21,"verses":[89]}],"verseLabel":"الأنبياء: 89","question":"ما فائدة ذكر صفة الوارث في دعاء زكريا؟","answer":"ناسبت الصفة طلب الولد والخوف من الانفراد؛ فذكّر أن وراثة الله باقية شاملة وأكمل من وراثة الأقارب.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص15–16، تحت عنوان «فائدة ذكر صفة الوارث»","url":""}]},{"id":"s21-84","number":84,"surah":21,"verses":[90],"references":[{"surah":21,"verses":[90]}],"verseLabel":"الأنبياء: 90","question":"ما نكتة التعبير بالفعل ﴿يُسَارِعُونَ﴾ في وصف الأنبياء؟","answer":"صيغة المسارعة تصور شدة المبادرة والمنافسة في الخير كلما سنحت فرصته، فلا يتراخون عنه ولا يكتفون بقدر سابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص21، تحت عنوان «نكتة التعبير بالمسارعة»","url":""}]},{"id":"s21-85","number":85,"surah":21,"verses":[91],"references":[{"surah":21,"verses":[91]}],"verseLabel":"الأنبياء: 91","question":"ما سرّ إفراد ﴿آيَةً﴾ في ﴿وَجَعَلْنَاهَا وَابْنَهَا آيَةً لِلْعَالَمِينَ﴾؟","answer":"لأن شأن مريم وابنها في المعجزة واحد؛ فحملها وولادته من غير أب حال مشتركة تكون آية واحدة، وإن كان في كل منهما آيات أخرى مستقلة. ويحتمل أيضًا إرادة الجنس بلفظ ﴿آية﴾، فيشمل ما لكل واحد منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص37–38، تحت عنوان «سر التعبير بالإفراد ﴿آية﴾ دون التثنية»","url":""}]},{"id":"s21-86","number":86,"surah":21,"verses":[92],"references":[{"surah":21,"verses":[92]}],"verseLabel":"الأنبياء: 92","question":"ما دلالة ﴿أُمَّةً وَاحِدَةً﴾ في ختام قصص الأنبياء؟","answer":"أكد وصف الأمة بأنها واحدة أن أصل دعوات الأنبياء جميعًا هو التوحيد الخالص، رغم اختلاف الأزمنة والشرائع، فنفى تعدد الأصول والآلهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص45، تحت عنوان «فائدة الوصف بـ﴿وَاحِدَةً﴾»","url":""}]},{"id":"s21-87","number":87,"surah":21,"verses":[93],"references":[{"surah":21,"verses":[93]}],"verseLabel":"الأنبياء: 93","question":"ما دلالة تصوير اختلافهم في الدين بـ﴿وَتَقَطَّعُوا أَمْرَهُمْ بَيْنَهُمْ﴾؟","answer":"صُوّر الدين شيئًا نفيسًا متماسكًا كان ينبغي صونه، فمزقوه قطعًا. وفي الصورة تشنيع لتفرقهم؛ إذ صاروا فرقًا تتنازع وتتباين، وضيّعوا باختلافهم ما كان يجمعهم على الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص56، تحت عنوان «بلاغة الاستعارة المكنية»","url":""}]},{"id":"s21-88","number":88,"surah":21,"verses":[95],"references":[{"surah":21,"verses":[95]}],"verseLabel":"الأنبياء: 95","question":"ما دلالة اختيار ﴿وَحَرَامٌ﴾ في قوله: ﴿وَحَرَامٌ عَلَى قَرْيَةٍ أَهْلَكْنَاهَا﴾؟","answer":"قرر اللفظ الامتناع والتحقق؛ فلا سبيل للقوم المهلكين إلى الرجوع الذي ينفعهم بعد نزول الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص71–72، تحت عنوان «دلالة اختيار مفردة ﴿وَحَرَامٌ﴾»","url":""}]},{"id":"s21-144","number":144,"surah":21,"verses":[95],"references":[{"surah":21,"verses":[95]}],"verseLabel":"الأنبياء: 95","question":"ما غرض حذف متعلق ﴿يَرْجِعُونَ﴾؟","answer":"عمم الحذف وجوه الرجوع المنفي، فيحتمل الرجوع إلى الدنيا أو التوبة أو الإيمان والإنابة، بحسب توجيه السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص77، تحت عنوان «غرض حذف متعلق ﴿يَرْجِعُونَ﴾»","url":""}]},{"id":"s21-89","number":89,"surah":21,"verses":[96],"references":[{"surah":21,"verses":[96]}],"verseLabel":"الأنبياء: 96","question":"ما فائدة العموم في قوله: ﴿مِنْ كُلِّ حَدَبٍ﴾؟","answer":"صوّر العموم أفواجًا كثيرة تتدفق من المرتفعات ومن شتى جهات الأرض، فبرزت كثرة الجمع وانتشاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص85–86، تحت عنوان «فائدة التعبير بلفظ العموم ﴿كُلِّ﴾»","url":""}]},{"id":"s21-145","number":145,"surah":21,"verses":[96],"references":[{"surah":21,"verses":[96]}],"verseLabel":"الأنبياء: 96","question":"ما دلالة التعبير بـ﴿يَنْسِلُونَ﴾؟","answer":"يدل النسلان على سرعة الخروج والحركة والانتشار، فأكمل صورة الكثرة المتدفقة من كل جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص86–87، تحت عنوان «دلالة التعبير بـ﴿يَنْسِلُونَ﴾»","url":""}]},{"id":"s21-90","number":90,"surah":21,"verses":[97],"references":[{"surah":21,"verses":[97]}],"verseLabel":"الأنبياء: 97","question":"ما بلاغة ﴿إِذَا﴾ الفجائية في قوله: ﴿فَإِذَا هِيَ شَاخِصَةٌ﴾؟","answer":"أبرزت مباغتة أهوال القيامة للكافرين وانتقالهم الفوري إلى الدهشة من غير استعداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص90، تحت عنوان «بلاغة إذا الفجائية»","url":""}]},{"id":"s21-146","number":146,"surah":21,"verses":[97],"references":[{"surah":21,"verses":[97]}],"verseLabel":"الأنبياء: 97","question":"ما سر التعبير بـ﴿شَاخِصَةٌ﴾ عن أبصار الكافرين؟","answer":"الشخوص إحداد البصر وثباته بلا طرف، فكَنَى عن دهشة أصحاب الأبصار وشدة فزعهم مما رأوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص91–92، تحت عنوان «سر التعبير بـ﴿شَاخِصَةٌ﴾»","url":""}]},{"id":"s21-91","number":91,"surah":21,"verses":[98],"references":[{"surah":21,"verses":[98]}],"verseLabel":"الأنبياء: 98","question":"ما دلالة التعبير عنهم وعن معبوداتهم بـ﴿حَصَبُ جَهَنَّمَ﴾؟","answer":"الحصب ما يُرمى به في النار، وفي اللفظ تصوير لمهانتهم وإلقائهم فيها إلقاء الحصى الصغار. فقد صار ما عظّموه مع أنفسهم وقودًا للنار، لا وزن له ولا قدرة على النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص104، تحت عنوان «دلالة استعمال لفظ ﴿حصب﴾ دون مرادفاتها»","url":""}]},{"id":"s21-92","number":92,"surah":21,"verses":[99],"references":[{"surah":21,"verses":[99]}],"verseLabel":"الأنبياء: 99","question":"ما بلاغة استعمال ﴿لَوْ﴾ في قوله: ﴿لَوْ كَانَ هَؤُلَاءِ آلِهَةً مَا وَرَدُوهَا﴾؟","answer":"رتبت لو امتناع الجواب على امتناع الشرط، فدخول المعبودات النار برهان على بطلان ألوهيتها وعجزها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص106–107، تحت عنوان «بلاغة استعمال ﴿لَوْ﴾»","url":""}]},{"id":"s21-147","number":147,"surah":21,"verses":[99],"references":[{"surah":21,"verses":[99]}],"verseLabel":"الأنبياء: 99","question":"ما فائدة نفي الورود دون الدخول في قوله: ﴿مَا وَرَدُوهَا﴾؟","answer":"نفي الورود أبلغ؛ فلو كانت آلهة لما قاربت النار أو بلغتها أصلًا، فضلًا عن دخولها والخلود فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص108، تحت عنوان «فائدة نفي الورود دون الدخول»","url":""}]},{"id":"s21-93","number":93,"surah":21,"verses":[100],"references":[{"surah":21,"verses":[100]}],"verseLabel":"الأنبياء: 100","question":"ما دلالة الواو في قوله: ﴿وَهُمْ فِيهَا لَا يَسْمَعُونَ﴾ بعد ذكر الزفير؟","answer":"جمعت الواو حالين من العذاب: زفيرًا من شدة النار، وحرمانًا من السماع، فتضاعفت صورة الألم والعزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص113، تحت عنوان «نوع الواو ودلالتها»","url":""}]},{"id":"s21-148","number":148,"surah":21,"verses":[100],"references":[{"surah":21,"verses":[100]}],"verseLabel":"الأنبياء: 100","question":"ما نكتة حذف مفعول ﴿يَسْمَعُونَ﴾؟","answer":"عمم الحذف ما حرموا سماعه، فيشمل الكلام النافع وما يسرهم أو يخفف عنهم، ويحتمل أن شدة الزفير والعذاب حجبت أسماعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص114، تحت عنوان «نكتة حذف مفعول ﴿يَسْمَعُونَ﴾»","url":""}]},{"id":"s21-94","number":94,"surah":21,"verses":[101],"references":[{"surah":21,"verses":[101]}],"verseLabel":"الأنبياء: 101","question":"ما دلالة ﴿سَبَقَتْ لَهُمْ مِنَّا الْحُسْنَى﴾؟","answer":"السبق كناية عن ثبوت وعد الله الحسن وضمان النجاة والرضوان قبل ورود مشهد العذاب؛ فيطمئن أهل السعادة إلى ما كتب لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص120، تحت عنوان «بلاغة الكناية في لفظ ﴿سَبَقَتْ﴾»","url":""}]},{"id":"s21-95","number":95,"surah":21,"verses":[103],"references":[{"surah":21,"verses":[103]}],"verseLabel":"الأنبياء: 103","question":"ما غرض حذف القول قبل قوله: ﴿هَذَا يَوْمُكُمُ﴾؟","answer":"عجّل الحذف عرض البشارة ووصلها بالمؤمنين مباشرة، فكأنهم يسمعونها فور استقبال الملائكة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص136، تحت عنوان «الغرض من حذف لفظ القول»","url":""}]},{"id":"s21-149","number":149,"surah":21,"verses":[103],"references":[{"surah":21,"verses":[103]}],"verseLabel":"الأنبياء: 103","question":"ما دلالة اسم الإشارة القريب في قوله: ﴿هَذَا يَوْمُكُمُ﴾؟","answer":"جعل اليوم الموعود حاضرًا مشاهدًا بعد طول انتظار، فزاد اليقين والسرور بتحقق الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص136، تحت عنوان «دلالة التعبير باسم الإشارة القريب ﴿هَذَا﴾»","url":""}]},{"id":"s21-150","number":150,"surah":21,"verses":[103],"references":[{"surah":21,"verses":[103]}],"verseLabel":"الأنبياء: 103","question":"ما دلالة إضافة اليوم إليهم في قوله: ﴿يَوْمُكُمُ﴾؟","answer":"خصهم اليوم بكرامته وبشراه، فهو يوم فوزهم الذي وعدوا به، في مقابل يوم الحسرة على المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص136–137، تحت عنوان «دلالة الإضافة في ﴿يَوْمُكُمُ﴾»","url":""}]},{"id":"s21-96","number":96,"surah":21,"verses":[104],"references":[{"surah":21,"verses":[104]}],"verseLabel":"الأنبياء: 104","question":"ما دلالة تشبيه طي السماء بطي السجل؟","answer":"يقرب التشبيه تحول السماء بصورة طي الصحيفة وما كُتب فيها؛ فيختصر مشهدًا كونيًا عظيمًا في صورة محسوسة موجزة. وفيه بيان يسر ذلك على الله وسهولته، كسهولة طي الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص142–143، تحت عنوان «بلاغة التشبيه في قوله: ﴿كطي﴾»","url":""}]},{"id":"s21-97","number":97,"surah":21,"verses":[104],"references":[{"surah":21,"verses":[104]}],"verseLabel":"الأنبياء: 104","question":"ما دلالة التشبيه في ﴿كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُعِيدُهُ﴾؟","answer":"شبّهت الكاف إعادة الخلق بابتدائه من جهة القدرة والإمكان؛ فالذي أوجده أول مرة قادر على إعادته، من غير إيحاء بأن المعاد مجرد خلق شبيه بالأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص144، تحت عنوان «دلالة التعبير بالكاف في قوله: ﴿كَمَا﴾ دون مثل»","url":""}]},{"id":"s21-98","number":98,"surah":21,"verses":[105],"references":[{"surah":21,"verses":[105]}],"verseLabel":"الأنبياء: 105","question":"ما دلالة الميراث في ﴿أَنَّ الْأَرْضَ يَرِثُهَا عِبَادِيَ الصَّالِحُونَ﴾؟","answer":"إن أريدت أرض الدنيا، فالميراث انتقالها من الظالمين إلى المؤمنين الصالحين. وإن أريدت أرض الجنة، فهو تصوير لنيل نعيمها دون عناء ما لاقوه في الدنيا، كحصول الميراث بلا كد في اكتسابه. وقد ذكر المبحث الوجهين، فلا تُحصر الأرض في الدنيا وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص155–156، تحت عنوان «سر التعبير بالميراث في قوله ﴿يرثها﴾»","url":""}]},{"id":"s21-99","number":99,"surah":21,"verses":[106],"references":[{"surah":21,"verses":[106]}],"verseLabel":"الأنبياء: 106","question":"ما غرض تنكير ﴿بَلَاغًا﴾ في قوله: ﴿إِنَّ فِي هَذَا لَبَلَاغًا﴾؟","answer":"يفيد التنكير التعظيم؛ ففيما تقدم كفاية عظيمة تبلغ بالمتدبر إلى الحق والاتعاظ والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص160، تحت عنوان «الغرض من التنكير في قوله: ﴿بَلَاغًا﴾»","url":""}]},{"id":"s21-151","number":151,"surah":21,"verses":[106],"references":[{"surah":21,"verses":[106]}],"verseLabel":"الأنبياء: 106","question":"ما سر التعبير بـ﴿عَابِدِينَ﴾ دون المؤمنين؟","answer":"اختير العابدون لأن العبادة إيمان ظهر أثره في الطاعة ومجاهدة النفس، فهم أحق الناس بالانتفاع بهذا البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص161، تحت عنوان «دلالة التعبير بالعابدين دون المؤمنين»","url":""}]},{"id":"s21-100","number":100,"surah":21,"verses":[107],"references":[{"surah":21,"verses":[107]}],"verseLabel":"الأنبياء: 107","question":"ما بلاغة القصر في قوله: ﴿وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِلْعَالَمِينَ﴾؟","answer":"قصر الإرسال على الرحمة لإبراز مقصد الرسالة الأعظم ورد ما يصفها به المكذبون من الشدة أو الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص164–165، تحت عنوان «بلاغة أسلوب القصر في الآية»","url":""}]},{"id":"s21-152","number":152,"surah":21,"verses":[107],"references":[{"surah":21,"verses":[107]}],"verseLabel":"الأنبياء: 107","question":"ما دلالة التعبير بالمصدر ﴿رَحْمَةً﴾ عن الرسول؟","answer":"بالغ المصدر حتى كأن الرسول نفس الرحمة، ودل على ثباتها وعمومها لما في هديه وتشريعه من مصالح العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص166، تحت عنوان «دلالة التعبير بالمصدر ﴿رَحْمَةً﴾»","url":""}]},{"id":"s21-101","number":101,"surah":21,"verses":[108],"references":[{"surah":21,"verses":[108]}],"verseLabel":"الأنبياء: 108","question":"ما غرض التعبير بالاسم ﴿مُسْلِمُونَ﴾ في قوله: ﴿فَهَلْ أَنْتُمْ مُسْلِمُونَ﴾؟","answer":"يطلب الاسم منهم إسلامًا ثابتًا راسخًا يتصفون به، لا استجابة عارضة مترددة؛ فجاء بعد قيام حجة التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص172، تحت عنوان «الغرض من التعبير بالخبر اسمًا ﴿مُسْلِمُونَ﴾»","url":""}]},{"id":"s21-102","number":102,"surah":21,"verses":[109],"references":[{"surah":21,"verses":[109]}],"verseLabel":"الأنبياء: 109","question":"ما سر التعبير بـ﴿آذَنْتُكُمْ﴾؟","answer":"الإيذان إعلام يتضمن التحذير والإنذار، فدل على تبليغهم مع إبراء الذمة من عاقبة الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص175، تحت عنوان «سر التعبير بقوله: ﴿آذَنْتُكُمْ﴾»","url":""}]},{"id":"s21-153","number":153,"surah":21,"verses":[109],"references":[{"surah":21,"verses":[109]}],"verseLabel":"الأنبياء: 109","question":"ما الكناية في قوله: ﴿عَلَى سَوَاءٍ﴾؟","answer":"كَنَى عن شمول البلاغ ووضوحه للجميع؛ فلا خفاء في الحجة ولا اختصاص لفريق بالإنذار دون آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص176، تحت عنوان «الكناية في قوله: ﴿عَلَى سَوَاءٍ﴾»","url":""}]},{"id":"s21-103","number":103,"surah":21,"verses":[111],"references":[{"surah":21,"verses":[111]}],"verseLabel":"الأنبياء: 111","question":"ما سر التعبير بـ﴿لَعَلَّهُ﴾ في تأخير الوعيد؟","answer":"تفيد لعل الإشفاق والتحذير من احتمال أن يكون الإمهال فتنة تستدرجهم وهم غافلون، لا علامة على سقوط الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص187، تحت عنوان «سر التعبير بـ﴿لَعَلَّ﴾»","url":""}]},{"id":"s21-154","number":154,"surah":21,"verses":[111],"references":[{"surah":21,"verses":[111]}],"verseLabel":"الأنبياء: 111","question":"ما دلالة التعبير بالظرفية ﴿إِلَى حِينٍ﴾؟","answer":"قيد المتاع بغاية مجهولة لهم معلومة لله، فقرر أنه مؤقت ينتهي عند الأجل المقدر، ولا يدل الإمهال على النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص188، تحت عنوان «دلالة التعبير بالظرفية ﴿إِلَى حِينٍ﴾»","url":""}]},{"id":"s21-104","number":104,"surah":21,"verses":[112],"references":[{"surah":21,"verses":[112]}],"verseLabel":"الأنبياء: 112","question":"ما دلالة حذف متعلق الحكم في دعاء: ﴿رَبِّ احْكُمْ﴾؟","answer":"عمم الحذف ما يطلب الفصل فيه، أي احكم بين الرسول ومكذبيه وفيما اختلفوا فيه، مع تفويض صورة الحكم إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص193، تحت عنوان «دلالة حذف المتعلق الثاني للفعل ﴿احْكُمْ﴾»","url":""}]},{"id":"s21-155","number":155,"surah":21,"verses":[112],"references":[{"surah":21,"verses":[112]}],"verseLabel":"الأنبياء: 112","question":"لماذا قُيّد الحكم بقوله: ﴿بِالْحَقِّ﴾ مع أن الله لا يحكم إلا بالحق؟","answer":"جاء القيد لإظهار عدل الحكم المطلوب وطمأنة الرسول ووعيد المكذبين؛ فهو فصل يكشف المحق من المبطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص193، تحت عنوان «سر ذكر القيد ﴿بِالْحَقِّ﴾ والله لا يحكم إلا بالحق»","url":""}]},{"id":"s21-156","number":156,"surah":21,"verses":[112],"references":[{"surah":21,"verses":[112]}],"verseLabel":"الأنبياء: 112","question":"ما بلاغة اتصال ختام سورة الأنبياء بمطلعها؟","answer":"افتتحت بذكر غفلة المكذبين وإعراضهم عن الذكر، وختمت بطلب حكم الله والاستعانة على افترائهم؛ فالتقى المطلع والخاتمة في الإنذار والرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص197، تحت عنوان «بلاغة ختام السورة بهذه الآية مع مراعاة مطلعها»","url":""}]},{"id":"s21-105","number":105,"surah":21,"verses":[33],"references":[{"surah":21,"verses":[33]}],"verseLabel":"الأنبياء: 33","question":"ما بلاغة التعبير عن حركة الأجرام بالسباحة في قوله: ﴿كُلٌّ فِي فَلَكٍ يَسْبَحُونَ﴾؟","answer":"استعيرت السباحة لحركة الشمس والقمر والأجرام في أفلاكها، فصورتها حركة حية منتظمة، وسوّغ هذا التشخيص جمع الضمير كالعقلاء مع عموم ﴿كل﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص311–312، تحت عنوان «بلاغة الاستعارة»","url":""}]},{"id":"s21-157","number":157,"surah":21,"verses":[4],"references":[{"surah":21,"verses":[4]}],"verseLabel":"الأنبياء: 4","question":"ما سر التعبير بـ﴿يَعْلَمُ الْقَوْلَ﴾، وما دلالة إفراد ﴿السَّمَاءِ﴾ هنا وجمعها في سورة الفرقان؟","answer":"«القول» أعم من «السر» لأنه يشمل السر والجهر، فناسبه لفظ «السماء» الذي هو أعم من «السماوات». أما في الفرقان فجاء ﴿يَعْلَمُ السِّرَّ فِي السَّمَاوَاتِ﴾، فناسب الأخصُّ الأخصَّ. كما أن سياق الأنبياء ذكر النجوى وما قالوه فيها، فكان ذكر «القول» أنسب وأبلغ في إحاطة العلم بما أسروا وما أعلنوا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 21–23، مبحث «يعلم القول في السماء والأرض»؛ وانظر: فاضل السامرائي، التعبير القرآني، ص 52–53، مبحث «مناسبة العموم والخصوص في التعبير».","url":""}]},{"id":"s21-158","number":158,"surah":21,"verses":[30],"references":[{"surah":21,"verses":[30]}],"verseLabel":"الأنبياء: 30","question":"ما سر الإخبار بالمصدر ﴿رَتْقًا﴾ بدل «مرتوقتين»؟","answer":"المصدر يصح أن يخبر به عن المفرد والمثنى والجمع، لكنه هنا يحقق أيضًا المبالغة؛ فكأن السماوات والأرض كانتا عين الرتق وشدة الالتئام، لا مجرد شيئين موصوفين به. ثم قابل هذا التماسك بالفعل ﴿فَفَتَقْنَاهُمَا﴾ الذي يصور الفصل بعد الالتحام.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 76–78، مبحث «كانتا رتقًا ففتقناهما».","url":""}]},{"id":"s21-159","number":159,"surah":21,"verses":[36],"references":[{"surah":21,"verses":[36]}],"verseLabel":"الأنبياء: 36","question":"ما سر نفي فعلهم بـ﴿إِنْ﴾ في قوله: ﴿إِنْ يَتَّخِذُونَكَ إِلَّا هُزُوًا﴾، والتعبير بالمصدر ﴿هُزُوًا﴾؟","answer":"النفي بـ«إن» يلائم هذا الموضع ويقصر شأنهم عند رؤيته على اتخاذه موضع استهزاء. وجاء ﴿هُزُوًا﴾ مصدرًا بمعنى اسم المفعول للمبالغة، فكأنهم جعلوه نفس الهزء، مع أن المفارقة أنهم يعيبون ذكر آلهتهم وهم بذكر الرحمن كافرون.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 90–94، مبحث «وإذا رآك الذين كفروا».","url":""}]},{"id":"s21-160","number":160,"surah":21,"verses":[39],"references":[{"surah":21,"verses":[39]}],"verseLabel":"الأنبياء: 39","question":"ما سر حذف جواب ﴿لَوْ﴾ في قوله تعالى: ﴿لَوْ يَعْلَمُ الَّذِينَ كَفَرُوا﴾؟","answer":"حُذف الجواب للتهويل؛ لأن العبارة المحددة لا تستوعب فظاعة ما سيعلمونه، فتُترك النفس تتخيل من الهول ما لا يبلغه التصريح. وصار ﴿حِينَ﴾ مفعولًا للعلم: لو يعلمون ذلك الوقت الذي لا يستطيعون فيه دفع النار عن وجوههم ولا ظهورهم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 97–101، مبحث «لو يعلم الذين كفروا».","url":""}]},{"id":"s21-161","number":161,"surah":21,"verses":[40],"references":[{"surah":21,"verses":[40]}],"verseLabel":"الأنبياء: 40","question":"ما الفرق بين قوله: ﴿فَلَا يَسْتَطِيعُونَ رَدَّهَا﴾ وبين أن يقال: «فلا يردونها»؟","answer":"«لا يردونها» قد تحتمل وجود القدرة مع ترك الفعل، أما ﴿فَلَا يَسْتَطِيعُونَ﴾ فتنفي أصل القدرة على الرد. وجاءت ﴿بَغْتَةً﴾ مصدرًا للمبالغة، ثم ربطت الفاء المباغتة بالبهت مباشرة، فصورت سرعة الغلبة وانقطاع المهلة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 101–102، مبحث «بل تأتيهم بغتة فتبهتهم».","url":""}]},{"id":"s21-162","number":162,"surah":21,"verses":[45],"references":[{"surah":21,"verses":[45]}],"verseLabel":"الأنبياء: 45","question":"ما أثر العدول عن وصفهم بعدم الاستجابة إلى تصويرهم بالصم؟","answer":"لم يقل إنهم لا يستجيبون للإنذار، بل جعلهم بمنزلة الصم الذين لا يسمعون الدعاء أصلًا؛ فانتقل من تقرير موقف إلى صورة محسوسة تكشف شدة إغلاقهم لوسائل الهداية. وخص السمع لأن الإنذار خطاب يُسمع، لكنهم عطّلوا أثره في نفوسهم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 111–113، مبحث «ولا يسمع الصم الدعاء».","url":""}]},{"id":"s21-163","number":163,"surah":21,"verses":[60,61],"references":[{"surah":21,"verses":[60,61]}],"verseLabel":"الأنبياء: 60، 61","question":"ما سر معاملتهم الأصنام معاملة العقلاء في قولهم: ﴿فَتًى يَذْكُرُهُمْ﴾؟","answer":"قالوا ﴿يَذْكُرُهُمْ﴾ بضمير العقلاء، لا «يذكرها»، لأن اعتقادهم الفاسد رفع الأصنام في أذهانهم إلى منزلة ذوات عاقلة. فكشف الضمير نفسه خلل تصورهم قبل أن تكشفه حجة إبراهيم، ثم جاء ﴿عَلَى أَعْيُنِ النَّاسِ﴾ لتصوير الإحضار العلني المشهود.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 149–150، مبحث «سمعنا فتى يذكرهم».","url":""}]},{"id":"s21-164","number":164,"surah":21,"verses":[68],"references":[{"surah":21,"verses":[68]}],"verseLabel":"الأنبياء: 68","question":"ما دلالة التشديد في ﴿حَرِّقُوهُ﴾، ولم اختير في الأنبياء دون التخيير المذكور في العنكبوت؟","answer":"صيغة التفعيل تدل على التكثير والمبالغة، فليست مجرد إيقاع النار بل إحراقًا شديدًا متتابعًا. وفي الأنبياء استقر رأيهم على أشد العقوبتين نصرة لآلهتهم، أما العنكبوت فحكى مرحلة اقتراح القتل أو التحريق قبل استقرارهم على التنفيذ.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 154–156، مبحث «قالوا حرقوه».","url":""}]},{"id":"s21-165","number":165,"surah":21,"verses":[73],"references":[{"surah":21,"verses":[73]}],"verseLabel":"الأنبياء: 73","question":"ما سر تكرار الفعل والضمير في ﴿وَجَعَلْنَاهُمْ أَئِمَّةً﴾ بدل عطف «أئمة» على ما قبله؟","answer":"التكرار يرفع احتمال أن يكون الأئمة جماعة أخرى غير المذكورين؛ فقد أعاد الفعل ومفعوله ليقرر أن الأنبياء أنفسهم هم الذين جعلهم أئمة. وبذلك تتحدد مرجعية الهداية فيهم، ثم قيدها بقوله ﴿بِأَمْرِنَا﴾ حتى لا تُفهم إمامتهم مستقلة عن وحي الله.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 162–165، مبحث «وجعلناهم أئمة».","url":""}]},{"id":"s21-166","number":166,"surah":21,"verses":[74,75],"references":[{"surah":21,"verses":[74,75]}],"verseLabel":"الأنبياء: 74، 75","question":"ما سر استعمال ﴿نَجَّيْنَاهُ﴾ في سورة الأنبياء، واستعمال ﴿أَنْجَيْنَاهُ﴾ في الأعراف والنمل في قصة لوط نفسها؟","answer":"يراعي الاستعمال القرآني فرقًا دقيقًا بين الصيغتين؛ فـ«نجّى» تستعمل حيث يكون في النجاة تلبث وتمهل، أما «أنجى» فتدل على سرعة التخليص من الشدة. عرض موضع الأنبياء النجاة إجمالًا فقال ﴿نَجَّيْنَاهُ﴾، بينما صورت الأعراف والنمل خطر الإخراج واقتراب العقوبة، فناسبهما ﴿أَنْجَيْنَاهُ﴾ الأسرع دلالة.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص 70–77، مبحث «فعّل وأفعل بمعنى: نجّى وأنجى».","url":""}]},{"id":"s21-167","number":167,"surah":21,"verses":[79],"references":[{"surah":21,"verses":[79]}],"verseLabel":"الأنبياء: 79","question":"ما سر تقديم الجبال على الطير، واختيار الفعل ﴿يُسَبِّحْنَ﴾ بدل اسم الفاعل؟","answer":"قُدمت الجبال لأن تسخير الجماد وتسبيحه أعجب وأدل على القدرة من تسبيح الطير وهو حيوان. واختير الفعل المضارع ﴿يُسَبِّحْنَ﴾ ليدل على تجدد التسبيح حالًا بعد حال، بخلاف «مسبحات» الذي يغلب عليه ثبوت الوصف.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 180–181، مبحث «وسخرنا مع داود الجبال يسبحن والطير».","url":""}]},{"id":"s21-168","number":168,"surah":21,"verses":[80],"references":[{"surah":21,"verses":[80]}],"verseLabel":"الأنبياء: 80","question":"ما سر طلب الشكر في الأنبياء: ﴿فَهَلْ أَنْتُمْ شَاكِرُونَ﴾، وطلب العمل الصالح في سبأ بعد ذكر الدروع؟","answer":"في الأنبياء صرّح بأن اللبوس صُنع ﴿لَكُمْ﴾ ليحصن الناس، فناسب أن يطالبهم بالشكر على النعمة. أما في سبأ فوصف الدروع بالسابغات، أي الكاملات الوافيات، فناسب الأمر بالعمل الصالح، وهو أعم من الشكر؛ فجاء كل ختام على قدر ما أبرز السياق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 181–183، مبحث «وعلمناه صنعة لبوس لكم».","url":""}]},{"id":"s21-169","number":169,"surah":21,"verses":[82],"references":[{"surah":21,"verses":[82]}],"verseLabel":"الأنبياء: 82","question":"ما سر جمع الفعل في ﴿مَنْ يَغُوصُونَ لَهُ﴾، وإفراده في قوله بسورة سبأ: ﴿مَنْ يَعْمَلُ بَيْنَ يَدَيْهِ﴾؟","answer":"حمل فعل الأنبياء على معنى «مَن» الجمعي لأن السياق ذكر طائفتين أو عملين: الغوص والعمل دونه، فناسبه الجمع. أما سبأ فذكر أصل العمل وإن تنوعت صوره، فحمل الفعل على لفظ «مَن» المفرد؛ فجاء كل عدد ملائمًا لسعة المذكور في سياقه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 188–190، مبحث «ومن الشياطين من يغوصون له».","url":""}]},{"id":"s21-170","number":170,"surah":21,"verses":[83,84],"references":[{"surah":21,"verses":[83,84]}],"verseLabel":"الأنبياء: 83، 84","question":"ما سر مجيء قصة أيوب المبتلى الصابر بعد سليمان الغني الشاكر؟","answer":"جمع الترتيب صورتَي الابتلاء: نعمة واسعة تقتضي الشكر، وضر شديد يقتضي الصبر. فسليمان نموذج الغني الشاكر، وأيوب نموذج المبتلى الصابر؛ وباجتماعهما يكتمل ميزان العبودية في السراء والضراء.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 191–195، مبحث «وأيوب إذ نادى ربه».","url":""}]},{"id":"s21-171","number":171,"surah":21,"verses":[85,86],"references":[{"surah":21,"verses":[85,86]}],"verseLabel":"الأنبياء: 85، 86","question":"ما سر ذكر إسماعيل وإدريس وذي الكفل عقب قصة أيوب؟","answer":"الرابط البلاغي هو الصبر؛ فقد ختم وصف أيوب في موضع آخر بأنه صابر، ثم جمع هؤلاء بقوله ﴿كُلٌّ مِنَ الصَّابِرِينَ﴾. فالترتيب ليس جمع أسماء متفرقة، بل انتقال من نموذج مفصل للصبر إلى طائفة يشملها الوصف نفسه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 196، مبحث «كل من الصابرين».","url":""}]},{"id":"s21-172","number":172,"surah":21,"verses":[87],"references":[{"surah":21,"verses":[87]}],"verseLabel":"الأنبياء: 87","question":"ما دلالة ﴿مُغَاضِبًا﴾، وما المعنى الدقيق لقوله: ﴿لَنْ نَقْدِرَ عَلَيْهِ﴾؟","answer":"«مغاضب» من المفاعلة، أي غاضب قومه بسبب إصرارهم، وليس المعنى أنه غضب من ربه. و﴿نَقْدِرَ عَلَيْهِ﴾ تعني نضيّق عليه، لا نعجز عنه؛ فظن أن المجال متسع له في الانتقال إلى قوم آخرين، ثم أدرك أن خروجه كان قبل الإذن.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 197–198، مبحث «وذا النون إذ ذهب مغاضبًا».","url":""}]},{"id":"s21-173","number":173,"surah":21,"verses":[91],"references":[{"surah":21,"verses":[91]}],"verseLabel":"الأنبياء: 91","question":"ما سر قوله هنا: ﴿فَنَفَخْنَا فِيهَا﴾، وقوله في التحريم: ﴿فَنَفَخْنَا فِيهِ﴾؟","answer":"الضمير في الأنبياء يعود إلى مريم المذكورة بالموصول ﴿الَّتِي أَحْصَنَتْ﴾، فالمقام يبرز شخصها وابنها آية للعالمين. وفي التحريم يعود الضمير إلى الفرج المذكور صراحة، فاختار كل موضع مرجعًا يناسب بناء الجملة وغرض السياق، من غير تعارض في المعنى.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 213–216، مبحث «فنفخنا فيها من روحنا».","url":""}]},{"id":"s21-174","number":174,"surah":21,"verses":[104],"references":[{"surah":21,"verses":[104]}],"verseLabel":"الأنبياء: 104","question":"ما سر التعبير بالماضي واسم الفاعل معًا في قوله: ﴿إِنَّا كُنَّا فَاعِلِينَ﴾ عن أمر سيقع مستقبلًا؟","answer":"نُزِّل المستقبل منزلة الماضي في التحقق، فجاء ﴿كُنَّا﴾ كأن الفعل قد وقع وانقضى. ثم جيء باسم الفاعل ﴿فَاعِلِينَ﴾ لما فيه من الثبوت، وأكدت الجملة بـ«إن»؛ فتضافرت ثلاثة أساليب لتقرير أن إعادة الخلق وعد محقق لا مجال للشك فيه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 243–247، مبحث «يوم نطوي السماء».","url":""}]},{"id":"s21-175","number":175,"surah":21,"verses":[107],"references":[{"surah":21,"verses":[107]}],"verseLabel":"الأنبياء: 107","question":"ما سر جعل الرسول ﷺ نفسه ﴿رَحْمَةً لِلْعَالَمِينَ﴾، لا مجرد صاحب رحمة؟","answer":"الإخبار بالمصدر أبلغ؛ فكأنه عين الرحمة التي أُرسلت إلى العالمين، لا شخص اتصف بجزء منها. واختيار «الرحمة» دون «الرأفة» يحقق العموم؛ فالرأفة تختص غالبًا بدفع المكروه، أما الرحمة فتشمل دفع الضر وجلب الخير والهداية.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 249–251، مبحث «وما أرسلناك إلا رحمة للعالمين».","url":""}]},{"id":"s21-176","number":176,"surah":21,"verses":[108],"references":[{"surah":21,"verses":[108]}],"verseLabel":"الأنبياء: 108","question":"ما سر اجتماع أداتي الحصر في قوله: ﴿إِنَّمَا يُوحَى إِلَيَّ أَنَّمَا إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾؟","answer":"الأولى تقصر الوحي في هذا المقام على المقصد الأصلي للرسالة، والثانية تقصر الألوهية على إله واحد؛ فاجتمع قصر الحكم على الشيء وقصر الشيء على الحكم. ويحتمل أن تكون «ما» الأولى موصولة: إن الذي يوحى إلي هو وحدانية إلهكم، وفي الاحتمالين توكيد لمركزية التوحيد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 251–256، مبحث «قل إنما يوحى إلي أنما إلهكم إله واحد».","url":""}]},{"id":"s21-177","number":177,"surah":21,"verses":[112],"references":[{"surah":21,"verses":[112]}],"verseLabel":"الأنبياء: 112","question":"كيف ردَّت خاتمة سورة الأنبياء على مطلعها، حتى بدا آخرها كأنه تمام المشهد الأول؟","answer":"افتتحت السورة باقتراب الحساب وبغفلة المعرضين، ثم عادت في أواخرها إلى اقتراب الوعد واعترافهم: ﴿قَدْ كُنَّا فِي غَفْلَةٍ﴾، وختمت بطلب الحكم الحق. فتحول الإنذار الأول إلى مشهد واقع في الخاتمة، واتصل أول السورة بآخرها اتصال السبب بالنتيجة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 262–266، مبحث «قال رب احكم بالحق».","url":""}]},{"id":"s21-178","number":178,"surah":21,"verses":[1],"references":[{"surah":21,"verses":[1]}],"verseLabel":"الأنبياء: 1","question":"ما سر افتتاح سورة الأنبياء بقوله تعالى: ﴿اقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ﴾، وما صلته بخاتمة سورة طه؟","answer":"جاء الافتتاح متصلًا بقوله في ختام طه: ﴿وَأَجَلٌ مُسَمًّى﴾، ومن معاني هذا الأجل يوم القيامة، وهو موعد الحساب المذكور في مطلع الأنبياء. كما يتقابل إعراض الناس في أول الأنبياء مع الإعراض عن الذكر المذكور في ختام طه، فتبدو السورتان متلاحمتين في الإنذار من الغفلة وقرب الحساب.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 5–6، مبحث «ارتباط سورة الأنبياء بخواتيم سورة طه».","url":""}]},{"id":"s21-179","number":179,"surah":21,"verses":[2],"references":[{"surah":21,"verses":[2]}],"verseLabel":"الأنبياء: 2","question":"ما دلالة التعبير بـ﴿مَا يَأْتِيهِمْ﴾ بدل نفي الإتيان بـ«لا»؟","answer":"نُفي الفعل بـ«ما» لأنها مع المضارع تدل في الأصل على الحال، فصوّرت حالتهم القائمة وقت نزول الذكر: يأتيهم الوحي وهم معرضون لاعبون. أما «لا» فتغلب في نفي المستقبل. واختيار المضارع ﴿يَأْتِيهِمْ﴾ يصوّر تجدد الإتيان واستمراره، بخلاف صيغة الماضي التي قد تدل على واقعة انقضت.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 13–16، مبحث «ما يأتيهم من ذكر من ربهم محدث».","url":""}]},{"id":"s21-180","number":180,"surah":21,"verses":[2],"references":[{"surah":21,"verses":[2]}],"verseLabel":"الأنبياء: 2","question":"ما دلالة تكرار «مِن» في قوله تعالى: ﴿مِنْ ذِكْرٍ مِنْ رَبِّهِمْ﴾؟","answer":"جاءت «مِن» الأولى للاستغراق والتوكيد، فالمعنى أنهم يلهون عن كل ذكر يأتيهم، لا عن نوع خاص منه. ثم أضيف الذكر إلى ربهم لزيادة تقبيح الإعراض؛ فالذكر آتٍ من خالقهم ومربيهم ورازقهم والمتولي لشؤونهم، وكان حقه أن يُقابل بالتعظيم والقبول لا باللعب والغفلة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 13–16، مبحث «ما يأتيهم من ذكر من ربهم محدث».","url":""}]},{"id":"s21-181","number":181,"surah":21,"verses":[3],"references":[{"surah":21,"verses":[3]}],"verseLabel":"الأنبياء: 3","question":"ما دلالة إظهار ﴿الَّذِينَ ظَلَمُوا﴾ بعد واو الجماعة في قوله: ﴿وَأَسَرُّوا النَّجْوَى الَّذِينَ ظَلَمُوا﴾؟","answer":"يحتمل أن يكون ﴿الَّذِينَ ظَلَمُوا﴾ بدلًا من واو ﴿أَسَرُّوا﴾؛ فيُذكر الفاعلون أولًا على الإجمال ثم يبيَّنون بوصف الظلم، وفي ذلك تسجيل عليهم بأن نجواهم ظلم. ويحتمل أن يكون مبتدأ مؤخرًا خبره ﴿وَأَسَرُّوا النَّجْوَى﴾، أو منصوبًا على الذم؛ وهذه الأوجه تلتقي في إبرازهم والعناية بذم فعلهم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 17–21، مبحث «وأسروا النجوى الذين ظلموا: الأوجه الإعرابية ودلالاتها».","url":""}]},{"id":"s21-182","number":182,"surah":21,"verses":[4],"references":[{"surah":21,"verses":[4]}],"verseLabel":"الأنبياء: 4","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وَهُوَ السَّمِيعُ الْعَلِيمُ﴾؟","answer":"ذكر السياق ما يُسمع وما يُعلم: فالنجوى قول يُسمع، وإسرارها أمر يحيط به العلم، فناسب أن تختم الآية بصفتي السمع والعلم. وجاء الوصفان معرفين للدلالة على كمال هاتين الصفتين وحصر الكمال المطلق فيهما لله سبحانه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 21–23، مبحث «مناسبة ختام الآية بالسميع العليم».","url":""}]},{"id":"s21-183","number":183,"surah":21,"verses":[10],"references":[{"surah":21,"verses":[10]}],"verseLabel":"الأنبياء: 10","question":"ما سعة الدلالة في قوله تعالى: ﴿فِيهِ ذِكْرُكُمْ﴾؟","answer":"يجمع «الذكر» معاني الشرف والصيت والثناء، كما يدل على الكتاب المبيّن للدين، وعلى الموعظة والتذكير. فالقرآن يجمع لهم الهداية والموعظة ومكارم الأخلاق والشرف الحسن بين الأمم، ولذلك أعقب ذلك بالاستفهام ﴿أَفَلَا تَعْقِلُونَ﴾ توبيخًا لمن يرفض هذا الخير كله.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 35–36، مبحث «لقد أنزلنا إليكم كتابًا فيه ذكركم».","url":""}]},{"id":"s21-184","number":184,"surah":21,"verses":[19,20],"references":[{"surah":21,"verses":[19,20]}],"verseLabel":"الأنبياء: 19–20","question":"ما سر إطلاق ﴿يُسَبِّحُونَ﴾ وحذف الجار، وقولِه: ﴿اللَّيْلَ وَالنَّهَارَ﴾ بلا باء؟","answer":"جاء التسبيح مطلقًا ليشمل صوره كلها، بخلاف ﴿يُسَبِّحُونَ لَهُ﴾ أو ﴿يُسَبِّحُونَهُ﴾ المقيدتين. ونصب ﴿اللَّيْلَ وَالنَّهَارَ﴾ يدل على استغراق الزمن كله، ثم أكده بقوله: ﴿لَا يَفْتُرُونَ﴾؛ فالمقام مقام عبادة دائمة لا تتخللها فترة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 50–55، مبحث «يسبحون الليل والنهار لا يفترون».","url":""}]},{"id":"s21-185","number":185,"surah":21,"verses":[24],"references":[{"surah":21,"verses":[24]}],"verseLabel":"الأنبياء: 24","question":"ما سر تكرار الإنكار في قوله: ﴿أَمِ اتَّخَذُوا مِنْ دُونِهِ آلِهَةً﴾، ثم تحديهم بقوله: ﴿هَاتُوا بُرْهَانَكُمْ﴾؟","answer":"كرر الاستفهام الإنكاري استفظاعًا لشأن الشرك وتعظيمًا لقبحه، ثم نقلهم من الدعوى إلى ميدان البرهان. وقدّم لهم القرآن الحجة العقلية في فساد تعدد الآلهة، ثم أحالهم إلى الوحي الحاضر والسابق؛ فظهر أن قولهم عارٍ من الدليلين جميعًا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 62–63، مبحث «قل هاتوا برهانكم».","url":""}]},{"id":"s21-186","number":186,"surah":21,"verses":[31],"references":[{"surah":21,"verses":[31]}],"verseLabel":"الأنبياء: 31","question":"ما سر تسمية الجبال ﴿رَوَاسِيَ﴾ في الدنيا، والعدول عنها إلى «الجبال» في مشاهد القيامة؟","answer":"الرواسي هي الجبال الثابتة الراسخة، وهذا وصفها في نظام الدنيا حين تمنع الأرض أن تميد بأهلها. أما يوم القيامة فتنسف وتدك، فلا تكون رواسي؛ لذلك يأتي الاسم العام «الجبال» في مشاهد زوال ثباتها، فيتطابق اللفظ مع حالها.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 78–81، مبحث «وجعلنا في الأرض رواسي».","url":""}]},{"id":"s21-187","number":187,"surah":21,"verses":[37],"references":[{"surah":21,"verses":[37]}],"verseLabel":"الأنبياء: 37","question":"ما سر المبالغة في قوله: ﴿خُلِقَ الْإِنْسَانُ مِنْ عَجَلٍ﴾، ولماذا بُني الفعل للمجهول؟","answer":"لم يصف الإنسان بالعجلة فحسب، بل جعله كأنه مخلوق منها، للدلالة على شدة لزومها له. وبُني ﴿خُلِقَ﴾ للمجهول لأن العجلة هنا صفة مذمومة، فلم يسندها السياق إلى الله صراحة، ثم عالجها بالنهي: ﴿فَلَا تَسْتَعْجِلُونِ﴾.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 94–95، مبحث «خلق الإنسان من عجل».","url":""}]},{"id":"s21-188","number":188,"surah":21,"verses":[38],"references":[{"surah":21,"verses":[38]}],"verseLabel":"الأنبياء: 38","question":"ما دلالة المضارع ﴿يَقُولُونَ﴾ واسم الإشارة القريب ﴿هَذَا الْوَعْدُ﴾؟","answer":"المضارع يصور تكرار قولهم وتجدد استهزائهم، لا مقالة وقعت وانتهت. واسم الإشارة للقريب يحضر الوعد أمامهم لأنهم يواجهون المؤمنين به ساعة سماعه، كما أن خطاب الجمع ﴿إِنْ كُنْتُمْ﴾ يدل على أنهم يواجهون جماعة المؤمنين لا الرسول وحده.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 96–97، مبحث «ويقولون متى هذا الوعد».","url":""}]},{"id":"s21-189","number":189,"surah":21,"verses":[42],"references":[{"surah":21,"verses":[42]}],"verseLabel":"الأنبياء: 42","question":"ما سر اختيار اسم ﴿الرَّحْمَنِ﴾ وتقديم الليل في قوله: ﴿مَنْ يَكْلَؤُكُمْ بِاللَّيْلِ وَالنَّهَارِ مِنَ الرَّحْمَنِ﴾؟","answer":"ألمح اسم الرحمن إلى أن إبقاءهم وحفظهم، مع استحقاقهم العذاب، أثر من رحمته. وقُدّم الليل لأن الداهية فيه أشد وقعًا والناس فيه أغفل وأقل استعدادًا، فالسؤال يوقظ شعورهم بعجزهم عن حماية أنفسهم في كل وقت.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 105–106، مبحث «من يكلؤكم بالليل والنهار من الرحمن».","url":""}]}]);
